+#include <string>
+#include <vector>
+#include <stdexcept>
+#include <cctype>
+#include <algorithm>
+#include <cstddef>
+
+enum class TokenType { Identifier, Number, String, Operator, Punctuation };
+
+struct Token {
+  TokenType type;
+  std::string text;
+};
+
+bool operator==(const Token& a, const Token& b) {
+  return a.type == b.type && a.text == b.text;
+}
+
+namespace simple_tokenizer {
+
+namespace {
+
+bool is_ident_start(char c) {
+  return std::isalpha(static_cast<unsigned char>(c)) || c == '_';
+}
+
+bool is_ident_continue(char c) {
+  return std::isalnum(static_cast<unsigned char>(c)) || c == '_';
+}
+
+bool is_digit(char c) {
+  return c >= '0' && c <= '9';
+}
+
+bool is_whitespace(char c) {
+  return c == ' ' || c == '\t' || c == '\n' || c == '\r';
+}
+
+bool is_single_operator(char c) {
+  return std::string("+-*/%=<>!&|^~?").find(c) != std::string::npos;
+}
+
+bool is_punctuation(char c) {
+  return std::string("()[]{},;:.").find(c) != std::string::npos;
+}
+
+} // namespace
+
+std::vector<Token> tokenize(const std::string& input) {
+  std::vector<Token> tokens;
+  const std::vector<std::string> multi_operators = {
+    "==", "!=", "<=", ">=", "&&", "||", "++", "--", "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "<<", ">>", "->", "::"
+  };
+
+  std::size_t i = 0;
+  while (i < input.size()) {
+    char c = input[i];
+
+    if (is_whitespace(c)) {
+      ++i;
+      continue;
+    }
+
+    if (c == '/' && i + 1 < input.size() && input[i + 1] == '/') {
+      i += 2;
+      while (i < input.size() && input[i] != '\n') {
+        ++i;
+      }
+      continue;
+    }
+
+    if (c == '/' && i + 1 < input.size() && input[i + 1] == '*') {
+      i += 2;
+      bool closed = false;
+      while (i < input.size()) {
+        if (input[i] == '*' && i + 1 < input.size() && input[i + 1] == '/') {
+          i += 2;
+          closed = true;
+          break;
+        }
+        ++i;
+      }
+      if (!closed) {
+        throw std::invalid_argument("unterminated block comment");
+      }
+      continue;
+    }
+
+    if (is_ident_start(c)) {
+      std::size_t start = i;
+      while (i < input.size() && is_ident_continue(input[i])) {
+        ++i;
+      }
+      tokens.push_back({TokenType::Identifier, input.substr(start, i - start)});
+      continue;
+    }
+
+    if (is_digit(c)) {
+      std::size_t start = i;
+      while (i < input.size() && is_digit(input[i])) {
+        ++i;
+      }
+
+      if (i < input.size() && input[i] == '.' && i + 1 < input.size() && is_digit(input[i + 1])) {
+        ++i;
+        while (i < input.size() && is_digit(input[i])) {
+          ++i;
+        }
+      }
+
+      if (i < input.size() && (input[i] == 'e' || input[i] == 'E')) {
+        std::size_t exp_start = i;
+        ++i;
+        if (i < input.size() && (input[i] == '+' || input[i] == '-')) {
+          ++i;
+        }
+        if (i < input.size() && is_digit(input[i])) {
+          while (i < input.size() && is_digit(input[i])) {
+            ++i;
+          }
+        } else {
+          i = exp_start;
+        }
+      }
+
+      tokens.push_back({TokenType::Number, input.substr(start, i - start)});
+      continue;
+    }
+
+    if (c == '"') {
+      ++i;
+      std::string value;
+      bool closed = false;
+      while (i < input.size()) {
+        char ch = input[i];
+        if (ch == '"') {
+          ++i;
+          closed = true;
+          break;
+        }
+        if (ch == '\\') {
+          if (i + 1 >= input.size()) {
+            throw std::invalid_argument("unterminated string");
+          }
+          char next = input[i + 1];
+          switch (next) {
+            case '"': value.push_back('"'); break;
+            case '\\': value.push_back('\\'); break;
+            case 'n': value.push_back('\n'); break;
+            case 't': value.push_back('\t'); break;
+            case 'r': value.push_back('\r'); break;
+            default:
+              throw std::invalid_argument("invalid escape sequence");
+          }
+          i += 2;
+        } else {
+          value.push_back(ch);
+          ++i;
+        }
+      }
+      if (!closed) {
+        throw std::invalid_argument("unterminated string");
+      }
+      tokens.push_back({TokenType::String, value});
+      continue;
+    }
+
+    if (i + 1 < input.size()) {
+      std::string two = input.substr(i, 2);
+      if (std::find(multi_operators.begin(), multi_operators.end(), two) != multi_operators.end()) {
+        tokens.push_back({TokenType::Operator, two});
+        i += 2;
+        continue;
+      }
+    }
+
+    if (is_single_operator(c)) {
+      tokens.push_back({TokenType::Operator, std::string(1, c)});
+      ++i;
+      continue;
+    }
+
+    if (is_punctuation(c)) {
+      tokens.push_back({TokenType::Punctuation, std::string(1, c)});
+      ++i;
+      continue;
+    }
+
+    throw std::invalid_argument("invalid character");
+  }
+
+  return tokens;
+}
+
+} // namespace simple_tokenizer
