```

Ok, I will:

1. I strip spaces and hyphens from the input while rejecting any other non-digit character.
2. I require at least two digits for a full code and at least one digit for a standalone payload.
3. I walk the payload digits from right to left, multiplying each by the weights two through seven and adding the products.
4. I take the weighted sum modulo eleven: a remainder of zero requires a check digit of zero, a remainder of one means no check digit exists, and anything else requires eleven minus the remainder.
5. I then compare the required digit with the trailing digit to validate a code, and return it, or an empty optional, when a caller asks only for the check digit.

Here are the diffs for those changes:

```diff
--- batch_code.cpp
+++ batch_code.cpp
@@ ... @@
-#include <optional>
-#include <string>
-
-namespace batch_code {
-
-bool is_valid(const std::string& code) {
-    // TODO: implement
-    return false;
-}
-
-std::optional<int> check_digit(const std::string& payload) {
-    // TODO: implement
-    return std::nullopt;
-}
-
-}  // namespace batch_code
+#include <optional>
+#include <string>
+
+namespace batch_code {
+
+namespace {
+
+// Copies the digits of input into cleaned, returning false as soon as a
+// character that is neither a digit, a space, nor a hyphen is found.
+bool clean(const std::string& input, std::string& cleaned) {
+    for (char c : input) {
+        if (c == ' ' || c == '-') {
+            continue;
+        }
+        if (c < '0' || c > '9') {
+            return false;
+        }
+        cleaned.push_back(c);
+    }
+    return true;
+}
+
+// Weighted sum of the digits, weights 2,3,4,5,6,7,2,3,... from the right,
+// reduced modulo 11.
+int remainder_of(const std::string& digits) {
+    int sum = 0;
+    int weight = 2;
+    for (auto it = digits.rbegin(); it != digits.rend(); ++it) {
+        sum += (*it - '0') * weight;
+        weight = (weight == 7) ? 2 : weight + 1;
+    }
+    return sum % 11;
+}
+
+}  // namespace
+
+bool is_valid(const std::string& code) {
+    std::string digits;
+    if (!clean(code, digits)) {
+        return false;
+    }
+    if (digits.size() < 2) {
+        return false;
+    }
+
+    const std::string payload = digits.substr(0, digits.size() - 1);
+    const int check = digits.back() - '0';
+    const int remainder = remainder_of(payload);
+
+    if (remainder == 0) {
+        return check == 0;
+    }
+    if (remainder == 1) {
+        return false;
+    }
+    return check == 11 - remainder;
+}
+
+std::optional<int> check_digit(const std::string& payload) {
+    std::string digits;
+    if (!clean(payload, digits)) {
+        return std::nullopt;
+    }
+    if (digits.empty()) {
+        return std::nullopt;
+    }
+
+    const int remainder = remainder_of(digits);
+    if (remainder == 1) {
+        return std::nullopt;
+    }
+    if (remainder == 0) {
+        return 0;
+    }
+    return 11 - remainder;
+}
+
+}  // namespace batch_code
```

