}

```

Ok, I will:

1. I scan the pattern and text with two indices, advancing both when a literal or question mark matches.
2. When I see a star, I remember its pattern position and the current text position, then tentatively let it match zero characters.
3. If a later mismatch occurs and a star was seen, I backtrack by letting that star consume one more character and retry from just after the star.
4. After the text is consumed, I allow any trailing stars to match empty and require the pattern index to reach the end.
5. I handle empty patterns, empty texts, consecutive stars, and question marks that must match exactly one character.

Here are the diffs for those changes:

```diff
--- simple_pattern_matching.cpp
+++ simple_pattern_matching.cpp
@@ ... @@
-#include <string>
-
-bool matches_pattern(const std::string& pattern, const std::string& text) {
-    (void)pattern;
-    (void)text;
-    return false;
-}
+#include <string>
+
+bool matches_pattern(const std::string& pattern, const std::string& text) {
+    std::size_t p = 0;
+    std::size_t t = 0;
+    std::size_t star = std::string::npos;
+    std::size_t match = 0;
+
+    while (t < text.size()) {
+        if (p < pattern.size() && (pattern[p] == '?' || pattern[p] == text[t])) {
+            ++p;
+            ++t;
+        } else if (p < pattern.size() && pattern[p] == '*') {
+            star = p;
+            match = t;
+            ++p;
+        } else if (star != std::string::npos) {
+            p = star + 1;
+            ++match;
+            t = match;
+        } else {
+            return false;
+        }
+    }
+
+    while (p < pattern.size() && pattern[p] == '*') {
+        ++p;
+    }
+
+    return p == pattern.size();
+}
