+ring_buffer::ring_buffer(size_t capacity) : capacity_(capacity), buffer_(capacity) {
+    if (capacity == 0) {
+        throw std::invalid_argument("Capacity must be greater than 0");
+    }
+}
+
+bool ring_buffer::write(int value) {
+    bool overwrite = (size_ == capacity_);
+    if (overwrite) {
+        buffer_[head_] = value;
+        head_ = (head_ + 1) % capacity_;
+    } else {
+        buffer_[(head_ + size_) % capacity_] = value;
+        ++size_;
+    }
+    return overwrite;
+}
+
+std::optional<int> ring_buffer::read() {
+    if (size_ == 0) {
+        return std::nullopt;
+    }
+    int value = buffer_[head_];
+    head_ = (head_ + 1) % capacity_;
+    --size_;
+    return value;
+}
+
+std::optional<int> ring_buffer::peek() const {
+    if (size_ == 0) {
+        return std::nullopt;
+    }
+    return buffer_[head_];
+}
