+int min_cuts(const std::string& s) {
+    int n = s.size();
+    if (n == 0) return 0;
+    std::vector<std::vector<bool>> isPal(n, std::vector<bool>(n, false));
+    for (int i = 0; i < n; ++i) {
+        isPal[i][i] = true;
+    }
+    for (int i = 0; i < n - 1; ++i) {
+        if (s[i] == s[i+1]) {
+            isPal[i][i+1] = true;
+        }
+    }
+    for (int len = 3; len <= n; ++len) {
+        for (int i = 0; i <= n - len; ++i) {
+            int j = i + len - 1;
+            if (s[i] == s[j] && isPal[i+1][j-1]) {
+                isPal[i][j] = true;
+            }
+        }
+    }
+    std::vector<int> dp(n, 0);
+    for (int i = 0; i < n; ++i) {
+        if (isPal[0][i]) {
+            dp[i] = 0;
+        } else {
+            dp[i] = i;
+            for (int j = 0; j < i; ++j) {
+                if (isPal[j+1][i]) {
+                    dp[i] = std::min(dp[i], dp[j] + 1);
+                }
+            }
+        }
+    }
+    return dp[n-1];
+}
