+std::string normalize(const std::string& token) {
+    auto is_kept = [](unsigned char c) {
+        return std::isalnum(c) || c == '\'';
+    };
+
+    std::string lowered;
+    lowered.reserve(token.size());
+    for (unsigned char c : token) {
