+namespace {
+
+std::string trim(const std::string& s) {
+    const std::string whitespace = " \t\n\r\f\v";
+    std::size_t start = s.find_first_not_of(whitespace);
+    if (start == std::string::npos) {
+        return "";
+    }
+    std::size_t end = s.find_last_not_of(whitespace);
+    return s.substr(start, end - start + 1);
+}
+
+}  // namespace
+
+std::map<std::string, std::string> parse_key_value_string(const std::string& input) {
+    std::map<std::string, std::string> result;
+    std::size_t pos = 0;
+
+    while (pos <= input.size()) {
+        std::size_t comma = input.find(',', pos);
+        std::string segment;
+
+        if (comma == std::string::npos) {
+            segment = input.substr(pos);
+        } else {
+            segment = input.substr(pos, comma - pos);
+        }
+
+        std::string trimmed = trim(segment);
+
+        if (!trimmed.empty()) {
+            std::size_t equals = trimmed.find('=');
+            std::string key;
+            std::string value;
+
+            if (equals == std::string::npos) {
+                key = trimmed;
+            } else {
+                key = trim(trimmed.substr(0, equals));
+                value = trim(trimmed.substr(equals + 1));
+            }
+
+            if (!key.empty()) {
+                result[key] = value;
+            }
+        }
+
+        if (comma == std::string::npos) {
+            break;
+        }
+        pos = comma + 1;
+    }
+
+    return result;
