+int round_fraction(int numerator, int denominator) {
+    if (denominator == 0) {
+        throw std::invalid_argument("denominator must not be zero");
+    }
+    if (numerator == 0) {
+        return 0;
+    }
+
+    bool negative = (numerator < 0) != (denominator < 0);
+
+    long long abs_num = numerator < 0 ? -static_cast<long long>(numerator) : static_cast<long long>(numerator);
+    long long abs_den = denominator < 0 ? -static_cast<long long>(denominator) : static_cast<long long>(denominator);
+
+    long long quotient = abs_num / abs_den;
+    long long remainder = abs_num % abs_den;
+
+    if (2 * remainder >= abs_den) {
+        ++quotient;
+    }
+
+    long long result = negative ? -quotient : quotient;
+    return static_cast<int>(result);
