+std::string minimum_window(const std::string& text, const std::string& required) {
+    if (required.empty() || text.empty() || required.size() > text.size()) {
+        return "";
+    }
+
+    std::array<int, 256> need{};
+    for (char ch : required) {
+        ++need[static_cast<unsigned char>(ch)];
+    }
+
+    std::array<int, 256> window{};
+    std::size_t missing = required.size();
