+    while (position <= trimmed_input.size()) {
+        const std::size_t comma = trimmed_input.find(',', position);
+        std::string token;
+
+        if (comma == std::string::npos) {
+            token = trimmed_input.substr(position);
+        } else {
+            token = trimmed_input.substr(position, comma - position);
+        }
+
+        token = trim(token);
+
+        if (token.empty()) {
+            throw std::invalid_argument("empty token");
+        }
+
+        std::size_t parsed_characters = 0;
+        const int value = std::stoi(token, &parsed_characters);
+
+        if (parsed_characters != token.size()) {
+            throw std::invalid_argument("invalid token");
