+static long long mod_pow(long long base, long long exp, long long mod) {
+    long long result = 1 % mod;
+    base %= mod;
+    if (base < 0) {
+        base += mod;
+    }
+
+    while (exp > 0) {
+        if (exp & 1LL) {
+            result = (result * base) % mod;
+        }
+        base = (base * base) % mod;
+        exp >>= 1LL;
+    }
+
+    return result;
+}
+
+static bool is_prime(long long p) {
+    if (p < 2) {
+        return false;
+    }
+    if (p % 2 == 0) {
+        return p == 2;
+    }
+
+    for (long long d = 3; d * d <= p; d += 2) {
+        if (p % d == 0) {
+            return false;
+        }
+    }
+
+    return true;
+}
+
+std::vector<long long> modular_square_roots(long long n, long long p) {
+    if (p < 2 || p > 2147483647LL || !is_prime(p)) {
+        throw std::invalid_argument("p must be a prime in the range [2, 2147483647]");
+    }
+
+    n %= p;
+    if (n < 0) {
+        n += p;
+    }
+
+    if (p == 2) {
+        return {n};
+    }
+
+    if (n == 0) {
+        return {0};
+    }
+
+    long long legendre = mod_pow(n, (p - 1) / 2, p);
+    if (legendre != 1) {
+        return {};
+    }
+
+    long long root = 0;
+
+    if (p % 4 == 3) {
+        root = mod_pow(n, (p + 1) / 4, p);
+    } else {
+        long long q = p - 1;
+        int s = 0;
+        while ((q & 1LL) == 0) {
+            q >>= 1LL;
+            ++s;
+        }
+
+        long long z = 2;
+        while (mod_pow(z, (p - 1) / 2, p) != p - 1) {
+            ++z;
+        }
+
+        long long c = mod_pow(z, q, p);
+        long long x = mod_pow(n, (q + 1) / 2, p);
+        long long t = mod_pow(n, q, p);
+        int m = s;
+
+        while (t != 1) {
+            int i = 1;
+            long long t2 = (t * t) % p;
+
+            while (t2 != 1) {
+                t2 = (t2 * t2) % p;
+                ++i;
+                if (i == m) {
+                    throw std::logic_error("Tonelli-Shanks failed");
+                }
+            }
+
+            long long b = mod_pow(c, 1LL << (m - i - 1), p);
+            x = (x * b) % p;
+            b = (b * b) % p;
+            t = (t * b) % p;
+            c = b;
+            m = i;
+        }
+
+        root = x;
+    }
+
+    long long other = (p - root) % p;
+
+    if (root <= other) {
+        return {root, other};
+    }
+
+    return {other, root};
