+            values.push_back(matrix[top][c]);
+        }
+
+        for (int r = top + 1; r <= bottom; ++r) {
+            values.push_back(matrix[r][right]);
+        }
+
+        if (bottom > top) {
+            for (int c = right - 1; c >= left; --c) {
+                values.push_back(matrix[bottom][c]);
+            }
+        }
+
+        if (right > left) {
+            for (int r = bottom - 1; r > top; --r) {
+                values.push_back(matrix[r][left]);
+            }
+        }
+
+        const int length = static_cast<int>(values.size());
+
