+        for (int i = 0; i < length; ++i) {
+            const int source = (i - shift + length) % length;
+            rotated[i] = values[source];
+        }
+
+        int index = 0;
+
+        for (int c = left; c <= right; ++c) {
+            matrix[top][c] = rotated[index++];
