+long long mod_pow(long long base, long long exp, long long mod) {
+    base %= mod;
+    if (base < 0) {
+        base += mod;
+    }
+
+    long long result = 1;
+    while (exp > 0) {
+        if (exp & 1) {
+            result = (result * base) % mod;
+        }
+        base = (base * base) % mod;
+        exp >>= 1;
+    }
+    return result;
