+long long modular_sqrt(long long n, long long p) {
+    if (p == 2) {
+        long long residue = n % 2;
+        if (residue < 0) {
+            residue += 2;
+        }
+        return residue;
+    }
+
+    n %= p;
+    if (n < 0) {
+        n += p;
+    }
+    if (n == 0) {
+        return 0;
+    }
+
+    if (legendre(n, p) != 1) {
+        return -1;
+    }
+
+    if (p % 4 == 3) {
+        long long root = mod_pow(n, (p + 1) / 4, p);
+        return std::min(root, p - root);
+    }
+
+    long long q = p - 1;
+    int s = 0;
+    while ((q & 1) == 0) {
+        q >>= 1;
+        ++s;
+    }
