+std::optional<long long> chinese_remainder(const std::vector<long long>& remainders,
+                                          const std::vector<long long>& moduli) {
+    if (remainders.size() != moduli.size()) {
+        return std::nullopt;
+    }
+    if (remainders.empty()) {
+        return 0LL;
+    }
+
+    long long current_remainder = 0;
+    long long current_modulus = 1;
+
+    for (std::size_t i = 0; i < remainders.size(); ++i) {
+        long long next_remainder = remainders[i];
+        long long next_modulus = moduli[i];
+
+        if (next_modulus <= 0) {
+            return std::nullopt;
+        }
