+        long long difference = next_remainder - current_remainder;
+        long long g = std::gcd(current_modulus, next_modulus);
+
+        if (difference % g != 0) {
+            return std::nullopt;
+        }
+
+        long long reduced_current = current_modulus / g;
+        long long reduced_next = next_modulus / g;
+        long long reduced_difference = difference / g;
+
+        long long inverse = 0;
+        if (reduced_next != 1) {
+            long long unused = 0;
+            extended_gcd(reduced_current, reduced_next, inverse, unused);
+            inverse = normalize(inverse, reduced_next);
+        }
+
+        __int128 multiplier = (__int128)(reduced_difference % reduced_next) * inverse;
+        multiplier %= reduced_next;
+        if (multiplier < 0) {
+            multiplier += reduced_next;
+        }
+
+        __int128 new_remainder = (__int128)current_remainder + (__int128)current_modulus * multiplier;
+        __int128 new_modulus = (__int128)reduced_current * next_modulus;
