+private:
+    struct Node {
+        int key;
+        int priority;
+        std::uint64_t sequence;
+        std::size_t heap_index;
+    };
+
+    std::vector<Node> heap_;
+    std::unordered_map<int, std::size_t> index_of_key_;
+    std::uint64_t next_sequence_ = 0;
+
+    bool better(const Node& left, const Node& right) const;
