+bool IndexedPriorityQueue::better(const Node& left, const Node& right) const {
+    if (left.priority != right.priority) {
+        return left.priority > right.priority;
+    }
+    return left.sequence < right.sequence;
+}
+
+void IndexedPriorityQueue::swap_nodes(std::size_t left, std::size_t right) {
+    std::swap(heap_[left], heap_[right]);
+    heap_[left].heap_index = left;
+    heap_[right].heap_index = right;
+    index_of_key_[heap_[left].key] = left;
+    index_of_key_[heap_[right].key] = right;
+}
+
+std::size_t IndexedPriorityQueue::bubble_up(std::size_t index) {
+    while (index > 0) {
+        std::size_t parent = (index - 1) / 2;
+        if (!better(heap_[index], heap_[parent])) {
+            break;
+        }
+        swap_nodes(index, parent);
+        index = parent;
+    }
+    return index;
+}
+
+std::size_t IndexedPriorityQueue::bubble_down(std::size_t index) {
+    const std::size_t count = heap_.size();
+
+    while (true) {
+        std::size_t best = index;
+        std::size_t left = 2 * index + 1;
+        std::size_t right = 2 * index + 2;
+
+        if (left < count && better(heap_[left], heap_[best])) {
+            best = left;
+        }
+        if (right < count && better(heap_[right], heap_[best])) {
+            best = right;
+        }
+        if (best == index) {
+            break;
+        }
+
+        swap_nodes(index, best);
+        index = best;
+    }
+
+    return index;
+}
+
+void IndexedPriorityQueue::fix(std::size_t index) {
+    index = bubble_up(index);
+    bubble_down(index);
+}
