+    if (index_of_key_.find(key) != index_of_key_.end()) {
+        throw std::invalid_argument("duplicate key");
+    }
+
+    std::size_t index = heap_.size();
+    heap_.push_back(Node{key, priority, next_sequence_++, index});
+    index_of_key_.emplace(key, index);
+    bubble_up(index);
+}
