+    if (heap_.empty()) {
+        throw std::out_of_range("queue is empty");
+    }
+    return heap_.front().key;
+}
+
+int IndexedPriorityQueue::pop() {
+    int key = top();
+    remove(key);
+    return key;
+}
+
+bool IndexedPriorityQueue::change_priority(int key, int new_priority) {
+    auto it = index_of_key_.find(key);
+    if (it == index_of_key_.end()) {
+        return false;
+    }
+
+    std::size_t index = it->second;
+    heap_[index].priority = new_priority;
+    fix(index);
+    return true;
+}
+
+bool IndexedPriorityQueue::remove(int key) {
+    auto it = index_of_key_.find(key);
+    if (it == index_of_key_.end()) {
+        return false;
+    }
+
+    std::size_t index = it->second;
+    std::size_t last = heap_.size() - 1;
+
+    if (index != last) {
+        int moved_key = heap_[last].key;
+        heap_[index] = heap_[last];
+        heap_[index].heap_index = index;
+        index_of_key_[moved_key] = index;
+        index_of_key_.erase(key);
+        heap_.pop_back();
+        fix(index);
+    } else {
+        index_of_key_.erase(key);
+        heap_.pop_back();
+    }
+
+    return true;
+}
