+            return false;
+        }
+        if (state_ == VendingState::Dispensing || state_ == VendingState::SoldOut) {
+            return false;
+        }
+        credit_ += cents;
+        state_ = VendingState::Collecting;
+        return true;
+    }
+
+    bool select() {
+        if (state_ != VendingState::Collecting) {
+            return false;
+        }
+        if (stock_ <= 0 || credit_ < price_) {
+            return false;
+        }
+        credit_ -= price_;
+        --stock_;
+        state_ = VendingState::Dispensing;
+        return true;
+    }
