+        } else if (credit_ > 0) {
+            state_ = VendingState::Collecting;
+        } else {
+            state_ = VendingState::Idle;
+        }
+    }
+
+private:
+    int price_;
+    int stock_;
+    int credit_;
+    VendingState state_;
