+#include <cstddef>
+#include <stdexcept>
+#include <vector>
+
+namespace circular_buffer {
+
+template <typename T>
+class circular_buffer {
+public:
+    explicit circular_buffer(std::size_t capacity)
+        : capacity_(capacity), data_(capacity), head_(0), size_(0) {}
+
+    void write(T value) {
+        if (size_ == capacity_) {
+            throw std::domain_error("buffer is full");
+        }
+        data_[(head_ + size_) % capacity_] = value;
+        ++size_;
+    }
+
+    T read() {
+        if (size_ == 0) {
+            throw std::domain_error("buffer is empty");
+        }
+        T value = data_[head_];
+        head_ = (head_ + 1) % capacity_;
+        --size_;
+        return value;
+    }
+
+    void overwrite(T value) {
+        if (capacity_ == 0) {
+            return;
+        }
+        if (size_ == capacity_) {
+            data_[head_] = value;
+            head_ = (head_ + 1) % capacity_;
+        } else {
+            write(value);
+        }
+    }
+
+    void clear() {
+        head_ = 0;
+        size_ = 0;
+    }
+
+private:
+    std::size_t capacity_;
+    std::vector<T> data_;
+    std::size_t head_;
+    std::size_t size_;
+};
