+        if (!passable(start) || !passable(goal)) {
+            return std::nullopt;
+        }
+
+        if (start == goal) {
+            return std::vector<Point>{start};
+        }
+
+        const int inf = std::numeric_limits<int>::max();
+        std::vector<std::vector<int>> dist(
+            height_, std::vector<int>(width_, inf));
+        std::vector<std::vector<Point>> prev(
+            height_, std::vector<Point>(width_, Point{-1, -1}));
+
+        using Node = std::tuple<int, int, int>;
+        std::priority_queue<Node, std::vector<Node>, std::greater<Node>> pq;
+
+        dist[start.row][start.col] = terrain_cost(start);
+        pq.push({dist[start.row][start.col], start.row, start.col});
+
+        const int dr[4] = {-1, 1, 0, 0};
+        const int dc[4] = {0, 0, -1, 1};
+
+        while (!pq.empty()) {
+            auto [cost, row, col] = pq.top();
+            pq.pop();
