+            path.push_back(current);
+            Point parent = prev[current.row][current.col];
+            if (parent.row == -1 && parent.col == -1) {
+                return std::nullopt;
+            }
+            current = parent;
+        }
+
+        path.push_back(start);
+        std::reverse(path.begin(), path.end());
+        return path;
+    }
