+        return point.row >= 0 && point.row < height_ &&
+               point.col >= 0 && point.col < width_;
+    }
+
+    bool passable(Point point) const {
+        return in_bounds(point) && cells_[point.row][point.col] != '#';
+    }
+
+    int terrain_cost(Point point) const {
+        switch (cells_[point.row][point.col]) {
+            case '.': return 1;
+            case '~': return 3;
+            case '^': return 5;
+            default: return 0;
+        }
+    }
