+#include <vector>
+
+int minimum_moves(int eggs, int floors) {
+    if (eggs < 1) throw std::invalid_argument("eggs must be at least 1");
+    if (floors < 0) throw std::invalid_argument("floors must be non-negative");
+    if (floors == 0) return 0;
+    if (eggs == 1) return floors;
+
+    // With e >= 17 eggs, 2^17 - 1 > 100000, which is plenty for all realistic inputs.
+    const int e = std::min(eggs, 17);
+    // dp[k][m] = maximum number of floors that can be covered with k eggs and m moves.
+    std::vector<std::vector<int>> dp(e + 1, std::vector<int>(floors + 1, 0));
