+        if (interval.second <= start) {
+            continue;
+        }
+        if (interval.first >= end) {
+            break;
+        }
+        int from = std::max(interval.first, start);
+        if (from > cursor) {
+            gaps.emplace_back(cursor, from);
+        }
+        cursor = std::max(cursor, std::min(interval.second, end));
+    }
+    if (cursor < end) {
+        gaps.emplace_back(cursor, end);
+    }
+    return gaps;
