+class MinDeque {
+private:
+    std::vector<std::pair<int, int>> front_stack; // (value, min_so_far)
+    std::vector<std::pair<int, int>> back_stack;
+
+    void transfer_front_to_back() {
+        while (!front_stack.empty()) {
+            int val = front_stack.back().first;
+            front_stack.pop_back();
+            int new_min = back_stack.empty() ? val : std::min(val, back_stack.back().second);
+            back_stack.push_back({val, new_min});
+        }
+    }
+
+    void transfer_back_to_front() {
+        while (!back_stack.empty()) {
+            int val = back_stack.back().first;
+            back_stack.pop_back();
+            int new_min = front_stack.empty() ? val : std::min(val, front_stack.back().second);
+            front_stack.push_back({val, new_min});
+        }
+    }
+
+public:
+    void push_front(int value) {
+        int new_min = front_stack.empty() ? value : std::min(value, front_stack.back().second);
+        front_stack.push_back({value, new_min});
+    }
+
+    void push_back(int value) {
+        int new_min = back_stack.empty() ? value : std::min(value, back_stack.back().second);
+        back_stack.push_back({value, new_min});
+    }
+
+    int pop_front() {
+        if (empty()) throw std::out_of_range("MinDeque is empty");
+        if (front_stack.empty()) {
+            transfer_back_to_front();
+        }
+        int val = front_stack.back().first;
+        front_stack.pop_back();
+        return val;
+    }
+
+    int pop_back() {
+        if (empty()) throw std::out_of_range("MinDeque is empty");
+        if (back_stack.empty()) {
+            transfer_front_to_back();
+        }
+        int val = back_stack.back().first;
+        back_stack.pop_back();
+        return val;
+    }
+
+    int front() {
+        if (empty()) throw std::out_of_range("MinDeque is empty");
+        if (front_stack.empty()) {
+            transfer_back_to_front();
+        }
+        return front_stack.back().first;
+    }
+
+    int back() {
+        if (empty()) throw std::out_of_range("MinDeque is empty");
+        if (back_stack.empty()) {
+            transfer_front_to_back();
+        }
+        return back_stack.back().first;
+    }
+
+    int get_min() const {
+        if (empty()) throw std::out_of_range("MinDeque is empty");
+        if (front_stack.empty()) return back_stack.back().second;
+        if (back_stack.empty()) return front_stack.back().second;
+        return std::min(front_stack.back().second, back_stack.back().second);
+    }
+
+    bool empty() const {
+        return front_stack.empty() && back_stack.empty();
+    }
+
+    size_t size() const {
+        return front_stack.size() + back_stack.size();
+    }
