+#include <unordered_map>
+
+std::size_t count_palindromic_anagram_substrings(const std::string& text) {
+    std::unordered_map<int, std::size_t> prefixCount;
+    prefixCount.reserve(text.size() * 2 + 1);
+    prefixCount[0] = 1;
+
+    int mask = 0;
+    std::size_t total = 0;
+
+    for (char ch : text) {
+        mask ^= 1 << (ch - 'a');
+
+        auto same = prefixCount.find(mask);
+        if (same != prefixCount.end()) {
+            total += same->second;
+        }
+
+        for (int bit = 0; bit < 26; ++bit) {
+            auto oneOdd = prefixCount.find(mask ^ (1 << bit));
+            if (oneOdd != prefixCount.end()) {
+                total += oneOdd->second;
+            }
+        }
+
+        ++prefixCount[mask];
+    }
+
+    return total;
