+namespace bit_manipulation {
+namespace {
+
+int polynomial_degree(std::uint64_t value) {
+    int degree = -1;
+    while (value != 0) {
+        ++degree;
+        value >>= 1;
+    }
+    return degree;
+}
+
+struct U128 {
+    std::uint64_t low;
+    std::uint64_t high;
+};
+
+U128 carryless_multiply_full(std::uint64_t a, std::uint64_t b) {
+    U128 product{0, 0};
+    for (int i = 0; i < 64; ++i) {
+        if ((b >> i) & 1ULL) {
+            product.low ^= (a << i);
+            if (i != 0) {
+                product.high ^= (a >> (64 - i));
+            }
+        }
+    }
+    return product;
+}
+
+std::uint64_t reduce_full_product(U128 value, std::uint64_t modulus) {
+    if (modulus == 0) {
+        throw std::invalid_argument("modulus must be nonzero");
+    }
+
+    const int modulus_degree = polynomial_degree(modulus);
+    if (modulus_degree == 0) {
+        return 0;
+    }
+
+    for (int bit = 127; bit >= modulus_degree; --bit) {
+        bool set = false;
+        if (bit >= 64) {
+            set = ((value.high >> (bit - 64)) & 1ULL) != 0;
+        } else {
+            set = ((value.low >> bit) & 1ULL) != 0;
+        }
+
+        if (!set) {
+            continue;
+        }
+
+        const int shift = bit - modulus_degree;
+        if (shift >= 64) {
+            value.high ^= (modulus << (shift - 64));
+        } else {
+            value.low ^= (modulus << shift);
+            if (shift != 0) {
+                value.high ^= (modulus >> (64 - shift));
+            }
+        }
+    }
+
+    return value.low;
+}
+
+} // namespace
