+    if (divisor == 0) {
+        throw std::invalid_argument("divisor must be nonzero");
+    }
+
+    const int divisor_degree = polynomial_degree(divisor);
+    if (divisor_degree == 0) {
+        return 0;
+    }
+
+    std::uint64_t remainder = dividend;
+    while (remainder != 0) {
+        const int remainder_degree = polynomial_degree(remainder);
+        if (remainder_degree < divisor_degree) {
+            break;
+        }
+        remainder ^= (divisor << (remainder_degree - divisor_degree));
+    }
+
+    return remainder;
+}
