+#include <cstdint>
+#include <stdexcept>
+#include <utility>
+#include <vector>
+
+namespace combinatorics {
+
+std::uint64_t count_linear_extensions(
+    int n,
+    const std::vector<std::pair<int, int>>& constraints) {
+    if (n < 0 || n > 20) {
+        throw std::invalid_argument("n must be between 0 and 20");
+    }
+
+    for (const auto& constraint : constraints) {
+        const int before = constraint.first;
+        const int after = constraint.second;
+        if (before < 0 || before >= n || after < 0 || after >= n) {
+            throw std::invalid_argument("constraint label out of range");
+        }
+    }
+
+    const int total_masks = 1 << n;
+    std::vector<std::uint64_t> dp(total_masks, 0);
+    dp[0] = 1;
+
+    for (int mask = 0; mask < total_masks; ++mask) {
+        if (dp[mask] == 0) {
+            continue;
+        }
+
+        for (int next = 0; next < n; ++next) {
+            if (mask & (1 << next)) {
+                continue;
+            }
+
+            bool allowed = true;
+            for (const auto& constraint : constraints) {
+                if (constraint.second == next &&
+                    (mask & (1 << constraint.first)) == 0) {
+                    allowed = false;
+                    break;
+                }
+            }
+
+            if (allowed) {
+                dp[mask | (1 << next)] += dp[mask];
+            }
+        }
+    }
+
+    const std::uint64_t result = dp[total_masks - 1];
+    if (n > 0 && result == 0) {
+        throw std::invalid_argument("constraints contain a cycle");
+    }
+
+    return result;
