+unsigned trailing_zeros(std::uint64_t value) {
+    unsigned count = 0;
+    while ((value & 1) == 0) {
+        value >>= 1;
+        ++count;
+    }
+    return count;
+}
+
+} // namespace
+
+std::uint64_t next_with_same_popcount(std::uint64_t value) {
+    if (value == 0) {
+        return 0;
+    }
+
+    std::uint64_t lowest_bit = value & (~value + 1);
+    std::uint64_t ripple = value + lowest_bit;
+
+    if (ripple == 0) {
+        return 0;
+    }
+
+    std::uint64_t ones = value ^ ripple;
+    unsigned shift = trailing_zeros(lowest_bit) + 2;
+
+    if (shift >= 64) {
+        return ripple;
+    }
+
