+std::string to_roman(int value) {
+    if (value < 1 || value > 3999) {
+        throw std::invalid_argument("value must be between 1 and 3999");
+    }
+
+    struct Symbol {
+        int value;
+        const char* text;
+    };
+
+    static const Symbol symbols[] = {
+        {1000, "M"},
+        {900, "CM"},
+        {500, "D"},
+        {400, "CD"},
+        {100, "C"},
+        {90, "XC"},
+        {50, "L"},
+        {40, "XL"},
+        {10, "X"},
+        {9, "IX"},
+        {5, "V"},
+        {4, "IV"},
+        {1, "I"}
+    };
+
+    std::string result;
+    for (const Symbol& symbol : symbols) {
+        while (value >= symbol.value) {
+            result += symbol.text;
+            value -= symbol.value;
+        }
+    }
+
+    return result;
