+int from_roman(const std::string& numeral) {
+    if (numeral.empty()) {
+        throw std::invalid_argument("empty Roman numeral");
+    }
+
+    auto value_of = [](char c) -> int {
+        switch (c) {
+            case 'I': return 1;
+            case 'V': return 5;
+            case 'X': return 10;
+            case 'L': return 50;
+            case 'C': return 100;
+            case 'D': return 500;
+            case 'M': return 1000;
+            default: return 0;
+        }
+    };
+
+    int total = 0;
+    for (std::string::size_type i = 0; i < numeral.size(); ++i) {
+        int current = value_of(numeral[i]);
+        if (current == 0) {
+            throw std::invalid_argument("invalid Roman numeral character");
+        }
+
+        if (i + 1 < numeral.size()) {
+            int next = value_of(numeral[i + 1]);
+            if (next == 0) {
+                throw std::invalid_argument("invalid Roman numeral character");
+            }
+
+            if (current < next) {
+                total -= current;
+            } else {
+                total += current;
+            }
+        } else {
+            total += current;
+        }
+    }
