+    int shortest_path_length() const {
+        const int rows = static_cast<int>(grid_.size());
+        const int cols = static_cast<int>(grid_[0].size());
+
+        int sr = -1, sc = -1, er = -1, ec = -1;
+        for (int r = 0; r < rows; ++r) {
+            for (int c = 0; c < cols; ++c) {
+                const char ch = grid_[r][c];
+                if (ch == 'S') { sr = r; sc = c; }
+                else if (ch == 'E') { er = r; ec = c; }
+            }
+        }
+
+        std::vector<std::vector<int>> dist(
+            rows, std::vector<int>(cols, std::numeric_limits<int>::max()));
+
+        using Node = std::tuple<int, int, int>;
+        std::priority_queue<Node, std::vector<Node>, std::greater<Node>> pq;
+
+        dist[sr][sc] = 0;
+        pq.push({0, sr, sc});
+
+        const int dr[4] = {-1, 1, 0, 0};
+        const int dc[4] = {0, 0, -1, 1};
+
+        while (!pq.empty()) {
+            int d, r, c;
+            std::tie(d, r, c) = pq.top();
+            pq.pop();
+
+            if (d > dist[r][c]) continue;
+            if (r == er && c == ec) return d;
+
+            for (int k = 0; k < 4; ++k) {
+                const int nr = r + dr[k];
+                const int nc = c + dc[k];
+                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
+                const int step = cell_cost(grid_[nr][nc]);
+                if (step < 0) continue;
+                const int nd = d + step;
+                if (nd < dist[nr][nc]) {
+                    dist[nr][nc] = nd;
+                    pq.push({nd, nr, nc});
+                }
+            }
