+class LinkedList {
+public:
+    LinkedList() = default;
+
+    void push_back(int value);
+    void push_front(int value);
+    void reverse();
+    std::size_t remove(int value);
+    bool empty() const;
+    std::size_t size() const;
+    std::vector<int> to_vector() const;
+
+private:
+    struct Node {
+        int value;
+        std::unique_ptr<Node> next;
+    };
+
+    std::unique_ptr<Node> head_;
+    Node* tail_ = nullptr;
+    std::size_t size_ = 0;
+};
