+void LinkedList::push_back(int value) {
+    auto node = std::make_unique<Node>(Node{value, nullptr});
+    Node* raw = node.get();
+    if (tail_) {
+        tail_->next = std::move(node);
+    } else {
+        head_ = std::move(node);
+    }
+    tail_ = raw;
+    ++size_;
+}
+
+void LinkedList::push_front(int value) {
+    auto node = std::make_unique<Node>(Node{value, std::move(head_)});
+    if (!tail_) {
+        tail_ = node.get();
+    }
+    head_ = std::move(node);
+    ++size_;
+}
+
+void LinkedList::reverse() {
+    Node* old_head = head_.get();
+    Node* prev = nullptr;
+    Node* cur = head_.release();
+    while (cur) {
+        Node* nxt = cur->next.release();
+        cur->next.reset(prev);
+        prev = cur;
+        cur = nxt;
+    }
+    head_.reset(prev);
+    tail_ = old_head;
+}
+
+std::size_t LinkedList::remove(int value) {
+    std::size_t removed = 0;
+
+    while (head_ && head_->value == value) {
+        head_ = std::move(head_->next);
+        ++removed;
+        --size_;
+    }
+
+    Node* prev = head_.get();
+    while (prev && prev->next) {
+        if (prev->next->value == value) {
+            prev->next = std::move(prev->next->next);
+            ++removed;
+            --size_;
+        } else {
+            prev = prev->next.get();
+        }
+    }
+
+    if (head_) {
+        Node* cur = head_.get();
+        while (cur->next) {
+            cur = cur->next.get();
+        }
+        tail_ = cur;
+    } else {
+        tail_ = nullptr;
+    }
+
+    return removed;
+}
+
+bool LinkedList::empty() const {
+    return size_ == 0;
+}
+
+std::size_t LinkedList::size() const {
+    return size_;
+}
+
+std::vector<int> LinkedList::to_vector() const {
+    std::vector<int> result;
+    Node* cur = head_.get();
+    while (cur) {
+        result.push_back(cur->value);
+        cur = cur->next.get();
+    }
+    return result;
