+#include <algorithm>
+#include <utility>
+#include <vector>
+
+std::vector<std::vector<int>> rotate_layers(std::vector<std::vector<int>> matrix, int rotations) {
+    if (matrix.empty() || matrix.front().empty()) {
+        return matrix;
+    }
+
+    const int rows = static_cast<int>(matrix.size());
+    const int cols = static_cast<int>(matrix.front().size());
+    const int layer_count = std::min(rows, cols) / 2;
+
+    for (int layer = 0; layer < layer_count; ++layer) {
+        const int top = layer;
+        const int left = layer;
+        const int bottom = rows - 1 - layer;
+        const int right = cols - 1 - layer;
+
+        std::vector<std::pair<int, int>> positions;
+
+        for (int col = left; col <= right; ++col) {
+            positions.emplace_back(top, col);
+        }
+        for (int row = top + 1; row <= bottom; ++row) {
+            positions.emplace_back(row, right);
+        }
+        for (int col = right - 1; col >= left; --col) {
+            positions.emplace_back(bottom, col);
+        }
+        for (int row = bottom - 1; row > top; --row) {
+            positions.emplace_back(row, left);
+        }
+
+        const int perimeter = static_cast<int>(positions.size());
+        int shift = rotations % perimeter;
+        if (shift < 0) {
+            shift += perimeter;
+        }
+
+        std::vector<int> values;
+        values.reserve(perimeter);
+        for (const auto& position : positions) {
+            values.push_back(matrix[position.first][position.second]);
+        }
+
+        for (int i = 0; i < perimeter; ++i) {
+            const auto& position = positions[i];
+            matrix[position.first][position.second] = values[(i + shift) % perimeter];
+        }
+    }
+
+    return matrix;
+}
