+std::vector<std::string> palindromic_anagrams(const std::string& text) {
+    std::array<int, 26> counts{};
+
+    for (unsigned char ch : text) {
+        if (std::isalpha(ch)) {
+            counts[std::tolower(ch) - 'a']++;
+        }
+    }
+
+    int odd_count = 0;
+    char middle = '\0';
+
+    for (int i = 0; i < 26; ++i) {
+        if (counts[i] % 2 != 0) {
+            ++odd_count;
+            middle = static_cast<char>('a' + i);
+        }
+    }
+
+    if (odd_count > 1) {
+        return {};
+    }
+
+    std::string half;
+    for (int i = 0; i < 26; ++i) {
+        half.append(counts[i] / 2, static_cast<char>('a' + i));
+    }
+
+    std::vector<std::string> palindromes;
+    std::string permutation = half;
+
+    do {
+        std::string palindrome = permutation;
+
+        if (odd_count == 1) {
+            palindrome.push_back(middle);
+        }
+
+        palindrome.append(permutation.rbegin(), permutation.rend());
+        palindromes.push_back(palindrome);
+    } while (std::next_permutation(permutation.begin(), permutation.end()));
+
+    return palindromes;
