+    }
+
+    void add(int value) {
+        add_range(value, value);
+    }
+
+    void add_range(int lo, int hi) {
+        if (lo > hi) {
+            return;
+        }
+        intervals_.push_back({lo, hi});
+        normalize();
+    }
+
+    bool contains(int value) const {
+        for (const auto& iv : intervals_) {
+            if (value >= iv.first && value <= iv.second) {
+                return true;
+            }
+            if (iv.first > value) {
+                return false;
+            }
+        }
+        return false;
+    }
+
+    bool empty() const {
+        return intervals_.empty();
+    }
+
+    std::size_t size() const {
+        long long total = 0;
+        for (const auto& iv : intervals_) {
+            total += static_cast<long long>(iv.second) - static_cast<long long>(iv.first) + 1;
+        }
+        return static_cast<std::size_t>(total);
+    }
+
+    std::vector<Interval> intervals() const {
+        return intervals_;
+    }
+
+    IntervalSet union_with(const IntervalSet& other) const {
+        IntervalSet result;
+        result.intervals_.reserve(intervals_.size() + other.intervals_.size());
+        for (const auto& iv : intervals_) {
+            result.intervals_.push_back(iv);
+        }
+        for (const auto& iv : other.intervals_) {
+            result.intervals_.push_back(iv);
+        }
+        result.normalize();
+        return result;
+    }
+
+    IntervalSet intersection(const IntervalSet& other) const {
+        IntervalSet result;
+        std::size_t i = 0;
+        std::size_t j = 0;
+        while (i < intervals_.size() && j < other.intervals_.size()) {
+            const int lo = std::max(intervals_[i].first, other.intervals_[j].first);
+            const int hi = std::min(intervals_[i].second, other.intervals_[j].second);
+            if (lo <= hi) {
+                result.intervals_.push_back({lo, hi});
+            }
+            if (intervals_[i].second < other.intervals_[j].second) {
+                ++i;
+            } else if (intervals_[i].second > other.intervals_[j].second) {
+                ++j;
+            } else {
+                ++i;
+                ++j;
+            }
+        }
+        result.normalize();
+        return result;
+    }
