+    IntervalSet difference(const IntervalSet& other) const {
+        IntervalSet result;
+        for (const auto& mine : intervals_) {
+            std::vector<Interval> pieces{mine};
+            for (const auto& theirs : other.intervals_) {
+                if (pieces.empty()) {
+                    break;
+                }
+                std::vector<Interval> remaining;
+                for (const auto& piece : pieces) {
+                    if (theirs.second < piece.first || theirs.first > piece.second) {
+                        remaining.push_back(piece);
+                        continue;
+                    }
+                    if (theirs.first > piece.first) {
+                        remaining.push_back({piece.first, theirs.first - 1});
+                    }
+                    if (theirs.second < piece.second) {
+                        remaining.push_back({theirs.second + 1, piece.second});
+                    }
+                }
+                pieces = std::move(remaining);
+            }
+            for (const auto& piece : pieces) {
+                result.intervals_.push_back(piece);
+            }
+        }
+        result.normalize();
