+        if (intervals_.empty()) {
+            return;
+        }
+        std::sort(intervals_.begin(), intervals_.end());
+        std::vector<Interval> merged;
+        for (const auto& iv : intervals_) {
+            if (iv.first > iv.second) {
+                continue;
+            }
+            if (!merged.empty() &&
