+int longest_substring_with_k_distinct(const std::string& s, int k) {
+    if (k <= 0 || s.empty()) {
+        return 0;
+    }
+
+    std::unordered_map<char, int> counts;
+    std::size_t left = 0;
+    std::size_t best = 0;
+
+    for (std::size_t right = 0; right < s.size(); ++right) {
+        ++counts[s[right]];
+
+        while (counts.size() > static_cast<std::size_t>(k)) {
+            auto it = counts.find(s[left]);
+            if (--it->second == 0) {
+                counts.erase(it);
+            }
+            ++left;
+        }
+
+        best = std::max(best, right - left + 1);
+    }
+
+    return static_cast<int>(best);
+}
