+    const std::string normalized_left = normalize_number(left);
+    const std::string normalized_right = normalize_number(right);
+
+    if (normalized_left.size() < normalized_right.size()) {
+        return -1;
+    }
+    if (normalized_left.size() > normalized_right.size()) {
+        return 1;
+    }
