+    const bool right_is_numeric = is_numeric(right);
+
+    if (left_is_numeric && right_is_numeric) {
+        return compare_numeric(left, right);
+    }
+    if (left_is_numeric) {
+        return -1;
+    }
+    if (right_is_numeric) {
+        return 1;
+    }
+
+    if (left < right) {
+        return -1;
+    }
+    if (left > right) {
