+std::vector<std::string> parse_command_line(const std::string& input) {
+    std::vector<std::string> tokens;
+    std::string current;
+    bool in_token = false;
+
+    enum class State { Normal, Single, Double };
+    State state = State::Normal;
+
+    auto is_whitespace = [](char c) {
+        return c == ' ' || c == '\t' || c == '\r' || c == '\n';
+    };
+
+    std::size_t i = 0;
+    while (i < input.size()) {
+        char c = input[i];
+
+        if (state == State::Normal) {
+            if (is_whitespace(c)) {
+                if (in_token) {
+                    tokens.push_back(current);
+                    current.clear();
+                    in_token = false;
+                }
+                ++i;
+            } else if (c == '\'') {
+                in_token = true;
+                state = State::Single;
+                ++i;
+            } else if (c == '"') {
+                in_token = true;
+                state = State::Double;
+                ++i;
+            } else if (c == '\\') {
+                if (i + 1 >= input.size()) {
+                    throw std::invalid_argument("trailing backslash");
+                }
+                in_token = true;
+                current.push_back(input[i + 1]);
+                i += 2;
+            } else {
+                in_token = true;
+                current.push_back(c);
+                ++i;
+            }
+        } else if (state == State::Single) {
+            if (c == '\'') {
+                state = State::Normal;
+                ++i;
+            } else {
+                current.push_back(c);
+                ++i;
+            }
+        } else {
+            if (c == '"') {
+                state = State::Normal;
+                ++i;
+            } else if (c == '\\') {
+                if (i + 1 >= input.size()) {
+                    throw std::invalid_argument("unterminated escape");
+                }
+                char escaped = input[i + 1];
+                switch (escaped) {
+                    case '"': current.push_back('"'); break;
+                    case '\\': current.push_back('\\'); break;
+                    case 'n': current.push_back('\n'); break;
+                    case 't': current.push_back('\t'); break;
+                    default: throw std::invalid_argument("invalid escape");
+                }
+                i += 2;
+            } else {
+                current.push_back(c);
+                ++i;
+            }
+        }
+    }
