+std::vector<std::string> tokenize(const std::string& input) {
+    std::vector<std::string> tokens;
+    std::string current;
+    bool has_token = false;
+    bool in_quotes = false;
+
+    for (std::size_t i = 0; i < input.size(); ++i) {
+        char c = input[i];
+
+        if (in_quotes) {
+            if (c == '\\') {
+                if (i + 1 >= input.size()) {
+                    throw std::invalid_argument("backslash at end of input");
+                }
+                current += input[++i];
+            } else if (c == '"') {
+                in_quotes = false;
+            } else {
+                current += c;
+            }
+        } else if (c == '"') {
+            in_quotes = true;
+            has_token = true;
+        } else if (std::isspace(static_cast<unsigned char>(c))) {
+            if (has_token) {
+                tokens.push_back(current);
+                current.clear();
+                has_token = false;
+            }
+        } else {
+            current += c;
+            has_token = true;
+        }
+    }
+
+    if (in_quotes) {
+        throw std::invalid_argument("unterminated quoted region");
+    }
+    if (has_token) {
+        tokens.push_back(current);
+    }
+    return tokens;
+}
