+#include <string>
+#include <stdexcept>
+
+namespace base_conversion {
+
+namespace {
+
+int digit_value(char c) {
+    if (c >= '0' && c <= '9') return c - '0';
+    if (c >= 'a' && c <= 'z') return c - 'a' + 10;
+    if (c >= 'A' && c <= 'Z') return c - 'A' + 10;
+    return -1;
+}
+
+char value_digit(int v) {
+    static const char* digits = "0123456789abcdefghijklmnopqrstuvwxyz";
+    return digits[v];
+}
+
+}
+
+std::string convert(const std::string& number, int from_base, int to_base) {
+    if (from_base < 2 || from_base > 36) {
+        throw std::invalid_argument("from_base out of range");
+    }
+    if (to_base < 2 || to_base > 36) {
+        throw std::invalid_argument("to_base out of range");
+    }
+    if (number.empty()) {
+        throw std::invalid_argument("empty input");
+    }
+
+    bool negative = false;
+    std::size_t start = 0;
+    if (number[0] == '-') {
+        negative = true;
+        start = 1;
+    } else if (number[0] == '+') {
+        start = 1;
+    }
+    if (start >= number.size()) {
+        throw std::invalid_argument("no digits after sign");
+    }
+
+    long long value = 0;
+    for (std::size_t i = start; i < number.size(); ++i) {
+        int d = digit_value(number[i]);
+        if (d < 0 || d >= from_base) {
+            throw std::invalid_argument("invalid digit for source base");
+        }
+        value = value * from_base + d;
+    }
+
+    if (value == 0) {
+        return "0";
+    }
+
+    std::string result;
+    while (value > 0) {
+        result.insert(result.begin(), value_digit(static_cast<int>(value % to_base)));
+        value /= to_base;
+    }
+
+    if (negative) {
+        result.insert(result.begin(), '-');
+    }
+    return result;
+}
+
