+std::uint8_t hamming_encode(std::uint8_t data) {
+    data &= 0x0F;
+    std::uint8_t code = 0;
+    if (data & 0x01) code |= 1u << 2;
+    if (data & 0x02) code |= 1u << 4;
+    if (data & 0x04) code |= 1u << 5;
+    if (data & 0x08) code |= 1u << 6;
+
+    bool p1 = ((code >> 2) ^ (code >> 4) ^ (code >> 6)) & 1;
+    bool p2 = ((code >> 2) ^ (code >> 5) ^ (code >> 6)) & 1;
+    bool p3 = ((code >> 4) ^ (code >> 5) ^ (code >> 6)) & 1;
+
+    if (p1) code |= 1u << 0;
+    if (p2) code |= 1u << 1;
+    if (p3) code |= 1u << 3;
+    return code;
+}
+
+std::uint8_t hamming_decode(std::uint8_t code) {
+    code &= 0x7F;
+    int s0 = ((code >> 0) ^ (code >> 2) ^ (code >> 4) ^ (code >> 6)) & 1;
+    int s1 = ((code >> 1) ^ (code >> 2) ^ (code >> 5) ^ (code >> 6)) & 1;
+    int s2 = ((code >> 3) ^ (code >> 4) ^ (code >> 5) ^ (code >> 6)) & 1;
+    int syndrome = (s2 << 2) | (s1 << 1) | s0;
+
+    if (syndrome != 0) {
+        code ^= static_cast<std::uint8_t>(1u << (syndrome - 1));
+    }
+
+    std::uint8_t data = 0;
+    if (code & (1u << 2)) data |= 0x01;
+    if (code & (1u << 4)) data |= 0x02;
