+#include <algorithm>
+#include <vector>
+
+std::vector<int> remove_duplicates(std::vector<int> const& values) {
+    std::vector<int> result;
+    for (int value : values) {
+        bool already_seen = false;
+        for (int kept : result) {
+            if (kept == value) {
+                already_seen = true;
+                break;
+            }
+        }
+        if (!already_seen) {
+            result.push_back(value);
+        }
+    }
+    return result;
+}
