+std::vector<std::vector<int>> chunk(std::vector<int> const& values, int size) {
+    std::vector<std::vector<int>> result;
+    if (size <= 0 || values.empty()) {
+        return result;
+    }
+
+    std::size_t step = static_cast<std::size_t>(size);
+    for (std::size_t start = 0; start < values.size(); start += step) {
+        std::size_t finish = std::min(values.size(), start + step);
+        result.emplace_back(values.begin() + static_cast<std::ptrdiff_t>(start),
+                            values.begin() + static_cast<std::ptrdiff_t>(finish));
+    }
+    return result;
+}
