+    if (number.empty()) {
+        return false;
+    }
+
+    int interim = 0;
+    for (char ch : number) {
+        if (!is_ascii_digit(ch)) {
+            return false;
+        }
+        interim = DAMM[interim][ch - '0'];
+    }
+
+    return interim == 0;
