+    if (payload.empty()) {
+        throw std::invalid_argument("payload must not be empty");
+    }
+
+    int interim = 0;
+    for (char ch : payload) {
+        if (!is_ascii_digit(ch)) {
+            throw std::invalid_argument("payload must contain only digits");
+        }
+        interim = DAMM[interim][ch - '0'];
+    }
+
+    for (int digit = 0; digit < 10; ++digit) {
+        if (DAMM[interim][digit] == 0) {
+            return static_cast<char>('0' + digit);
+        }
+    }
+
+    throw std::logic_error("Damm table row has no zero");
