+private:
+    struct Node {
+        int value;
+        Node* next;
+        explicit Node(int v) : value(v), next(nullptr) {}
+    };
+
+    Node* head_ = nullptr;
+    Node* tail_ = nullptr;
+    std::size_t size_ = 0;
+
+    void copy_from(const LinkedList& other);
