+    return size_;
+}
+
+void LinkedList::clear() {
+    Node* current = head_;
+    while (current != nullptr) {
+        Node* next = current->next;
+        delete current;
+        current = next;
+    }
+    head_ = nullptr;
+    tail_ = nullptr;
+    size_ = 0;
+}
+
+LinkedList LinkedList::merge_sorted(const LinkedList& other) const {
+    LinkedList result;
+    Node* left = head_;
+    Node* right = other.head_;
+    while (left != nullptr && right != nullptr) {
+        if (left->value <= right->value) {
+            result.push_back(left->value);
+            left = left->next;
+        } else {
+            result.push_back(right->value);
+            right = right->next;
+        }
+    }
+    while (left != nullptr) {
+        result.push_back(left->value);
+        left = left->next;
+    }
+    while (right != nullptr) {
+        result.push_back(right->value);
+        right = right->next;
+    }
+    return result;
+}
+
+void LinkedList::copy_from(const LinkedList& other) {
+    Node* current = other.head_;
+    while (current != nullptr) {
+        push_back(current->value);
+        current = current->next;
