+#include <string>
+#include <stdexcept>
+#include <cctype>
+
+namespace expr {
+
+namespace {
+
+class Parser {
+public:
+    explicit Parser(const std::string& text) : src(text), pos(0) {}
+
+    long long parse() {
+        skip();
+        long long value = parseExpression();
+        skip();
+        if (pos != src.size()) {
+            throw std::invalid_argument("unexpected trailing input");
+        }
+        return value;
+    }
+
+private:
+    const std::string& src;
+    std::size_t pos;
+
+    void skip() {
+        while (pos < src.size() &&
+               std::isspace(static_cast<unsigned char>(src[pos]))) {
+            ++pos;
+        }
+    }
+
+    long long parseExpression() {
+        long long value = parseTerm();
+        while (true) {
+            skip();
+            if (pos < src.size() && (src[pos] == '+' || src[pos] == '-')) {
+                char op = src[pos++];
+                long long rhs = parseTerm();
+                value = (op == '+') ? value + rhs : value - rhs;
+            } else {
+                break;
+            }
+        }
+        return value;
+    }
+
+    long long parseTerm() {
+        long long value = parseFactor();
+        while (true) {
+            skip();
+            if (pos < src.size() && (src[pos] == '*' || src[pos] == '/')) {
+                char op = src[pos++];
+                long long rhs = parseFactor();
+                if (op == '*') {
+                    value *= rhs;
+                } else {
+                    if (rhs == 0) {
+                        throw std::domain_error("division by zero");
+                    }
+                    value /= rhs;
+                }
+            } else {
+                break;
+            }
+        }
+        return value;
+    }
+
+    long long parseFactor() {
+        skip();
+        if (pos >= src.size()) {
+            throw std::invalid_argument("unexpected end of expression");
+        }
+        char c = src[pos];
+        if (c == '+') {
+            ++pos;
+            return parseFactor();
+        }
+        if (c == '-') {
+            ++pos;
+            return -parseFactor();
+        }
+        if (c == '(') {
+            ++pos;
+            long long value = parseExpression();
+            skip();
+            if (pos >= src.size() || src[pos] != ')') {
+                throw std::invalid_argument("expected ')'");
+            }
+            ++pos;
+            return value;
+        }
+        if (std::isdigit(static_cast<unsigned char>(c))) {
+            long long value = 0;
+            while (pos < src.size() &&
+                   std::isdigit(static_cast<unsigned char>(src[pos]))) {
