+#include <vector>
+
+int count_decodings(const std::string& s) {
+    if (s.empty()) return 0;
+    int n = static_cast<int>(s.size());
+    std::vector<int> dp(n + 1, 0);
+    dp[0] = 1;
+    if (s[0] != '0') {
+        dp[1] = 1;
+    }
+    for (int i = 2; i <= n; ++i) {
+        int one = s[i - 1] - '0';
+        if (one >= 1 && one <= 9) {
+            dp[i] += dp[i - 1];
+        }
+        int two = (s[i - 2] - '0') * 10 + (s[i - 1] - '0');
+        if (two >= 10 && two <= 26) {
+            dp[i] += dp[i - 2];
+        }
+    }
+    return dp[n];
+}
