+    std::string result;
+    for (const auto& entry : table) {
+        int num = entry.first;
+        const std::string& symbol = entry.second;
+        while (value >= num) {
+            result += symbol;
+            value -= num;
+        }
+    }
+    return result;
+}
+
+int from_roman(const std::string& roman) {
+    if (roman.empty()) {
+        throw std::invalid_argument("empty roman numeral");
+    }
+
+    auto char_value = [](char c) -> int {
+        switch (c) {
+            case 'I': return 1;
+            case 'V': return 5;
+            case 'X': return 10;
+            case 'L': return 50;
+            case 'C': return 100;
+            case 'D': return 500;
+            case 'M': return 1000;
+            default: throw std::invalid_argument("invalid roman character");
+        }
+    };
+
+    auto is_allowed_pair = [](char a, char b) {
+        std::string pair;
+        pair += a;
+        pair += b;
+        return pair == "IV" || pair == "IX" || pair == "XL" ||
+               pair == "XC" || pair == "CD" || pair == "CM";
+    };
+
+    int sum = 0;
+    std::size_t i = 0;
+    while (i < roman.size()) {
+        int current = char_value(roman[i]);
+        if (i + 1 < roman.size()) {
+            int next = char_value(roman[i + 1]);
+            if (current < next) {
+                if (!is_allowed_pair(roman[i], roman[i + 1])) {
+                    throw std::invalid_argument("invalid subtractive pair");
+                }
+                sum += next - current;
+                i += 2;
+                continue;
+            }
+        }
+        sum += current;
+        ++i;
+    }
+
+    if (sum < 1 || sum > 3999) {
+        throw std::invalid_argument("value out of range");
+    }
+    if (to_roman(sum) != roman) {
+        throw std::invalid_argument("non-canonical roman numeral");
+    }
