+std::pair<long long, long long> pell_minimal_solution(long long n) {
+    if (n <= 0) {
+        throw std::invalid_argument("n must be a positive integer");
+    }
+
+    long long a0 = static_cast<long long>(std::sqrt(static_cast<long double>(n)));
+    while (a0 * a0 > n) --a0;
+    while ((a0 + 1) * (a0 + 1) <= n) ++a0;
+
+    if (a0 * a0 == n) {
+        throw std::invalid_argument("n must not be a perfect square");
+    }
+
+    long long m = 0;
+    long long d = 1;
+    long long a = a0;
+    std::vector<long long> period;
+
+    do {
+        m = d * a - m;
+        d = (n - m * m) / d;
+        a = (a0 + m) / d;
+        period.push_back(a);
+    } while (a != 2 * a0);
+
+    long long h_prev2 = 0;
+    long long h_prev1 = 1;
+    long long k_prev2 = 1;
+    long long k_prev1 = 0;
+    long long h = 0;
+    long long k = 0;
+
+    auto step = [&](long long ai) {
+        h = ai * h_prev1 + h_prev2;
+        k = ai * k_prev1 + k_prev2;
+        h_prev2 = h_prev1;
+        h_prev1 = h;
+        k_prev2 = k_prev1;
+        k_prev1 = k;
+    };
+
+    step(a0);
+
+    while (true) {
+        for (long long ai : period) {
+            step(ai);
+            if (h * h - n * k * k == 1) {
+                return {h, k};
+            }
+        }
