+namespace derangements {
+
+namespace {
+
+unsigned long long binomial(int n, int k) {
+    if (k < 0 || k > n) return 0;
+    if (k > n - k) k = n - k;
+    unsigned long long result = 1;
+    for (int i = 0; i < k; ++i) {
+        result = result * static_cast<unsigned long long>(n - i) /
+                 static_cast<unsigned long long>(i + 1);
+    }
+    return result;
+}
+
+unsigned long long derangement(int m) {
+    if (m == 0) return 1;
+    if (m == 1) return 0;
+    unsigned long long prev2 = 1;  // D(0)
+    unsigned long long prev1 = 0;  // D(1)
+    for (int i = 2; i <= m; ++i) {
+        unsigned long long cur =
+            static_cast<unsigned long long>(i - 1) * (prev1 + prev2);
+        prev2 = prev1;
+        prev1 = cur;
+    }
+    return prev1;
+}
+
+}
+
+unsigned long long count_permutations_with_fixed_points(int n, int k) {
+    if (n < 0 || n > 20 || k < 0 || k > 20) {
+        throw std::invalid_argument("n and k must be in [0, 20]");
+    }
+    if (k > n) return 0;
+    return binomial(n, k) * derangement(n - k);
+}
+
+}
