+int count_n_queens(int n) {
+    if (n < 0 || n > 12) {
+        return -1;
+    }
+    if (n == 0) {
+        return 1;
+    }
+
+    const int all_columns = (1 << n) - 1;
+    int count = 0;
+
+    std::function<void(int, int, int)> place_queens =
+        [&](int columns, int left_diagonals, int right_diagonals) {
+            if (columns == all_columns) {
+                ++count;
+                return;
+            }
+
+            int available = all_columns & ~(columns | left_diagonals | right_diagonals);
+            while (available != 0) {
+                int bit = available & -available;
+                available ^= bit;
+                place_queens(
+                    columns | bit,
+                    (left_diagonals | bit) << 1,
+                    (right_diagonals | bit) >> 1
+                );
+            }
+        };
