+    long long floor() const {
+        long long quotient = n_ / d_;
+        long long remainder = n_ % d_;
+
+        if (remainder < 0) {
+            --quotient;
+        }
+
+        return quotient;
+    }
+
+    long long ceil() const {
+        long long quotient = n_ / d_;
+        long long remainder = n_ % d_;
+
+        if (remainder > 0) {
+            ++quotient;
+        }
+
+        return quotient;
+    }
+
+    long long round() const {
+        long long quotient = n_ / d_;
+        long long remainder = n_ % d_;
+
+        if (remainder < 0) {
+            remainder += d_;
+            --quotient;
+        }
+
+        if (remainder == 0) {
+            return quotient;
+        }
+
+        long long complement = d_ - remainder;
+
+        if (remainder < complement) {
+            return quotient;
+        }
+
+        if (remainder > complement) {
+            return quotient + 1;
+        }
