+#include <string>
+#include <unordered_map>
+#include <utility>
+#include <vector>
+
+class PalindromeAnagram {
+    static bool isPalindrome(const std::string& s) {
+        int i = 0;
+        int j = static_cast<int>(s.size()) - 1;
+        while (i < j) {
+            if (s[i] != s[j]) {
+                return false;
+            }
+            ++i;
+            --j;
+        }
+        return true;
+    }
+
+    static std::string reversed(std::string s) {
+        std::reverse(s.begin(), s.end());
+        return s;
+    }
+
+public:
+    bool canFormPalindrome(const std::string& text) {
+        int counts[36] = {0};
+        for (char c : text) {
+            if (c >= '0' && c <= '9') {
+                counts[c - '0']++;
+            } else if (c >= 'a' && c <= 'z') {
+                counts[c - 'a' + 10]++;
+            } else if (c >= 'A' && c <= 'Z') {
+                counts[c - 'A' + 10]++;
+            }
+        }
+        int odd = 0;
+        for (int k = 0; k < 36; ++k) {
+            if (counts[k] % 2 != 0) {
+                ++odd;
+            }
+        }
+        return odd <= 1;
+    }
+
+    std::vector<std::pair<int, int>> palindromePairs(const std::vector<std::string>& words) {
+        std::unordered_map<std::string, int> lookup;
+        for (int i = 0; i < static_cast<int>(words.size()); ++i) {
+            lookup[words[i]] = i;
+        }
+
+        std::vector<std::pair<int, int>> result;
+        for (int i = 0; i < static_cast<int>(words.size()); ++i) {
+            const std::string& word = words[i];
+            const int n = static_cast<int>(word.size());
+            for (int j = 0; j <= n; ++j) {
+                const std::string left = word.substr(0, j);
+                const std::string right = word.substr(j);
+
+                if (isPalindrome(left)) {
+                    auto it = lookup.find(reversed(right));
+                    if (it != lookup.end() && it->second != i) {
+                        result.push_back({it->second, i});
+                    }
+                }
+
+                if (j != n && isPalindrome(right)) {
+                    auto it = lookup.find(reversed(left));
+                    if (it != lookup.end() && it->second != i) {
+                        result.push_back({i, it->second});
+                    }
+                }
+            }
+        }
