+class MemoizedFunction {
+public:
+    using Function = std::function<long long(long long)>;
+
+    MemoizedFunction(Function function, std::size_t capacity)
+        : function_(std::move(function)), capacity_(capacity) {}
+
+    long long operator()(long long input) {
+        auto cached = cache_.find(input);
+        if (cached != cache_.end()) {
+            ++hits_;
+            order_.splice(order_.begin(), order_, cached->second);
+            return cached->second->second;
+        }
+
+        ++misses_;
+        const long long result = function_(input);
+
+        if (capacity_ == 0) {
+            return result;
+        }
+
+        auto existing = cache_.find(input);
+        if (existing != cache_.end()) {
+            existing->second->second = result;
+            order_.splice(order_.begin(), order_, existing->second);
+            return result;
+        }
+
+        if (cache_.size() == capacity_) {
+            auto last = std::prev(order_.end());
+            cache_.erase(last->first);
+            order_.pop_back();
+        }
+
+        order_.push_front({input, result});
+        cache_.emplace(input, order_.begin());
+        return result;
+    }
+
+    std::size_t hits() const { return hits_; }
+    std::size_t misses() const { return misses_; }
+    std::size_t size() const { return cache_.size(); }
+
+    bool contains(long long input) const {
+        return cache_.find(input) != cache_.end();
+    }
+
+    void clear() {
+        order_.clear();
+        cache_.clear();
+    }
+
+private:
+    using Entry = std::pair<long long, long long>;
+
+    Function function_;
+    std::size_t capacity_;
+    std::list<Entry> order_;
+    std::unordered_map<long long, std::list<Entry>::iterator> cache_;
+    std::size_t hits_ = 0;
+    std::size_t misses_ = 0;
+};
