+#include <stdexcept>
+#include <cstdint>
+#include <sstream>
+#include <iomanip>
+
+namespace {
+constexpr std::uint64_t BASE = 1000000000ULL;
+
+void add_small(std::vector<std::uint32_t>& digits, std::uint32_t value) {
+    std::uint64_t carry = value;
+    for (std::size_t i = 0; i < digits.size() && carry > 0; ++i) {
+        std::uint64_t sum = static_cast<std::uint64_t>(digits[i]) + carry;
+        digits[i] = static_cast<std::uint32_t>(sum % BASE);
+        carry = sum / BASE;
+    }
+    while (carry > 0) {
+        digits.push_back(static_cast<std::uint32_t>(carry % BASE));
+        carry /= BASE;
+    }
+}
+
+void subtract_small(std::vector<std::uint32_t>& digits, std::uint32_t value) {
+    std::uint64_t borrow = value;
+    for (std::size_t i = 0; i < digits.size() && borrow > 0; ++i) {
+        if (digits[i] >= borrow) {
+            digits[i] = static_cast<std::uint32_t>(digits[i] - borrow);
+            borrow = 0;
+        } else {
+            digits[i] = static_cast<std::uint32_t>(BASE + digits[i] - borrow);
+            borrow = 1;
+        }
+    }
+    while (digits.size() > 1 && digits.back() == 0) {
+        digits.pop_back();
+    }
+}
+
+std::string to_decimal(const std::vector<std::uint32_t>& digits) {
+    std::ostringstream out;
+    out << digits.back();
+    for (std::size_t i = digits.size() - 1; i-- > 0; ) {
+        out << std::setw(9) << std::setfill('0') << digits[i];
+    }
+    return out.str();
+}
+} // namespace
+
+std::string derangement_count(int n) {
+    if (n < 0) {
+        throw std::invalid_argument("derangement_count requires a non-negative integer");
+    }
+    if (n == 0) {
+        return "1";
+    }
+    if (n == 1) {
+        return "0";
+    }
+
+    std::vector<std::uint32_t> digits{0}; // D(1)
+
+    for (int i = 2; i <= n; ++i) {
+        std::uint64_t carry = 0;
+        for (std::uint32_t& chunk : digits) {
+            std::uint64_t product =
+                static_cast<std::uint64_t>(chunk) * static_cast<std::uint64_t>(i) + carry;
+            chunk = static_cast<std::uint32_t>(product % BASE);
+            carry = product / BASE;
+        }
+        while (carry > 0) {
+            digits.push_back(static_cast<std::uint32_t>(carry % BASE));
+            carry /= BASE;
+        }
+
+        if (i % 2 == 0) {
+            add_small(digits, 1);
+        } else {
+            subtract_small(digits, 1);
+        }
+    }
+
+    return to_decimal(digits);
+}
