+#include <algorithm>
+#include <map>
+#include <queue>
+#include <set>
+#include <vector>
+
+class Graph {
+public:
+    void add_edge(int u, int v) {
+        adj_[u].insert(v);
+        adj_[v].insert(u);
+    }
+
+    bool has_edge(int u, int v) const {
+        auto it = adj_.find(u);
+        if (it == adj_.end()) {
+            return false;
+        }
+        return it->second.count(v) > 0;
+    }
+
+    std::vector<int> neighbors(int node) const {
+        auto it = adj_.find(node);
+        if (it == adj_.end()) {
+            return {};
+        }
+        return std::vector<int>(it->second.begin(), it->second.end());
+    }
+
+    std::vector<int> shortest_path(int from, int to) const {
+        if (adj_.find(from) == adj_.end() || adj_.find(to) == adj_.end()) {
+            return {};
+        }
+        if (from == to) {
+            return {from};
+        }
+
+        std::map<int, int> parent;
+        std::queue<int> frontier;
+        parent[from] = from;
+        frontier.push(from);
+
+        while (!frontier.empty()) {
+            int current = frontier.front();
+            frontier.pop();
+
+            for (int next : adj_.at(current)) {
+                if (parent.count(next) > 0) {
+                    continue;
+                }
+                parent[next] = current;
+                if (next == to) {
+                    std::vector<int> path;
+                    int walk = to;
+                    while (walk != from) {
+                        path.push_back(walk);
+                        walk = parent.at(walk);
+                    }
+                    path.push_back(from);
+                    std::reverse(path.begin(), path.end());
+                    return path;
+                }
+                frontier.push(next);
+            }
+        }
+
+        return {};
+    }
+
+    int connected_components() const {
+        std::set<int> visited;
+        int components = 0;
+
+        for (const auto& entry : adj_) {
+            if (visited.count(entry.first) > 0) {
+                continue;
+            }
+            ++components;
+            std::queue<int> frontier;
+            frontier.push(entry.first);
+            visited.insert(entry.first);
+
+            while (!frontier.empty()) {
+                int current = frontier.front();
+                frontier.pop();
+                for (int next : adj_.at(current)) {
+                    if (visited.count(next) == 0) {
+                        visited.insert(next);
+                        frontier.push(next);
+                    }
+                }
+            }
+        }
+
+        return components;
+    }
+
+    int node_count() const {
+        return static_cast<int>(adj_.size());
+    }
+
+private:
+    std::map<int, std::set<int>> adj_;
+};
