+class ShoppingCart {
+public:
+    void add_item(const std::string& name, int unit_price_cents, int quantity) {
+        if (name.empty()) {
+            throw std::invalid_argument("item name must not be empty");
+        }
+        if (unit_price_cents < 0) {
+            throw std::invalid_argument("unit price must not be negative");
+        }
+        if (quantity <= 0) {
+            throw std::invalid_argument("quantity must be positive");
+        }
+
