+        if (it == items_.end()) {
+            items_.insert({name, Item{unit_price_cents, quantity}});
+        } else {
+            it->second.price = unit_price_cents;
+            it->second.quantity += quantity;
+        }
+    }
+
+    bool remove_item(const std::string& name, int quantity) {
+        if (quantity <= 0) {
+            throw std::invalid_argument("quantity must be positive");
+        }
+
+        auto it = items_.find(name);
+        if (it == items_.end()) {
+            return false;
+        }
+        if (it->second.quantity < quantity) {
+            return false;
+        }
+        if (it->second.quantity == quantity) {
+            items_.erase(it);
+        } else {
+            it->second.quantity -= quantity;
+        }
+        return true;
+    }
+
