+#include <vector>
+#include <string>
+#include <stdexcept>
+#include <cctype>
+#include <climits>
+
+namespace {
+std::string trim(const std::string& text) {
+    std::size_t begin = 0;
+    while (begin < text.size() &&
+           std::isspace(static_cast<unsigned char>(text[begin]))) {
+        ++begin;
+    }
+
+    std::size_t end = text.size();
+    while (end > begin &&
+           std::isspace(static_cast<unsigned char>(text[end - 1]))) {
+        --end;
+    }
+
+    return text.substr(begin, end - begin);
+}
+}
+
+std::vector<int> parse_scores(const std::string& input) {
+    std::vector<int> scores;
+    std::size_t start = 0;
+
+    while (start <= input.size()) {
+        const std::size_t comma = input.find(',', start);
+        const std::size_t length =
+            comma == std::string::npos ? std::string::npos : comma - start;
+        const std::string segment = trim(input.substr(start, length));
+
+        if (!segment.empty()) {
+            std::size_t index = 0;
+            bool negative = false;
+
+            if (segment[index] == '+' || segment[index] == '-') {
+                negative = segment[index] == '-';
+                ++index;
+            }
+
+            if (index == segment.size()) {
+                throw std::invalid_argument("invalid score");
+            }
+
+            int value = 0;
+            for (; index < segment.size(); ++index) {
+                const char ch = segment[index];
+                if (!std::isdigit(static_cast<unsigned char>(ch))) {
+                    throw std::invalid_argument("invalid score");
+                }
+
+                const int digit = ch - '0';
+                if (negative) {
+                    if (value < (INT_MIN + digit) / 10) {
+                        throw std::out_of_range("score out of range");
+                    }
+                    value = value * 10 - digit;
+                } else {
+                    if (value > (INT_MAX - digit) / 10) {
+                        throw std::out_of_range("score out of range");
+                    }
+                    value = value * 10 + digit;
+                }
+            }
+
+            scores.push_back(value);
+        }
+
+        if (comma == std::string::npos) {
+            break;
+        }
+        start = comma + 1;
+    }
+
+    return scores;
+}
