+    long long result = 0;
+    if (n == 0) {
+        result = 0;
+    } else if (n == 1) {
+        result = 1;
+    } else {
+        result = fibonacci(n - 1) + fibonacci(n - 2);
+    }
+
+    cache_[n] = result;
+    return result;
+}
