+        auto it = position_.find(key);
+        if (it == position_.end()) {
+            throw std::out_of_range("unknown key");
+        }
+        std::size_t index = it->second;
+        int old_priority = heap_[index].priority;
+        heap_[index].priority = new_priority;
+        if (new_priority < old_priority) {
+            sift_up(index);
+        } else {
+            sift_down(index);
+        }
+    }
