+    void sift_up(std::size_t index) {
+        while (index > 0) {
+            std::size_t parent = (index - 1) / 2;
+            if (less_than(heap_[index], heap_[parent])) {
+                swap_positions(index, parent);
+                index = parent;
+            } else {
+                break;
+            }
+        }
+    }
+
+    void sift_down(std::size_t index) {
+        std::size_t count = heap_.size();
+        while (true) {
+            std::size_t left = 2 * index + 1;
+            std::size_t right = 2 * index + 2;
+            std::size_t smallest = index;
+            if (left < count && less_than(heap_[left], heap_[smallest])) {
+                smallest = left;
+            }
+            if (right < count && less_than(heap_[right], heap_[smallest])) {
+                smallest = right;
+            }
+            if (smallest == index) {
+                break;
+            }
+            swap_positions(index, smallest);
+            index = smallest;
+        }
+    }
