+GameState analyze(const std::string& board) {
+    if (board.size() != 9) {
+        return GameState::invalid;
+    }
+
+    int countX = 0;
+    int countO = 0;
+    for (char cell : board) {
+        if (cell == 'X') {
+            ++countX;
+        } else if (cell == 'O') {
+            ++countO;
+        } else if (cell != '.') {
+            return GameState::invalid;
+        }
