+        {0, 3, 6}, {1, 4, 7}, {2, 5, 8},
+        {0, 4, 8}, {2, 4, 6}
+    };
+
+    bool xWins = false;
+    bool oWins = false;
+    for (const auto& line : lines) {
+        if (board[line[0]] == board[line[1]] &&
+            board[line[1]] == board[line[2]]) {
+            if (board[line[0]] == 'X') {
+                xWins = true;
+            } else if (board[line[0]] == 'O') {
+                oWins = true;
+            }
+        }
+    }
+
+    if (xWins && oWins) {
+        return GameState::invalid;
+    }
+    if (xWins) {
+        return (countX == countO + 1) ? GameState::x_wins
+                                      : GameState::invalid;
+    }
+    if (oWins) {
+        return (countX == countO) ? GameState::o_wins
+                                  : GameState::invalid;
+    }
