+namespace {
+
+bool valid_grid(const std::vector<std::string>& grid) {
+    if (grid.empty()) {
+        return false;
+    }
+
+    const std::size_t width = grid[0].size();
+    for (const auto& row : grid) {
+        if (row.size() != width) {
+            return false;
+        }
+    }
+
+    return true;
+}
+
+bool in_bounds(const std::vector<std::string>& grid, Point p) {
+    return p.row >= 0 &&
+           p.row < static_cast<int>(grid.size()) &&
+           p.col >= 0 &&
+           p.col < static_cast<int>(grid[p.row].size());
+}
+
+int terrain_cost(const std::vector<std::string>& grid, Point p) {
+    if (!in_bounds(grid, p)) {
+        return -1;
+    }
+
+    const char cell = grid[p.row][p.col];
+    if (cell == '.') {
+        return 1;
+    }
+    if (cell >= '1' && cell <= '9') {
+        return cell - '0';
+    }
+
+    return -1;
+}
+
+bool path_less(const std::vector<Point>& a, const std::vector<Point>& b) {
+    return std::lexicographical_compare(
+        a.begin(), a.end(), b.begin(), b.end(),
+        [](const Point& x, const Point& y) {
+            if (x.row != y.row) {
+                return x.row < y.row;
+            }
+            return x.col < y.col;
+        });
+}
+
+struct State {
+    int cost;
+    std::vector<Point> path;
+    Point at;
+};
+
+struct CompareState {
+    bool operator()(const State& a, const State& b) const {
+        if (a.cost != b.cost) {
+            return a.cost > b.cost;
+        }
+        return path_less(b.path, a.path);
