+    const int rows = static_cast<int>(grid.size());
+    const int cols = static_cast<int>(grid[0].size());
+    const int inf = std::numeric_limits<int>::max();
+
+    std::vector<std::vector<int>> best_cost(rows, std::vector<int>(cols, inf));
+    std::vector<std::vector<std::vector<Point>>> best_path(
+        rows, std::vector<std::vector<Point>>(cols));
+
+    std::priority_queue<State, std::vector<State>, CompareState> queue;
+
+    best_cost[start.row][start.col] = start_cost;
+    best_path[start.row][start.col] = {start};
+    queue.push(State{start_cost, {start}, start});
+
+    const int dr[4] = {-1, 1, 0, 0};
+    const int dc[4] = {0, 0, -1, 1};
