+            std::vector<Point> next_path = current.path;
+            next_path.push_back(next);
+
+            const bool better_cost = next_cost < best_cost[next.row][next.col];
+            const bool same_cost_better_path =
+                next_cost == best_cost[next.row][next.col] &&
+                (best_path[next.row][next.col].empty() ||
