+std::vector<long long> modular_square_roots(long long n, long long p) {
+    if (p == 2) {
+        long long residue = ((n % 2) + 2) % 2;
+        return {residue};
+    }
+
+    long long a = ((n % p) + p) % p;
+    if (a == 0) {
+        return {0};
+    }
+
+    auto mod_pow = [p](long long base, long long exponent) {
+        long long result = 1;
+        base %= p;
+        while (exponent > 0) {
+            if (exponent & 1LL) {
+                result = (result * base) % p;
+            }
+            base = (base * base) % p;
+            exponent >>= 1;
+        }
+        return result;
+    };
