+        return {};
+    }
+
+    if (p % 4 == 3) {
+        long long r = mod_pow(a, (p + 1) / 4);
+        long long s = p - r;
+        if (r > s) {
+            std::swap(r, s);
+        }
+        return {r, s};
+    }
+
+    long long q = p - 1;
+    int s = 0;
+    while (q % 2 == 0) {
+        q /= 2;
+        ++s;
+    }
+
+    long long z = 2;
+    while (mod_pow(z, (p - 1) / 2) != p - 1) {
+        ++z;
+    }
+
+    long long m = s;
+    long long c = mod_pow(z, q);
+    long long t = mod_pow(a, q);
+    long long r = mod_pow(a, (q + 1) / 2);
+
+    while (t != 1) {
+        long long i = 1;
+        long long t2 = (t * t) % p;
+        while (t2 != 1) {
+            t2 = (t2 * t2) % p;
+            ++i;
+        }
+
+        long long exponent = 1LL << (m - i - 1);
+        long long b = mod_pow(c, exponent);
+        r = (r * b) % p;
+        c = (b * b) % p;
+        t = (t * c) % p;
+        m = i;
+    }
+
+    long long other = p - r;
+    if (r > other) {
+        std::swap(r, other);
+    }
