+namespace {
+
+std::tuple<long long, long long, long long> extended_gcd(long long a, long long b) {
+    if (b == 0) {
+        return std::make_tuple(a, 1LL, 0LL);
+    }
+
+    auto next = extended_gcd(b, a % b);
+    long long g = std::get<0>(next);
+    long long x1 = std::get<1>(next);
+    long long y1 = std::get<2>(next);
+
+    return std::make_tuple(g, y1, x1 - (a / b) * y1);
+}
+
+}  // namespace
+
+std::optional<std::pair<long long, long long>> chinese_remainder(
+    const std::vector<std::pair<long long, long long>>& congruences) {
+    long long x = 0;
+    long long mod = 1;
+
+    for (const auto& congruence : congruences) {
+        long long r = congruence.first;
+        long long m = congruence.second;
+
+        if (m <= 0) {
+            throw std::invalid_argument("modulus must be positive");
+        }
+
+        r %= m;
+        if (r < 0) {
+            r += m;
+        }
+
+        long long diff = r - x;
+        auto eg = extended_gcd(mod, m);
+        long long g = std::get<0>(eg);
+        long long u = std::get<1>(eg);
+
+        if (diff % g != 0) {
+            return std::nullopt;
+        }
+
+        long long reduced_mod = m / g;
+        long long k = ((diff / g) * u) % reduced_mod;
+        if (k < 0) {
+            k += reduced_mod;
+        }
+
+        long long old_mod = mod;
+        x = x + old_mod * k;
+        mod = old_mod / g * m;
+        x %= mod;
+        if (x < 0) {
+            x += mod;
+        }
+    }
+
+    return std::make_pair(x, mod);
+}
