+std::vector<Robot::Command> Robot::parse_program(const std::string& text) {
+    std::vector<Command> program;
+    std::size_t index = 0;
+
+    parse_program_impl(text, index, false, program);
+
+    skip_whitespace(text, index);
+
+    if (index < text.size()) {
+        throw std::invalid_argument("unexpected closing bracket");
+    }
