+#include <cstddef>
+#include <stdexcept>
+#include <vector>
+
+class RingBuffer {
+public:
+    explicit RingBuffer(std::size_t capacity) : capacity_(capacity), read_index_(0), write_index_(0), size_(0) {
+        if (capacity == 0) {
+            throw std::invalid_argument("Capacity must be greater than 0");
+        }
+        buffer_.resize(capacity);
+    }
+
+    void write(int value) {
+        if (full()) {
+            throw std::runtime_error("Buffer is full");
+        }
+        buffer_[write_index_] = value;
+        write_index_ = (write_index_ + 1) % capacity_;
+        ++size_;
+    }
+
+    int read() {
+        if (empty()) {
+            throw std::runtime_error("Buffer is empty");
+        }
+        int value = buffer_[read_index_];
+        read_index_ = (read_index_ + 1) % capacity_;
+        --size_;
+        return value;
+    }
+
+    void overwrite(int value) {
+        if (full()) {
+            read(); // discard oldest
+        }
+        write(value);
+    }
+
+    void clear() {
+        read_index_ = 0;
+        write_index_ = 0;
+        size_ = 0;
+    }
+
+    bool empty() const {
+        return size_ == 0;
+    }
+
+    bool full() const {
+        return size_ == capacity_;
+    }
+
+private:
+    std::size_t capacity_;
+    std::vector<int> buffer_;
+    std::size_t read_index_;
+    std::size_t write_index_;
+    std::size_t size_;
+};
