+#include <algorithm>
+#include <functional>
+
+struct Interval {
+    int start;
+    int end;
+    std::vector<int> allowed_resources;
+};
+
+std::vector<int> schedule_intervals(int num_resources, const std::vector<Interval>& intervals) {
+    if (intervals.empty()) return {};
+    if (num_resources <= 0) return {};
+
+    int n = intervals.size();
+    struct Item {
+        int start, end;
+        std::vector<int> allowed;
+        int index;
+    };
+    std::vector<Item> items;
+    for (int i = 0; i < n; ++i) {
+        items.push_back({intervals[i].start, intervals[i].end, intervals[i].allowed_resources, i});
+    }
+    std::sort(items.begin(), items.end(), [](const Item& a, const Item& b) {
+        if (a.start != b.start) return a.start < b.start;
+        return a.end < b.end;
+    });
+
+    std::vector<int> last_end(num_resources, -1);
+    std::vector<int> assignment(n, -1);
+    std::vector<int> result;
+
+    std::function<bool(int)> backtrack = [&](int pos) -> bool {
+        if (pos == n) {
+            result.resize(n);
+            for (int i = 0; i < n; ++i) {
+                result[items[i].index] = assignment[i];
+            }
+            return true;
+        }
+        const auto& item = items[pos];
+        for (int res : item.allowed) {
+            if (res < 0 || res >= num_resources) continue;
+            if (last_end[res] <= item.start) {
+                int old_end = last_end[res];
+                last_end[res] = item.end;
+                assignment[pos] = res;
+                if (backtrack(pos + 1)) return true;
+                last_end[res] = old_end;
+                assignment[pos] = -1;
+            }
+        }
+        return false;
+    };
+
+    if (backtrack(0)) {
+        return result;
+    }
+    return {};
+}
