+    size_t first = 0;
+    while (first + 1 < digits.size() && digits[first] == 0) {
+        ++first;
+    }
+    digits.erase(digits.begin(), digits.begin() + first);
+
+    std::string result;
+    std::vector<int> current = digits;
+    while (!current.empty()) {
+        int remainder = 0;
+        std::vector<int> quotient;
+        for (int d : current) {
+            int value = remainder * from_base + d;
+            int q = value / to_base;
+            remainder = value % to_base;
+            if (!quotient.empty() || q != 0) {
