+struct UnitInfo {
+    Dimension dim;
+    double scale;
+};
+
+static const std::map<std::string, UnitInfo> units = {
+    {"m", {{1,0,0}, 1.0}},
+    {"km", {{1,0,0}, 1000.0}},
+    {"cm", {{1,0,0}, 0.01}},
