+std::pair<Dimension, double> parse_unit(const std::string& expr) {
+    Dimension dim = {0,0,0};
+    double scale = 1.0;
+    if (expr.empty()) {
+        throw std::invalid_argument("Empty unit expression");
+    }
+
+    size_t i = 0;
+    bool first = true;
+    char op = '*';
+    while (i < expr.size()) {
+        if (!first) {
+            if (expr[i] != '*' && expr[i] != '/') {
+                throw std::invalid_argument("Expected '*' or '/'");
+            }
+            op = expr[i];
+            ++i;
+            if (i >= expr.size()) {
+                throw std::invalid_argument("Trailing operator");
+            }
+        }
+        first = false;
+
+        size_t j = i;
+        while (j < expr.size() && expr[j] != '*' && expr[j] != '/') {
+            ++j;
+        }
+        std::string term = expr.substr(i, j - i);
+        if (term.empty()) {
+            throw std::invalid_argument("Empty term");
+        }
+
+        std::string unit_str;
+        int exponent = 1;
+        size_t hat = term.find('^');
+        if (hat != std::string::npos) {
+            unit_str = term.substr(0, hat);
+            std::string exp_str = term.substr(hat + 1);
+            if (exp_str.empty()) {
+                throw std::invalid_argument("Missing exponent");
+            }
+            size_t k = 0;
+            if (exp_str[k] == '-') {
+                ++k;
+            }
+            if (k >= exp_str.size()) {
+                throw std::invalid_argument("Invalid exponent");
+            }
+            for (; k < exp_str.size(); ++k) {
+                if (!std::isdigit(static_cast<unsigned char>(exp_str[k]))) {
+                    throw std::invalid_argument("Invalid exponent");
+                }
+            }
+            exponent = std::stoi(exp_str);
+        } else {
+            unit_str = term;
+        }
+
+        if (unit_str.empty()) {
+            throw std::invalid_argument("Missing unit");
+        }
+
+        auto it = units.find(unit_str);
+        if (it == units.end()) {
+            throw std::invalid_argument("Unknown unit: " + unit_str);
+        }
+
+        if (op == '/') {
+            exponent = -exponent;
+        }
+
+        dim[0] += it->second.dim[0] * exponent;
+        dim[1] += it->second.dim[1] * exponent;
+        dim[2] += it->second.dim[2] * exponent;
+        scale *= std::pow(it->second.scale, exponent);
+
+        i = j;
+    }
+
+    return {dim, scale};
+}
+
+double convert(double value, const std::string& from, const std::string& to) {
+    auto [dim_from, scale_from] = parse_unit(from);
+    auto [dim_to, scale_to] = parse_unit(to);
+    if (dim_from != dim_to) {
+        throw std::invalid_argument("Incompatible units");
+    }
+    return value * (scale_from / scale_to);
+}
