+// MinCoins returns the minimum number of coins needed to make amount.
+// It returns -1 if the amount cannot be made.
+func MinCoins(coins []int, amount int) int {
+	if amount < 0 {
+		return -1
+	}
+	if amount == 0 {
+		return 0
+	}
+
+	unreachable := amount + 1
+	dp := make([]int, amount+1)
+	for i := 1; i <= amount; i++ {
+		dp[i] = unreachable
+	}
+
+	for i := 1; i <= amount; i++ {
+		for _, coin := range coins {
+			if coin <= 0 || coin > i {
+				continue
+			}
+			if dp[i-coin] == unreachable {
+				continue
+			}
+			if candidate := dp[i-coin] + 1; candidate < dp[i] {
+				dp[i] = candidate
+			}
+		}
+	}
+
+	if dp[amount] == unreachable {
+		return -1
+	}
+	return dp[amount]
+}
