+	sum = func(items []any, depth int) int {
+		total := 0
+		for _, item := range items {
+			switch v := item.(type) {
+			case int:
+				total += v * depth
+			case []any:
+				total += sum(v, depth+1)
+			}
+		}
+		return total
+	}
+	return sum(list, 1)
+}
+
