+	max := 0
+
+	var walk func([]any, int)
+	walk = func(items []any, depth int) {
+		for _, item := range items {
+			switch v := item.(type) {
+			case int:
+				if depth > max {
+					max = depth
+				}
+			case []any:
+				walk(v, depth+1)
+			}
+		}
+	}
+
