+			}
+			esc := p.input[p.pos]
+			switch esc {
+			case '\\':
+				b.WriteByte('\\')
+			case '"':
+				b.WriteByte('"')
+			case '\'':
+				b.WriteByte('\'')
+			case 'n':
+				b.WriteByte('\n')
+			case 't':
+				b.WriteByte('\t')
+			case 'r':
+				b.WriteByte('\r')
+			default:
+				return "", fmt.Errorf("invalid escape sequence \\%c", esc)
+			}
+			p.pos++
+			continue
+		}
+		b.WriteByte(c)
+		p.pos++
+	}
+	return "", fmt.Errorf("unterminated quoted string")
+}
+
+func (p *parser) parseBare() (string, error) {
+	start := p.pos
+	for p.pos < len(p.input) {
+		c := p.input[p.pos]
+		if isSpaceByte(c) || isBareDelim(c) {
+			break
+		}
+		p.pos++
+	}
+	if p.pos == start {
+		return "", fmt.Errorf("expected value at position %d", p.pos)
+	}
+	return p.input[start:p.pos], nil
+}
+
+func (p *parser) matchKeyword(kw string) bool {
+	p.skipSpace()
+	if p.pos+len(kw) > len(p.input) {
+		return false
+	}
+	for i := 0; i < len(kw); i++ {
+		a := p.input[p.pos+i]
+		b := kw[i]
+		if a >= 'a' && a <= 'z' {
+			a -= 'a' - 'A'
+		}
+		if b >= 'a' && b <= 'z' {
+			b -= 'a' - 'A'
+		}
+		if a != b {
+			return false
+		}
+	}
+	end := p.pos + len(kw)
+	if end < len(p.input) && isIdentPart(p.input[end]) {
+		return false
+	}
+	p.pos = end
+	return true
+}
+
+func isIdentStart(c byte) bool {
+	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_'
+}
+
+func isIdentPart(c byte) bool {
+	return isIdentStart(c) || (c >= '0' && c <= '9') || c == '.'
+}
+
+func isBareDelim(c byte) bool {
+	switch c {
+	case '(', ')', '=', '!', '~', '<', '>', '"', '\'', '\\':
+		return true
+	}
+	return false
+}
+
+func isSpaceByte(c byte) bool {
+	return c == ' ' || c == '\t' || c == '\n' || c == '\r'
+}
