+package combinatorics
+
+import (
+	"errors"
+	"math/big"
+)
+
+func StirlingSecondKind(n, k int) (*big.Int, error) {
+	if n < 0 || k < 0 {
+		return nil, errors.New("n and k must be non-negative")
+	}
+	if k > n {
+		return big.NewInt(0), nil
+	}
+	if n == 0 {
+		return big.NewInt(1), nil
+	}
+
+	dp := make([]*big.Int, k+1)
+	for i := range dp {
+		dp[i] = new(big.Int)
+	}
+	dp[0].SetInt64(1)
+
+	for i := 1; i <= n; i++ {
+		upper := i
+		if upper > k {
+			upper = k
+		}
+		for j := upper; j >= 1; j-- {
+			term := new(big.Int).Mul(big.NewInt(int64(j)), dp[j])
+			term.Add(term, dp[j-1])
+			dp[j] = term
+		}
+		dp[0].SetInt64(0)
+	}
+
+	return new(big.Int).Set(dp[k]), nil
+}
+
+func Bell(n int) (*big.Int, error) {
+	if n < 0 {
+		return nil, errors.New("n must be non-negative")
+	}
+	if n == 0 {
+		return big.NewInt(1), nil
+	}
+
+	dp := make([]*big.Int, n+1)
+	for i := range dp {
+		dp[i] = new(big.Int)
+	}
+	dp[0].SetInt64(1)
+
+	for i := 1; i <= n; i++ {
+		for j := i; j >= 1; j-- {
+			term := new(big.Int).Mul(big.NewInt(int64(j)), dp[j])
+			term.Add(term, dp[j-1])
+			dp[j] = term
+		}
+		dp[0].SetInt64(0)
+	}
+
+	sum := new(big.Int)
+	for _, v := range dp {
+		sum.Add(sum, v)
+	}
+	return sum, nil
