+	if rb.count == len(rb.data) {
+		rb.data[rb.head] = value
+		rb.head = (rb.head + 1) % len(rb.data)
+		return
+	}
+	index := (rb.head + rb.count) % len(rb.data)
+	rb.data[index] = value
+	rb.count++
+}
+
+func (rb *RingBuffer) Clear() {
+	rb.head = 0
+	rb.count = 0
