+// Median returns the median of the combined sorted values from a and b.
+func Median(a, b []int) float64 {
+	if len(a) > len(b) {
+		a, b = b, a
+	}
+
+	m, n := len(a), len(b)
+	totalLeft := (m + n + 1) / 2
+	lo, hi := 0, m
