+		{-1, 0},
+		{0, 1},
+		{0, -1},
+	}
+
+	queue := []point{{0, 0}}
+	dist[0][0] = 0
+
+	for len(queue) > 0 {
+		current := queue[0]
+		queue = queue[1:]
+
+		for _, direction := range directions {
+			nextRow := current.row + direction[0]
+			nextCol := current.col + direction[1]
+
