+import (
+	"errors"
+)
+
+var letterValues = map[rune]int{
+	'A': 10, 'B': 12, 'C': 13, 'D': 14, 'E': 15, 'F': 16, 'G': 17,
+	'H': 18, 'I': 19, 'J': 20, 'K': 21, 'L': 23, 'M': 24, 'N': 25,
+	'O': 26, 'P': 27, 'Q': 28, 'R': 29, 'S': 30, 'T': 31, 'U': 32,
+	'V': 34, 'W': 35, 'X': 36, 'Y': 37, 'Z': 38,
+}
+
+// CheckDigit returns the ISO 6346 check digit for a 10-character identification string.
+func CheckDigit(code string) (int, error) {
+	if len(code) != 10 {
+		return 0, errors.New("identification string must be exactly 10 characters")
+	}
+	sum := 0
+	for i := 0; i < 10; i++ {
+		c := code[i]
+		var value int
+		if c >= '0' && c <= '9' {
+			value = int(c - '0')
+		} else if c >= 'A' && c <= 'Z' {
+			value = letterValues[rune(c)]
+		} else if c >= 'a' && c <= 'z' {
+			value = letterValues[rune(c-'a'+'A')]
+		} else {
+			return 0, errors.New("invalid character in identification string")
+		}
+		sum += value * (1 << i)
+	}
+	digit := sum % 11
+	if digit == 10 {
+		digit = 0
+	}
+	return digit, nil
+}
+
+// Validate reports whether code is a valid 11-character ISO 6346 container code.
+func Validate(code string) bool {
+	if len(code) != 11 {
+		return false
+	}
+	prefix := code[:10]
+	check := code[10]
+	if check < '0' || check > '9' {
+		return false
+	}
+	digit, err := CheckDigit(prefix)
+	if err != nil {
+		return false
+	}
+	return int(check-'0') == digit
+}
