+package kthsmallestpairdistance
+
+import "sort"
+
+// SmallestDistancePair returns the k-th smallest absolute difference among all
+// unordered pairs of nums. It returns -1 for invalid input.
+func SmallestDistancePair(nums []int, k int) int {
+	n := len(nums)
+	if n < 2 {
+		return -1
+	}
+
+	totalPairs := n * (n - 1) / 2
+	if k < 1 || k > totalPairs {
+		return -1
+	}
+
+	sorted := append([]int(nil), nums...)
+	sort.Ints(sorted)
+
+	countAtMost := func(limit int) int {
+		count := 0
+		left := 0
+		for right := 1; right < len(sorted); right++ {
+			for sorted[right]-sorted[left] > limit {
+				left++
+			}
+			count += right - left
+		}
+		return count
+	}
+
+	lo, hi := 0, sorted[n-1]-sorted[0]
+	for lo < hi {
+		mid := lo + (hi-lo)/2
+		if countAtMost(mid) >= k {
+			hi = mid
+		} else {
+			lo = mid + 1
+		}
+	}
+
+	return lo
+}
