+
+var ErrConflict = errors.New("conflicting records")
+
+type recordState struct {
+	version  int
+	payload  string
+	conflict bool
+}
+
+func MergeRecords(batches ...[]Record) ([]Record, error) {
+	states := make(map[string]recordState)
+
+	for _, batch := range batches {
+		for _, rec := range batch {
+			st, ok := states[rec.ID]
+			if !ok || rec.Version > st.version {
+				states[rec.ID] = recordState{
+					version: rec.Version,
+					payload: rec.Payload,
+				}
+				continue
+			}
+
+			if rec.Version == st.version && rec.Payload != st.payload {
+				st.conflict = true
+				states[rec.ID] = st
+			}
+		}
+	}
+
+	result := make([]Record, 0, len(states))
+	for id, st := range states {
+		if st.conflict {
+			return nil, ErrConflict
+		}
+		result = append(result, Record{
+			ID:      id,
+			Version: st.version,
+			Payload: st.payload,
+		})
+	}
+
+	sort.Slice(result, func(i, j int) bool {
+		return result[i].ID < result[j].ID
+	})
+
+	return result, nil
