+func Evaluate(expr string) (bool, error) {
+	p := &parser{input: expr}
+	p.skipSpace()
+	if p.eof() {
+		return false, errors.New("empty expression")
+	}
+
+	value, err := p.parseOr()
+	if err != nil {
+		return false, err
+	}
+
+	p.skipSpace()
+	if !p.eof() {
+		return false, errors.New("unexpected trailing input")
+	}
