+type parser struct {
+	input string
+	pos   int
+}
+
+func (p *parser) eof() bool {
+	return p.pos >= len(p.input)
+}
+
+func (p *parser) skipSpace() {
+	for !p.eof() && unicode.IsSpace(rune(p.input[p.pos])) {
+		p.pos++
+	}
+}
+
+func (p *parser) consume(token string) bool {
+	if strings.HasPrefix(p.input[p.pos:], token) {
+		p.pos += len(token)
+		return true
+	}
+	return false
+}
+
+func (p *parser) parseOr() (bool, error) {
+	left, err := p.parseAnd()
+	if err != nil {
+		return false, err
+	}
+
+	for {
+		p.skipSpace()
+		if !p.consume("||") {
+			break
+		}
+
+		right, err := p.parseAnd()
+		if err != nil {
+			return false, err
+		}
+		left = left || right
+	}
+
+	return left, nil
+}
+
+func (p *parser) parseAnd() (bool, error) {
+	left, err := p.parseNot()
+	if err != nil {
+		return false, err
+	}
+
+	for {
+		p.skipSpace()
+		if !p.consume("&&") {
+			break
+		}
+
+		right, err := p.parseNot()
+		if err != nil {
+			return false, err
+		}
+		left = left && right
+	}
+
+	return left, nil
+}
+
+func (p *parser) parseNot() (bool, error) {
+	p.skipSpace()
+	if p.consume("!") {
+		value, err := p.parseNot()
+		if err != nil {
+			return false, err
+		}
+		return !value, nil
+	}
+
+	return p.parsePrimary()
+}
+
+func (p *parser) parsePrimary() (bool, error) {
+	p.skipSpace()
+
+	if p.consume("(") {
+		value, err := p.parseOr()
+		if err != nil {
+			return false, err
+		}
+
+		p.skipSpace()
+		if !p.consume(")") {
+			return false, errors.New("missing closing parenthesis")
+		}
+		return value, nil
+	}
+
+	if p.matchKeyword("true") {
+		return true, nil
+	}
+	if p.matchKeyword("false") {
+		return false, nil
+	}
+
+	return false, errors.New("expected expression")
+}
+
+func (p *parser) matchKeyword(keyword string) bool {
+	if !strings.HasPrefix(p.input[p.pos:], keyword) {
+		return false
+	}
+
+	end := p.pos + len(keyword)
+	if end < len(p.input) && isWordByte(rune(p.input[end])) {
+		return false
+	}
+
+	p.pos = end
+	return true
+}
+
+func isWordByte(r rune) bool {
+	return r == '_' || unicode.IsLetter(r) || unicode.IsDigit(r)
