+// PrimesUpTo returns all prime numbers less than or equal to n in ascending order.
+func PrimesUpTo(n int) []int {
+	if n < 2 {
+		return []int{}
+	}
+
+	isComposite := make([]bool, n+1)
+	primes := make([]int, 0)
+
+	for candidate := 2; candidate <= n; candidate++ {
+		if isComposite[candidate] {
+			continue
