+package stringcompression
+
+import (
+	"errors"
+	"strconv"
+	"strings"
+	"unicode/utf8"
+)
+
+func Compress(s string) string {
+	if s == "" {
+		return ""
+	}
+
+	var b strings.Builder
+	runes := []rune(s)
+	i := 0
+	for i < len(runes) {
+		r := runes[i]
+		j := i + 1
+		for j < len(runes) && runes[j] == r {
+			j++
+		}
+		count := j - i
+
+		if r == '\\' || (r >= '0' && r <= '9') {
+			b.WriteByte('\\')
+		}
+		b.WriteRune(r)
+		b.WriteString(strconv.Itoa(count))
+
+		i = j
+	}
+	return b.String()
+}
+
+func Decompress(s string) (string, error) {
+	var b strings.Builder
+	i := 0
+	for i < len(s) {
+		var r rune
+		if s[i] == '\\' {
+			i++
+			if i >= len(s) {
+				return "", errors.New("trailing backslash")
+			}
+			c := s[i]
+			if c != '\\' && (c < '0' || c > '9') {
+				return "", errors.New("invalid escape")
+			}
+			r = rune(c)
+			i++
+		} else {
+			if s[i] >= '0' && s[i] <= '9' {
+				return "", errors.New("unescaped digit")
+			}
+			var size int
+			r, size = utf8.DecodeRuneInString(s[i:])
+			i += size
+		}
+
+		start := i
+		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
+			i++
+		}
+		if start == i {
+			return "", errors.New("missing count")
+		}
+		if s[start] == '0' {
+			return "", errors.New("zero or leading zero count")
+		}
+		count, err := strconv.Atoi(s[start:i])
+		if err != nil {
+			return "", err
+		}
+		for k := 0; k < count; k++ {
+			b.WriteRune(r)
+		}
+	}
+	return b.String(), nil
+}
