+package listops
+
+func Deduplicate(items []int) []int {
+	if items == nil {
+		return nil
+	}
+	seen := make(map[int]bool, len(items))
+	result := make([]int, 0, len(items))
+	for _, value := range items {
+		if !seen[value] {
+			seen[value] = true
+			result = append(result, value)
+		}
+	}
+	return result
+}
+
+func Chunk(items []int, size int) [][]int {
+	if size <= 0 || len(items) == 0 {
+		return nil
+	}
+	chunkCount := (len(items) + size - 1) / size
+	chunks := make([][]int, 0, chunkCount)
+	for start := 0; start < len(items); start += size {
+		end := start + size
+		if end > len(items) {
+			end = len(items)
+		}
+		chunk := make([]int, end-start)
+		copy(chunk, items[start:end])
+		chunks = append(chunks, chunk)
+	}
+	return chunks
+}
+
+func RotateLeft(items []int, n int) []int {
+	if items == nil {
+		return nil
+	}
+	length := len(items)
+	if length == 0 {
+		return []int{}
+	}
+	shift := n % length
+	if shift < 0 {
+		shift += length
+	}
+	result := make([]int, length)
+	for index := 0; index < length; index++ {
+		result[index] = items[(index+shift)%length]
+	}
+	return result
+}
