+package stringcompression
+
+import (
+	"fmt"
+	"strconv"
+	"strings"
+)
+
+// isASCIIDigit reports whether r is one of the ten ASCII digits.
+func isASCIIDigit(r rune) bool {
+	return r >= '0' && r <= '9'
+}
+
+// needsEscape reports whether r must be prefixed with a backslash so that
+// Decompress will read it back as a literal character.
+func needsEscape(r rune) bool {
+	return r == '\\' || isASCIIDigit(r)
+}
+
+// Compress returns the run-length encoded form of s.
+func Compress(s string) string {
+	runes := []rune(s)
+
+	var b strings.Builder
+	for i := 0; i < len(runes); {
+		j := i + 1
+		for j < len(runes) && runes[j] == runes[i] {
+			j++
+		}
+
+		r := runes[i]
+		if needsEscape(r) {
+			b.WriteRune('\\')
+		}
+		b.WriteRune(r)
+
+		if n := j - i; n > 1 {
+			b.WriteString(strconv.Itoa(n))
+		}
+
+		i = j
+	}
+
+	return b.String()
+}
+
+// Decompress decodes a string produced by Compress.
+func Decompress(s string) (string, error) {
+	runes := []rune(s)
+
+	var b strings.Builder
+	for i := 0; i < len(runes); {
+		var char rune
+		if runes[i] == '\\' {
+			if i+1 >= len(runes) {
+				return "", fmt.Errorf("compression: escape character at index %d has nothing to escape", i)
+			}
+			char = runes[i+1]
+			i += 2
+		} else {
+			char = runes[i]
+			i++
+		}
+
+		start := i
+		for i < len(runes) && isASCIIDigit(runes[i]) {
+			i++
+		}
+
+		count := 1
+		if i > start {
+			digits := string(runes[start:i])
+			if len(digits) > 1 && digits[0] == '0' {
+				return "", fmt.Errorf("compression: repeat count %q must not have a leading zero", digits)
+			}
+			n, err := strconv.Atoi(digits)
+			if err != nil {
+				return "", fmt.Errorf("compression: invalid repeat count %q: %w", digits, err)
+			}
+			if n == 0 {
+				return "", fmt.Errorf("compression: repeat count %q must be at least 1", digits)
+			}
+			count = n
+		}
+
+		for k := 0; k < count; k++ {
+			b.WriteRune(char)
+		}
+	}
+
+	return b.String(), nil
+}
