+}
+
+type minHeap []item
+
+func (h minHeap) Len() int {
+	return len(h)
+}
+
+func (h minHeap) Less(i, j int) bool {
+	if h[i].cost != h[j].cost {
+		return h[i].cost < h[j].cost
+	}
+	if h[i].p.Row != h[j].p.Row {
+		return h[i].p.Row < h[j].p.Row
+	}
+	return h[i].p.Col < h[j].p.Col
+}
+
