+func FindPath(grid []string) ([]Point, int, error) {
+	rows, cols, start, end, cellCost, err := parseGrid(grid)
+	if err != nil {
+		return nil, 0, err
+	}
+
+	inf := int(^uint(0) >> 1)
+	dist := make([][]int, rows)
+	prev := make([][]Point, rows)
+
+	for r := 0; r < rows; r++ {
+		dist[r] = make([]int, cols)
+		prev[r] = make([]Point, cols)
+		for c := 0; c < cols; c++ {
+			dist[r][c] = inf
+			prev[r][c] = Point{-1, -1}
+		}
+	}
+
+	dist[start.Row][start.Col] = cellCost[start.Row][start.Col]
+	h := &minHeap{{p: start, cost: dist[start.Row][start.Col]}}
+	heap.Init(h)
+
+	dirs := [][2]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}
+
+	for h.Len() > 0 {
+		cur := heap.Pop(h).(item)
+		if cur.cost != dist[cur.p.Row][cur.p.Col] {
+			continue
+		}
+		if cur.p == end {
