+	rows := len(grid)
+	cols := len(grid[0])
+	if cols == 0 {
+		return 0, 0, Point{-1, -1}, Point{-1, -1}, nil, ErrInvalidGrid
+	}
+
+	start := Point{-1, -1}
+	end := Point{-1, -1}
+	costs := make([][]int, rows)
+
+	for r, row := range grid {
+		if len(row) != cols {
+			return 0, 0, Point{-1, -1}, Point{-1, -1}, nil, ErrInvalidGrid
+		}
+
+		costs[r] = make([]int, cols)
+		for c := 0; c < cols; c++ {
+			ch := row[c]
+			switch {
+			case ch == '#':
+				costs[r][c] = -1
+			case ch == 'S':
+				if start.Row != -1 {
+					return 0, 0, Point{-1, -1}, Point{-1, -1}, nil, ErrInvalidGrid
+				}
+				start = Point{r, c}
+				costs[r][c] = 1
+			case ch == 'E':
+				if end.Row != -1 {
+					return 0, 0, Point{-1, -1}, Point{-1, -1}, nil, ErrInvalidGrid
+				}
+				end = Point{r, c}
+				costs[r][c] = 1
+			case ch == '.':
+				costs[r][c] = 1
+			case ch >= '1' && ch <= '9':
+				costs[r][c] = int(ch - '0')
+			default:
+				return 0, 0, Point{-1, -1}, Point{-1, -1}, nil, ErrInvalidGrid
+			}
+		}
+	}
+
+	if start.Row == -1 || end.Row == -1 {
+		return 0, 0, Point{-1, -1}, Point{-1, -1}, nil, ErrInvalidGrid
+	}
+
+	return rows, cols, start, end, costs, nil
