+    }
+
+    cols := len(grid[0])
+    if cols == 0 {
+        return nil, 0, errors.New("grid has an empty row")
+    }
+
+    start := Point{-1, -1}
+    end := Point{-1, -1}
+
+    for r, row := range grid {
+        if len(row) != cols {
+            return nil, 0, errors.New("grid rows must have equal length")
+        }
+        for c := 0; c < len(row); c++ {
+            switch row[c] {
+            case 'S':
