+                    return nil, 0, errors.New("grid must contain exactly one start")
+                }
+                start = Point{r, c}
+            case 'E':
+                if end.Row != -1 {
+                    return nil, 0, errors.New("grid must contain exactly one end")
+                }
+                end = Point{r, c}
+            case '#', '.', '~', '^':
+            default:
+                return nil, 0, errors.New("grid contains an invalid character")
+            }
+        }
+    }
+
+    if start.Row == -1 {
+        return nil, 0, errors.New("grid is missing a start")
+    }
+    if end.Row == -1 {
+        return nil, 0, errors.New("grid is missing an end")
+    }
+
