+    dist := make([][]int, rows)
+    prev := make([][]Point, rows)
+    for r := 0; r < rows; r++ {
+        dist[r] = make([]int, cols)
+        prev[r] = make([]Point, cols)
+        for c := 0; c < cols; c++ {
+            dist[r][c] = maxInt
+            prev[r][c] = Point{-1, -1}
+        }
+    }
