+        {-1, 0},
+        {1, 0},
+        {0, -1},
+        {0, 1},
+    }
+
+    found := false
+    for pq.Len() > 0 {
+        item := heap.Pop(pq).(*queueItem)
+        p := item.point
+
+        if item.cost != dist[p.Row][p.Col] {
+            continue
+        }
+        if p == end {
+            found = true
+            break
+        }
+
+        for _, d := range directions {
+            nr := p.Row + d.Row
+            nc := p.Col + d.Col
