+    path := []Point{}
+    for cur := end; ; {
+        path = append(path, cur)
+        if cur == start {
+            break
+        }
+        cur = prev[cur.Row][cur.Col]
+        if cur.Row == -1 {
+            return nil, 0, errors.New("no path exists")
+        }
+    }
+
+    for i, j := 0, len(path)-1; i < j; i, j = i+1, j-1 {
+        path[i], path[j] = path[j], path[i]
+    }
+
+    return path, dist[end.Row][end.Col], nil
+}
+
+func tileCost(ch byte) int {
+    switch ch {
+    case '~':
+        return 3
+    case '^':
+        return 5
+    default:
+        return 1
+    }
