+package listops
+
+func RotateLeft(values []int, n int) []int {
+	if len(values) == 0 {
+		return []int{}
+	}
+
+	shift := n % len(values)
+	if shift < 0 {
+		shift += len(values)
+	}
+
+	result := make([]int, 0, len(values))
+	result = append(result, values[shift:]...)
+	result = append(result, values[:shift]...)
+	return result
+}
+
+func RotateRight(values []int, n int) []int {
+	return RotateLeft(values, -n)
+}
+
+func Unique(values []int) []int {
+	result := make([]int, 0, len(values))
+	seen := make(map[int]bool)
+
+	for _, value := range values {
+		if !seen[value] {
+			seen[value] = true
+			result = append(result, value)
+		}
+	}
+
+	return result
+}
+
+func Interleave(a, b []int) []int {
+	result := make([]int, 0, len(a)+len(b))
+	longest := len(a)
+	if len(b) > longest {
+		longest = len(b)
+	}
+
+	for i := 0; i < longest; i++ {
+		if i < len(a) {
+			result = append(result, a[i])
+		}
+		if i < len(b) {
+			result = append(result, b[i])
+		}
+	}
+
+	return result
+}
