+func (r *RingBuffer) Write(value int) error {
+	if r.count == len(r.data) {
+		return ErrFull
+	}
+	r.data[r.tail] = value
+	r.tail = (r.tail + 1) % len(r.data)
+	r.count++
+	return nil
