+package tokenizer
+
+import "unicode"
+
+// Tokenize splits input into tokens.
+func Tokenize(input string) []string {
+	tokens := []string{}
+	runes := []rune(input)
+	n := len(runes)
+
+	isWordStart := func(r rune) bool {
+		return unicode.IsLetter(r) || r == '_'
+	}
+	isWordPart := func(r rune) bool {
+		return unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_'
+	}
+	isASCIIDigit := func(r rune) bool {
+		return r >= '0' && r <= '9'
+	}
+
+	for i := 0; i < n; {
+		r := runes[i]
+
+		if unicode.IsSpace(r) {
+			i++
+			continue
+		}
+
+		if isWordStart(r) {
+			start := i
+			i++
+			for i < n && isWordPart(runes[i]) {
+				i++
+			}
+			tokens = append(tokens, string(runes[start:i]))
+			continue
+		}
+
+		if isASCIIDigit(r) {
+			start := i
+			i++
+			for i < n && isASCIIDigit(runes[i]) {
+				i++
+			}
+			if i+1 < n && runes[i] == '.' && isASCIIDigit(runes[i+1]) {
+				i++
+				for i < n && isASCIIDigit(runes[i]) {
+					i++
+				}
+			}
+			tokens = append(tokens, string(runes[start:i]))
+			continue
+		}
+
+		tokens = append(tokens, string(r))
+		i++
+	}
+
+	return tokens
+}
