+package wordfrequency
+
+import (
+	"sort"
+	"strings"
+	"unicode"
+)
+
+type WordCount struct {
+	Word  string
+	Count int
+}
+
+func CountWords(text string, stopWords []string) map[string]int {
+	counts := make(map[string]int)
+	stop := make(map[string]struct{}, len(stopWords))
+	for _, word := range stopWords {
+		stop[strings.ToLower(word)] = struct{}{}
+	}
+
+	runes := []rune(text)
+	current := make([]rune, 0, 16)
+
+	flush := func() {
+		if len(current) == 0 {
+			return
+		}
+		word := string(current)
+		current = current[:0]
+		if _, isStop := stop[word]; isStop {
+			return
+		}
+		counts[word]++
+	}
+
+	for i := 0; i < len(runes); {
+		r := runes[i]
+		if unicode.IsLetter(r) || unicode.IsDigit(r) {
+			current = append(current, unicode.ToLower(r))
+			i++
+			continue
+		}
+
+		if r == '\'' && len(current) > 0 && i+1 < len(runes) && unicode.IsLetter(runes[i+1]) {
+			prev := current[len(current)-1]
+			if unicode.IsLetter(prev) {
+				current = append(current, r)
+				i++
+				continue
+			}
+		}
+
+		flush()
+		i++
+	}
+
+	flush()
+	return counts
+}
+
+func TopWords(counts map[string]int, n int) []WordCount {
+	if n <= 0 {
+		return []WordCount{}
+	}
+
+	ranked := make([]WordCount, 0, len(counts))
+	for word, count := range counts {
+		if count > 0 {
+			ranked = append(ranked, WordCount{Word: word, Count: count})
+		}
+	}
+
+	sort.Slice(ranked, func(i, j int) bool {
+		if ranked[i].Count != ranked[j].Count {
+			return ranked[i].Count > ranked[j].Count
+		}
+		return ranked[i].Word < ranked[j].Word
+	})
+
+	if n < len(ranked) {
+		return ranked[:n]
+	}
+	return ranked
+}
