+package scheduling
+
+import "sort"
+
+type Interval struct {
+	Start int
+	End   int
+}
+
+func FreeSlots(busy []Interval, dayStart, dayEnd, minDuration int) []Interval {
+	if dayStart >= dayEnd {
+		return []Interval{}
+	}
+
+	var valid []Interval
+	for _, b := range busy {
+		if b.Start >= b.End {
+			continue
+		}
+		start := b.Start
+		if start < dayStart {
+			start = dayStart
+		}
+		end := b.End
+		if end > dayEnd {
+			end = dayEnd
+		}
+		if start < end {
+			valid = append(valid, Interval{Start: start, End: end})
+		}
+	}
+
+	if len(valid) == 0 {
+		if dayEnd-dayStart >= minDuration || minDuration <= 0 {
+			return []Interval{{Start: dayStart, End: dayEnd}}
+		}
+		return []Interval{}
+	}
+
+	sort.Slice(valid, func(i, j int) bool {
+		return valid[i].Start < valid[j].Start
+	})
+
+	merged := []Interval{valid[0]}
+	for _, v := range valid[1:] {
+		last := &merged[len(merged)-1]
+		if v.Start <= last.End {
+			if v.End > last.End {
+				last.End = v.End
+			}
+		} else {
+			merged = append(merged, v)
+		}
+	}
+
+	var free []Interval
+	prevEnd := dayStart
+	for _, m := range merged {
+		if m.Start > prevEnd {
+			gap := Interval{Start: prevEnd, End: m.Start}
+			if minDuration <= 0 || gap.End-gap.Start >= minDuration {
+				free = append(free, gap)
+			}
+		}
+		if m.End > prevEnd {
+			prevEnd = m.End
+		}
+	}
+	if prevEnd < dayEnd {
+		gap := Interval{Start: prevEnd, End: dayEnd}
+		if minDuration <= 0 || gap.End-gap.Start >= minDuration {
+			free = append(free, gap)
+		}
+	}
+
+	if free == nil {
+		return []Interval{}
+	}
+	return free
+}
