+// Compare compares two dot-separated version strings.
+// It returns -1 if version1 is lower, 0 if equal, and 1 if higher.
+func Compare(version1, version2 string) int {
+	parts1 := strings.Split(version1, ".")
+	parts2 := strings.Split(version2, ".")
+
+	maxLen := len(parts1)
+	if len(parts2) > maxLen {
+		maxLen = len(parts2)
+	}
+
+	for i := 0; i < maxLen; i++ {
+		part1 := "0"
+		if i < len(parts1) {
+			part1 = parts1[i]
+		}
+
+		part2 := "0"
+		if i < len(parts2) {
+			part2 = parts2[i]
+		}
+
+		cmp := compareParts(part1, part2)
+		if cmp != 0 {
+			return cmp
+		}
+	}
+
+	return 0
+}
+
+func compareParts(a, b string) int {
+	a = strings.TrimLeft(a, "0")
+	b = strings.TrimLeft(b, "0")
+
+	if a == "" {
+		a = "0"
+	}
+	if b == "" {
+		b = "0"
+	}
+
+	if len(a) < len(b) {
+		return -1
+	}
+	if len(a) > len(b) {
+		return 1
+	}
+	if a < b {
+		return -1
+	}
+	if a > b {
+		return 1
+	}
+	return 0
