+func (h *entryHeap) Push(x interface{}) {
+	*h = append(*h, x.(entry))
+}
+
+func (h *entryHeap) Pop() interface{} {
+	old := *h
+	n := len(old)
+	item := old[n-1]
+	*h = old[:n-1]
+	return item
+}
+
+type Queue struct {
+	h       entryHeap
+	nextSeq int
+}
