+func Chunk(values []int, size int) [][]int {
+	if size <= 0 {
+		return nil
+	}
+	if len(values) == 0 {
+		return [][]int{}
+	}
+
+	chunks := make([][]int, 0, (len(values)+size-1)/size)
+	for start := 0; start < len(values); start += size {
+		end := start + size
+		if end > len(values) {
+			end = len(values)
+		}
