+func Interleave(left, right []int) []int {
+	result := make([]int, 0, len(left)+len(right))
+
+	maxLength := len(left)
+	if len(right) > maxLength {
+		maxLength = len(right)
+	}
+
+	for i := 0; i < maxLength; i++ {
+		if i < len(left) {
+			result = append(result, left[i])
+		}
+		if i < len(right) {
+			result = append(result, right[i])
+		}
+	}
