+		}
+	case HalfAwayFromZero:
+		cmp := new(big.Int).Lsh(r, 1).Cmp(d)
+		inc = cmp >= 0
+	case HalfTowardZero:
+		cmp := new(big.Int).Lsh(r, 1).Cmp(d)
+		inc = cmp > 0
+	}
