+func (p *parser) parseExpression() (*expression, error) {
+	p.skipWhitespace()
+	if p.eof() {
+		return nil, errors.New("unexpected end of expression")
+	}
+
+	ch := p.input[p.pos]
+	switch {
+	case ch == '(':
+		return p.parseCall()
+	case ch == '-' || isDigit(ch):
+		return p.parseNumber()
+	case isIdentifierStart(ch):
+		name := p.parseIdentifier()
+		return &expression{kind: variableExpr, name: name}, nil
+	default:
+		return nil, fmt.Errorf("unexpected character %q at position %d", ch, p.pos)
+	}
+}
+
+func (p *parser) parseCall() (*expression, error) {
+	p.pos++ // consume '('
+	p.skipWhitespace()
+	if p.eof() {
+		return nil, errors.New("unterminated expression")
+	}
+	if !isIdentifierStart(p.input[p.pos]) {
+		return nil, fmt.Errorf("expected operator at position %d", p.pos)
+	}
+
+	operator := p.parseIdentifier()
+	var args []*expression
+
+	for {
+		p.skipWhitespace()
+		if p.eof() {
+			return nil, fmt.Errorf("missing closing parenthesis for %q", operator)
+		}
+		if p.input[p.pos] == ')' {
+			p.pos++
+			break
+		}
+
+		arg, err := p.parseExpression()
+		if err != nil {
+			return nil, err
+		}
+		args = append(args, arg)
+	}
+
+	return &expression{kind: callExpr, name: operator, children: args}, nil
+}
+
+func (p *parser) parseNumber() (*expression, error) {
+	start := p.pos
+
+	if p.input[p.pos] == '-' {
+		p.pos++
+		if p.eof() || !isDigit(p.input[p.pos]) {
+			return nil, fmt.Errorf("invalid number at position %d", start)
+		}
+	}
+
+	for !p.eof() && isDigit(p.input[p.pos]) {
+		p.pos++
+	}
+
+	text := p.input[start:p.pos]
+	n, err := strconv.Atoi(text)
+	if err != nil {
+		return nil, fmt.Errorf("invalid integer %q: %v", text, err)
+	}
+
+	return &expression{kind: numberExpr, number: n}, nil
+}
+
+func (p *parser) parseIdentifier() string {
+	start := p.pos
+	for !p.eof() && isIdentifierPart(p.input[p.pos]) {
+		p.pos++
+	}
+	return p.input[start:p.pos]
+}
+
+func (p *parser) skipWhitespace() {
+	for !p.eof() {
+		switch p.input[p.pos] {
+		case ' ', '\t', '\n', '\r':
+			p.pos++
+		default:
+			return
+		}
+	}
+}
+
+func (p *parser) eof() bool {
+	return p.pos >= len(p.input)
+}
+
+func isDigit(ch byte) bool {
+	return ch >= '0' && ch <= '9'
+}
+
+func isIdentifierStart(ch byte) bool {
+	return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch == '_'
+}
+
+func isIdentifierPart(ch byte) bool {
+	return isIdentifierStart(ch) || isDigit(ch)
+}
+
+func evaluate(e *expression, env map[string]int) (int, error) {
+	switch e.kind {
+	case numberExpr:
+		return e.number, nil
+	case variableExpr:
+		value, ok := env[e.name]
+		if !ok {
+			return 0, fmt.Errorf("unknown variable %q", e.name)
+		}
+		return value, nil
+	case callExpr:
+		return evaluateCall(e, env)
+	default:
+		return 0, errors.New("unknown expression")
+	}
+}
+
+func evaluateCall(e *expression, env map[string]int) (int, error) {
+	switch e.name {
+	case "add", "sub", "mul", "div", "mod", "pow":
+		if len(e.children) != 2 {
+			return 0, fmt.Errorf("%s expects 2 arguments", e.name)
+		}
+
+		left, err := evaluate(e.children[0], env)
+		if err != nil {
+			return 0, err
+		}
+		right, err := evaluate(e.children[1], env)
+		if err != nil {
+			return 0, err
+		}
+
+		switch e.name {
+		case "add":
+			return left + right, nil
+		case "sub":
+			return left - right, nil
+		case "mul":
+			return left * right, nil
+		case "div":
+			if right == 0 {
+				return 0, errors.New("division by zero")
+			}
+			return left / right, nil
+		case "mod":
+			if right == 0 {
+				return 0, errors.New("modulo by zero")
+			}
+			return left % right, nil
+		case "pow":
+			if right < 0 {
+				return 0, errors.New("negative exponent")
+			}
+			return integerPower(left, right), nil
+		}
+	case "neg":
+		if len(e.children) != 1 {
+			return 0, errors.New("neg expects 1 argument")
+		}
+		value, err := evaluate(e.children[0], env)
+		if err != nil {
+			return 0, err
+		}
+		return -value, nil
+	case "if":
+		if len(e.children) != 3 {
+			return 0, errors.New("if expects 3 arguments")
+		}
+
+		condition, err := evaluate(e.children[0], env)
+		if err != nil {
+			return 0, err
+		}
+		if condition != 0 {
+			return evaluate(e.children[1], env)
+		}
+		return evaluate(e.children[2], env)
+	case "let":
+		if len(e.children) != 3 {
+			return 0, errors.New("let expects 3 arguments")
+		}
+		if e.children[0].kind != variableExpr {
+			return 0, errors.New("let binding must be a variable")
+		}
+
+		name := e.children[0].name
+		value, err := evaluate(e.children[1], env)
+		if err != nil {
+			return 0, err
+		}
+
+		nextEnv := make(map[string]int, len(env)+1)
+		for key, val := range env {
+			nextEnv[key] = val
+		}
+		nextEnv[name] = value
+
+		return evaluate(e.children[2], nextEnv)
+	}
+
+	return 0, fmt.Errorf("unknown operator %q", e.name)
+}
+
+func integerPower(base, exponent int) int {
+	result := 1
+	for exponent > 0 {
+		if exponent&1 == 1 {
+			result *= base
+		}
+		base *= base
+		exponent >>= 1
+	}
+	return result
+}
