+		best := left
+		right := left + 1
+		if right < n && pq.less(right, left) {
+			best = right
+		}
+
+		if !pq.less(best, i) {
+			return
+		}
+		pq.swap(i, best)
+		i = best
+	}
+}
+
+func (pq *PriorityQueue[K, V]) fix(i int) {
+	if i < 0 || i >= len(pq.items) {
+		return
+	}
+
+	if i > 0 && pq.less(i, (i-1)/2) {
+		pq.up(i)
+		return
+	}
+	pq.down(i)
