+package priorityqueue
+
+type entry struct {
+	value    string
+	priority int
+	seq      int
+}
+
+type PriorityQueue struct {
+	items   []entry
+	nextSeq int
+}
+
+func New() *PriorityQueue {
+	return &PriorityQueue{}
+}
+
+func (pq *PriorityQueue) Push(value string, priority int) {
+	item := entry{value: value, priority: priority, seq: pq.nextSeq}
+	pq.nextSeq++
+	pq.items = append(pq.items, item)
+	pq.siftUp(len(pq.items) - 1)
+}
+
+func (pq *PriorityQueue) Pop() (string, bool) {
+	if len(pq.items) == 0 {
+		return "", false
+	}
+
+	n := len(pq.items) - 1
+	pq.swap(0, n)
+	item := pq.items[n]
+	pq.items = pq.items[:n]
+
+	if n > 0 {
+		pq.siftDown(0)
+	}
+
+	return item.value, true
+}
+
+func (pq *PriorityQueue) Peek() (string, bool) {
+	if len(pq.items) == 0 {
+		return "", false
+	}
+	return pq.items[0].value, true
+}
+
+func (pq *PriorityQueue) Len() int {
+	return len(pq.items)
+}
+
+func (pq *PriorityQueue) IsEmpty() bool {
+	return len(pq.items) == 0
+}
+
+func (pq *PriorityQueue) less(i, j int) bool {
+	a, b := pq.items[i], pq.items[j]
+	if a.priority != b.priority {
+		return a.priority < b.priority
+	}
+	return a.seq < b.seq
+}
+
+func (pq *PriorityQueue) swap(i, j int) {
+	pq.items[i], pq.items[j] = pq.items[j], pq.items[i]
+}
+
+func (pq *PriorityQueue) siftUp(i int) {
+	for i > 0 {
+		parent := (i - 1) / 2
+		if !pq.less(i, parent) {
+			break
+		}
+		pq.swap(i, parent)
+		i = parent
+	}
+}
+
+func (pq *PriorityQueue) siftDown(i int) {
+	n := len(pq.items)
+	for {
+		left := 2*i + 1
+		if left >= n {
+			break
+		}
+
+		smallest := left
+		right := left + 1
+		if right < n && pq.less(right, left) {
+			smallest = right
+		}
+
+		if !pq.less(smallest, i) {
+			break
+		}
+
+		pq.swap(i, smallest)
+		i = smallest
+	}
+}
