+package patternmatch
+
+type matchState struct {
+	i, j int
+}
+
+type runeRange struct {
+	lo, hi rune
+}
+
+// Match reports whether text matches pattern according to the exercise rules.
+func Match(pattern, text string) bool {
+	p := []rune(pattern)
+	s := []rune(text)
+
+	memo := make(map[matchState]bool)
+	seen := make(map[matchState]bool)
+
+	var matches func(i, j int) bool
+	matches = func(i, j int) bool {
+		state := matchState{i: i, j: j}
+		if seen[state] {
+			return memo[state]
+		}
+		seen[state] = true
+
+		result := false
+		if i == len(p) {
+			result = j == len(s)
+		} else {
+			switch p[i] {
+			case '*':
+				result = matches(i+1, j) || (j < len(s) && matches(i, j+1))
+			case '?':
+				result = j < len(s) && matches(i+1, j+1)
