+func parseClass(p []rune, start int) (end int, negated bool, ranges []runeRange) {
+	i := start + 1
+	if i < len(p) && p[i] == '!' {
+		negated = true
+		i++
+	}
+
+	for i < len(p) && p[i] != ']' {
+		lo := p[i]
+		if i+1 < len(p) && p[i+1] == '-' && i+2 < len(p) && p[i+2] != ']' {
+			hi := p[i+2]
+			ranges = append(ranges, runeRange{lo: lo, hi: hi})
+			i += 3
+		} else {
+			ranges = append(ranges, runeRange{lo: lo, hi: lo})
+			i++
+		}
+	}
+
+	if i < len(p) {
+		i++ // consume closing bracket
+	}
+	return i, negated, ranges
+}
+
+func classMatches(ranges []runeRange, negated bool, r rune) bool {
+	matched := false
+	for _, rr := range ranges {
+		if r >= rr.lo && r <= rr.hi {
+			matched = true
+			break
+		}
+	}
+	if negated {
+		return !matched
+	}
+	return matched
