+package columnartransposition
+
+import "errors"
+
+func Encode(plaintext string, key int) (string, error) {
+	if key <= 0 {
+		return "", errors.New("key must be positive")
+	}
+
+	runes := []rune(plaintext)
+	n := len(runes)
+	if n == 0 || key >= n {
+		return plaintext, nil
+	}
+
+	encoded := make([]rune, 0, n)
+	for col := 0; col < key; col++ {
+		for idx := col; idx < n; idx += key {
+			encoded = append(encoded, runes[idx])
+		}
+	}
+
+	return string(encoded), nil
+}
+
+func Decode(ciphertext string, key int) (string, error) {
+	if key <= 0 {
+		return "", errors.New("key must be positive")
+	}
+
+	runes := []rune(ciphertext)
+	n := len(runes)
+	if n == 0 || key >= n {
+		return ciphertext, nil
+	}
+
+	fullRows := n / key
+	rem := n % key
+	rows := fullRows
+	if rem > 0 {
+		rows++
+	}
+
+	grid := make([][]rune, rows)
+	for i := range grid {
+		grid[i] = make([]rune, key)
+	}
+
+	pos := 0
+	for col := 0; col < key; col++ {
+		height := fullRows
+		if col < rem {
+			height++
+		}
+		for row := 0; row < height; row++ {
+			grid[row][col] = runes[pos]
+			pos++
+		}
+	}
+
+	decoded := make([]rune, 0, n)
+	for row := 0; row < rows; row++ {
+		for col := 0; col < key; col++ {
+			if row*key+col < n {
+				decoded = append(decoded, grid[row][col])
+			}
+		}
+	}
+
+	return string(decoded), nil
+}
