+func DaysInMonth(year, month int) (int, error) {
+	if year < 1 || year > 9999 || month < 1 || month > 12 {
+		return 0, ErrInvalidDate
+	}
+
+	switch month {
+	case 2:
+		if IsLeapYear(year) {
+			return 29, nil
+		}
+		return 28, nil
+	case 4, 6, 9, 11:
+		return 30, nil
+	default:
+		return 31, nil
+	}
+}
