+	if date.Year < 1 || date.Year > 9999 {
+		return ErrInvalidDate
+	}
+	if date.Month < 1 || date.Month > 12 {
+		return ErrInvalidDate
+	}
+
+	days, err := DaysInMonth(date.Year, date.Month)
+	if err != nil {
+		return err
+	}
+	if date.Day < 1 || date.Day > days {
+		return ErrInvalidDate
+	}
+	return nil
+}
+
+func DayOfYear(date Date) (int, error) {
+	if err := validateDate(date); err != nil {
+		return 0, err
+	}
+
+	total := 0
+	for month := 1; month < date.Month; month++ {
+		days, err := DaysInMonth(date.Year, month)
+		if err != nil {
+			return 0, err
+		}
+		total += days
+	}
+	return total + date.Day, nil
+}
