+
+type Memo struct {
+	mu       sync.Mutex
+	capacity int
+	ttl      time.Duration
+	entries  map[string]*list.Element
+	lru      *list.List
+	inflight map[string]*flight
+}
+
+type entry struct {
+	key       string
+	value     any
+	expiresAt time.Time
+}
+
+type flight struct {
+	done       chan struct{}
+	value      any
+	err        error
+	panicValue any
+	panicked   bool
+}
+
+func New(capacity int, ttl time.Duration) *Memo {
+	return &Memo{
+		capacity: capacity,
+		ttl:      ttl,
+		entries:  make(map[string]*list.Element),
+		lru:      list.New(),
+		inflight: make(map[string]*flight),
+	}
+}
+
+func (m *Memo) Get(key string, compute func() (any, error)) (any, error) {
+	m.mu.Lock()
+	if elem, ok := m.entries[key]; ok {
+		it := elem.Value.(*entry)
+		if it.expired(time.Now()) {
+			m.removeElementLocked(elem)
+		} else {
+			m.lru.MoveToFront(elem)
+			value := it.value
+			m.mu.Unlock()
+			return value, nil
+		}
+	}
+
+	if f, ok := m.inflight[key]; ok {
+		m.mu.Unlock()
+		<-f.done
+		if f.panicked {
+			panic(f.panicValue)
+		}
+		return f.value, f.err
+	}
+
+	f := &flight{done: make(chan struct{})}
+	m.inflight[key] = f
+	m.mu.Unlock()
+
+	var value any
+	var err error
+	var panicValue any
+	panicked := false
+
+	func() {
+		defer func() {
+			if r := recover(); r != nil {
+				panicked = true
+				panicValue = r
+			}
+		}()
+		value, err = compute()
+	}()
+
+	m.mu.Lock()
+	delete(m.inflight, key)
+	if !panicked && err == nil {
+		m.storeLocked(key, value)
+	}
+	f.value = value
+	f.err = err
+	f.panicValue = panicValue
+	f.panicked = panicked
+	close(f.done)
+	m.mu.Unlock()
+
+	if panicked {
+		panic(panicValue)
+	}
+	return value, err
+}
+
+func (m *Memo) Delete(key string) {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	if elem, ok := m.entries[key]; ok {
+		m.removeElementLocked(elem)
+	}
+}
+
+func (m *Memo) Len() int {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	m.pruneExpiredLocked()
+	return len(m.entries)
+}
+
+func (m *Memo) storeLocked(key string, value any) {
+	if m.capacity <= 0 {
+		return
+	}
+	expiresAt := time.Time{}
+	if m.ttl > 0 {
+		expiresAt = time.Now().Add(m.ttl)
+	}
+
+	if elem, ok := m.entries[key]; ok {
+		it := elem.Value.(*entry)
+		it.value = value
+		it.expiresAt = expiresAt
+		m.lru.MoveToFront(elem)
+		return
+	}
+
+	elem := m.lru.PushFront(&entry{key: key, value: value, expiresAt: expiresAt})
+	m.entries[key] = elem
+	for len(m.entries) > m.capacity {
+		m.removeOldestLocked()
+	}
+}
+
+func (m *Memo) removeOldestLocked() {
+	elem := m.lru.Back()
+	if elem != nil {
+		m.removeElementLocked(elem)
+	}
+}
+
+func (m *Memo) removeElementLocked(elem *list.Element) {
+	m.lru.Remove(elem)
+	delete(m.entries, elem.Value.(*entry).key)
+}
+
+func (m *Memo) pruneExpiredLocked() {
+	now := time.Now()
+	for elem := m.lru.Back(); elem != nil; {
+		prev := elem.Prev()
+		if elem.Value.(*entry).expired(now) {
+			m.removeElementLocked(elem)
+		}
+		elem = prev
+	}
+}
+
+func (e *entry) expired(now time.Time) bool {
+	return !e.expiresAt.IsZero() && !now.Before(e.expiresAt)
+}
