+
+// Encode encrypts plaintext using the Bifid cipher with the given period.
+func Encode(plaintext string, period int) (string, error) {
+	if period < 1 {
+		return "", errors.New("period must be at least 1")
+	}
+
+	text := normalize(plaintext)
+	if len(text) == 0 {
+		return "", nil
+	}
+
+	var cipher strings.Builder
+	for start := 0; start < len(text); start += period {
+		end := start + period
+		if end > len(text) {
+			end = len(text)
+		}
+		block := text[start:end]
+		n := len(block)
+		seq := make([]int, 0, 2*n)
+
+		for i := 0; i < n; i++ {
+			idx := strings.IndexByte(square, block[i])
+			seq = append(seq, idx/5+1)
+		}
+		for i := 0; i < n; i++ {
+			idx := strings.IndexByte(square, block[i])
+			seq = append(seq, idx%5+1)
+		}
+
+		for i := 0; i < n; i++ {
+			row := seq[2*i]
+			col := seq[2*i+1]
+			cipher.WriteByte(square[(row-1)*5+(col-1)])
+		}
+	}
+
+	return cipher.String(), nil
+}
+
