+func Decode(ciphertext string, period int) (string, error) {
+	if period < 1 {
+		return "", errors.New("period must be at least 1")
+	}
+
+	text := normalize(ciphertext)
+	if len(text) == 0 {
+		return "", nil
+	}
+
+	var plain strings.Builder
+	for start := 0; start < len(text); start += period {
+		end := start + period
+		if end > len(text) {
+			end = len(text)
+		}
+		block := text[start:end]
+		n := len(block)
+		seq := make([]int, 0, 2*n)
+
+		for i := 0; i < n; i++ {
+			idx := strings.IndexByte(square, block[i])
+			seq = append(seq, idx/5+1, idx%5+1)
+		}
+
+		for i := 0; i < n; i++ {
+			row := seq[i]
+			col := seq[n+i]
+			plain.WriteByte(square[(row-1)*5+(col-1)])
+		}
+	}
+
