+func normalize(s string) string {
+	var b strings.Builder
+	for _, r := range s {
+		if r >= 'a' && r <= 'z' {
+			r -= 'a' - 'A'
+		}
+		if r < 'A' || r > 'Z' {
+			continue
+		}
+		if r == 'J' {
+			r = 'I'
+		}
+		b.WriteRune(r)
+	}
