+import "errors"
+
+var (
+	ErrDequeEmpty = errors.New("deque is empty")
+	ErrDequeFull  = errors.New("deque is full")
+)
+
+type Deque struct {
+	items    []int
+	head     int
+	size     int
+	capacity int
+}
+
+func NewDeque(capacity int) *Deque {
+	if capacity < 1 {
+		panic("capacity must be at least 1")
+	}
+
+	return &Deque{
+		items:    make([]int, capacity),
+		capacity: capacity,
+	}
+}
+
+func (d *Deque) Len() int {
+	return d.size
+}
+
+func (d *Deque) IsEmpty() bool {
+	return d.size == 0
+}
+
+func (d *Deque) IsFull() bool {
+	return d.size == d.capacity
+}
+
+func (d *Deque) PushFront(value int) error {
+	if d.IsFull() {
+		return ErrDequeFull
+	}
+
+	d.head = (d.head - 1 + d.capacity) % d.capacity
+	d.items[d.head] = value
+	d.size++
+
+	return nil
+}
+
+func (d *Deque) PushBack(value int) error {
+	if d.IsFull() {
+		return ErrDequeFull
+	}
+
+	index := (d.head + d.size) % d.capacity
+	d.items[index] = value
+	d.size++
+
+	return nil
+}
+
+func (d *Deque) PopFront() (int, error) {
+	if d.IsEmpty() {
+		return 0, ErrDequeEmpty
+	}
+
+	value := d.items[d.head]
+	d.head = (d.head + 1) % d.capacity
+	d.size--
+
+	if d.size == 0 {
+		d.head = 0
+	}
+
+	return value, nil
+}
+
+func (d *Deque) PopBack() (int, error) {
+	if d.IsEmpty() {
+		return 0, ErrDequeEmpty
+	}
+
+	index := (d.head + d.size - 1) % d.capacity
+	value := d.items[index]
+	d.size--
+
+	if d.size == 0 {
+		d.head = 0
+	}
+
+	return value, nil
+}
+
+func (d *Deque) PeekFront() (int, error) {
+	if d.IsEmpty() {
+		return 0, ErrDequeEmpty
+	}
+
+	return d.items[d.head], nil
+}
+
+func (d *Deque) PeekBack() (int, error) {
+	if d.IsEmpty() {
+		return 0, ErrDequeEmpty
+	}
+
+	index := (d.head + d.size - 1) % d.capacity
+	return d.items[index], nil
+}
