+func EditDistance(a, b string) int {
+	ra := []rune(a)
+	rb := []rune(b)
+	n := len(ra)
+	m := len(rb)
+	if n == 0 {
+		return m
+	}
+	if m == 0 {
+		return n
+	}
+	prev := make([]int, m+1)
+	curr := make([]int, m+1)
+	for j := 0; j <= m; j++ {
+		prev[j] = j
+	}
