+			ins := curr[j-1] + 1
+			sub := prev[j-1] + cost
+			best := del
+			if ins < best {
+				best = ins
+			}
+			if sub < best {
+				best = sub
+			}
+			curr[j] = best
+		}
+		prev, curr = curr, prev
+	}
+	return prev[m]
