+	value      T
+	err        error
+	panicked   bool
+	panicValue any
+}
+
+type Cache[T any] struct {
+	mu       sync.Mutex
+	capacity int
+	ttl      time.Duration
+	now      func() time.Time
+	lru      *list.List
+	items    map[string]*list.Element
+	calls    map[string]*call[T]
