+	completed = true
+
+	c.mu.Lock()
+	if err == nil {
+		c.setLocked(key, value, c.now())
+	}
+	pending.value = value
+	pending.err = err
+	delete(c.calls, key)
+	close(pending.done)
+	c.mu.Unlock()
+
+	return value, err
+}
