+func PrimePairs(n int) [][2]int {
+	if n < 4 || n%2 != 0 {
+		return nil
+	}
+
+	isComposite := make([]bool, n+1)
+	for i := 2; i*i <= n; i++ {
+		if isComposite[i] {
+			continue
+		}
+		for j := i * i; j <= n; j += i {
