+func MinWindow(s, t string) string {
+	if t == "" {
+		return ""
+	}
+
+	sr := []rune(s)
+	tr := []rune(t)
+	if len(sr) < len(tr) {
+		return ""
+	}
+
+	need := make(map[rune]int)
+	for _, r := range tr {
+		need[r]++
+	}
+
+	have := 0
+	required := len(need)
+	counts := make(map[rune]int)
+	left := 0
+	bestLeft := 0
+	bestLen := len(sr) + 1
+
+	for right, r := range sr {
+		counts[r]++
+		if need[r] > 0 && counts[r] == need[r] {
+			have++
+		}
+
+		for have == required {
+			if right-left+1 < bestLen {
+				bestLen = right - left + 1
+				bestLeft = left
+			}
+
+			lr := sr[left]
+			if need[lr] > 0 && counts[lr] == need[lr] {
+				have--
+			}
+			counts[lr]--
+			left++
+		}
+	}
+
+	if bestLen == len(sr)+1 {
+		return ""
+	}
+	return string(sr[bestLeft : bestLeft+bestLen])
