+	*pq = append(*pq, x.(*item))
+}
+
+func (pq *priorityQueue) Pop() interface{} {
+	old := *pq
+	n := len(old)
+	last := old[n-1]
+	old[n-1] = nil
+	*pq = old[:n-1]
+	return last
