+		if len(bits) == 5 {
+			value := 0
+			for _, bit := range bits {
+				value <<= 1
+				if bit == 'B' {
+					value++
+				}
+			}
+
+			if value < 26 {
+				out.WriteByte(byte('A' + value))
+			}
+
+			bits = bits[:0]
+		}
+	}
