+		return Date{}, errors.New("ordinal out of supported range")
+	}
+	lo, hi := 1, 9999
+	for lo < hi {
+		mid := (lo + hi + 1) / 2
+		if daysBeforeYear(mid) <= ord {
+			lo = mid
+		} else {
+			hi = mid - 1
+		}
+	}
+	year := lo
+	rem := ord - daysBeforeYear(year)
+	month := time.January
+	for {
+		dim := daysInMonth(year, month)
+		if rem < dim {
+			break
+		}
+		rem -= dim
+		month++
+	}
+	return Date{Year: year, Month: month, Day: rem + 1}, nil
