+func Apply(s string, ops []Operation) (string, error) {
+	if len(ops) == 0 {
+		return s, nil
+	}
+
+	runes := []rune(s)
+
+	for i, op := range ops {
+		if op.Start < 0 || op.Length <= 0 || op.Start > len(runes) || op.Length > len(runes)-op.Start {
