+func rotateRunes(runes []rune, steps int, right bool) {
+	n := len(runes)
+	if n == 0 {
+		return
+	}
+
+	steps %= n
+	if steps < 0 {
+		steps += n
+	}
+
+	if !right {
+		steps = (n - steps) % n
+	}
+
+	if steps == 0 {
+		return
+	}
+
+	temp := make([]rune, steps)
+	copy(temp, runes[n-steps:])
+	copy(runes[steps:], runes[:n-steps])
+	copy(runes[:steps], temp)
+}
