+import "errors"
+
+func Pack(values []int64, width int) ([]byte, error) {
+	if width < 1 || width > 64 {
+		return nil, errors.New("width must be between 1 and 64")
+	}
+
+	totalBits := width * len(values)
+	data := make([]byte, (totalBits+7)/8)
+	bitPos := 0
+
+	for _, value := range values {
+		if width < 64 {
+			min := int64(-1) << uint(width-1)
+			max := (int64(1) << uint(width-1)) - 1
+			if value < min || value > max {
+				return nil, errors.New("value does not fit in width bits")
+			}
+		}
+
+		u := uint64(value)
+		for i := 0; i < width; i++ {
+			if (u>>uint(i))&1 != 0 {
+				data[bitPos>>3] |= byte(1) << uint(bitPos&7)
+			}
+			bitPos++
+		}
+	}
+
+	return data, nil
+}
+
+func Unpack(data []byte, width, count int) ([]int64, error) {
+	if width < 1 || width > 64 {
+		return nil, errors.New("width must be between 1 and 64")
+	}
+	if count < 0 {
+		return nil, errors.New("count must not be negative")
+	}
+
+	required := (width*count + 7) / 8
+	if len(data) != required {
+		return nil, errors.New("data length does not match width and count")
+	}
+
+	values := make([]int64, count)
+	bitPos := 0
+	for j := 0; j < count; j++ {
+		var u uint64
+		for i := 0; i < width; i++ {
+			if (data[bitPos>>3]>>uint(bitPos&7))&1 != 0 {
+				u |= uint64(1) << uint(i)
+			}
+			bitPos++
+		}
+
+		if width < 64 {
+			signBit := uint64(1) << uint(width-1)
+			if u&signBit != 0 {
+				u |= ^((uint64(1) << uint(width)) - 1)
+			}
+		}
+		values[j] = int64(u)
+	}
+
+	return values, nil
+}
