+
+// RoundingMode selects how a fraction is rounded.
+type RoundingMode int
+
+const (
+	HalfUp RoundingMode = iota
+	HalfEven
+	TowardZero
+	AwayFromZero
+	Floor
+	Ceil
+)
+
+// Fraction is an exact rational number.
+type Fraction struct {
+	Num int64
+	Den int64
+}
+
+// New builds a canonical fraction with a positive denominator.
+func New(num, den int64) (Fraction, error) {
+	if den == 0 {
+		return Fraction{}, ErrZeroDenominator
+	}
+	if den < 0 {
+		num, den = -num, -den
+	}
+	g := gcd(absInt64(num), absInt64(den))
+	if g > 1 {
+		num /= g
+		den /= g
+	}
+	if num == 0 {
+		den = 1
+	}
+	return Fraction{Num: num, Den: den}, nil
+}
+
+// String renders the fraction as "n/d", or "n" when the denominator is 1.
+func (f Fraction) String() string {
+	if f.Den == 1 {
+		return strconv.FormatInt(f.Num, 10)
+	}
+	return strconv.FormatInt(f.Num, 10) + "/" + strconv.FormatInt(f.Den, 10)
+}
+
+// Round rounds the fraction to the nearest integer using mode.
+func (f Fraction) Round(mode RoundingMode) (int64, error) {
+	if f.Den == 0 {
+		return 0, ErrZeroDenominator
+	}
+	num, den := f.Num, f.Den
+	if den < 0 {
+		num, den = -num, -den
+	}
+	q := num / den
+	r := num % den
+	if r == 0 {
+		return q, nil
+	}
+	ar := r
+	if ar < 0 {
+		ar = -ar
+	}
+	switch mode {
+	case TowardZero:
+		return q, nil
+	case Floor:
+		if num < 0 {
+			return q - 1, nil
+		}
+		return q, nil
+	case Ceil:
+		if num > 0 {
+			return q + 1, nil
+		}
+		return q, nil
+	case AwayFromZero:
+		return stepAway(num, q), nil
+	case HalfUp:
+		// Compare twice the remainder with the denominator without
+		// doubling anything, so large values cannot overflow.
+		if ar >= den-ar {
+			return stepAway(num, q), nil
+		}
+		return q, nil
+	case HalfEven:
+		if ar > den-ar {
+			return stepAway(num, q), nil
+		}
+		if ar < den-ar {
+			return q, nil
+		}
+		if q%2 == 0 {
+			return q, nil
+		}
+		return stepAway(num, q), nil
+	}
+	return 0, fmt.Errorf("fractions: unknown rounding mode %d", mode)
+}
+
+// RoundToDecimal rounds the fraction to the given number of decimal places.
+func (f Fraction) RoundToDecimal(places int, mode RoundingMode) (string, error) {
+	if f.Den == 0 {
+		return "", ErrZeroDenominator
+	}
+	if places < 0 {
+		return "", ErrNegativePlaces
+	}
+	num, den := f.Num, f.Den
+	if den < 0 {
+		num, den = -num, -den
+	}
+	pow := int64(1)
+	for i := 0; i < places; i++ {
+		pow *= 10
+	}
+	rounded, err := Fraction{Num: num * pow, Den: den}.Round(mode)
+	if err != nil {
+		return "", err
+	}
+	if places == 0 {
+		return strconv.FormatInt(rounded, 10), nil
+	}
+	sign := ""
+	if rounded < 0 {
+		sign = "-"
+		rounded = -rounded
+	}
+	digits := fmt.Sprintf("%0*d", places+1, rounded)
+	whole := digits[:len(digits)-places]
+	frac := digits[len(digits)-places:]
+	return sign + whole + "." + frac, nil
+}
+
+func stepAway(num, q int64) int64 {
+	if num > 0 {
+		return q + 1
+	}
+	return q - 1
+}
+
+func gcd(a, b int64) int64 {
+	for b != 0 {
+		a, b = b, a%b
+	}
+	return a
+}
+
+func absInt64(x int64) int64 {
+	if x < 0 {
+		return -x
+	}
+	return x
+}
