+				continue
+			}
+			if grid[nr][nc] == '#' {
+				continue
+			}
+
+			nextCost := current.cost + enterCost(grid[nr][nc])
+			if nextCost < dist[nr][nc] {
+				dist[nr][nc] = nextCost
+				prev[nr][nc] = current.point
+				heap.Push(pq, pathNode{point: Point{Row: nr, Col: nc}, cost: nextCost})
