+// ShortestPath returns the number of steps in the shortest path from 'S' to 'E'
+// in the given maze grid, or -1 if no such path exists.
+func ShortestPath(grid []string) int {
+	if len(grid) == 0 {
+		return -1
+	}
+
+	rows := make([][]rune, len(grid))
+	for i, line := range grid {
+		rows[i] = []rune(line)
+	}
+
+	var start, end point
+	foundStart, foundEnd := false, false
+	for r, row := range rows {
+		for c, ch := range row {
+			switch ch {
+			case 'S':
+				if foundStart {
+					return -1
+				}
+				start = point{r, c}
+				foundStart = true
+			case 'E':
+				if foundEnd {
+					return -1
+				}
+				end = point{r, c}
+				foundEnd = true
+			}
+		}
+	}
+	if !foundStart || !foundEnd {
+		return -1
+	}
+
+	passable := func(r, c int) bool {
+		if r < 0 || r >= len(rows) || c < 0 || c >= len(rows[r]) {
+			return false
+		}
+		ch := rows[r][c]
+		return ch == '.' || ch == 'S' || ch == 'E'
+	}
+
+	visited := make([][]bool, len(rows))
+	dist := make([][]int, len(rows))
+	for i := range rows {
+		visited[i] = make([]bool, len(rows[i]))
+		dist[i] = make([]int, len(rows[i]))
+	}
+
+	dirs := [4][2]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}
+	queue := []point{start}
+	visited[start.row][start.col] = true
+
+	for len(queue) > 0 {
+		cur := queue[0]
+		queue = queue[1:]
+
+		if cur.row == end.row && cur.col == end.col {
+			return dist[cur.row][cur.col]
+		}
+
+		for _, d := range dirs {
+			nr, nc := cur.row+d[0], cur.col+d[1]
+			if !passable(nr, nc) || visited[nr][nc] {
+				continue
+			}
+			visited[nr][nc] = true
+			dist[nr][nc] = dist[cur.row][cur.col] + 1
+			queue = append(queue, point{nr, nc})
+		}
