+package topo
+
+import (
+	"errors"
+	"sort"
+)
+
+var errCycle = errors.New("graph contains a cycle")
+
+func collectNodes(adj map[string][]string) []string {
+	seen := make(map[string]bool)
+	var nodes []string
+	add := func(n string) {
+		if !seen[n] {
+			seen[n] = true
+			nodes = append(nodes, n)
+		}
+	}
+	for u, vs := range adj {
+		add(u)
+		for _, v := range vs {
+			add(v)
+		}
+	}
+	sort.Strings(nodes)
+	return nodes
+}
+
+func dedup(adj map[string][]string) map[string][]string {
+	out := make(map[string][]string)
+	for u, vs := range adj {
+		seen := make(map[string]bool)
+		for _, v := range vs {
+			if !seen[v] {
+				seen[v] = true
+				out[u] = append(out[u], v)
+			}
+		}
+		if _, ok := out[u]; !ok {
+			out[u] = []string{}
+		}
+	}
+	return out
+}
+
+func TopologicalSort(adj map[string][]string) ([]string, error) {
+	nodes := collectNodes(adj)
+	edges := dedup(adj)
+
+	indeg := make(map[string]int, len(nodes))
+	for _, n := range nodes {
+		indeg[n] = 0
+	}
+	for u := range edges {
+		for _, v := range edges[u] {
+			indeg[v]++
+		}
+	}
+
+	var ready []string
+	for _, n := range nodes {
+		if indeg[n] == 0 {
+			ready = append(ready, n)
+		}
+	}
+
+	order := make([]string, 0, len(nodes))
+	for len(ready) > 0 {
+		sort.Strings(ready)
+		u := ready[0]
+		ready = ready[1:]
+		order = append(order, u)
+		for _, v := range edges[u] {
+			indeg[v]--
+			if indeg[v] == 0 {
+				ready = append(ready, v)
+			}
+		}
+	}
+
+	if len(order) != len(nodes) {
+		return nil, errCycle
+	}
+	return order, nil
+}
