+	order, err := TopologicalSort(adj)
+	if err != nil {
+		return 0, err
+	}
+
+	edges := dedup(adj)
+	dist := make(map[string]int, len(order))
+	longest := 0
+
+	for _, u := range order {
+		for _, v := range edges[u] {
+			if d := dist[u] + 1; d > dist[v] {
+				dist[v] = d
+				if d > longest {
+					longest = d
+				}
+			}
+		}
+	}
+	return longest, nil
