+// ShortestPath returns the number of steps in the shortest path from S to E.
+// It returns -1 and false when no path exists or the grid is invalid.
+func ShortestPath(grid []string) (int, bool) {
+	if len(grid) == 0 {
+		return -1, false
+	}
+
+	cols := len(grid[0])
+	if cols == 0 {
+		return -1, false
+	}
+
+	start := point{row: -1, col: -1}
+	end := point{row: -1, col: -1}
+
+	for r, row := range grid {
+		if len(row) != cols {
+			return -1, false
+		}
+
+		for c := 0; c < cols; c++ {
+			switch row[c] {
+			case '.', '#':
+				// Valid non-special cells.
+			case 'S':
+				if start.row != -1 {
+					return -1, false
+				}
+				start = point{row: r, col: c}
+			case 'E':
+				if end.row != -1 {
+					return -1, false
+				}
+				end = point{row: r, col: c}
+			default:
+				return -1, false
+			}
+		}
+	}
+
+	if start.row == -1 || end.row == -1 {
+		return -1, false
+	}
+
+	if start == end {
+		return 0, true
+	}
+
+	rows := len(grid)
+	dist := make([][]int, rows)
+	for r := range dist {
+		dist[r] = make([]int, cols)
+		for c := range dist[r] {
+			dist[r][c] = -1
+		}
+	}
+
+	queue := []point{start}
+	dist[start.row][start.col] = 0
+
+	directions := [][2]int{
+		{1, 0},
+		{-1, 0},
+		{0, 1},
+		{0, -1},
+	}
+
+	for head := 0; head < len(queue); head++ {
+		current := queue[head]
+
+		if current == end {
+			return dist[current.row][current.col], true
+		}
+
+		for _, direction := range directions {
+			nextRow := current.row + direction[0]
+			nextCol := current.col + direction[1]
+
+			if nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols {
+				continue
+			}
+
+			if dist[nextRow][nextCol] != -1 {
+				continue
+			}
+
+			if grid[nextRow][nextCol] == '#' {
+				continue
+			}
+
+			dist[nextRow][nextCol] = dist[current.row][current.col] + 1
+			queue = append(queue, point{row: nextRow, col: nextCol})
+		}
+	}
+
+	return -1, false
+}
