+import "container/heap"
+
+type Task struct {
+	ID       string
+	Priority int
+}
+
+type item struct {
+	id       string
+	priority int
+	seq      uint64
+}
+
+type Queue struct {
+	items   []*item
+	index   map[string]int
+	nextSeq uint64
+}
+
+type itemHeap struct {
+	q *Queue
+}
+
+func (h itemHeap) Len() int {
+	return len(h.q.items)
+}
+
+func (h itemHeap) Less(i, j int) bool {
+	a, b := h.q.items[i], h.q.items[j]
+	if a.priority != b.priority {
+		return a.priority < b.priority
+	}
+	return a.seq < b.seq
+}
+
+func (h itemHeap) Swap(i, j int) {
+	h.q.items[i], h.q.items[j] = h.q.items[j], h.q.items[i]
+	h.q.index[h.q.items[i].id] = i
+	h.q.index[h.q.items[j].id] = j
+}
+
+func (h itemHeap) Push(x any) {
+	it := x.(*item)
+	h.q.index[it.id] = len(h.q.items)
+	h.q.items = append(h.q.items, it)
+}
+
+func (h itemHeap) Pop() any {
+	n := len(h.q.items)
+	it := h.q.items[n-1]
+	h.q.items[n-1] = nil
+	h.q.items = h.q.items[:n-1]
+	delete(h.q.index, it.id)
+	return it
+}
+
+func New() *Queue {
+	return &Queue{index: make(map[string]int)}
+}
