+	if q.index == nil {
+		q.index = make(map[string]int)
+	}
+	if _, exists := q.index[id]; exists {
+		return false
+	}
+
+	it := &item{id: id, priority: priority, seq: q.nextSeq}
+	q.nextSeq++
+	heap.Push(itemHeap{q}, it)
+	return true
+}
+
+func (q *Queue) Pop() (Task, bool) {
+	if len(q.items) == 0 {
