+type Congruence struct {
+	Remainder int64
+	Modulus   int64
+}
+
+func SolveCongruences(congruences []Congruence) (int64, int64, bool) {
+	x := int64(0)
+	m := int64(1)
+
+	for _, c := range congruences {
+		if c.Modulus <= 0 {
+			return 0, 0, false
+		}
+
+		r := mod(c.Remainder, c.Modulus)
+		g := gcd(m, c.Modulus)
+		diff := r - mod(x, c.Modulus)
+		if diff%g != 0 {
+			return 0, 0, false
+		}
+
+		m1 := m / g
+		m2 := c.Modulus / g
+		diffDiv := diff / g
+
+		var k int64
+		if m2 == 1 {
+			k = 0
+		} else {
+			inv := modInverse(mod(m1, m2), m2)
+			k = mod(mod(diffDiv, m2)*inv, m2)
+		}
+
+		newM := m * m2
+		x = mod(x+mod(m, newM)*mod(k, newM), newM)
+		m = newM
+	}
+
+	return x, m, true
+}
+
+func mod(a, b int64) int64 {
+	r := a % b
+	if r < 0 {
+		r += b
+	}
+	return r
+}
+
+func gcd(a, b int64) int64 {
+	for b != 0 {
+		a, b = b, a%b
+	}
+	if a < 0 {
+		return -a
+	}
+	return a
+}
+
+func modInverse(a, m int64) int64 {
+	_, x, _ := extendedGCD(a, m)
+	return mod(x, m)
+}
+
+func extendedGCD(a, b int64) (int64, int64, int64) {
+	if b == 0 {
+		return a, 1, 0
+	}
+	g, x1, y1 := extendedGCD(b, a%b)
+	x := y1
+	y := x1 - (a/b)*y1
+	return g, x, y
+}
