+func NextAvailable(from, before time.Time, duration time.Duration, loc *time.Location, openHour, closeHour int, busy []Interval) (time.Time, bool) {
+	if loc == nil || duration <= 0 || openHour < 0 || closeHour > 24 || openHour >= closeHour || !before.After(from) {
+		return time.Time{}, false
+	}
+
+	localFrom := from.In(loc)
+	day := time.Date(localFrom.Year(), localFrom.Month(), localFrom.Day(), 0, 0, 0, 0, loc)
+
+	for {
+		if !day.Before(before) {
+			return time.Time{}, false
+		}
+
+		if day.Weekday() != time.Saturday && day.Weekday() != time.Sunday {
+			open := time.Date(day.Year(), day.Month(), day.Day(), openHour, 0, 0, 0, loc)
+			close := time.Date(day.Year(), day.Month(), day.Day(), closeHour, 0, 0, 0, loc)
+
+			candidate := open
+			if candidate.Before(from) {
+				candidate = from.In(loc)
+			}
+
+			for {
+				slotEnd := candidate.Add(duration)
+				if slotEnd.After(before) {
+					return time.Time{}, false
+				}
+				if slotEnd.After(close) {
+					break
+				}
+
+				blocked := false
+				for _, b := range busy {
+					if b.End.After(b.Start) && b.Start.Before(slotEnd) && b.End.After(candidate) {
+						candidate = b.End
+						blocked = true
+						break
+					}
+				}
+				if !blocked {
+					return candidate.In(loc), true
+				}
+			}
+		}
