+package rotate
+
+func Reverse(s string) string {
+	runes := []rune(s)
+	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
+		runes[i], runes[j] = runes[j], runes[i]
+	}
+	return string(runes)
+}
+
+func Rotate(s string, offset int) string {
+	runes := []rune(s)
+	n := len(runes)
+	if n == 0 {
+		return ""
+	}
+
+	offset %= n
+	if offset < 0 {
+		offset += n
+	}
+	if offset == 0 {
+		return s
+	}
+
+	rotated := make([]rune, n)
+	copy(rotated, runes[offset:])
+	copy(rotated[n-offset:], runes[:offset])
+	return string(rotated)
+}
