+// Package wordfreq provides small helpers for counting words and for
+// manipulating maps of word frequencies.
+package wordfreq
+
+import (
+	"sort"
+	"strings"
+	"unicode"
+)
+
+// CountWords returns a map from each normalized word in text to the number
+// of times it appears.
+//
+// A word is a maximal run of Unicode letters and digits; every other rune is
+// a separator. Words are lowercased before being counted.
+func CountWords(text string) map[string]int {
+	counts := make(map[string]int)
+
+	var b strings.Builder
+	flush := func() {
+		if b.Len() > 0 {
+			counts[b.String()]++
+			b.Reset()
+		}
+	}
+
+	for _, r := range text {
+		if unicode.IsLetter(r) || unicode.IsDigit(r) {
+			b.WriteRune(unicode.ToLower(r))
+		} else {
+			flush()
+		}
+	}
+	flush()
+
+	return counts
+}
+
+// TopWords returns the n most frequent words in counts, ordered by
+// descending count and then alphabetically by word.
+func TopWords(counts map[string]int, n int) []string {
+	if n <= 0 {
+		return []string{}
+	}
+
+	words := make([]string, 0, len(counts))
+	for w := range counts {
+		words = append(words, w)
+	}
+
+	sort.Slice(words, func(i, j int) bool {
+		if counts[words[i]] != counts[words[j]] {
+			return counts[words[i]] > counts[words[j]]
+		}
+		return words[i] < words[j]
+	})
+
+	if n < len(words) {
+		words = words[:n]
+	}
+
+	return words
+}
+
+// Merge returns a new map containing the sum of all the given maps.
+func Merge(maps ...map[string]int) map[string]int {
+	result := make(map[string]int)
+	for _, m := range maps {
+		for k, v := range m {
+			result[k] += v
+		}
+	}
+	return result
+}
+
+// Filter returns a new map containing only the entries of counts whose
+// value is greater than or equal to minCount.
+func Filter(counts map[string]int, minCount int) map[string]int {
+	result := make(map[string]int)
+	for k, v := range counts {
+		if v >= minCount {
+			result[k] = v
+		}
+	}
+	return result
+}
