+// Match reports whether text matches pattern.
+func Match(pattern, text string) bool {
+	p := []rune(pattern)
+	t := []rune(text)
+
+	tokens := make([]token, 0, len(p))
+	for i := 0; i < len(p); i++ {
+		switch p[i] {
+		case '\\':
+			if i+1 < len(p) {
+				i++
+				tokens = append(tokens, token{kind: 'l', lit: p[i]})
+			} else {
+				tokens = append(tokens, token{kind: 'l', lit: '\\'})
+			}
+		case '?':
+			tokens = append(tokens, token{kind: '?'})
+		case '*':
+			if len(tokens) == 0 || tokens[len(tokens)-1].kind != '*' {
+				tokens = append(tokens, token{kind: '*'})
+			}
+		default:
+			tokens = append(tokens, token{kind: 'l', lit: p[i]})
+		}
+	}
+
+	dp := make([][]bool, len(tokens)+1)
+	for i := range dp {
+		dp[i] = make([]bool, len(t)+1)
+	}
+	dp[0][0] = true
+
+	for i := 1; i <= len(tokens); i++ {
+		tok := tokens[i-1]
+		if tok.kind == '*' {
+			dp[i][0] = dp[i-1][0]
+		}
+
+		for j := 1; j <= len(t); j++ {
+			switch tok.kind {
+			case '*':
+				dp[i][j] = dp[i-1][j] || dp[i][j-1]
+			case '?':
+				dp[i][j] = dp[i-1][j-1]
+			case 'l':
+				dp[i][j] = dp[i-1][j-1] && tok.lit == t[j-1]
+			}
+		}
+	}
+
+	return dp[len(tokens)][len(t)]
+}
