+package listops
+
+import "fmt"
+
+// Chunk splits nums into consecutive sub-slices of length size. The final
+// chunk may be shorter. A non-positive size is an error.
+func Chunk(nums []int, size int) ([][]int, error) {
+	if size <= 0 {
+		return nil, fmt.Errorf("chunk size must be positive, got %d", size)
+	}
+
+	capacity := (len(nums) + size - 1) / size
+	chunks := make([][]int, 0, capacity)
+	for i := 0; i < len(nums); i += size {
+		end := i + size
+		if end > len(nums) {
+			end = len(nums)
+		}
+		chunk := make([]int, end-i)
+		copy(chunk, nums[i:end])
+		chunks = append(chunks, chunk)
+	}
+	return chunks, nil
+}
+
+// Compact removes consecutive duplicate values from nums.
+func Compact(nums []int) []int {
+	out := make([]int, 0, len(nums))
+	for i, v := range nums {
+		if i == 0 || v != nums[i-1] {
+			out = append(out, v)
+		}
+	}
+	return out
+}
+
+// RotateLeft returns a new slice with nums rotated left by n positions.
+func RotateLeft(nums []int, n int) []int {
+	length := len(nums)
+	out := make([]int, length)
+	if length == 0 {
+		return out
+	}
+
+	shift := ((n % length) + length) % length
+	for i := 0; i < length; i++ {
+		out[i] = nums[(i+shift)%length]
+	}
+	return out
+}
