+import (
+	"container/list"
+	"sync"
+	"time"
+)
+
+type Stats struct {
+	Hits      int
+	Misses    int
+	Evictions int
+}
+
+type entry struct {
+	key       string
+	value     string
+	expiresAt time.Time
+}
+
+type call struct {
+	done  chan struct{}
+	value string
+	err   error
+}
+
+type Memo struct {
+	mu       sync.Mutex
+	capacity int
+	ttl      time.Duration
+	entries  map[string]*list.Element
+	lru      *list.List
+	calls    map[string]*call
+	stats    Stats
+}
+
+func New(capacity int, ttl time.Duration) *Memo {
+	if capacity <= 0 {
+		panic("memo: capacity must be positive")
+	}
+
+	return &Memo{
+		capacity: capacity,
+		ttl:      ttl,
+		entries:  make(map[string]*list.Element),
+		lru:      list.New(),
+		calls:    make(map[string]*call),
+	}
+}
+
+func (m *Memo) Get(key string, compute func() (string, error)) (string, error) {
+	m.mu.Lock()
+	now := time.Now()
+
+	if el, ok := m.entries[key]; ok {
+		e := el.Value.(*entry)
+		if m.ttl <= 0 || now.Before(e.expiresAt) {
+			m.stats.Hits++
+			m.lru.MoveToFront(el)
+			value := e.value
+			m.mu.Unlock()
+			return value, nil
+		}
+		m.removeElementLocked(el)
+	}
+
+	m.stats.Misses++
+
+	if c, ok := m.calls[key]; ok {
+		m.mu.Unlock()
+		<-c.done
+		return c.value, c.err
+	}
+
+	c := &call{done: make(chan struct{})}
+	m.calls[key] = c
+	m.mu.Unlock()
+
+	value, err := compute()
+
+	m.mu.Lock()
+	c.value = value
+	c.err = err
+	delete(m.calls, key)
+
+	if err == nil {
+		m.storeLocked(key, value)
+	}
+
+	close(c.done)
+	m.mu.Unlock()
+
+	return value, err
+}
+
+func (m *Memo) Invalidate(key string) {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	if el, ok := m.entries[key]; ok {
+		m.removeElementLocked(el)
+	}
+}
+
+func (m *Memo) Clear() {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	m.entries = make(map[string]*list.Element)
+	m.lru.Init()
+}
+
+func (m *Memo) Stats() Stats {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	return m.stats
+}
+
+func (m *Memo) removeElementLocked(el *list.Element) {
+	e := el.Value.(*entry)
+	delete(m.entries, e.key)
+	m.lru.Remove(el)
+}
+
+func (m *Memo) storeLocked(key, value string) {
+	var expiresAt time.Time
+	if m.ttl > 0 {
+		expiresAt = time.Now().Add(m.ttl)
+	}
+
+	if el, ok := m.entries[key]; ok {
+		e := el.Value.(*entry)
+		e.value = value
+		e.expiresAt = expiresAt
+		m.lru.MoveToFront(el)
+		return
+	}
+
+	e := &entry{
+		key:       key,
+		value:     value,
+		expiresAt: expiresAt,
+	}
+	el := m.lru.PushFront(e)
+	m.entries[key] = el
+
+	for len(m.entries) > m.capacity {
+		back := m.lru.Back()
+		if back == nil {
+			break
+		}
+		m.removeElementLocked(back)
+		m.stats.Evictions++
+	}
+}
