+// CountPaths returns the number of right/down paths from the top-left cell
+// to the bottom-right cell.
+func CountPaths(grid []string) int {
+	if len(grid) == 0 {
+		return 0
+	}
+
+	width := len(grid[0])
+	if width == 0 {
+		return 0
+	}
+
+	for _, row := range grid {
+		if len(row) != width {
+			return 0
+		}
+		for i := 0; i < width; i++ {
+			if row[i] != '.' && row[i] != '#' {
+				return 0
+			}
+		}
+	}
+
+	if grid[0][0] == '#' || grid[len(grid)-1][width-1] == '#' {
+		return 0
+	}
+
+	dp := make([]int, width)
+	dp[0] = 1
+
+	for r := 0; r < len(grid); r++ {
+		for c := 0; c < width; c++ {
+			if grid[r][c] == '#' {
+				dp[c] = 0
+				continue
+			}
+			if c > 0 {
+				dp[c] += dp[c-1]
+			}
+		}
+	}
+
+	return dp[width-1]
