+	setB := toSet(b)
+	intersection := make(map[int]struct{})
+	for _, value := range a {
+		if _, ok := setB[value]; ok {
+			intersection[value] = struct{}{}
+		}
+	}
+	return sortedKeys(intersection)
+}
+
+// Difference returns the sorted unique values that occur in a but not b.
+func Difference(a, b []int) []int {
+	setB := toSet(b)
+	difference := make(map[int]struct{})
+	for _, value := range a {
+		if _, ok := setB[value]; !ok {
+			difference[value] = struct{}{}
+		}
+	}
+	return sortedKeys(difference)
+}
+
+// SymmetricDifference returns the sorted unique values that occur in exactly one of a or b.
+func SymmetricDifference(a, b []int) []int {
+	setA := toSet(a)
+	setB := toSet(b)
+	result := make(map[int]struct{})
+	for value := range setA {
+		if _, ok := setB[value]; !ok {
+			result[value] = struct{}{}
+		}
+	}
+	for value := range setB {
+		if _, ok := setA[value]; !ok {
+			result[value] = struct{}{}
+		}
+	}
+	return sortedKeys(result)
+}
+
+// IsSubset reports whether every unique value in a also occurs in b.
+func IsSubset(a, b []int) bool {
+	setB := toSet(b)
+	for _, value := range a {
+		if _, ok := setB[value]; !ok {
+			return false
+		}
+	}
+	return true
+}
+
+// Equal reports whether a and b contain exactly the same unique values.
+func Equal(a, b []int) bool {
+	return IsSubset(a, b) && IsSubset(b, a)
+}
