+package playlist
+
+func RotatePlaylist(songs []string, steps int) []string {
+	result := make([]string, len(songs))
+	n := len(songs)
+	if n == 0 {
+		return result
+	}
+
+	steps %= n
+	if steps < 0 {
+		steps += n
+	}
+
+	for i, song := range songs {
+		result[(i+steps)%n] = song
+	}
+
+	return result
+}
+
+func DeduplicatePlaylist(songs []string) []string {
+	result := make([]string, 0, len(songs))
+	seen := make(map[string]bool, len(songs))
+
+	for _, song := range songs {
+		if seen[song] {
+			continue
+		}
+		seen[song] = true
+		result = append(result, song)
+	}
+
+	return result
+}
+
+func InterleavePlaylists(first, second []string) []string {
+	result := make([]string, 0, len(first)+len(second))
+	maxLen := len(first)
+	if len(second) > maxLen {
+		maxLen = len(second)
+	}
+
+	for i := 0; i < maxLen; i++ {
+		if i < len(first) {
+			result = append(result, first[i])
+		}
+		if i < len(second) {
+			result = append(result, second[i])
+		}
+	}
+
+	return result
+}
+
+func ChunkPlaylist(songs []string, size int) [][]string {
+	if size <= 0 {
+		return nil
+	}
+
+	chunks := make([][]string, 0)
+
+	for start := 0; start < len(songs); start += size {
+		end := start + size
+		if end > len(songs) {
+			end = len(songs)
+		}
+
+		chunk := make([]string, end-start)
+		copy(chunk, songs[start:end])
+		chunks = append(chunks, chunk)
+	}
+
+	return chunks
+}
