+	ErrInvalidRate       = errors.New("interest rate must not be negative")
+)
+
+const (
+	kindDeposit     = "deposit"
+	kindWithdraw    = "withdraw"
+	kindTransferOut = "transfer-out"
+	kindTransferIn  = "transfer-in"
+	kindInterest    = "interest"
+)
+
+// Transaction records a single movement on an account.
+type Transaction struct {
+	Kind    string
+	Amount  int64
+	Balance int64
+}
+
+// Account is a bank account.
+type Account struct {
+	owner   string
+	balance int64
+	closed  bool
+	history []Transaction
+}
+
+// NewAccount creates an open account owned by owner.
+func NewAccount(owner string, initialDeposit int64) (*Account, error) {
+	if initialDeposit < 0 {
+		return nil, ErrInvalidAmount
+	}
+	return &Account{owner: owner, balance: initialDeposit}, nil
+}
+
+// Owner returns the account owner.
+func (a *Account) Owner() string {
+	return a.owner
+}
+
+// Balance returns the current balance.
+func (a *Account) Balance() int64 {
+	return a.balance
+}
+
+// Closed reports whether the account has been closed.
+func (a *Account) Closed() bool {
+	return a.closed
+}
+
+// History returns a copy of the recorded transactions, oldest first.
+func (a *Account) History() []Transaction {
+	out := make([]Transaction, len(a.history))
+	copy(out, a.history)
+	return out
+}
+
+// record appends a transaction using the current balance.
+func (a *Account) record(kind string, amount int64) {
+	a.history = append(a.history, Transaction{
+		Kind:    kind,
+		Amount:  amount,
+		Balance: a.balance,
+	})
+}
+
+// Deposit credits amount to the account.
+func (a *Account) Deposit(amount int64) error {
+	if amount <= 0 {
+		return ErrInvalidAmount
+	}
+	if a.closed {
+		return ErrAccountClosed
+	}
+	a.balance += amount
+	a.record(kindDeposit, amount)
+	return nil
+}
+
+// Withdraw debits amount from the account.
+func (a *Account) Withdraw(amount int64) error {
+	if amount <= 0 {
+		return ErrInvalidAmount
+	}
+	if a.closed {
+		return ErrAccountClosed
+	}
+	if amount > a.balance {
+		return ErrInsufficientFunds
+	}
+	a.balance -= amount
+	a.record(kindWithdraw, amount)
+	return nil
+}
+
+// Close marks the account as closed.
+func (a *Account) Close() error {
+	if a.closed {
+		return ErrAccountClosed
+	}
+	if a.balance != 0 {
+		return ErrNonZeroBalance
+	}
+	a.closed = true
+	return nil
+}
+
+// Transfer moves amount from one account to another atomically.
+func Transfer(from, to *Account, amount int64) error {
+	if amount <= 0 {
+		return ErrInvalidAmount
+	}
+	if from == to {
+		return ErrSameAccount
+	}
+	if from.closed || to.closed {
+		return ErrAccountClosed
+	}
+	if from.balance < amount {
+		return ErrInsufficientFunds
+	}
+
+	from.balance -= amount
+	from.record(kindTransferOut, amount)
+	to.balance += amount
+	to.record(kindTransferIn, amount)
+	return nil
+}
+
+// Banker is implemented by every kind of account.
+type Banker interface {
+	Deposit(int64) error
+	Withdraw(int64) error
+	Balance() int64
+}
+
+// TotalBalance sums the balances of all given accounts.
+func TotalBalance(accounts []Banker) int64 {
+	var total int64
+	for _, acc := range accounts {
+		total += acc.Balance()
+	}
+	return total
+}
+
+// SavingsAccount is an account that accrues interest.
+type SavingsAccount struct {
+	Account
+	rateBps int64
+}
+
+// NewSavingsAccount creates a savings account with a rate in basis points.
+func NewSavingsAccount(owner string, initialDeposit, rateBps int64) (*SavingsAccount, error) {
+	if rateBps < 0 {
+		return nil, ErrInvalidRate
+	}
+	if initialDeposit < 0 {
+		return nil, ErrInvalidAmount
+	}
+	return &SavingsAccount{
+		Account: Account{owner: owner, balance: initialDeposit},
+		rateBps: rateBps,
+	}, nil
+}
+
+// AddInterest credits one period of interest and returns the amount credited.
+func (s *SavingsAccount) AddInterest() (int64, error) {
+	if s.closed {
+		return 0, ErrAccountClosed
+	}
+	interest := s.balance * s.rateBps / 10000
+	if interest == 0 {
+		return 0, nil
+	}
+	s.balance += interest
+	s.record(kindInterest, interest)
+	return interest, nil
+}
