+type Fraction struct {
+	rat *big.Rat
+}
+
+func New(numerator, denominator int64) (Fraction, error) {
+	if denominator == 0 {
+		return Fraction{}, ErrZeroDenominator
+	}
+	return Fraction{rat: new(big.Rat).SetFrac(big.NewInt(numerator), big.NewInt(denominator))}, nil
+}
+
+func (f Fraction) value() *big.Rat {
+	if f.rat == nil {
+		return new(big.Rat)
+	}
+	return f.rat
+}
+
+func (f Fraction) String() string {
+	return f.value().RatString()
+}
+
+func (f Fraction) Add(other Fraction) Fraction {
+	return Fraction{rat: new(big.Rat).Add(f.value(), other.value())}
+}
+
+func (f Fraction) Sub(other Fraction) Fraction {
+	return Fraction{rat: new(big.Rat).Sub(f.value(), other.value())}
+}
+
+func (f Fraction) Mul(other Fraction) Fraction {
+	return Fraction{rat: new(big.Rat).Mul(f.value(), other.value())}
+}
+
+func (f Fraction) Div(other Fraction) (Fraction, error) {
+	if other.value().Sign() == 0 {
+		return Fraction{}, ErrDivisionByZero
+	}
+	return Fraction{rat: new(big.Rat).Quo(f.value(), other.value())}, nil
+}
+
+func (f Fraction) Equal(other Fraction) bool {
+	return f.value().Cmp(other.value()) == 0
+}
+
+func (f Fraction) Round(mode RoundingMode) (int64, error) {
+	if mode < ToZero || mode > NearestTiesToOdd {
+		return 0, ErrInvalidRoundingMode
+	}
+
+	r := f.value()
+	n := r.Num()
+	d := r.Denom()
+
+	q := new(big.Int)
+	rem := new(big.Int)
+	q.QuoRem(n, d, rem)
+
+	result := new(big.Int).Set(q)
+	if rem.Sign() == 0 {
+		if !result.IsInt64() {
+			return 0, ErrOutOfRange
+		}
+		return result.Int64(), nil
+	}
+
+	sign := 1
+	if n.Sign() < 0 {
+		sign = -1
+	}
+
+	switch mode {
+	case ToZero:
+	case AwayFromZero:
+		result.Add(result, big.NewInt(int64(sign)))
+	case Floor:
+		if sign < 0 {
+			result.Sub(result, big.NewInt(1))
+		}
+	case Ceiling:
+		if sign > 0 {
+			result.Add(result, big.NewInt(1))
+		}
+	case NearestTiesToZero, NearestTiesAwayFromZero, NearestTiesToEven, NearestTiesToOdd:
+		twiceRem := new(big.Int).Abs(rem)
+		twiceRem.Lsh(twiceRem, 1)
+		switch twiceRem.Cmp(d) {
+		case -1:
+			// The fraction is closer to the truncated quotient.
+		case 1:
+			result.Add(result, big.NewInt(int64(sign)))
+		case 0:
+			switch mode {
+			case NearestTiesToZero:
+				// The truncated quotient is already toward zero.
+			case NearestTiesAwayFromZero:
+				result.Add(result, big.NewInt(int64(sign)))
+			case NearestTiesToEven:
+				if isOdd(result) {
+					result.Add(result, big.NewInt(int64(sign)))
+				}
+			case NearestTiesToOdd:
+				if !isOdd(result) {
+					result.Add(result, big.NewInt(int64(sign)))
+				}
+			}
+		}
+	}
+
+	if !result.IsInt64() {
+		return 0, ErrOutOfRange
+	}
+	return result.Int64(), nil
+}
+
+func isOdd(x *big.Int) bool {
+	abs := new(big.Int).Abs(x)
+	return abs.Bit(0) == 1
+}
