+package modularsqrt
+
+// ModSqrt returns the smaller non-negative square root of a modulo the prime p.
+// The boolean result reports whether a square root exists.
+func ModSqrt(a, p int64) (int64, bool) {
+	if p <= 1 {
+		return 0, false
+	}
+
+	a = normalize(a, p)
+
+	if a == 0 {
+		return 0, true
+	}
+
+	if p == 2 {
+		return a, true
+	}
+
+	if modPow(a, (p-1)/2, p) != 1 {
+		return 0, false
+	}
+
+	q := p - 1
+	s := int64(0)
+	for q%2 == 0 {
+		q /= 2
+		s++
+	}
+
+	z := int64(2)
+	for modPow(z, (p-1)/2, p) != p-1 {
+		z++
+	}
+
+	c := modPow(z, q, p)
+	x := modPow(a, (q+1)/2, p)
+	t := modPow(a, q, p)
+	m := s
+
+	for t != 1 {
+		i := int64(1)
+		t2 := (t * t) % p
+
+		for t2 != 1 {
+			t2 = (t2 * t2) % p
+			i++
+			if i >= m {
+				return 0, false
+			}
+		}
+
+		b := c
+		for j := int64(0); j < m-i-1; j++ {
+			b = (b * b) % p
+		}
+
+		x = (x * b) % p
+		t = (t * b % p) * b % p
+		c = (b * b) % p
+		m = i
+	}
+
+	if x > p-x {
+		x = p - x
+	}
+
+	return x, true
+}
+
+func normalize(a, p int64) int64 {
+	r := a % p
+	if r < 0 {
+		r += p
+	}
+	return r
+}
+
+func modPow(base, exp, mod int64) int64 {
+	result := int64(1) % mod
+	base %= mod
+
+	for exp > 0 {
+		if exp&1 == 1 {
+			result = (result * base) % mod
+		}
+		base = (base * base) % mod
+		exp >>= 1
+	}
+
+	return result
+}
