+package morton
+
+func EncodeZ(x, y uint32) uint64 {
+	var code uint64
+	for i := 0; i < 32; i++ {
+		code |= uint64((x>>i)&1) << (2 * i)
+		code |= uint64((y>>i)&1) << (2*i + 1)
+	}
+	return code
