+func DecodeZ(code uint64) (uint32, uint32) {
+	var x, y uint32
+	for i := 0; i < 32; i++ {
+		x |= uint32((code>>(2*i))&1) << i
+		y |= uint32((code>>(2*i+1))&1) << i
+	}
+	return x, y
+}
+
+func GrayEncode(n uint64) uint64 {
+	return n ^ (n >> 1)
+}
+
+func GrayDecode(g uint64) uint64 {
+	n := g
+	for shift := uint(1); shift < 64; shift <<= 1 {
+		n ^= n >> shift
+	}
+	return n
