+func NextGeneration(grid [][]bool) [][]bool {
+	if len(grid) == 0 {
+		return [][]bool{}
+	}
+	rows := len(grid)
+	cols := len(grid[0])
+	next := make([][]bool, rows)
+	for i := range next {
+		next[i] = make([]bool, cols)
+	}
+	for r := 0; r < rows; r++ {
+		for c := 0; c < cols; c++ {
