+package memoize
+
+import (
+	"container/list"
+	"sync"
+)
+
+type cacheEntry struct {
+	key   string
+	value string
+}
+
+type inflight struct {
+	done  chan struct{}
+	value string
+	err   error
+}
+
+type Cache struct {
+	mu       sync.Mutex
+	capacity int
+	entries  map[string]*list.Element
+	order    *list.List
+	calls    map[string]*inflight
+}
+
+func New(capacity int) *Cache {
+	if capacity <= 0 {
+		panic("memoize: capacity must be positive")
+	}
+	return &Cache{
+		capacity: capacity,
+		entries:  make(map[string]*list.Element),
+		order:    list.New(),
+		calls:    make(map[string]*inflight),
+	}
+}
+
+func (c *Cache) Get(key string, compute func() (string, error)) (string, error) {
+	c.mu.Lock()
+	if elem, ok := c.entries[key]; ok {
+		c.order.MoveToFront(elem)
+		value := elem.Value.(*cacheEntry).value
+		c.mu.Unlock()
+		return value, nil
+	}
+
+	if call, ok := c.calls[key]; ok {
+		c.mu.Unlock()
+		<-call.done
+		return call.value, call.err
+	}
+
+	call := &inflight{done: make(chan struct{})}
+	c.calls[key] = call
+	c.mu.Unlock()
+
+	value, err := compute()
+
+	c.mu.Lock()
+	delete(c.calls, key)
+	if err == nil {
+		elem := c.order.PushFront(&cacheEntry{key: key, value: value})
+		c.entries[key] = elem
+		if c.order.Len() > c.capacity {
+			oldest := c.order.Back()
+			if oldest != nil {
+				evicted := oldest.Value.(*cacheEntry)
+				delete(c.entries, evicted.key)
+				c.order.Remove(oldest)
+			}
+		}
+	}
+	call.value = value
+	call.err = err
+	close(call.done)
+	c.mu.Unlock()
+
+	return value, err
+}
