+import (
+	"container/list"
+	"sync"
+)
+
+type ComputeFunc func(string) (int, error)
+
+type Stats struct {
+	Hits      int
+	Misses    int
+	Evictions int
+}
+
+type cacheEntry struct {
+	key   string
+	value int
+}
+
+type MemoCache struct {
+	mu        sync.Mutex
+	fn        ComputeFunc
+	capacity  int
+	order     *list.List
+	items     map[string]*list.Element
+	hits      int
+	misses    int
+	evictions int
+}
+
+func New(fn ComputeFunc, capacity int) *MemoCache {
+	return &MemoCache{
+		fn:       fn,
+		capacity: capacity,
+		order:    list.New(),
+		items:    make(map[string]*list.Element),
+	}
+}
+
+func (c *MemoCache) Get(key string) (int, error) {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+
+	if c.capacity > 0 {
+		if elem, ok := c.items[key]; ok {
+			c.hits++
+			c.order.MoveToFront(elem)
+			return elem.Value.(*cacheEntry).value, nil
+		}
+	}
+
+	c.misses++
+	value, err := c.fn(key)
+	if err != nil {
+		return value, err
+	}
+
+	if c.capacity <= 0 {
+		return value, nil
+	}
+
+	if elem, ok := c.items[key]; ok {
+		c.order.MoveToFront(elem)
+		elem.Value.(*cacheEntry).value = value
+		return value, nil
+	}
+
+	if c.order.Len() >= c.capacity {
+		oldest := c.order.Back()
+		if oldest != nil {
+			entry := oldest.Value.(*cacheEntry)
+			delete(c.items, entry.key)
+			c.order.Remove(oldest)
+			c.evictions++
+		}
+	}
+
+	elem := c.order.PushFront(&cacheEntry{key: key, value: value})
+	c.items[key] = elem
+	return value, nil
+}
