+package gridpath
+
+import "errors"
+
+var ErrInvalidGrid = errors.New("invalid grid")
+var ErrNoPath = errors.New("no path to all keys")
+
+func ShortestPathToCollectKeys(grid []string) (int, error) {
+	if len(grid) == 0 {
+		return 0, ErrInvalidGrid
+	}
+
+	cols := len(grid[0])
+	if cols == 0 {
+		return 0, ErrInvalidGrid
+	}
+
+	startRow, startCol := -1, -1
+	keyIndex := make(map[byte]int)
+
+	for row, line := range grid {
+		if len(line) != cols {
+			return 0, ErrInvalidGrid
+		}
+		for col := 0; col < cols; col++ {
+			ch := line[col]
+			switch {
+			case ch == '@':
+				if startRow != -1 {
+					return 0, ErrInvalidGrid
+				}
+				startRow, startCol = row, col
+			case ch >= 'a' && ch <= 'z':
+				if _, exists := keyIndex[ch]; exists {
+					return 0, ErrInvalidGrid
+				}
+				keyIndex[ch] = len(keyIndex)
+			case ch == '.' || ch == '#':
+			case ch >= 'A' && ch <= 'Z':
+			default:
+				return 0, ErrInvalidGrid
+			}
+		}
+	}
+
+	if startRow == -1 {
+		return 0, ErrInvalidGrid
+	}
+	if len(keyIndex) == 0 {
+		return 0, nil
+	}
+
+	type state struct {
+		row  int
+		col  int
+		mask int
+	}
+	type node struct {
+		state state
+		dist  int
+	}
+
+	fullMask := (1 << len(keyIndex)) - 1
+	start := state{row: startRow, col: startCol, mask: 0}
+	queue := []node{{state: start, dist: 0}}
+	visited := map[state]bool{start: true}
+	directions := [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
+
+	for len(queue) > 0 {
+		cur := queue[0]
+		queue = queue[1:]
+
+		if cur.state.mask == fullMask {
+			return cur.dist, nil
+		}
+
+		for _, d := range directions {
+			nextRow := cur.state.row + d[0]
+			nextCol := cur.state.col + d[1]
+
+			if nextRow < 0 || nextRow >= len(grid) || nextCol < 0 || nextCol >= cols {
+				continue
+			}
+
+			ch := grid[nextRow][nextCol]
+			if ch == '#' {
+				continue
+			}
+
+			if ch >= 'A' && ch <= 'Z' {
+				key := ch - 'A' + 'a'
+				idx, ok := keyIndex[key]
+				if !ok || cur.state.mask&(1<<idx) == 0 {
+					continue
+				}
+			}
+
+			nextMask := cur.state.mask
+			if ch >= 'a' && ch <= 'z' {
+				idx := keyIndex[ch]
+				nextMask |= 1 << idx
+			}
+
+			next := state{row: nextRow, col: nextCol, mask: nextMask}
+			if visited[next] {
+				continue
+			}
+			visited[next] = true
+			queue = append(queue, node{state: next, dist: cur.dist + 1})
+		}
+	}
+
+	return 0, ErrNoPath
+}
