+// LegendreSymbol returns the Legendre symbol (a/p) for an odd prime p.
+//
+// It returns 0 when a is divisible by p, 1 when a is a non-zero quadratic
+// residue modulo p, and -1 when a is a quadratic non-residue modulo p.
+func LegendreSymbol(a, p int64) int {
+	a = mod(a, p)
+	if a == 0 {
+		return 0
+	}
+	if powMod(a, (p-1)/2, p) == 1 {
+		return 1
+	}
+	return -1
+}
+
+// ModSqrt returns the smallest non-negative x such that x*x ≡ a (mod p),
+// or -1 when a is not a quadratic residue modulo p.
+func ModSqrt(a, p int64) int64 {
+	a = mod(a, p)
+	if a == 0 {
+		return 0
+	}
+	if LegendreSymbol(a, p) != 1 {
+		return -1
+	}
+
+	var r int64
+	if p%4 == 3 {
+		r = powMod(a, (p+1)/4, p)
+	} else {
+		r = tonelliShanks(a, p)
+	}
+	if r > p-r {
+		r = p - r
+	}
+	return r
+}
+
+// tonelliShanks finds a square root of a modulo the odd prime p, where a is
+// known to be a non-zero quadratic residue and p ≡ 1 (mod 4).
+func tonelliShanks(a, p int64) int64 {
+	// Write p-1 = q * 2^s with q odd.
+	q := p - 1
+	s := 0
+	for q%2 == 0 {
+		q /= 2
+		s++
+	}
+
+	// Find a quadratic non-residue to generate the 2-Sylow subgroup.
+	z := int64(2)
+	for LegendreSymbol(z, p) != -1 {
+		z++
+	}
+
+	m := s
+	c := powMod(z, q, p)
+	t := powMod(a, q, p)
+	r := powMod(a, (q+1)/2, p)
+
+	for t != 1 {
+		// Least i > 0 with t^(2^i) ≡ 1.
+		i := 1
+		tt := t * t % p
+		for tt != 1 {
+			tt = tt * tt % p
+			i++
+		}
+		b := powMod(c, int64(1)<<uint(m-i-1), p)
+		r = r * b % p
+		c = b * b % p
+		t = t * c % p
+		m = i
+	}
+	return r
