+
+var (
+	ErrConflict      = errors.New("conflicting records")
+	ErrInvalidRecord = errors.New("invalid record")
+)
+
+type Record struct {
+	Key       string
+	Revision  int
+	UpdatedAt int64
+	Deleted   bool
+	Value     string
+	Tags      []string
+}
+
+func MergeRecords(batches [][]Record) ([]Record, error) {
+	groups := make(map[string][]Record)
+
+	for _, batch := range batches {
+		for _, record := range batch {
+			if record.Key == "" || record.Revision < 0 {
+				return nil, ErrInvalidRecord
+			}
+			groups[record.Key] = append(groups[record.Key], record)
+		}
+	}
+
+	keys := make([]string, 0, len(groups))
+	for key := range groups {
+		keys = append(keys, key)
+	}
+	sort.Strings(keys)
+
+	result := make([]Record, 0, len(groups))
+
+	for _, key := range keys {
+		records := groups[key]
+
+		maxRevision := records[0].Revision
+		for _, record := range records {
+			if record.Revision > maxRevision {
+				maxRevision = record.Revision
+			}
+		}
+
+		var maxUpdatedAt int64
+		foundUpdatedAt := false
+		for _, record := range records {
+			if record.Revision != maxRevision {
+				continue
+			}
+			if !foundUpdatedAt || record.UpdatedAt > maxUpdatedAt {
+				maxUpdatedAt = record.UpdatedAt
+				foundUpdatedAt = true
+			}
+		}
+
+		var winner Record
+		foundWinner := false
+
+		for _, record := range records {
+			if record.Revision != maxRevision || record.UpdatedAt != maxUpdatedAt {
+				continue
+			}
+
+			if !foundWinner {
+				winner = record
+				foundWinner = true
+				continue
+			}
+
+			if winner.Value != record.Value || winner.Deleted != record.Deleted {
+				return nil, ErrConflict
+			}
+		}
+
+		if winner.Deleted {
+			continue
+		}
+
+		tagSet := make(map[string]struct{})
+		for _, record := range records {
+			if record.Deleted {
+				continue
+			}
+			for _, tag := range record.Tags {
+				if tag != "" {
+					tagSet[tag] = struct{}{}
+				}
+			}
+		}
+
+		var tags []string
+		if len(tagSet) > 0 {
+			tags = make([]string, 0, len(tagSet))
+			for tag := range tagSet {
+				tags = append(tags, tag)
+			}
+			sort.Strings(tags)
+		}
+
+		result = append(result, Record{
+			Key:       key,
+			Revision:  maxRevision,
+			UpdatedAt: maxUpdatedAt,
+			Deleted:   false,
+			Value:     winner.Value,
+			Tags:      tags,
+		})
+	}
+
+	return result, nil
