+package filterparse
+
+import (
+	"errors"
+	"fmt"
+	"strings"
+)
+
+type Expr interface {
+	exprNode()
+}
+
+type Comparison struct {
+	Field string
+	Op    string
+	Value string
+}
+
+func (Comparison) exprNode() {}
+
+type Binary struct {
+	Op    string
+	Left  Expr
+	Right Expr
+}
+
+func (Binary) exprNode() {}
+
+type Not struct {
+	Expr Expr
+}
+
+func (Not) exprNode() {}
+
+func ParseFilter(input string) (Expr, error) {
+	tokens, err := lex(input)
+	if err != nil {
+		return nil, err
+	}
+
+	p := &parser{tokens: tokens}
+	if p.peek().kind == tokEOF {
+		return nil, errors.New("empty filter")
+	}
+
+	expr, err := p.parseOr()
+	if err != nil {
+		return nil, err
+	}
+	if p.peek().kind != tokEOF {
+		return nil, fmt.Errorf("unexpected token %q", p.peek().text)
+	}
+	return expr, nil
+}
+
+type tokenKind int
+
+const (
+	tokEOF tokenKind = iota
+	tokWord
+	tokString
+	tokOperator
+	tokAnd
+	tokOr
+	tokNot
+	tokLParen
+	tokRParen
+)
+
+type token struct {
+	kind tokenKind
+	text string
+}
+
+func lex(input string) ([]token, error) {
+	tokens := make([]token, 0)
+
+	for i := 0; i < len(input); {
+		c := input[i]
+		if isSpace(c) {
+			i++
+			continue
+		}
+
+		switch c {
+		case '(':
+			tokens = append(tokens, token{kind: tokLParen, text: "("})
+			i++
+		case ')':
+			tokens = append(tokens, token{kind: tokRParen, text: ")"})
+			i++
+		case '"':
+			value, n, err := scanQuoted(input[i:])
+			if err != nil {
+				return nil, err
+			}
+			tokens = append(tokens, token{kind: tokString, text: value})
+			i += n
+		case '=', '!', '>', '<':
+			op, n, err := scanOperator(input[i:])
+			if err != nil {
+				return nil, err
+			}
+			tokens = append(tokens, token{kind: tokOperator, text: op})
+			i += n
+		default:
+			if !isWordChar(c) {
+				return nil, fmt.Errorf("unexpected character %q", c)
+			}
+			start := i
+			for i < len(input) && isWordChar(input[i]) {
+				i++
+			}
+			word := input[start:i]
+			kind := tokWord
+			switch word {
+			case "AND":
+				kind = tokAnd
+			case "OR":
+				kind = tokOr
+			case "NOT":
+				kind = tokNot
+			}
+			tokens = append(tokens, token{kind: kind, text: word})
+		}
+	}
+
+	tokens = append(tokens, token{kind: tokEOF})
+	return tokens, nil
+}
+
+func scanQuoted(s string) (string, int, error) {
+	var b strings.Builder
+
+	for i := 1; i < len(s); {
+		c := s[i]
+		if c == '"' {
+			return b.String(), i + 1, nil
+		}
+		if c == '\\' {
+			i++
+			if i >= len(s) {
+				return "", 0, errors.New("unterminated escape sequence")
+			}
+			switch s[i] {
+			case '"':
+				b.WriteByte('"')
+			case '\\':
+				b.WriteByte('\\')
+			case 'n':
+				b.WriteByte('\n')
+			case 't':
+				b.WriteByte('\t')
+			case 'r':
+				b.WriteByte('\r')
+			default:
+				return "", 0, fmt.Errorf("invalid escape sequence \\%c", s[i])
+			}
+			i++
+			continue
+		}
+		if c == '\n' || c == '\r' {
+			return "", 0, errors.New("newline in quoted string")
+		}
+		b.WriteByte(c)
+		i++
+	}
+
+	return "", 0, errors.New("unterminated quoted string")
+}
+
+func scanOperator(s string) (string, int, error) {
+	if len(s) >= 2 {
+		two := s[:2]
+		switch two {
+		case "!=", ">=", "<=":
+			return two, 2, nil
+		}
+	}
+
+	switch s[0] {
+	case '=', '>', '<':
+		return s[:1], 1, nil
+	case '!':
+		return "", 0, errors.New("expected '=' after '!'")
+	default:
+		return "", 0, fmt.Errorf("unexpected operator character %q", s[0])
+	}
+}
+
+func isSpace(c byte) bool {
+	return c == ' ' || c == '\t' || c == '\n' || c == '\r'
+}
+
+func isASCIILetter(c byte) bool {
+	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
+}
+
+func isDigit(c byte) bool {
+	return c >= '0' && c <= '9'
+}
+
+func isWordChar(c byte) bool {
+	return isASCIILetter(c) || isDigit(c) || c == '_' || c == '.' || c == '-' || c == ':' || c == '/' || c == '@'
+}
+
+func validField(s string) bool {
+	if len(s) == 0 {
+		return false
+	}
+	if !isASCIILetter(s[0]) && s[0] != '_' {
+		return false
+	}
+	for i := 1; i < len(s); i++ {
+		c := s[i]
+		if !isASCIILetter(c) && !isDigit(c) && c != '_' && c != '.' && c != '-' {
+			return false
+		}
+	}
+	return true
+}
+
+type parser struct {
+	tokens []token
+	pos    int
+}
+
+func (p *parser) peek() token {
+	return p.tokens[p.pos]
+}
+
+func (p *parser) next() token {
+	t := p.tokens[p.pos]
+	p.pos++
+	return t
+}
+
+func (p *parser) match(kind tokenKind) bool {
+	if p.peek().kind == kind {
+		p.pos++
+		return true
+	}
+	return false
+}
+
+func (p *parser) expect(kind tokenKind, what string) (token, error) {
+	if p.peek().kind != kind {
+		return token{}, fmt.Errorf("expected %s, found %q", what, p.peek().text)
+	}
+	return p.next(), nil
+}
+
+func (p *parser) parseOr() (Expr, error) {
+	left, err := p.parseAnd()
+	if err != nil {
+		return nil, err
+	}
+
+	for p.match(tokOr) {
+		right, err := p.parseAnd()
+		if err != nil {
+			return nil, err
+		}
+		left = Binary{Op: "OR", Left: left, Right: right}
+	}
+	return left, nil
+}
+
+func (p *parser) parseAnd() (Expr, error) {
+	left, err := p.parseNot()
+	if err != nil {
+		return nil, err
+	}
+
+	for p.match(tokAnd) {
+		right, err := p.parseNot()
+		if err != nil {
+			return nil, err
+		}
+		left = Binary{Op: "AND", Left: left, Right: right}
+	}
+	return left, nil
+}
+
+func (p *parser) parseNot() (Expr, error) {
+	if p.match(tokNot) {
+		expr, err := p.parseNot()
+		if err != nil {
+			return nil, err
+		}
+		return Not{Expr: expr}, nil
+	}
+	return p.parsePrimary()
+}
+
+func (p *parser) parsePrimary() (Expr, error) {
+	if p.match(tokLParen) {
+		expr, err := p.parseOr()
+		if err != nil {
+			return nil, err
+		}
+		if _, err := p.expect(tokRParen, "closing parenthesis"); err != nil {
+			return nil, err
+		}
+		return expr, nil
+	}
+	return p.parseComparison()
+}
+
+func (p *parser) parseComparison() (Expr, error) {
+	fieldTok, err := p.expect(tokWord, "field name")
+	if err != nil {
+		return nil, err
+	}
+	if !validField(fieldTok.text) {
+		return nil, fmt.Errorf("invalid field name %q", fieldTok.text)
+	}
+
+	opTok, err := p.expect(tokOperator, "operator")
+	if err != nil {
+		return nil, err
+	}
+
+	var value string
+	switch p.peek().kind {
+	case tokWord:
+		value = p.next().text
+	case tokString:
+		value = p.next().text
+	default:
+		return nil, fmt.Errorf("expected value, found %q", p.peek().text)
+	}
+
+	return Comparison{Field: fieldTok.text, Op: opTok.text, Value: value}, nil
+}
