+}
+
+func (l *Library) ensureMaps() {
+	if l.books == nil {
+		l.books = make(map[string]*bookRecord)
+	}
+	if l.members == nil {
+		l.members = make(map[string]*memberRecord)
+	}
+}
+
+func (l *Library) AddBook(isbn, title string, copies int) error {
+	if isbn == "" || title == "" || copies < 1 {
+		return ErrInvalidBook
+	}
+
+	l.ensureMaps()
+
+	if book, ok := l.books[isbn]; ok {
+		if book.title != title {
+			return ErrBookConflict
+		}
+		book.copies += copies
+		book.available += copies
+		return nil
+	}
+
+	l.books[isbn] = &bookRecord{
+		isbn:      isbn,
+		title:     title,
+		copies:    copies,
+		available: copies,
+	}
+	return nil
+}
+
+func (l *Library) RegisterMember(id, name string) error {
+	if id == "" || name == "" {
+		return ErrInvalidMember
+	}
+
+	l.ensureMaps()
+
+	if _, ok := l.members[id]; ok {
+		return ErrMemberExists
+	}
+
+	l.members[id] = &memberRecord{
+		id:    id,
+		name:  name,
+		loans: make(map[string]bool),
+	}
+	return nil
+}
+
+func (l *Library) Borrow(memberID, isbn string) error {
+	l.ensureMaps()
+
+	member, ok := l.members[memberID]
+	if !ok {
+		return ErrMemberNotFound
+	}
+
+	book, ok := l.books[isbn]
+	if !ok {
+		return ErrBookNotFound
+	}
+
+	if member.loans[isbn] {
+		return ErrAlreadyBorrowed
+	}
+
+	if len(member.loans) >= 3 {
+		return ErrLoanLimit
+	}
+
+	if book.available < 1 {
+		return ErrNoCopies
+	}
+
+	book.available--
+	member.loans[isbn] = true
+	return nil
+}
+
+func (l *Library) Return(memberID, isbn string) error {
+	l.ensureMaps()
+
+	member, ok := l.members[memberID]
+	if !ok {
+		return ErrMemberNotFound
+	}
+
+	book, ok := l.books[isbn]
+	if !ok {
+		return ErrBookNotFound
+	}
+
+	if !member.loans[isbn] {
+		return ErrNotBorrowed
+	}
+
+	delete(member.loans, isbn)
+	book.available++
+	return nil
+}
+
+func (l *Library) AvailableCopies(isbn string) (int, error) {
+	l.ensureMaps()
+
+	book, ok := l.books[isbn]
+	if !ok {
+		return 0, ErrBookNotFound
+	}
+	return book.available, nil
+}
+
+func (l *Library) MemberLoans(memberID string) ([]string, error) {
+	l.ensureMaps()
+
+	member, ok := l.members[memberID]
+	if !ok {
+		return nil, ErrMemberNotFound
+	}
+
+	loans := make([]string, 0, len(member.loans))
+	for isbn := range member.loans {
+		loans = append(loans, isbn)
+	}
+	sort.Strings(loans)
+	return loans, nil
+}
