+	return countFrom(values, -1, memo), nil
+}
+
+func countFrom(counts []int, last int, memo map[string]int) int {
+	remaining := false
+	for _, count := range counts {
+		if count > 0 {
+			remaining = true
+			break
+		}
+	}
+	if !remaining {
+		return 1
+	}
+
+	key := stateKey(counts, last)
+	if result, ok := memo[key]; ok {
+		return result
+	}
+
+	total := 0
+	for i, count := range counts {
+		if count > 0 && i != last {
+			counts[i]--
+			total += countFrom(counts, i, memo)
+			counts[i]++
+		}
+	}
+
+	memo[key] = total
+	return total
+}
+
+func stateKey(counts []int, last int) string {
+	var builder strings.Builder
+
+	for _, count := range counts {
+		builder.WriteString(strconv.Itoa(count))
+		builder.WriteByte(',')
+	}
+	builder.WriteString(strconv.Itoa(last))
+
+	return builder.String()
