+package rotate
+
+import (
+	"strings"
+	"unicode"
+)
+
+func RotateMatrix(matrix [][]int, turns int) [][]int {
+	if matrix == nil {
+		return nil
+	}
+	if len(matrix) == 0 {
+		return [][]int{}
+	}
+
+	cols := len(matrix[0])
+	for _, row := range matrix {
+		if len(row) != cols {
+			return nil
+		}
+	}
+
+	turns = ((turns % 4) + 4) % 4
+	result := copyMatrix(matrix)
+	for i := 0; i < turns; i++ {
+		result = rotateOnce(result)
+	}
+	return result
+}
+
+func copyMatrix(matrix [][]int) [][]int {
+	result := make([][]int, len(matrix))
+	for i, row := range matrix {
+		result[i] = make([]int, len(row))
+		copy(result[i], row)
+	}
+	return result
+}
+
+func rotateOnce(matrix [][]int) [][]int {
+	rows := len(matrix)
+	if rows == 0 {
+		return [][]int{}
+	}
+
+	cols := len(matrix[0])
+	result := make([][]int, cols)
+	for r := 0; r < cols; r++ {
+		result[r] = make([]int, rows)
+		for c := 0; c < rows; c++ {
+			result[r][c] = matrix[rows-1-c][r]
+		}
+	}
+	return result
+}
+
+func ReverseWords(s string) string {
+	type token struct {
+		word bool
+		text string
+	}
+
+	runes := []rune(s)
+	tokens := make([]token, 0)
+	for i := 0; i < len(runes); {
+		j := i
+		isSpace := unicode.IsSpace(runes[i])
+		for j < len(runes) && unicode.IsSpace(runes[j]) == isSpace {
+			j++
+		}
+		tokens = append(tokens, token{
+			word: !isSpace,
+			text: string(runes[i:j]),
+		})
+		i = j
+	}
+
+	words := make([]string, 0)
+	for _, tok := range tokens {
+		if tok.word {
+			words = append(words, tok.text)
+		}
+	}
+	for i, j := 0, len(words)-1; i < j; i, j = i+1, j-1 {
+		words[i], words[j] = words[j], words[i]
+	}
+
+	var builder strings.Builder
+	wordIndex := 0
+	for _, tok := range tokens {
+		if tok.word {
+			builder.WriteString(words[wordIndex])
+			wordIndex++
+		} else {
+			builder.WriteString(tok.text)
+		}
+	}
+	return builder.String()
+}
