+package scheduling
+
+import "sort"
+
+type Interval struct {
+	Start int
+	End   int
+}
+
+func FindFreeSlots(busy []Interval, day Interval, duration int) []Interval {
+	free := []Interval{}
+	if duration <= 0 || day.End <= day.Start {
+		return free
+	}
+
+	clipped := make([]Interval, 0, len(busy))
+	for _, interval := range busy {
+		start := interval.Start
+		end := interval.End
+
+		if start < day.Start {
+			start = day.Start
+		}
+		if end > day.End {
+			end = day.End
+		}
+
+		if start < end {
+			clipped = append(clipped, Interval{Start: start, End: end})
+		}
+	}
+
+	sort.Slice(clipped, func(i, j int) bool {
+		if clipped[i].Start == clipped[j].Start {
+			return clipped[i].End < clipped[j].End
+		}
+		return clipped[i].Start < clipped[j].Start
+	})
+
+	merged := make([]Interval, 0, len(clipped))
+	for _, interval := range clipped {
+		if len(merged) == 0 || interval.Start > merged[len(merged)-1].End {
+			merged = append(merged, interval)
+			continue
+		}
+		if interval.End > merged[len(merged)-1].End {
+			merged[len(merged)-1].End = interval.End
+		}
+	}
+
+	cursor := day.Start
+	for _, interval := range merged {
+		if interval.Start-cursor >= duration {
+			free = append(free, Interval{Start: cursor, End: interval.Start})
+		}
+		if interval.End > cursor {
+			cursor = interval.End
+		}
+	}
+
+	if day.End-cursor >= duration {
+		free = append(free, Interval{Start: cursor, End: day.End})
+	}
+
+	return free
+}
