+		if !prefixSet[next] {
+			return
+		}
+		if wordSet[next] {
+			found[next] = true
+		}
+		used[r][c] = true
+		for dr := -1; dr <= 1; dr++ {
+			for dc := -1; dc <= 1; dc++ {
+				if dr == 0 && dc == 0 {
+					continue
+				}
+				dfs(r+dr, c+dc, next)
+			}
+		}
+		used[r][c] = false
+	}
+
+	for r := 0; r < rows; r++ {
+		for c := 0; c < cols; c++ {
+			dfs(r, c, "")
+		}
+	}
+
+	result := make([]string, 0, len(found))
+	for w := range found {
+		result = append(result, w)
+	}
+	sort.Strings(result)
+	return result
+}
