+package patternmatch
+
+// Match reports whether the entire text matches the pattern.
+func Match(pattern, text string) bool {
+    memo := make(map[[2]int]bool)
+    var match func(p, t int) bool
+    match = func(p, t int) bool {
+        key := [2]int{p, t}
+        if v, ok := memo[key]; ok {
+            return v
+        }
+        var res bool
+        if p == len(pattern) {
+            res = t == len(text)
+        } else {
+            switch pattern[p] {
+            case '*':
+                res = match(p+1, t) || (t < len(text) && match(p, t+1))
+            case '?':
+                res = t < len(text) && match(p+1, t+1)
+            case '[':
+                matcher, next, ok := parseClass(pattern, p)
+                if !ok {
+                    res = t < len(text) && text[t] == '[' && match(p+1, t+1)
+                } else {
+                    res = t < len(text) && matcher(text[t]) && match(next, t+1)
+                }
+            case '\\':
+                if p+1 < len(pattern) {
+                    res = t < len(text) && text[t] == pattern[p+1] && match(p+2, t+1)
+                } else {
+                    res = t < len(text) && text[t] == '\\' && match(p+1, t+1)
+                }
+            default:
+                res = t < len(text) && text[t] == pattern[p] && match(p+1, t+1)
+            }
+        }
+        memo[key] = res
+        return res
+    }
+    return match(0, 0)
+}
+
+func parseClass(pattern string, i int) (func(byte) bool, int, bool) {
+    i++ // skip '['
+    negate := false
+    if i < len(pattern) && (pattern[i] == '!' || pattern[i] == '^') {
+        negate = true
+        i++
+    }
+    var ranges [][2]byte
+    if i < len(pattern) && pattern[i] == ']' {
+        ranges = append(ranges, [2]byte{']', ']'})
+        i++
+    }
+    for {
+        if i >= len(pattern) {
+            return nil, 0, false
+        }
+        if pattern[i] == ']' {
+            i++
+            matcher := func(c byte) bool {
+                in := false
+                for _, r := range ranges {
+                    if c >= r[0] && c <= r[1] {
+                        in = true
+                        break
+                    }
+                }
+                if negate {
+                    return !in
+                }
+                return in
+            }
+            return matcher, i, true
+        }
+        var start byte
+        if pattern[i] == '\\' {
+            if i+1 < len(pattern) {
+                start = pattern[i+1]
+                i += 2
+            } else {
+                start = '\\'
+                i++
+            }
+        } else {
+            start = pattern[i]
+            i++
+        }
+        if i+1 < len(pattern) && pattern[i] == '-' && pattern[i+1] != ']' {
+            var end byte
+            if pattern[i+1] == '\\' {
+                if i+2 < len(pattern) {
+                    end = pattern[i+2]
+                    i += 3
+                } else {
+                    ranges = append(ranges, [2]byte{start, start})
+                    ranges = append(ranges, [2]byte{'-', '-'})
+                    continue
+                }
+            } else {
+                end = pattern[i+1]
+                i += 2
+            }
+            if start <= end {
+                ranges = append(ranges, [2]byte{start, end})
+            }
+        } else {
+            ranges = append(ranges, [2]byte{start, start})
+        }
+    }
+}
