+func DiagonalSum(matrix [][]int) (int, error) {
+	n := len(matrix)
+	for _, row := range matrix {
+		if len(row) != n {
+			return 0, errors.New("matrix is not square")
+		}
+	}
+	sum := 0
+	for i := 0; i < n; i++ {
+		sum += matrix[i][i]
+		sum += matrix[i][n-1-i]
