+			return "||", nil
+		}
+		return "", fmt.Errorf("line %d, column %d: invalid character", line, col)
+	default:
+		return "", fmt.Errorf("line %d, column %d: invalid character", line, col)
+	}
+}
+
+func isLetter(ch byte) bool {
+	return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z')
+}
+
+func isDigit(ch byte) bool {
+	return ch >= '0' && ch <= '9'
