+// Tokenize splits the input string into tokens separated by whitespace.
+// It returns a non-nil slice of non-empty tokens.
+func Tokenize(s string) []string {
+	tokens := []string{}
+	var current strings.Builder
+	for _, r := range s {
+		if r == ' ' || r == '\t' || r == '\n' || r == '\r' {
+			if current.Len() > 0 {
+				tokens = append(tokens, current.String())
+				current.Reset()
+			}
+		} else {
