+import "errors"
+
+type Point struct {
+	Row int
+	Col int
+}
+
+var (
+	ErrNoPath  = errors.New("no path")
+	ErrInvalid = errors.New("invalid start or end")
+)
+
+func ShortestPath(grid []string, start, end Point) (int, error) {
+	if len(grid) == 0 || len(grid[0]) == 0 {
+		return -1, ErrInvalid
+	}
+	rows := len(grid)
+	cols := len(grid[0])
+	if start.Row < 0 || start.Row >= rows || start.Col < 0 || start.Col >= cols {
+		return -1, ErrInvalid
+	}
+	if end.Row < 0 || end.Row >= rows || end.Col < 0 || end.Col >= cols {
+		return -1, ErrInvalid
+	}
+	if grid[start.Row][start.Col] == '#' || grid[end.Row][end.Col] == '#' {
+		return -1, ErrInvalid
+	}
+	if start == end {
+		return 0, nil
+	}
+
+	type node struct {
+		r, c, dist int
+	}
+	visited := make([][]bool, rows)
+	for i := range visited {
+		visited[i] = make([]bool, cols)
+	}
+	queue := []node{{start.Row, start.Col, 0}}
+	visited[start.Row][start.Col] = true
+	dirs := [4][2]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}
+
+	for len(queue) > 0 {
+		cur := queue[0]
+		queue = queue[1:]
+		for _, d := range dirs {
+			nr, nc := cur.r+d[0], cur.c+d[1]
+			if nr < 0 || nr >= rows || nc < 0 || nc >= cols {
+				continue
+			}
+			if visited[nr][nc] {
+				continue
+			}
+			if grid[nr][nc] == '#' {
+				continue
+			}
+			if nr == end.Row && nc == end.Col {
+				return cur.dist + 1, nil
+			}
+			visited[nr][nc] = true
+			queue = append(queue, node{nr, nc, cur.dist + 1})
+		}
+	}
