+		return []string{from}, 0, nil
+	}
+	nodes := g.Nodes()
+	const inf = int(^uint(0) >> 1)
+	dist := make(map[string]int, len(nodes))
+	path := make(map[string][]string, len(nodes))
+	visited := make(map[string]bool, len(nodes))
+	for _, n := range nodes {
+		dist[n] = inf
+	}
+	dist[from] = 0
+	path[from] = []string{from}
+
+	for {
+		current := ""
+		bestDist := inf
+		var bestPath []string
+		found := false
+		for _, n := range nodes {
+			if visited[n] {
+				continue
+			}
+			d, ok := dist[n]
+			if !ok || d == inf {
+				continue
+			}
+			if !found || d < bestDist || (d == bestDist && lessPath(path[n], bestPath)) {
