+package inventory
+
+import (
+	"errors"
+	"strconv"
+	"strings"
+)
+
+func UpdateInventory(events []string) (map[string]int, error) {
+	inventory := make(map[string]int)
+
+	for _, event := range events {
+		parts := strings.Split(event, " ")
+		if len(parts) != 3 {
+			return nil, errors.New("invalid event format")
+		}
+
+		operation, item, quantityText := parts[0], parts[1], parts[2]
+		if item == "" {
+			return nil, errors.New("invalid item")
+		}
+
+		quantity, ok := parsePositiveInt(quantityText)
+		if !ok {
+			return nil, errors.New("invalid quantity")
+		}
+
+		switch operation {
+		case "add":
+			inventory[item] += quantity
+		case "remove":
+			if inventory[item] < quantity {
+				return nil, errors.New("insufficient inventory")
+			}
+			inventory[item] -= quantity
+			if inventory[item] == 0 {
+				delete(inventory, item)
+			}
+		default:
+			return nil, errors.New("unknown operation")
+		}
+	}
+
+	return inventory, nil
+}
+
+func parsePositiveInt(text string) (int, bool) {
+	if text == "" {
+		return 0, false
+	}
+	for _, r := range text {
+		if r < '0' || r > '9' {
+			return 0, false
+		}
+	}
+	n, err := strconv.Atoi(text)
+	if err != nil || n <= 0 {
+		return 0, false
+	}
+	return n, true
+}
