+package ringrotation
+
+type cell struct {
+	row, col int
+}
+
+// Rotate returns a new matrix in which every concentric layer of matrix has
+// been rotated clockwise by k steps. Negative values of k rotate
+// counterclockwise. The input matrix is not modified.
+func Rotate(matrix [][]int, k int) [][]int {
+	if len(matrix) == 0 {
+		return nil
+	}
+
+	rows := len(matrix)
+	cols := len(matrix[0])
+
+	result := make([][]int, rows)
+	for r := 0; r < rows; r++ {
+		result[r] = make([]int, cols)
+	}
+	if cols == 0 {
+		return result
+	}
+
+	smallest := rows
+	if cols < smallest {
+		smallest = cols
+	}
+	layers := (smallest + 1) / 2
+
+	for layer := 0; layer < layers; layer++ {
+		ring := ringCells(rows, cols, layer)
+		if len(ring) == 0 {
+			continue
+		}
+		size := len(ring)
+		shift := ((k % size) + size) % size
+		for i, dst := range ring {
+			src := ring[(i-shift+size)%size]
+			result[dst.row][dst.col] = matrix[src.row][src.col]
+		}
+	}
+
+	return result
+}
+
+// ringCells lists the coordinates of one layer in clockwise order, starting
+// at the layer's top-left corner.
+func ringCells(rows, cols, layer int) []cell {
+	top, bottom := layer, rows-1-layer
+	left, right := layer, cols-1-layer
+	if top > bottom || left > right {
+		return nil
+	}
+
+	var ring []cell
+	for c := left; c <= right; c++ {
+		ring = append(ring, cell{top, c})
+	}
+	for r := top + 1; r <= bottom; r++ {
+		ring = append(ring, cell{r, right})
+	}
+	if bottom > top {
+		for c := right - 1; c >= left; c-- {
+			ring = append(ring, cell{bottom, c})
+		}
+	}
+	if right > left {
+		for r := bottom - 1; r > top; r-- {
+			ring = append(ring, cell{r, left})
+		}
+	}
+	return ring
+}
