+// ShortestPath returns the minimum number of steps from S to E in a grid.
+// It returns -1 if no path exists or the grid is invalid.
+func ShortestPath(grid []string) int {
+	if len(grid) == 0 {
+		return -1
+	}
+
+	rows := len(grid)
+	cols := len(grid[0])
+	if cols == 0 {
+		return -1
+	}
+
+	for _, row := range grid {
+		if len(row) != cols {
+			return -1
+		}
+	}
+
+	start := [2]int{-1, -1}
+	end := [2]int{-1, -1}
+	startCount := 0
+	endCount := 0
+
+	for r := 0; r < rows; r++ {
+		for c := 0; c < cols; c++ {
+			switch grid[r][c] {
+			case 'S':
+				startCount++
+				start = [2]int{r, c}
+			case 'E':
+				endCount++
+				end = [2]int{r, c}
+			case '.', '#':
+			default:
+				return -1
+			}
+		}
+	}
+
+	if startCount != 1 || endCount != 1 {
+		return -1
+	}
+
+	dist := make([][]int, rows)
+	for i := range dist {
+		dist[i] = make([]int, cols)
+		for j := range dist[i] {
+			dist[i][j] = -1
+		}
+	}
+
+	queue := [][2]int{start}
+	dist[start[0]][start[1]] = 0
+	dirs := [4][2]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}
+
+	for len(queue) > 0 {
+		cur := queue[0]
+		queue = queue[1:]
+
+		r, c := cur[0], cur[1]
+		if r == end[0] && c == end[1] {
+			return dist[r][c]
+		}
+
+		for _, d := range dirs {
+			nr, nc := r+d[0], c+d[1]
+			if nr < 0 || nr >= rows || nc < 0 || nc >= cols {
+				continue
+			}
+			if grid[nr][nc] == '#' {
+				continue
+			}
+			if dist[nr][nc] != -1 {
+				continue
+			}
+			dist[nr][nc] = dist[r][c] + 1
+			queue = append(queue, [2]int{nr, nc})
+		}
+	}
