+func parse(s string) (*version, error) {
+	// Split off build metadata
+	var buildMetadata []string
+	if idx := strings.Index(s, "+"); idx != -1 {
+		buildStr := s[idx+1:]
+		s = s[:idx]
+		if buildStr == "" {
+			return nil, errors.New("empty build metadata")
+		}
+		parts := strings.Split(buildStr, ".")
+		for _, p := range parts {
+			if p == "" {
+				return nil, errors.New("empty build metadata identifier")
+			}
+			if !isValidIdentifier(p) {
+				return nil, errors.New("invalid build metadata identifier")
+			}
+		}
+		buildMetadata = parts
+	}
+
+	// Split off pre-release
+	var preRelease []string
+	if idx := strings.Index(s, "-"); idx != -1 {
+		preStr := s[idx+1:]
+		s = s[:idx]
+		if preStr == "" {
+			return nil, errors.New("empty pre-release")
+		}
+		parts := strings.Split(preStr, ".")
+		for _, p := range parts {
+			if p == "" {
+				return nil, errors.New("empty pre-release identifier")
+			}
+			if !isValidIdentifier(p) {
+				return nil, errors.New("invalid pre-release identifier")
+			}
+			if isNumeric(p) && len(p) > 1 && p[0] == '0' {
+				return nil, errors.New("numeric pre-release identifier has leading zero")
+			}
+		}
+		preRelease = parts
+	}
