+package binarytree
+
+// Node represents a node in a binary search tree.
+type Node struct {
+	Value       int
+	Left, Right *Node
+}
+
+// Insert inserts value into the tree rooted at root and returns the
+// root of the resulting tree.
+func Insert(root *Node, value int) *Node {
+	if root == nil {
+		return &Node{Value: value}
+	}
+	if value < root.Value {
+		root.Left = Insert(root.Left, value)
+	} else if value > root.Value {
+		root.Right = Insert(root.Right, value)
+	}
+	return root
+}
+
+// InOrder returns the values stored in the tree in ascending order.
+func InOrder(root *Node) []int {
+	values := []int{}
+	walk(root, &values)
+	return values
+}
+
+func walk(n *Node, values *[]int) {
+	if n == nil {
+		return
+	}
+	walk(n.Left, values)
+	*values = append(*values, n.Value)
+	walk(n.Right, values)
+}
+
+// Height returns the number of levels in the tree.
+func Height(root *Node) int {
+	if root == nil {
+		return 0
+	}
+	left := Height(root.Left)
+	right := Height(root.Right)
+	if left > right {
+		return left + 1
+	}
+	return right + 1
+}
