+		}
+		numFactor, err := parseLength(parts[0])
+		if err != nil {
+			return unitInfo{}, fmt.Errorf("invalid speed unit %s: %v", s, err)
+		}
+		denFactor, err := parseTime(parts[1])
+		if err != nil {
+			return unitInfo{}, fmt.Errorf("invalid speed unit %s: %v", s, err)
+		}
+		return unitInfo{category: "speed", factor: numFactor / denFactor}, nil
+	}
+	if f, err := parseLength(s); err == nil {
+		return unitInfo{category: "length", factor: f}, nil
+	}
+	if f, err := parseTime(s); err == nil {
+		return unitInfo{category: "time", factor: f}, nil
+	}
+	if _, err := parseTemperature(s); err == nil {
+		return unitInfo{category: "temperature"}, nil
+	}
+	return unitInfo{}, fmt.Errorf("unknown unit: %s", s)
