+import java.math.BigInteger;
+
+public class CombinationRanker {
+    public static long rank(int n, int k, int[] combination) {
+        validateNK(n, k);
+        if (combination == null || combination.length != k) {
+            throw new IllegalArgumentException("Invalid combination length");
+        }
+        long rank = 0;
+        int prev = -1;
+        for (int i = 0; i < k; i++) {
+            int current = combination[i];
+            if (current < 0 || current >= n || current <= prev) {
+                throw new IllegalArgumentException("Invalid combination");
+            }
+            for (int v = prev + 1; v < current; v++) {
+                rank += binomial(n - v - 1, k - i - 1);
+            }
+            prev = current;
+        }
+        return rank;
+    }
+
+    public static int[] unrank(int n, int k, long rank) {
+        validateNK(n, k);
+        if (rank < 0) {
+            throw new IllegalArgumentException("Rank must be non-negative");
+        }
+        long total = binomial(n, k);
+        if (rank >= total) {
+            throw new IllegalArgumentException("Rank out of bounds");
+        }
+        int[] result = new int[k];
+        int start = 0;
+        for (int i = 0; i < k; i++) {
+            for (int v = start; v < n; v++) {
+                long count = binomial(n - v - 1, k - i - 1);
+                if (rank < count) {
+                    result[i] = v;
+                    start = v + 1;
+                    break;
+                } else {
+                    rank -= count;
+                }
+            }
+        }
+        return result;
+    }
+
+    private static void validateNK(int n, int k) {
+        if (n < 0 || k < 0 || k > n) {
+            throw new IllegalArgumentException("Invalid n or k");
+        }
+    }
+
+    private static long binomial(int n, int k) {
+        if (k < 0 || k > n) {
+            return 0;
+        }
+        if (k > n - k) {
+            k = n - k;
+        }
+        BigInteger result = BigInteger.ONE;
+        for (int i = 1; i <= k; i++) {
+            result = result.multiply(BigInteger.valueOf(n - k + i))
+                           .divide(BigInteger.valueOf(i));
+        }
+        return result.longValueExact();
+    }
+}
