+public class Memoizer<T, R> {
+
+    private static final int UNBOUNDED = -1;
+
+    private final Function<T, R> function;
+    private final int capacity;
+    private final LinkedHashMap<T, R> cache;
+
+    private int hits;
+    private int misses;
+
+    public Memoizer(Function<T, R> function) {
+        this(function, UNBOUNDED);
+    }
+
+    public Memoizer(Function<T, R> function, int capacity) {
+        if (function == null) {
+            throw new IllegalArgumentException("function must not be null");
+        }
+        if (capacity != UNBOUNDED && capacity < 1) {
+            throw new IllegalArgumentException("capacity must be positive");
+        }
+        this.function = function;
+        this.capacity = capacity;
+        this.cache = new LinkedHashMap<>(16, 0.75f, true);
+    }
+
+    public R compute(T key) {
+        if (cache.containsKey(key)) {
+            hits++;
+            return cache.get(key);
+        }
+
+        misses++;
+        R value = function.apply(key);
+        cache.put(key, value);
+        evictLeastRecentlyUsedIfNeeded();
+        return value;
+    }
+
+    public int hits() {
+        return hits;
+    }
+
+    public int misses() {
+        return misses;
+    }
+
+    public int size() {
+        return cache.size();
+    }
+
+    public boolean isCached(T key) {
+        return cache.containsKey(key);
+    }
+
+    public void clear() {
+        cache.clear();
+        hits = 0;
+        misses = 0;
+    }
+
+    private void evictLeastRecentlyUsedIfNeeded() {
+        if (capacity == UNBOUNDED || cache.size() <= capacity) {
+            return;
+        }
+        Iterator<T> leastRecentlyUsed = cache.keySet().iterator();
+        leastRecentlyUsed.next();
+        leastRecentlyUsed.remove();
+    }
+}
