+public class DigitSumGrouper {
+    public Map<Integer, List<Integer>> groupByDigitSum(List<Integer> numbers) {
+        Map<Integer, List<Integer>> result = new LinkedHashMap<>();
+        if (numbers == null) {
+            return result;
+        }
+        for (Integer number : numbers) {
+            if (number == null) {
+                continue;
+            }
+            int digitSum = computeDigitSum(number);
+            result.computeIfAbsent(digitSum, k -> new ArrayList<>()).add(number);
+        }
