+    public Fraction round(int maxDenominator) {
+        if (maxDenominator < 1) {
+            throw new IllegalArgumentException("maxDenominator must be at least 1");
+        }
+        if (denominator <= maxDenominator) {
+            return this;
+        }
+
+        boolean negative = numerator < 0;
+        BigInteger p = BigInteger.valueOf(Math.abs(numerator));
+        BigInteger q = BigInteger.valueOf(denominator);
+        BigInteger limit = BigInteger.valueOf(maxDenominator);
+
+        // Convergents p1/q1 of p/q from the continued fraction expansion;
+        // p0/q0 is the previous convergent.
+        BigInteger p0 = BigInteger.ZERO;
+        BigInteger q0 = BigInteger.ONE;
+        BigInteger p1 = BigInteger.ONE;
+        BigInteger q1 = BigInteger.ZERO;
+        BigInteger n = p;
+        BigInteger d = q;
+
+        while (d.signum() > 0) {
+            BigInteger term = n.divide(d);
+            BigInteger nextNumerator = p0.add(term.multiply(p1));
+            BigInteger nextDenominator = q0.add(term.multiply(q1));
+            if (nextDenominator.compareTo(limit) > 0) {
+                break;
+            }
+            p0 = p1;
+            q0 = q1;
+            p1 = nextNumerator;
+            q1 = nextDenominator;
+            BigInteger remainder = n.subtract(term.multiply(d));
+            n = d;
+            d = remainder;
+        }
+
+        // Largest semiconvergent between p1/q1 and p0/q0 that still fits.
+        BigInteger factor = limit.subtract(q0).divide(q1);
+        BigInteger candidateNumerator = p0.add(factor.multiply(p1));
+        BigInteger candidateDenominator = q0.add(factor.multiply(q1));
