+        BigInteger bestDenominator;
+        int comparison = distanceToCandidate.compareTo(distanceToConvergent);
+        if (comparison < 0) {
+            bestNumerator = candidateNumerator;
+            bestDenominator = candidateDenominator;
+        } else if (comparison > 0) {
+            bestNumerator = p1;
+            bestDenominator = q1;
+        } else if (candidateNumerator.multiply(q1).compareTo(p1.multiply(candidateDenominator)) <= 0) {
+            bestNumerator = candidateNumerator;
+            bestDenominator = candidateDenominator;
+        } else {
+            bestNumerator = p1;
+            bestDenominator = q1;
+        }
+
+        if (negative) {
+            bestNumerator = bestNumerator.negate();
+        }
+        return new Fraction(bestNumerator.longValueExact(), bestDenominator.longValueExact());
