+            throw new IllegalArgumentException("fromBase must be between 2 and 36 but was " + fromBase);
+        }
+        if (toBase < 2 || toBase > 36) {
+            throw new IllegalArgumentException("toBase must be between 2 and 36 but was " + toBase);
+        }
