+public final class MultisetArrangements {
+
+    private final int[] counts;
+
+    public MultisetArrangements(int[] counts) {
+        if (counts == null) {
+            throw new NullPointerException("counts must not be null");
+        }
+        this.counts = counts.clone();
+        for (int count : this.counts) {
+            if (count < 0) {
+                throw new IllegalArgumentException("counts must be non-negative");
+            }
+        }
+    }
+
+    public BigInteger totalArrangements() {
+        return multinomial(this.counts);
+    }
+
+    public BigInteger arrangementsWithNoAdjacentEqual() {
+        int[] blocks = new int[counts.length];
+        return sumOverBlocks(0, blocks, BigInteger.ONE);
+    }
+
+    private BigInteger sumOverBlocks(int index, int[] blocks, BigInteger coefficient) {
+        if (index == counts.length) {
+            return coefficient.multiply(multinomial(blocks));
+        }
+        int count = counts[index];
+        if (count == 0) {
+            blocks[index] = 0;
+            return sumOverBlocks(index + 1, blocks, coefficient);
+        }
+        BigInteger total = BigInteger.ZERO;
+        for (int j = 1; j <= count; j++) {
+            blocks[index] = j;
+            BigInteger term = coefficient.multiply(binomial(count - 1, j - 1));
+            if (((count - j) & 1) == 1) {
+                term = term.negate();
+            }
+            total = total.add(sumOverBlocks(index + 1, blocks, term));
+        }
+        return total;
+    }
+
+    private static BigInteger multinomial(int[] values) {
+        int remaining = 0;
+        for (int value : values) {
+            remaining += value;
+        }
+        BigInteger result = BigInteger.ONE;
+        for (int value : values) {
+            result = result.multiply(binomial(remaining, value));
+            remaining -= value;
+        }
+        return result;
+    }
+
+    private static BigInteger binomial(int n, int k) {
+        if (k < 0 || k > n) {
+            return BigInteger.ZERO;
+        }
+        k = Math.min(k, n - k);
+        BigInteger result = BigInteger.ONE;
+        for (int i = 1; i <= k; i++) {
+            result = result.multiply(BigInteger.valueOf(n - k + i)).divide(BigInteger.valueOf(i));
+        }
+        return result;
+    }
+}
