+        int previous = 0;
+
+        for (int i = numeral.length() - 1; i >= 0; i--) {
+            int current = symbolValue(numeral.charAt(i));
+
+            if (current < previous) {
+                value -= current;
+            } else {
+                value += current;
+                previous = current;
+            }
+        }
+
