+public class RangeIndex {
+    private final List<int[]> ranges = new ArrayList<>();
+
+    public RangeIndex() {
+    }
+
+    public void add(int start, int end) {
+        if (start > end) {
+            throw new IllegalArgumentException("start must not exceed end");
+        }
+
+        long threshold = (long) start - 1;
+        int first = firstRangeWithEndAtLeast(threshold);
+
+        int mergedStart = start;
+        int mergedEnd = end;
+        int i = first;
+
+        while (i < ranges.size() && (long) ranges.get(i)[0] <= (long) mergedEnd + 1) {
+            int[] range = ranges.get(i);
+            mergedStart = Math.min(mergedStart, range[0]);
+            mergedEnd = Math.max(mergedEnd, range[1]);
+            i++;
+        }
+
+        if (i > first) {
+            ranges.subList(first, i).clear();
+        }
+
+        ranges.add(first, new int[]{mergedStart, mergedEnd});
+    }
+
+    public boolean contains(int value) {
+        int i = firstRangeWithEndAtLeast(value);
+        return i < ranges.size() && ranges.get(i)[0] <= value;
+    }
+
+    public long countInRange(int start, int end) {
+        if (start > end) {
+            return 0;
+        }
+
+        int i = firstRangeWithEndAtLeast(start);
+        long total = 0;
+
+        while (i < ranges.size() && ranges.get(i)[0] <= end) {
+            int[] range = ranges.get(i);
+            long from = Math.max((long) start, range[0]);
+            long to = Math.min((long) end, range[1]);
+
+            if (from <= to) {
+                total += to - from + 1;
+            }
+
+            i++;
+        }
+
+        return total;
+    }
+
+    public long coveredCount() {
+        long total = 0;
+
+        for (int[] range : ranges) {
+            total += (long) range[1] - range[0] + 1;
+        }
+
+        return total;
+    }
+
+    public int kthSmallest(int k) {
+        if (k < 1 || k > coveredCount()) {
+            throw new IllegalArgumentException("k is outside the covered range");
+        }
+
+        long remaining = k;
+
+        for (int[] range : ranges) {
+            long length = (long) range[1] - range[0] + 1;
+
+            if (remaining <= length) {
+                return (int) ((long) range[0] + remaining - 1);
+            }
+
+            remaining -= length;
+        }
+
+        throw new IllegalArgumentException("k is outside the covered range");
+    }
