+public class IndexedPriorityQueue {
+    private static final class Node {
+        final String item;
+        int priority;
+        final long sequence;
+        int index;
+
+        Node(String item, int priority, long sequence, int index) {
+            this.item = item;
+            this.priority = priority;
+            this.sequence = sequence;
+            this.index = index;
+        }
+    }
+
+    private final List<Node> heap = new ArrayList<>();
+    private final Map<String, Node> byItem = new HashMap<>();
+    private long nextSequence = 0;
+
+    public void enqueue(String item, int priority) {
+        if (item == null) {
+            throw new IllegalArgumentException("item must not be null");
+        }
+        if (byItem.containsKey(item)) {
+            throw new IllegalArgumentException("duplicate item: " + item);
+        }
+
+        Node node = new Node(item, priority, nextSequence++, heap.size());
+        heap.add(node);
+        byItem.put(item, node);
+        siftUp(node.index);
+    }
+
+    public String dequeue() {
+        if (heap.isEmpty()) {
+            throw new NoSuchElementException("queue is empty");
+        }
+
+        String item = heap.get(0).item;
+        removeAt(0);
+        return item;
+    }
+
+    public String peek() {
+        if (heap.isEmpty()) {
+            throw new NoSuchElementException("queue is empty");
+        }
+        return heap.get(0).item;
+    }
+
+    public void changePriority(String item, int newPriority) {
+        Node node = byItem.get(item);
+        if (node == null) {
+            throw new NoSuchElementException("item not found");
+        }
+
+        int oldPriority = node.priority;
+        node.priority = newPriority;
+
+        if (newPriority < oldPriority) {
+            siftUp(node.index);
+        } else if (newPriority > oldPriority) {
+            siftDown(node.index);
+        }
+    }
+
+    public boolean remove(String item) {
+        Node node = byItem.get(item);
+        if (node == null) {
+            return false;
+        }
+
+        removeAt(node.index);
+        return true;
+    }
+
+    public boolean contains(String item) {
+        return item != null && byItem.containsKey(item);
+    }
+
+    public int size() {
+        return heap.size();
+    }
+
+    public boolean isEmpty() {
