+        Node removed = heap.get(pos);
+        byItem.remove(removed.item);
+
+        Node last = heap.remove(heap.size() - 1);
+
+        if (pos != heap.size()) {
+            heap.set(pos, last);
+            last.index = pos;
+
+            if (pos > 0 && less(last, heap.get((pos - 1) / 2))) {
