+        while (pos > 0) {
+            int parent = (pos - 1) / 2;
+            if (!less(heap.get(pos), heap.get(parent))) {
+                break;
+            }
+            swap(pos, parent);
+            pos = parent;
+        }
+    }
+
+    private void siftDown(int pos) {
+        int size = heap.size();
+
+        while (true) {
+            int left = pos * 2 + 1;
+            if (left >= size) {
+                break;
+            }
+
+            int right = left + 1;
+            int smallest = left;
+
+            if (right < size && less(heap.get(right), heap.get(left))) {
+                smallest = right;
+            }
+
+            if (!less(heap.get(smallest), heap.get(pos))) {
+                break;
+            }
+
+            swap(pos, smallest);
+            pos = smallest;
+        }
+    }
