+public final class BusinessDeadlineCalculator {
+    private final ZoneId zone;
+    private final LocalTime opening;
+    private final LocalTime closing;
+    private final Set<LocalDate> holidays;
+    private final Set<DayOfWeek> weekendDays;
+
+    public BusinessDeadlineCalculator(ZoneId zone, LocalTime opening, LocalTime closing,
+                                      Set<LocalDate> holidays, Set<DayOfWeek> weekendDays) {
+        this.zone = Objects.requireNonNull(zone, "zone");
+        this.opening = Objects.requireNonNull(opening, "opening");
+        this.closing = Objects.requireNonNull(closing, "closing");
+        this.holidays = Set.copyOf(Objects.requireNonNull(holidays, "holidays"));
+        this.weekendDays = Set.copyOf(Objects.requireNonNull(weekendDays, "weekendDays"));
+
+        if (!opening.isBefore(closing)) {
+            throw new IllegalArgumentException("opening must be before closing");
+        }
+    }
+
+    public ZonedDateTime deadlineAfter(ZonedDateTime start, long businessMinutes) {
+        if (businessMinutes < 0) {
+            throw new IllegalArgumentException("businessMinutes must be non-negative");
+        }
+
+        ZonedDateTime cursor = nextCountableMoment(
+                Objects.requireNonNull(start, "start").withZoneSameInstant(zone));
+        Duration remaining = Duration.ofMinutes(businessMinutes);
+
+        while (true) {
+            if (remaining.isZero()) {
+                return cursor;
+            }
+
+            LocalDate date = cursor.toLocalDate();
+
+            if (isBusinessDay(date)) {
+                ZonedDateTime close = at(date, closing);
+
+                if (cursor.isBefore(close)) {
+                    Duration available = Duration.between(cursor, close);
+                    int comparison = remaining.compareTo(available);
+
+                    if (comparison < 0) {
+                        return cursor.plus(remaining);
+                    }
+
+                    if (comparison == 0) {
+                        return close;
+                    }
+
+                    remaining = remaining.minus(available);
+                }
+            }
+
+            cursor = nextOpeningAfter(date);
+        }
+    }
+
+    private ZonedDateTime nextCountableMoment(ZonedDateTime moment) {
+        LocalDate date = moment.toLocalDate();
+
+        if (isBusinessDay(date)) {
+            ZonedDateTime open = at(date, opening);
+            ZonedDateTime close = at(date, closing);
+
+            if (moment.isBefore(open)) {
+                return open;
+            }
+
+            if (moment.isBefore(close)) {
+                return moment;
+            }
+        }
+
+        return nextOpeningAfter(date);
+    }
+
+    private ZonedDateTime nextOpeningAfter(LocalDate date) {
+        LocalDate next = date.plusDays(1);
+
+        while (!isBusinessDay(next)) {
+            next = next.plusDays(1);
+        }
+
+        return at(next, opening);
+    }
+
+    private boolean isBusinessDay(LocalDate date) {
+        return !weekendDays.contains(date.getDayOfWeek()) && !holidays.contains(date);
+    }
+
+    private ZonedDateTime at(LocalDate date, LocalTime time) {
+        return ZonedDateTime.of(date, time, zone);
+    }
