+public class PatternMatcher {
+    public static boolean matches(String pattern, String text) {
+        int patternLength = pattern.length();
+        int textLength = text.length();
+        boolean[][] dp = new boolean[patternLength + 1][textLength + 1];
+        dp[0][0] = true;
