+            LocalTime closesAt,
+            Set<LocalDate> holidays) {
+        if (start == null || opensAt == null || closesAt == null) {
+            throw new NullPointerException("start, opensAt, and closesAt must not be null");
+        }
+        if (!opensAt.isBefore(closesAt)) {
+            throw new IllegalArgumentException("opensAt must be before closesAt");
+        }
+        if (hours < 0) {
+            throw new IllegalArgumentException("hours must be non-negative");
+        }
+        if (hours == 0) {
+            return start;
+        }
