+        LocalDateTime current = start;
+
+        while (!isBusinessDay(current.toLocalDate(), nonWorkingDays)
+                || !current.toLocalTime().isBefore(closesAt)
+                || current.toLocalTime().isBefore(opensAt)) {
+            LocalDate date = current.toLocalDate();
+            LocalTime time = current.toLocalTime();
+
+            if (isBusinessDay(date, nonWorkingDays) && time.isBefore(opensAt)) {
+                current = LocalDateTime.of(date, opensAt);
+                break;
+            }
+
+            current = nextWorkingDayStart(date, opensAt, nonWorkingDays);
+        }
+
+        Duration remaining = Duration.ofHours(hours);
+
+        while (true) {
+            LocalDate date = current.toLocalDate();
+            LocalTime time = current.toLocalTime();
+
+            if (!isBusinessDay(date, nonWorkingDays)
+                    || time.isBefore(opensAt)
+                    || !time.isBefore(closesAt)) {
+                current = nextWorkingDayStart(date, opensAt, nonWorkingDays);
+                continue;
+            }
+
+            LocalDateTime close = LocalDateTime.of(date, closesAt);
+            Duration available = Duration.between(current, close);
+
+            if (remaining.compareTo(available) <= 0) {
+                return current.plus(remaining);
+            }
+
+            remaining = remaining.minus(available);
+            current = nextWorkingDayStart(date, opensAt, nonWorkingDays);
+        }
+    }
+
+    private static LocalDateTime nextWorkingDayStart(
+            LocalDate date,
+            LocalTime opensAt,
+            Set<LocalDate> nonWorkingDays) {
+        LocalDate next = date.plusDays(1);
+        while (!isBusinessDay(next, nonWorkingDays)) {
+            next = next.plusDays(1);
+        }
+        return LocalDateTime.of(next, opensAt);
+    }
+
+    private static boolean isBusinessDay(LocalDate date, Set<LocalDate> nonWorkingDays) {
+        DayOfWeek day = date.getDayOfWeek();
+        return day != DayOfWeek.SATURDAY
+                && day != DayOfWeek.SUNDAY
+                && !nonWorkingDays.contains(date);
+    }
