+    public static List<String> topUsers(List<String> lines, int limit) {
+        Map<String, Integer> counts = countUsers(lines);
+        List<String> users = new ArrayList<>(counts.keySet());
+        users.sort((first, second) -> {
+            int byCount = Integer.compare(counts.get(second), counts.get(first));
+            if (byCount != 0) {
+                return byCount;
+            }
+            return first.compareTo(second);
+        });
+
+        int safeLimit = Math.max(0, Math.min(limit, users.size()));
+        return new ArrayList<>(users.subList(0, safeLimit));
+    }
+
+    public static Map<String, Map<String, Integer>> countLevelsByUser(List<String> lines) {
+        Map<String, Map<String, Integer>> counts = new TreeMap<>();
+        for (ParsedLine line : parse(lines)) {
+            counts.computeIfAbsent(line.user, ignored -> new TreeMap<>())
+                    .merge(line.level, 1, Integer::sum);
+        }
+        return counts;
+    }
+
+    private static List<ParsedLine> parse(List<String> lines) {
+        List<ParsedLine> parsed = new ArrayList<>();
+        if (lines == null) {
+            return parsed;
+        }
+
+        for (String raw : lines) {
+            if (raw == null) {
+                continue;
+            }
+
+            String line = raw.trim();
+            if (line.isEmpty() || line.startsWith("#")) {
+                continue;
+            }
+
+            String[] parts = line.split("\\|", -1);
+            if (parts.length != 2) {
+                continue;
+            }
+
+            String level = parts[0].trim();
+            String user = parts[1].trim();
+            if (level.isEmpty() || user.isEmpty()) {
+                continue;
+            }
+
+            parsed.add(new ParsedLine(
+                    level.toUpperCase(Locale.ROOT),
+                    user.toLowerCase(Locale.ROOT)
+            ));
+        }
+
+        return parsed;
+    }
