+public class ParcelStateMachine {
+    public enum State {
+        CREATED,
+        PICKED_UP,
+        IN_TRANSIT,
+        OUT_FOR_DELIVERY,
+        DELIVERED,
+        FAILED_ATTEMPT,
+        RETURNED,
+        CANCELLED
+    }
+
+    public enum Event {
+        PICK_UP,
+        START_TRANSIT,
+        OUT_FOR_DELIVERY,
+        DELIVER,
+        FAIL_DELIVERY,
+        RETRY,
+        RETURN,
+        CANCEL
+    }
+
+    private State state;
+    private final List<State> history;
+    private int failedDeliveryAttempts;
+
+    public ParcelStateMachine() {
+        state = State.CREATED;
+        history = new ArrayList<>();
+        history.add(state);
+        failedDeliveryAttempts = 0;
+    }
+
+    public State getState() {
+        return state;
+    }
+
+    public List<State> getHistory() {
+        return Collections.unmodifiableList(new ArrayList<>(history));
+    }
+
+    public int getFailedDeliveryAttempts() {
+        return failedDeliveryAttempts;
+    }
+
+    public void handle(Event event) {
+        if (event == null) {
+            throw new NullPointerException("event must not be null");
+        }
+
+        switch (event) {
+            case PICK_UP:
+                requireState(State.CREATED, event);
+                transitionTo(State.PICKED_UP);
+                break;
+            case START_TRANSIT:
+                requireState(State.PICKED_UP, event);
+                transitionTo(State.IN_TRANSIT);
+                break;
+            case OUT_FOR_DELIVERY:
+                requireState(State.IN_TRANSIT, event);
+                transitionTo(State.OUT_FOR_DELIVERY);
+                break;
+            case DELIVER:
+                requireState(State.OUT_FOR_DELIVERY, event);
+                transitionTo(State.DELIVERED);
+                break;
+            case FAIL_DELIVERY:
+                requireState(State.OUT_FOR_DELIVERY, event);
+                failedDeliveryAttempts++;
+                if (failedDeliveryAttempts >= 3) {
+                    transitionTo(State.RETURNED);
+                } else {
+                    transitionTo(State.FAILED_ATTEMPT);
+                }
+                break;
+            case RETRY:
+                requireState(State.FAILED_ATTEMPT, event);
+                transitionTo(State.OUT_FOR_DELIVERY);
+                break;
+            case RETURN:
+                if (state == State.OUT_FOR_DELIVERY
+                        || state == State.FAILED_ATTEMPT
+                        || state == State.DELIVERED) {
+                    transitionTo(State.RETURNED);
+                } else {
+                    throw invalid(event);
+                }
+                break;
+            case CANCEL:
+                if (state == State.CREATED
+                        || state == State.PICKED_UP
+                        || state == State.IN_TRANSIT) {
+                    transitionTo(State.CANCELLED);
+                } else {
+                    throw invalid(event);
+                }
+                break;
+            default:
+                throw invalid(event);
+        }
