+public class PalindromeAnagramAnalyzer {
+    private static String normalize(String text) {
+        StringBuilder sb = new StringBuilder();
+        for (int i = 0; i < text.length(); i++) {
+            char c = text.charAt(i);
+            if (Character.isLetterOrDigit(c)) {
+                sb.append(Character.toLowerCase(c));
+            }
+        }
+        return sb.toString();
+    }
+
+    public static boolean isPalindrome(String text) {
+        String s = normalize(text);
+        int left = 0;
+        int right = s.length() - 1;
+        while (left < right) {
+            if (s.charAt(left) != s.charAt(right)) {
+                return false;
+            }
+            left++;
+            right--;
+        }
+        return true;
+    }
+
+    public static boolean canFormPalindrome(String text) {
+        String s = normalize(text);
+        Map<Character, Integer> counts = new HashMap<>();
+        for (int i = 0; i < s.length(); i++) {
+            counts.merge(s.charAt(i), 1, Integer::sum);
+        }
+
+        int oddCount = 0;
+        for (int count : counts.values()) {
+            if (count % 2 == 1) {
+                oddCount++;
+                if (oddCount > 1) {
+                    return false;
+                }
+            }
+        }
+        return true;
+    }
+
+    public static boolean areAnagrams(String first, String second) {
+        String a = normalize(first);
+        String b = normalize(second);
+        if (a.length() != b.length()) {
+            return false;
+        }
+
+        int[] counts = new int[Character.MAX_VALUE + 1];
+        for (int i = 0; i < a.length(); i++) {
+            counts[a.charAt(i)]++;
+        }
+        for (int i = 0; i < b.length(); i++) {
+            counts[b.charAt(i)]--;
+        }
+
+        for (int count : counts) {
+            if (count != 0) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    public static String smallestPalindromeAnagram(String text) {
+        String s = normalize(text);
+        if (!canFormPalindrome(s)) {
+            return "";
+        }
+
+        int[] counts = new int[Character.MAX_VALUE + 1];
+        for (int i = 0; i < s.length(); i++) {
+            counts[s.charAt(i)]++;
+        }
+
+        StringBuilder left = new StringBuilder();
+        char center = 0;
+        boolean hasCenter = false;
+
+        for (int i = 0; i < counts.length; i++) {
+            if (counts[i] == 0) {
+                continue;
+            }
+
+            char c = (char) i;
+            int pairs = counts[i] / 2;
+            for (int j = 0; j < pairs; j++) {
+                left.append(c);
+            }
+
+            if (counts[i] % 2 == 1) {
+                center = c;
+                hasCenter = true;
+            }
+        }
+
+        StringBuilder result = new StringBuilder(left);
+        if (hasCenter) {
+            result.append(center);
+        }
+        result.append(left.reverse());
+        return result.toString();
+    }
