+import java.math.BigInteger;
+import java.util.List;
+import java.util.Optional;
+
+public final class ChineseRemainderSolver {
+    private ChineseRemainderSolver() {
+    }
+
+    public static Optional<BigInteger> solve(List<BigInteger> remainders, List<BigInteger> moduli) {
+        if (remainders == null || moduli == null) {
+            throw new IllegalArgumentException("Remainders and moduli must not be null");
+        }
+        if (remainders.size() != moduli.size()) {
+            throw new IllegalArgumentException("Remainders and moduli must have the same size");
+        }
+
+        BigInteger result = BigInteger.ZERO;
+        BigInteger modulus = BigInteger.ONE;
+
+        for (int i = 0; i < remainders.size(); i++) {
+            BigInteger remainder = remainders.get(i);
+            BigInteger nextModulus = moduli.get(i);
+
+            if (remainder == null || nextModulus == null) {
+                throw new IllegalArgumentException("Remainders and moduli must not contain null");
+            }
+            if (nextModulus.signum() <= 0) {
+                throw new IllegalArgumentException("Moduli must be positive");
+            }
+
+            remainder = remainder.mod(nextModulus);
+
+            BigInteger gcd = modulus.gcd(nextModulus);
+            BigInteger difference = remainder.subtract(result);
+
+            if (!difference.mod(gcd).equals(BigInteger.ZERO)) {
+                return Optional.empty();
+            }
+
+            BigInteger reducedNextModulus = nextModulus.divide(gcd);
+            BigInteger multiplier;
+
+            if (reducedNextModulus.equals(BigInteger.ONE)) {
+                multiplier = BigInteger.ZERO;
+            } else {
+                BigInteger reducedCurrentModulus = modulus.divide(gcd);
+                BigInteger reducedDifference = difference.divide(gcd);
+                BigInteger inverse = reducedCurrentModulus.modInverse(reducedNextModulus);
+                multiplier = reducedDifference.multiply(inverse).mod(reducedNextModulus);
+            }
+
+            result = result.add(modulus.multiply(multiplier));
+            modulus = modulus.multiply(reducedNextModulus);
+            result = result.mod(modulus);
+        }
+
+        return Optional.of(result.mod(modulus));
+    }
+}
