+            counts.merge(c, 1, Integer::sum);
+        }
+
+        int oddCount = 0;
+        Character middle = null;
+        for (Map.Entry<Character, Integer> entry : counts.entrySet()) {
+            if (entry.getValue() % 2 != 0) {
+                oddCount++;
+                middle = entry.getKey();
