+        int halfLength = normalized.length() / 2;
+        List<String> halves = new ArrayList<>();
+        generateHalves(halfCounts, halfLength, new StringBuilder(), halves);
+
+        String middleText = middle == null ? "" : String.valueOf(middle);
+        List<String> result = new ArrayList<>();
+
+        for (String half : halves) {
