+import java.util.ArrayDeque;
+import java.util.Deque;
+
+public class LongestSubarrayWithRange {
+
+    public static int longestSubarray(int[] nums, int limit) {
+        if (nums == null || nums.length == 0 || limit < 0) {
+            return 0;
+        }
+
+        Deque<Integer> maxima = new ArrayDeque<>();
+        Deque<Integer> minima = new ArrayDeque<>();
+        int left = 0;
+        int best = 0;
+
+        for (int right = 0; right < nums.length; right++) {
+            while (!maxima.isEmpty() && nums[maxima.peekLast()] <= nums[right]) {
+                maxima.pollLast();
+            }
+            maxima.addLast(right);
+
+            while (!minima.isEmpty() && nums[minima.peekLast()] >= nums[right]) {
+                minima.pollLast();
+            }
+            minima.addLast(right);
+
+            while (nums[maxima.peekFirst()] - nums[minima.peekFirst()] > limit) {
+                if (maxima.peekFirst() == left) {
+                    maxima.pollFirst();
+                }
+                if (minima.peekFirst() == left) {
+                    minima.pollFirst();
+                }
+                left++;
+            }
+
+            best = Math.max(best, right - left + 1);
+        }
+
+        return best;
+    }
+}
