+public class MeetingScheduler {
+    public static int earliestSlot(int workStart, int workEnd, int[][] busy, int duration) {
+        if (workStart >= workEnd || duration <= 0) {
+            throw new IllegalArgumentException("Invalid working hours or duration");
+        }
+        if (busy == null) {
+            busy = new int[0][];
+        }
+        List<int[]> clipped = new ArrayList<>();
+        for (int[] interval : busy) {
+            if (interval == null || interval.length < 2) {
+                continue;
+            }
+            int s = Math.max(interval[0], workStart);
+            int e = Math.min(interval[1], workEnd);
+            if (s < e) {
+                clipped.add(new int[]{s, e});
+            }
+        }
+        clipped.sort((a, b) -> Integer.compare(a[0], b[0]));
+        List<int[]> merged = new ArrayList<>();
+        for (int[] interval : clipped) {
+            if (merged.isEmpty() || merged.get(merged.size() - 1)[1] < interval[0]) {
+                merged.add(new int[]{interval[0], interval[1]});
+            } else {
+                int[] last = merged.get(merged.size() - 1);
+                last[1] = Math.max(last[1], interval[1]);
+            }
+        }
+        int current = workStart;
+        for (int[] interval : merged) {
+            if (interval[0] - current >= duration) {
+                return current;
+            }
+            current = Math.max(current, interval[1]);
+        }
+        if (workEnd - current >= duration) {
+            return current;
+        }
+        return -1;
