+import java.util.ArrayDeque;
+import java.util.Arrays;
+import java.util.List;
+import java.util.Queue;
+
+public class GridPathFinder {
+
+    private static final int[] ROW_STEP = {-1, 1, 0, 0};
+    private static final int[] COL_STEP = {0, 0, -1, 1};
+    private static final char WALL = '#';
+    private static final char START = 'S';
+    private static final char END = 'E';
+
+    public int shortestPath(List<String> grid) {
+        if (grid == null || grid.isEmpty()) {
+            return -1;
+        }
+
+        int rows = grid.size();
+        int cols = grid.get(0).length();
+        int startRow = -1;
+        int startCol = -1;
+        int endRow = -1;
+        int endCol = -1;
+
+        for (int row = 0; row < rows; row++) {
+            for (int col = 0; col < cols; col++) {
+                char cell = grid.get(row).charAt(col);
+                if (cell == START) {
+                    startRow = row;
+                    startCol = col;
+                } else if (cell == END) {
+                    endRow = row;
+                    endCol = col;
+                }
+            }
+        }
+
+        if (startRow < 0 || endRow < 0) {
+            return -1;
+        }
+
+        int[][] distance = new int[rows][cols];
+        for (int[] row : distance) {
+            Arrays.fill(row, -1);
+        }
+
+        Queue<int[]> queue = new ArrayDeque<>();
+        distance[startRow][startCol] = 0;
+        queue.add(new int[]{startRow, startCol});
+
+        while (!queue.isEmpty()) {
+            int[] current = queue.poll();
+            int row = current[0];
+            int col = current[1];
+
+            if (row == endRow && col == endCol) {
+                return distance[row][col];
+            }
+
+            for (int direction = 0; direction < 4; direction++) {
+                int nextRow = row + ROW_STEP[direction];
+                int nextCol = col + COL_STEP[direction];
+
+                if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) {
+                    continue;
+                }
+                if (distance[nextRow][nextCol] != -1) {
+                    continue;
+                }
+                if (grid.get(nextRow).charAt(nextCol) == WALL) {
+                    continue;
+                }
+
+                distance[nextRow][nextCol] = distance[row][col] + 1;
+                queue.add(new int[]{nextRow, nextCol});
+            }
+        }
+
+        return -1;
+    }
