+public class MinMaxQueue {
+    private static final class Entry {
+        final int value;
+        final int min;
+        final int max;
+
+        Entry(int value, int min, int max) {
+            this.value = value;
+            this.min = min;
+            this.max = max;
+        }
+    }
+
+    private final Deque<Entry> inbox = new ArrayDeque<>();
+    private final Deque<Entry> outbox = new ArrayDeque<>();
+
+    public void enqueue(int value) {
+        if (inbox.isEmpty()) {
+            inbox.push(new Entry(value, value, value));
+        } else {
+            Entry top = inbox.peek();
+            inbox.push(new Entry(value, Math.min(value, top.min), Math.max(value, top.max)));
+        }
+    }
+
+    public int dequeue() {
+        moveToOutboxIfNeeded();
+        if (outbox.isEmpty()) {
+            throw new NoSuchElementException();
+        }
+        return outbox.pop().value;
+    }
+
+    public int peek() {
+        moveToOutboxIfNeeded();
+        if (outbox.isEmpty()) {
+            throw new NoSuchElementException();
+        }
+        return outbox.peek().value;
+    }
+
+    public boolean isEmpty() {
+        return inbox.isEmpty() && outbox.isEmpty();
+    }
+
+    public int size() {
+        return inbox.size() + outbox.size();
+    }
+
+    public int min() {
+        if (isEmpty()) {
+            throw new NoSuchElementException();
+        }
+        if (inbox.isEmpty()) {
+            return outbox.peek().min;
+        }
+        if (outbox.isEmpty()) {
+            return inbox.peek().min;
+        }
+        return Math.min(inbox.peek().min, outbox.peek().min);
+    }
+
+    public int max() {
+        if (isEmpty()) {
+            throw new NoSuchElementException();
+        }
+        if (inbox.isEmpty()) {
+            return outbox.peek().max;
+        }
+        if (outbox.isEmpty()) {
+            return inbox.peek().max;
+        }
+        return Math.max(inbox.peek().max, outbox.peek().max);
+    }
+
