+import java.util.TreeMap;
+
+public class SlidingWindowMedian {
+    private final TreeMap<Integer, Integer> lower = new TreeMap<>();
+    private final TreeMap<Integer, Integer> upper = new TreeMap<>();
+    private int lowerSize;
+    private int upperSize;
+
+    public int[] medians(int[] values, int windowSize) {
+        if (values == null || windowSize <= 0 || values.length == 0 || windowSize > values.length) {
+            return new int[0];
+        }
+
+        int windowCount = values.length - windowSize + 1;
+        int[] result = new int[windowCount];
+        int desiredLowerSize = (windowSize + 1) / 2;
+
+        for (int i = 0; i < windowSize; i++) {
+            add(values[i]);
+        }
+        rebalance(desiredLowerSize);
+        result[0] = lower.lastKey();
+
+        for (int i = windowSize; i < values.length; i++) {
+            remove(values[i - windowSize]);
+            add(values[i]);
+            rebalance(desiredLowerSize);
+            result[i - windowSize + 1] = lower.lastKey();
+        }
+
+        return result;
+    }
+
+    private void add(int value) {
+        if (lower.isEmpty()) {
+            if (!upper.isEmpty() && value > upper.firstKey()) {
+                addToUpper(value);
+            } else {
+                addToLower(value);
+            }
+        } else if (value <= lower.lastKey()) {
+            addToLower(value);
+        } else {
+            addToUpper(value);
+        }
+    }
+
+    private void remove(int value) {
+        if (lower.containsKey(value)) {
+            removeFromLower(value);
+        } else {
+            removeFromUpper(value);
+        }
+    }
+
+    private void rebalance(int desiredLowerSize) {
+        while (lowerSize > desiredLowerSize) {
+            int value = lower.lastKey();
+            removeFromLower(value);
+            addToUpper(value);
+        }
+
+        while (lowerSize < desiredLowerSize) {
+            int value = upper.firstKey();
+            removeFromUpper(value);
+            addToLower(value);
+        }
+    }
+
+    private void addToLower(int value) {
+        lower.merge(value, 1, Integer::sum);
+        lowerSize++;
+    }
+
+    private void addToUpper(int value) {
+        upper.merge(value, 1, Integer::sum);
+        upperSize++;
+    }
+
+    private void removeFromLower(int value) {
+        decrement(lower, value);
+        lowerSize--;
+    }
+
+    private void removeFromUpper(int value) {
+        decrement(upper, value);
+        upperSize--;
+    }
+
+    private void decrement(TreeMap<Integer, Integer> map, int value) {
+        int count = map.get(value);
