+public class CollatzConjecture {
+
+    public int stepsToReachOne(long start) {
+        if (start < 1) {
+            throw new IllegalArgumentException("start must be at least 1");
+        }
+        long n = start;
+        int steps = 0;
+        while (n != 1) {
+            if ((n & 1L) == 0L) {
+                n /= 2;
+            } else {
+                n = 3 * n + 1;
+            }
