+        if (limit < 1) {
+            throw new IllegalArgumentException("limit must be at least 1");
+        }
+        long bestStart = 1;
+        int bestSteps = 0;
+        for (long candidate = 2; candidate <= limit; candidate++) {
+            int steps = stepsToReachOne(candidate);
+            if (steps > bestSteps) {
+                bestSteps = steps;
+                bestStart = candidate;
+            }
+        }
+        return bestStart;
+    }
