+import java.util.PriorityQueue;
+
+public final class GridPathfinder {
+    private static final int[] DR = {1, 0, 0, -1};
+    private static final int[] DC = {0, -1, 1, 0};
+    private static final char[] DIRECTION = {'D', 'L', 'R', 'U'};
+
+    private GridPathfinder() {
+    }
+
+    public static String findPath(String[] grid) {
+        if (grid == null || grid.length == 0 || grid[0].length() == 0) {
+            return "";
+        }
+
+        int rows = grid.length;
+        int cols = grid[0].length();
+        int startRow = -1;
+        int startCol = -1;
+        int endRow = -1;
+        int endCol = -1;
+
+        for (int row = 0; row < rows; row++) {
+            if (grid[row].length() != cols) {
+                return "";
+            }
+            for (int col = 0; col < cols; col++) {
+                char cell = grid[row].charAt(col);
+                if (cell == 'S') {
+                    startRow = row;
+                    startCol = col;
+                } else if (cell == 'E') {
+                    endRow = row;
+                    endCol = col;
+                }
+            }
+        }
+
+        if (startRow == -1 || endRow == -1) {
+            return "";
+        }
+        if (startRow == endRow && startCol == endCol) {
+            return "";
+        }
+
+        PriorityQueue<Node> queue = new PriorityQueue<>((first, second) -> {
+            int byCost = Integer.compare(first.cost, second.cost);
+            if (byCost != 0) {
+                return byCost;
+            }
+            return first.path.compareTo(second.path);
+        });
+
+        boolean[][] visited = new boolean[rows][cols];
+        queue.add(new Node(startRow, startCol, 0, ""));
+
+        while (!queue.isEmpty()) {
+            Node current = queue.poll();
+            if (visited[current.row][current.col]) {
+                continue;
+            }
+            visited[current.row][current.col] = true;
+
+            if (current.row == endRow && current.col == endCol) {
+                return current.path;
+            }
+
+            for (int i = 0; i < 4; i++) {
+                int nextRow = current.row + DR[i];
+                int nextCol = current.col + DC[i];
+
+                if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) {
+                    continue;
+                }
+                if (visited[nextRow][nextCol]) {
+                    continue;
+                }
+
+                char cell = grid[nextRow].charAt(nextCol);
+                if (cell == '#') {
+                    continue;
+                }
+
+                int nextCost = current.cost + terrainCost(cell);
+                queue.add(new Node(nextRow, nextCol, nextCost, current.path + DIRECTION[i]));
+            }
+        }
+
+        return "";
+    }
+
+    private static int terrainCost(char cell) {
+        if (cell >= '1' && cell <= '9') {
+            return cell - '0';
+        }
+        return 1;
+    }
+
+    private static final class Node {
+        final int row;
+        final int col;
+        final int cost;
+        final String path;
+
+        Node(int row, int col, int cost, String path) {
+            this.row = row;
+            this.col = col;
+            this.cost = cost;
+            this.path = path;
+        }
+    }
