+            int index = (c >= '0' && c <= '9') ? (c - '0' + 26) : (c - 'a');
+            counts[index]++;
+        }
+        int odd = 0;
+        for (int count : counts) {
+            if (count % 2 != 0) {
+                odd++;
+            }
+        }
