+public class MatrixLayerRotation {
+    public static int[][] rotate(int[][] matrix, int rotations) {
+        if (matrix == null) {
+            return new int[0][0];
+        }
+
+        int rows = matrix.length;
+        if (rows == 0) {
+            return new int[0][0];
+        }
+
+        int cols = matrix[0].length;
+        for (int r = 0; r < rows; r++) {
+            if (matrix[r] == null || matrix[r].length != cols) {
+                throw new IllegalArgumentException("Matrix must be rectangular and contain no null rows");
+            }
+        }
+
+        int[][] result = new int[rows][cols];
+        if (cols == 0) {
+            return result;
+        }
+
+        int layerCount = (Math.min(rows, cols) + 1) / 2;
+
+        for (int layer = 0; layer < layerCount; layer++) {
+            List<Integer> values = extractLayer(matrix, layer, rows, cols);
+            int length = values.size();
+            int shift = Math.floorMod(rotations, length);
+
+            int top = layer;
+            int bottom = rows - 1 - layer;
+            int left = layer;
+            int right = cols - 1 - layer;
+            int index = 0;
+
+            for (int c = left; c <= right; c++) {
+                result[top][c] = values.get((index - shift + length) % length);
+                index++;
+            }
+
+            for (int r = top + 1; r <= bottom; r++) {
+                result[r][right] = values.get((index - shift + length) % length);
+                index++;
+            }
+
+            if (bottom > top) {
+                for (int c = right - 1; c >= left; c--) {
+                    result[bottom][c] = values.get((index - shift + length) % length);
+                    index++;
+                }
+            }
+
+            if (right > left) {
+                for (int r = bottom - 1; r > top; r--) {
+                    result[r][left] = values.get((index - shift + length) % length);
+                    index++;
+                }
+            }
+        }
+
+        return result;
+    }
