+    private static List<Integer> extractLayer(int[][] matrix, int layer, int rows, int cols) {
+        int top = layer;
+        int bottom = rows - 1 - layer;
+        int left = layer;
+        int right = cols - 1 - layer;
+        List<Integer> values = new ArrayList<>();
+
+        for (int c = left; c <= right; c++) {
+            values.add(matrix[top][c]);
+        }
+
+        for (int r = top + 1; r <= bottom; r++) {
+            values.add(matrix[r][right]);
+        }
+
+        if (bottom > top) {
