+import java.util.HashMap;
+import java.util.Map;
+
+public class MinimumWindowSubstring {
+    public String find(String source, String target) {
+        if (source == null || target == null) {
+            throw new IllegalArgumentException("source and target must not be null");
+        }
+        if (target.isEmpty()) {
+            return "";
+        }
+
+        Map<Character, Integer> need = new HashMap<>();
+        for (char c : target.toCharArray()) {
+            need.put(c, need.getOrDefault(c, 0) + 1);
+        }
+
+        Map<Character, Integer> window = new HashMap<>();
+        int required = need.size();
+        int formed = 0;
+        int left = 0;
+        int minLength = Integer.MAX_VALUE;
+        int minStart = 0;
+
+        for (int right = 0; right < source.length(); right++) {
+            char c = source.charAt(right);
+            window.put(c, window.getOrDefault(c, 0) + 1);
+
+            if (need.containsKey(c) && window.get(c).intValue() == need.get(c).intValue()) {
+                formed++;
+            }
+
+            while (formed == required) {
+                int currentLength = right - left + 1;
+                if (currentLength < minLength) {
+                    minLength = currentLength;
+                    minStart = left;
+                }
+
+                char removed = source.charAt(left);
+                window.put(removed, window.get(removed) - 1);
+                if (need.containsKey(removed) && window.get(removed) < need.get(removed)) {
+                    formed--;
+                }
+                left++;
+            }
+        }
+
+        if (minLength == Integer.MAX_VALUE) {
+            return "";
+        }
+        return source.substring(minStart, minStart + minLength);
+    }
