+import java.util.ArrayList;
+import java.util.Collections;
+import java.util.List;
+
+public class RunningTotals {
+    private int total;
+    private final List<Integer> history;
+    private final List<Operation> operations;
+
+    public RunningTotals() {
+        total = 0;
+        history = new ArrayList<>();
+        history.add(0);
+        operations = new ArrayList<>();
+    }
+
+    public void add(int amount) {
+        total += amount;
+        history.add(total);
+        operations.add(new Operation(amount, false));
+    }
+
+    public void reset() {
+        operations.add(new Operation(total, true));
+        total = 0;
+        history.add(total);
+    }
+
+    public void undo() {
+        if (operations.isEmpty()) {
+            throw new IllegalStateException("No operations to undo");
+        }
+        Operation op = operations.remove(operations.size() - 1);
+        history.remove(history.size() - 1);
+        if (op.isReset) {
+            total = op.value;
+        } else {
+            total -= op.value;
+        }
+    }
+
+    public int total() {
+        return total;
+    }
+
+    public List<Integer> history() {
+        return Collections.unmodifiableList(history);
+    }
+
+    public int max() {
+        return history.stream().mapToInt(Integer::intValue).max().orElse(0);
+    }
+
+    public int min() {
+        return history.stream().mapToInt(Integer::intValue).min().orElse(0);
+    }
+
+    private static class Operation {
+        final int value;
+        final boolean isReset;
+
+        Operation(int value, boolean isReset) {
+            this.value = value;
+            this.isReset = isReset;
+        }
+    }
+}
