+public class VendingMachine {
+    public enum State { IDLE, COLLECTING, DISPENSING }
+    public enum Result { SUCCESS, INSUFFICIENT_FUNDS, SOLD_OUT, UNKNOWN_ITEM, INVALID_STATE }
+
+    private static final int[] DENOMINATIONS = {100, 25, 10, 5, 1};
+
+    private final Map<String, Integer> stock = new HashMap<>();
+    private final Map<String, Integer> prices = new HashMap<>();
+
+    private State state = State.IDLE;
+    private int credit = 0;
+    private String pendingItem = null;
+    private List<Integer> pendingChange = null;
+
+    public VendingMachine(Map<String, Integer> stock, Map<String, Integer> prices) {
+        if (stock == null || prices == null) {
+            throw new IllegalArgumentException("Maps must not be null");
+        }
+
+        for (Map.Entry<String, Integer> entry : prices.entrySet()) {
+            if (entry.getKey() == null || entry.getValue() == null || entry.getValue() <= 0) {
+                throw new IllegalArgumentException("Invalid price entry");
+            }
+            this.prices.put(entry.getKey(), entry.getValue());
+        }
+
+        for (Map.Entry<String, Integer> entry : stock.entrySet()) {
+            if (entry.getKey() == null || entry.getValue() == null || entry.getValue() < 0) {
+                throw new IllegalArgumentException("Invalid stock entry");
+            }
+            if (!this.prices.containsKey(entry.getKey())) {
+                throw new IllegalArgumentException("Stock item has no price: " + entry.getKey());
+            }
+            this.stock.put(entry.getKey(), entry.getValue());
+        }
+    }
+
+    public State state() {
+        return state;
+    }
+
+    public int credit() {
+        return credit;
+    }
+
+    public int stockOf(String item) {
+        if (item == null) {
+            throw new IllegalArgumentException("Item must not be null");
+        }
+        return stock.getOrDefault(item, 0);
+    }
+
+    public int priceOf(String item) {
+        if (item == null || !prices.containsKey(item)) {
+            throw new IllegalArgumentException("Unknown item");
+        }
+        return prices.get(item);
+    }
+
+    public void insertCoin(int cents) {
+        if (!isValidCoin(cents)) {
+            throw new IllegalArgumentException("Invalid coin: " + cents);
+        }
+        if (state == State.DISPENSING) {
+            throw new IllegalStateException("Cannot insert coins while dispensing");
+        }
+        credit += cents;
+        state = State.COLLECTING;
+    }
+
+    public Result select(String item) {
+        if (item == null) {
+            throw new IllegalArgumentException("Item must not be null");
+        }
+        if (state == State.DISPENSING) {
+            return Result.INVALID_STATE;
+        }
+        if (!prices.containsKey(item)) {
+            return Result.UNKNOWN_ITEM;
+        }
+        if (stockOf(item) == 0) {
+            return Result.SOLD_OUT;
+        }
+
+        int price = prices.get(item);
+        if (credit < price) {
+            return Result.INSUFFICIENT_FUNDS;
+        }
+
+        int changeAmount = credit - price;
+        stock.put(item, stockOf(item) - 1);
+        pendingItem = item;
+        pendingChange = makeChange(changeAmount);
+        credit = 0;
+        state = State.DISPENSING;
+        return Result.SUCCESS;
+    }
+
+    public Dispense takeItem() {
+        if (state != State.DISPENSING) {
+            throw new IllegalStateException("No item is waiting to be taken");
+        }
+
+        Dispense result = new Dispense(pendingItem, pendingChange);
+        pendingItem = null;
+        pendingChange = null;
+        state = State.IDLE;
+        return result;
+    }
+
+    public List<Integer> cancel() {
+        if (state == State.DISPENSING) {
+            throw new IllegalStateException("Cannot cancel while dispensing");
+        }
+
+        List<Integer> returned = makeChange(credit);
+        credit = 0;
+        state = State.IDLE;
+        return returned;
+    }
+
+    private static boolean isValidCoin(int cents) {
+        return cents == 1 || cents == 5 || cents == 10 || cents == 25 || cents == 100;
+    }
+
+    private static List<Integer> makeChange(int amount) {
+        List<Integer> coins = new ArrayList<>();
+        for (int denomination : DENOMINATIONS) {
+            while (amount >= denomination) {
+                coins.add(denomination);
+                amount -= denomination;
+            }
+        }
+        return Collections.unmodifiableList(coins);
+    }
+
+    public static final class Dispense {
+        private final String item;
+        private final List<Integer> change;
+
+        public Dispense(String item, List<Integer> change) {
+            this.item = item;
+            this.change = Collections.unmodifiableList(new ArrayList<>(change));
+        }
+
+        public String item() {
+            return item;
+        }
+
+        public List<Integer> change() {
+            return change;
+        }
+    }
+}
