+import java.util.ArrayList;
+import java.util.HashMap;
+import java.util.List;
+import java.util.Locale;
+import java.util.Map;
+
+public class WordFrequencyAnalyzer {
+    public static Map<String, Integer> countWords(String text) {
+        Map<String, Integer> counts = new HashMap<>();
+        if (text == null) {
+            return counts;
+        }
+
+        StringBuilder current = new StringBuilder();
+        for (int i = 0; i < text.length(); ) {
+            int codePoint = text.codePointAt(i);
+            if (Character.isLetterOrDigit(codePoint)) {
+                current.appendCodePoint(codePoint);
+            } else if (current.length() > 0) {
+                addWord(counts, current.toString());
+                current.setLength(0);
+            }
+            i += Character.charCount(codePoint);
+        }
+
+        if (current.length() > 0) {
+            addWord(counts, current.toString());
+        }
+        return counts;
+    }
+
+    private static void addWord(Map<String, Integer> counts, String rawWord) {
+        String word = rawWord.toLowerCase(Locale.ROOT);
+        counts.put(word, counts.getOrDefault(word, 0) + 1);
+    }
+
+    public static List<String> topWords(String text, int limit) {
+        List<String> result = new ArrayList<>();
+        if (limit <= 0) {
+            return result;
+        }
+
+        Map<String, Integer> counts = countWords(text);
+        result.addAll(counts.keySet());
+        result.sort((a, b) -> {
+            int byCount = Integer.compare(counts.get(b), counts.get(a));
+            if (byCount != 0) {
+                return byCount;
+            }
+            return a.compareTo(b);
+        });
+
+        if (result.size() > limit) {
+            return new ArrayList<>(result.subList(0, limit));
+        }
+        return result;
+    }
+}
