+public class RotatingReverser {
+    private RotatingReverser() {
+    }
+
+    public static String rotateLeft(String text, int positions) {
+        requireText(text);
+        int length = text.length();
+        if (length == 0) {
+            return text;
+        }
+
+        int shift = Math.floorMod(positions, length);
+        if (shift == 0) {
+            return text;
+        }
+
+        return text.substring(shift) + text.substring(0, shift);
+    }
+
+    public static String rotateRight(String text, int positions) {
+        requireText(text);
+        int length = text.length();
+        if (length == 0) {
+            return text;
+        }
+
+        int shift = Math.floorMod(positions, length);
+        if (shift == 0) {
+            return text;
+        }
+
+        return text.substring(length - shift) + text.substring(0, length - shift);
+    }
+
+    public static String reverse(String text) {
+        requireText(text);
+        return new StringBuilder(text).reverse().toString();
+    }
+
+    public static String reverseBetween(String text, int start, int end) {
+        requireText(text);
+
+        if (start < 0 || end > text.length() || start > end) {
+            throw new IndexOutOfBoundsException("Invalid range");
+        }
+
+        if (start == end) {
+            return text;
+        }
+
+        return text.substring(0, start)
+                + new StringBuilder(text.substring(start, end)).reverse()
+                + text.substring(end);
+    }
+
+    private static void requireText(String text) {
+        if (text == null) {
+            throw new IllegalArgumentException("text must not be null");
