+            }
+        }
+        flush(current, counts);
+        return counts;
+    }
+
+    public static List<String> topWords(String text, int limit) {
+        List<String> result = new ArrayList<>();
+        if (limit <= 0) {
+            return result;
+        }
+
+        Map<String, Integer> counts = countWords(text);
+        List<String> words = new ArrayList<>(counts.keySet());
+        words.sort((a, b) -> {
+            int byFrequency = Integer.compare(counts.get(b), counts.get(a));
+            if (byFrequency != 0) {
+                return byFrequency;
+            }
+            return a.compareTo(b);
+        });
+
+        int end = Math.min(limit, words.size());
+        result.addAll(words.subList(0, end));
+        return result;
+    }
+
+    private static boolean isInternalApostrophe(String text, int index) {
+        if (index <= 0 || index >= text.length() - 1) {
+            return false;
+        }
+        char previous = normalizeApostrophe(text.charAt(index - 1));
+        char next = normalizeApostrophe(text.charAt(index + 1));
+        return Character.isLetterOrDigit(previous) && Character.isLetterOrDigit(next);
+    }
+
+    private static char normalizeApostrophe(char c) {
+        if (c == '\u2018' || c == '\u2019') {
+            return '\'';
+        }
+        return c;
+    }
+
+    private static void flush(StringBuilder current, Map<String, Integer> counts) {
+        if (current.length() == 0) {
+            return;
+        }
+        String word = current.toString().toLowerCase(Locale.ROOT);
+        counts.put(word, counts.getOrDefault(word, 0) + 1);
+        current.setLength(0);
+    }
