+            throw new NoSuchElementException("Priority queue is empty");
+        }
+
+        int smallest = heap.get(0);
+        int last = heap.remove(heap.size() - 1);
+
+        if (!heap.isEmpty()) {
+            heap.set(0, last);
+            siftDown(0);
+        }
+
+        return smallest;
+    }
