+            int right = index * 2 + 2;
+            int smallest = index;
+
+            if (left < size && heap.get(left) < heap.get(smallest)) {
+                smallest = left;
+            }
+
+            if (right < size && heap.get(right) < heap.get(smallest)) {
+                smallest = right;
+            }
+
+            if (smallest == index) {
+                break;
+            }
+
+            swap(index, smallest);
+            index = smallest;
+        }
+    }
