+import java.util.ArrayList;
+import java.util.List;
+
+public class EgyptianFraction {
+    public List<Long> decompose(long numerator, long denominator) {
+        if (numerator <= 0 || denominator <= 0) {
+            throw new IllegalArgumentException("Numerator and denominator must be positive.");
+        }
+        if (numerator >= denominator) {
+            throw new IllegalArgumentException("Fraction must be proper.");
+        }
+
+        long n = numerator;
+        long d = denominator;
+
+        long divisor = gcd(n, d);
+        n /= divisor;
+        d /= divisor;
+
+        List<Long> result = new ArrayList<>();
+
+        while (n != 0) {
+            long unitDenominator = d / n + (d % n == 0 ? 0 : 1);
+            result.add(unitDenominator);
+
+            n = n * unitDenominator - d;
+            d = d * unitDenominator;
+
+            divisor = gcd(n, d);
+            n /= divisor;
+            d /= divisor;
+        }
+
+        return result;
+    }
+
+    private long gcd(long a, long b) {
+        while (b != 0) {
+            long temp = a % b;
+            a = b;
+            b = temp;
+        }
+        return Math.abs(a);
+    }
