+public class BifidCipher {
+    private static final String ALPHABET = "ABCDEFGHIKLMNOPQRSTUVWXYZ";
+
+    private final char[][] square = new char[5][5];
+    private final Map<Character, int[]> positions = new HashMap<>();
+
+    public BifidCipher(String keyword) {
+        boolean[] used = new boolean[26];
+        StringBuilder letters = new StringBuilder();
+        String key = normalize(keyword);
+
+        for (int i = 0; i < key.length(); i++) {
+            char c = key.charAt(i);
+            int index = c - 'A';
+            if (!used[index]) {
+                used[index] = true;
+                letters.append(c);
+            }
+        }
+
+        for (int i = 0; i < ALPHABET.length(); i++) {
+            char c = ALPHABET.charAt(i);
+            int index = c - 'A';
+            if (!used[index]) {
+                used[index] = true;
+                letters.append(c);
+            }
+        }
+
+        for (int i = 0; i < 25; i++) {
+            char c = letters.charAt(i);
+            int row = i / 5;
+            int col = i % 5;
+            square[row][col] = c;
+            positions.put(c, new int[]{row + 1, col + 1});
+        }
+    }
+
+    public String encode(String plaintext) {
+        String text = normalize(plaintext);
+        int n = text.length();
+        if (n == 0) {
+            return "";
+        }
+
+        int[] rows = new int[n];
+        int[] cols = new int[n];
+
+        for (int i = 0; i < n; i++) {
+            int[] pos = positions.get(text.charAt(i));
+            rows[i] = pos[0];
+            cols[i] = pos[1];
+        }
+
+        int[] digits = new int[2 * n];
+        for (int i = 0; i < n; i++) {
+            digits[i] = rows[i];
+            digits[n + i] = cols[i];
+        }
+
+        StringBuilder result = new StringBuilder(n);
+        for (int i = 0; i < n; i++) {
+            int row = digits[2 * i];
+            int col = digits[2 * i + 1];
+            result.append(square[row - 1][col - 1]);
+        }
+
+        return result.toString();
+    }
+
+    public String decode(String ciphertext) {
+        String text = normalize(ciphertext);
+        int n = text.length();
+        if (n == 0) {
+            return "";
+        }
+
+        int[] digits = new int[2 * n];
+        int index = 0;
+
+        for (int i = 0; i < n; i++) {
+            int[] pos = positions.get(text.charAt(i));
+            digits[index++] = pos[0];
+            digits[index++] = pos[1];
+        }
+
+        StringBuilder result = new StringBuilder(n);
+        for (int i = 0; i < n; i++) {
+            int row = digits[i];
+            int col = digits[n + i];
+            result.append(square[row - 1][col - 1]);
+        }
+
+        return result.toString();
+    }
+
+    private static String normalize(String s) {
+        if (s == null) {
+            return "";
+        }
+
+        StringBuilder result = new StringBuilder();
+        for (int i = 0; i < s.length(); i++) {
+            char c = Character.toUpperCase(s.charAt(i));
+            if (c == 'J') {
+                c = 'I';
+            }
+            if (c >= 'A' && c <= 'Z') {
+                result.append(c);
+            }
+        }
+
+        return result.toString();
+    }
+}
