+    private void addToken(Map<String, Integer> counts, StringBuilder token) {
+        if (token.length() == 0) {
+            return;
+        }
+
+        String word = token.toString().toLowerCase(Locale.ROOT);
+        counts.merge(word, 1, Integer::sum);
+        token.setLength(0);
