+        }
+
+        List<Map.Entry<String, Integer>> entries = new ArrayList<>(totals.entrySet());
+        entries.sort((left, right) -> {
+            int byCount = Integer.compare(right.getValue(), left.getValue());
+            if (byCount != 0) {
