+            result.add(new int[]{cursor, dayEnd});
+        }
+
+        return result;
+    }
+
+    private static void validateInterval(int[] interval) {
+        if (interval == null || interval.length < 2 || interval[0] > interval[1]) {
+            throw new IllegalArgumentException("Invalid interval");
+        }
+    }
