+import java.util.*;
+
+public class KmerCounter {
+    public Map<String, Integer> count(String sequence, int k) {
+        Map<String, Integer> result = new HashMap<>();
+        if (sequence == null || k <= 0 || k > sequence.length()) {
+            return result;
+        }
+        String upper = sequence.toUpperCase(Locale.ROOT);
+        for (int i = 0; i <= upper.length() - k; i++) {
+            String kmer = upper.substring(i, i + k);
+            if (isValid(kmer)) {
+                result.merge(kmer, 1, Integer::sum);
+            }
+        }
+        return result;
+    }
+
+    private boolean isValid(String kmer) {
+        for (int i = 0; i < kmer.length(); i++) {
+            char c = kmer.charAt(i);
+            if (c != 'A' && c != 'C' && c != 'G' && c != 'T') {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    public List<String> mostFrequent(String sequence, int k, int n) {
+        Map<String, Integer> counts = count(sequence, k);
+        if (n <= 0 || counts.isEmpty()) {
+            return new ArrayList<>();
+        }
+        List<Map.Entry<String, Integer>> entries = new ArrayList<>(counts.entrySet());
+        entries.sort((a, b) -> {
+            int cmp = Integer.compare(b.getValue(), a.getValue());
+            if (cmp != 0) {
+                return cmp;
+            }
+            return a.getKey().compareTo(b.getKey());
+        });
+        List<String> result = new ArrayList<>();
+        for (int i = 0; i < Math.min(n, entries.size()); i++) {
+            result.add(entries.get(i).getKey());
+        }
+        return result;
+    }
