+public class CsvParser {
+    public static List<String> parseLine(String line) {
+        if (line == null) {
+            throw new IllegalArgumentException("Input line cannot be null");
+        }
+        List<String> fields = new ArrayList<>();
+        int i = 0;
+        int n = line.length();
+        while (i < n) {
