+        return values.clone();
+    }
+
+    public RingRotator rotate(int steps) {
+        int length = values.length;
+        if (length == 0) {
+            return new RingRotator();
+        }
+        int shift = Math.floorMod(steps, length);
+        int[] rotated = new int[length];
+        for (int i = 0; i < length; i++) {
+            rotated[(i + shift) % length] = values[i];
+        }
+        return new RingRotator(rotated);
+    }
+
+    public RingRotator reverse() {
+        return reverseRange(0, values.length);
+    }
+
+    public RingRotator reverseRange(int fromIndex, int toIndex) {
+        if (fromIndex < 0 || toIndex > values.length || fromIndex > toIndex) {
+            throw new IllegalArgumentException(
+                    "Invalid range [" + fromIndex + ", " + toIndex
+                            + ") for a ring of size " + values.length);
+        }
+        int[] reversed = values.clone();
+        int left = fromIndex;
+        int right = toIndex - 1;
+        while (left < right) {
+            int swapped = reversed[left];
+            reversed[left] = reversed[right];
+            reversed[right] = swapped;
+            left++;
+            right--;
+        }
+        return new RingRotator(reversed);
+    }
