+public class IntervalMerger {
+    public static int[][] merge(int[][] intervals) {
+        if (intervals == null || intervals.length == 0) {
+            return new int[0][];
+        }
+
+        int validCount = 0;
+        for (int[] interval : intervals) {
+            if (isValid(interval)) {
+                validCount++;
+            }
+        }
+
+        if (validCount == 0) {
+            return new int[0][];
+        }
+
+        int[][] valid = new int[validCount][];
+        int index = 0;
+        for (int[] interval : intervals) {
+            if (isValid(interval)) {
+                valid[index++] = new int[] { interval[0], interval[1] };
+            }
+        }
+
+        java.util.Arrays.sort(valid, (a, b) -> {
+            if (a[0] != b[0]) {
+                return Integer.compare(a[0], b[0]);
+            }
+            return Integer.compare(a[1], b[1]);
+        });
+
+        int[][] merged = new int[valid.length][];
+        int write = 0;
+        int[] current = valid[0];
+
+        for (int i = 1; i < valid.length; i++) {
+            int[] next = valid[i];
+            long gap = (long) next[0] - (long) current[1];
+            if (gap <= 1L) {
+                if (next[1] > current[1]) {
+                    current[1] = next[1];
+                }
+            } else {
+                merged[write++] = new int[] { current[0], current[1] };
+                current = next;
+            }
+        }
+
+        merged[write++] = new int[] { current[0], current[1] };
+        return java.util.Arrays.copyOf(merged, write);
+    }
+
+    private static boolean isValid(int[] interval) {
+        return interval != null
+                && interval.length == 2
+                && interval[0] <= interval[1];
