+    pq.sort((a, b) => a.d - b.d);
+    const { r, c, d } = pq.shift();
+
+    if (d > dist[r][c]) continue;
+    if (r === er && c === ec) break;
+
+    for (const [dr, dc] of dirs) {
+      const nr = r + dr;
+      const nc = c + dc;
+
+      if (!inBounds(nr, nc) || isWall(nr, nc)) continue;
+
+      const nd = d + costOf(nr, nc);
+
+      if (nd < dist[nr][nc]) {
