+  let right = normalized.length - 1;
+
+  while (left < right) {
+    if (normalized[left] !== normalized[right]) return false;
+    left++;
+    right--;
+  }
+
+  return true;
+}
+
+function canFormPalindrome(text) {
+  const normalized = normalizeWord(text);
+  const counts = new Map();
+
+  for (const ch of normalized) {
+    counts.set(ch, (counts.get(ch) || 0) + 1);
+  }
+
+  let oddCount = 0;
+  for (const count of counts.values()) {
+    if (count % 2 === 1) {
+      oddCount++;
+      if (oddCount > 1) return false;
+    }
+  }
+
+  return true;
+}
+
+function palindromicAnagrams(text) {
+  const normalized = normalizeWord(text);
+  if (!normalized) return [];
+
+  const counts = new Map();
+  for (const ch of normalized) {
+    counts.set(ch, (counts.get(ch) || 0) + 1);
+  }
+
+  const letters = [...counts.keys()].sort();
+  const halfCounts = new Map();
+  let middle = "";
+  let oddCount = 0;
+
+  for (const ch of letters) {
+    const count = counts.get(ch);
+    if (count % 2 === 1) {
+      oddCount++;
+      middle = ch;
+    }
+    halfCounts.set(ch, Math.floor(count / 2));
+  }
+
+  if (oddCount > 1) return [];
+
+  const halfLength = letters.reduce(
+    (sum, ch) => sum + halfCounts.get(ch),
+    0
+  );
+  const results = [];
+
+  function build(prefix) {
+    if (prefix.length === halfLength) {
+      const reversed = prefix.split("").reverse().join("");
+      results.push(prefix + middle + reversed);
+      return;
+    }
+
+    for (const ch of letters) {
+      const remaining = halfCounts.get(ch);
+      if (remaining > 0) {
+        halfCounts.set(ch, remaining - 1);
+        build(prefix + ch);
+        halfCounts.set(ch, remaining);
+      }
+    }
+  }
