+'use strict';
+
+const LENGTH = {
+  m: 1,
+  km: 1000,
+  cm: 0.01,
+  mm: 0.001,
+  mi: 1609.344,
+  ft: 0.3048,
+  in: 0.0254,
+};
+
+const MASS = {
+  g: 1,
+  kg: 1000,
+  mg: 0.001,
+  lb: 453.59237,
+  oz: 28.349523125,
+};
+
+const TEMPERATURE_UNITS = ['c', 'f', 'k'];
+const ABSOLUTE_ZERO_CELSIUS = -273.15;
+const EPSILON = 1e-9;
+
+function findCategory(unit) {
+  if (Object.prototype.hasOwnProperty.call(LENGTH, unit)) {
+    return 'length';
+  }
+  if (Object.prototype.hasOwnProperty.call(MASS, unit)) {
+    return 'mass';
+  }
+  if (TEMPERATURE_UNITS.includes(unit)) {
+    return 'temperature';
+  }
+  throw new Error(`Unknown unit: ${unit}`);
+}
+
+function temperatureToCelsius(value, unit) {
+  switch (unit) {
+    case 'c':
+      return value;
+    case 'f':
+      return ((value - 32) * 5) / 9;
+    case 'k':
+      return value - 273.15;
+    default:
+      throw new Error(`Unknown temperature unit: ${unit}`);
+  }
+}
+
