+  switch (unit) {
+    case 'c':
+      return celsius;
+    case 'f':
+      return (celsius * 9) / 5 + 32;
+    case 'k':
+      return celsius + 273.15;
+    default:
+      throw new Error(`Unknown temperature unit: ${unit}`);
+  }
+}
+
+function convert(value, fromUnit, toUnit) {
+  const from = String(fromUnit).toLowerCase();
+  const to = String(toUnit).toLowerCase();
+
+  const fromCategory = findCategory(from);
+  const toCategory = findCategory(to);
+
+  if (fromCategory !== toCategory) {
+    throw new Error(
+      `Cannot convert between ${fromCategory} and ${toCategory} units`
+    );
+  }
