+  let str = number.trim();
+  let isNegative = false;
+  if (str.startsWith('-')) {
+    isNegative = true;
+    str = str.slice(1);
+  }
+
+  if (str === '' || str === '.') {
+    throw new Error('Invalid number');
+  }
