+class PriorityQueue {
+  constructor() {
+    this.heap = [];
+    this.nextOrder = 0;
+  }
+
+  enqueue(item, priority) {
+    if (Number.isNaN(priority)) {
+      throw new Error('Priority must not be NaN');
+    }
+    const entry = { item, priority, order: this.nextOrder++ };
+    this.heap.push(entry);
+    this._bubbleUp(this.heap.length - 1);
+  }
+
+  dequeue() {
+    if (this.heap.length === 0) {
+      return undefined;
+    }
+    const root = this.heap[0];
+    const last = this.heap.pop();
+    if (this.heap.length > 0) {
+      this.heap[0] = last;
+      this._siftDown(0);
+    }
+    return root.item;
+  }
+
+  peek() {
+    if (this.heap.length === 0) {
+      return undefined;
+    }
+    return this.heap[0].item;
+  }
+
+  isEmpty() {
+    return this.heap.length === 0;
+  }
+
+  size() {
+    return this.heap.length;
+  }
+
+  changePriority(item, newPriority) {
+    if (Number.isNaN(newPriority)) {
+      throw new Error('Priority must not be NaN');
+    }
+
+    let targetIdx = -1;
+    let targetOrder = Infinity;
+    for (let i = 0; i < this.heap.length; i++) {
+      const entry = this.heap[i];
+      if (Object.is(entry.item, item) && entry.order < targetOrder) {
+        targetIdx = i;
+        targetOrder = entry.order;
+      }
+    }
