+    this.heap[targetIdx].priority = newPriority;
+    const settled = this._bubbleUp(targetIdx);
+    this._siftDown(settled);
+  }
+
+  _less(a, b) {
+    if (a.priority !== b.priority) {
+      return a.priority < b.priority;
+    }
+    return a.order < b.order;
+  }
+
+  _swap(i, j) {
+    const tmp = this.heap[i];
+    this.heap[i] = this.heap[j];
+    this.heap[j] = tmp;
+  }
+
+  _bubbleUp(i) {
+    while (i > 0) {
+      const parent = (i - 1) >> 1;
+      if (this._less(this.heap[i], this.heap[parent])) {
+        this._swap(i, parent);
+        i = parent;
+      } else {
