+    while (true) {
+      let smallest = i;
+      const left = 2 * i + 1;
+      const right = 2 * i + 2;
+      if (left < n && this._less(this.heap[left], this.heap[smallest])) {
+        smallest = left;
+      }
+      if (right < n && this._less(this.heap[right], this.heap[smallest])) {
+        smallest = right;
+      }
+      if (smallest === i) {
+        break;
+      }
+      this._swap(i, smallest);
+      i = smallest;
+    }
+  }
