+function greatestCommonDivisor(a, b) {
+  a = Math.abs(a);
+  b = Math.abs(b);
+
+  while (b !== 0) {
+    const remainder = a % b;
+    a = b;
+    b = remainder;
+  }
+
+  return a;
+}
+
+function simplify(numerator, denominator) {
+  if (denominator === 0) {
+    throw new Error('denominator must not be zero');
+  }
+
+  const sign = denominator < 0 ? -1 : 1;
+  const n = numerator * sign;
+  const d = denominator * sign;
+
+  if (n === 0) {
+    return { numerator: 0, denominator: 1 };
+  }
+
+  const divisor = greatestCommonDivisor(n, d);
+  return { numerator: n / divisor, denominator: d / divisor };
+}
+
+function roundFraction(numerator, denominator) {
+  const { numerator: n, denominator: d } = simplify(numerator, denominator);
+
+  let whole = Math.trunc(n / d);
+  let remainder = n - whole * d;
+
+  if (remainder < 0) {
+    whole -= 1;
+    remainder += d;
+  }
+
+  return 2 * remainder >= d ? whole + 1 : whole;
+}
+
+function toMixedNumber(numerator, denominator) {
+  const { numerator: n, denominator: d } = simplify(numerator, denominator);
+
+  if (n === 0) {
+    return '0';
+  }
+
+  const sign = n < 0 ? '-' : '';
+  const absolute = Math.abs(n);
+  const whole = Math.floor(absolute / d);
+  const remainder = absolute % d;
+
+  if (remainder === 0) {
+    return sign + whole;
+  }
+
+  if (whole === 0) {
+    return sign + remainder + '/' + d;
+  }
+
+  return sign + whole + ' ' + remainder + '/' + d;
+}
+
+module.exports = { simplify, roundFraction, toMixedNumber };
