+class Graph {
+  constructor() {
+    this.adjacency = Object.create(null);
+  }
+
+  addVertex(vertex) {
+    if (this.hasVertex(vertex)) {
+      return false;
+    }
+
+    this.adjacency[vertex] = [];
+    return true;
+  }
+
+  hasVertex(vertex) {
+    return Object.prototype.hasOwnProperty.call(this.adjacency, vertex);
+  }
+
+  addEdge(from, to) {
+    if (!this.hasVertex(from)) {
+      this.addVertex(from);
+    }
+
+    if (!this.hasVertex(to)) {
+      this.addVertex(to);
+    }
+
+    if (this.adjacency[from].includes(to)) {
+      return false;
+    }
+
+    this.adjacency[from].push(to);
+    return true;
+  }
+
+  hasEdge(from, to) {
+    return this.hasVertex(from) && this.adjacency[from].includes(to);
+  }
+
+  neighbors(vertex) {
+    if (!this.hasVertex(vertex)) {
+      return [];
+    }
+
+    return this.adjacency[vertex].slice();
+  }
+
+  removeEdge(from, to) {
+    if (!this.hasVertex(from)) {
+      return false;
+    }
+
+    const list = this.adjacency[from];
+    const index = list.indexOf(to);
+
+    if (index === -1) {
+      return false;
+    }
+
+    list.splice(index, 1);
+    return true;
+  }
+
+  removeVertex(vertex) {
+    if (!this.hasVertex(vertex)) {
+      return false;
+    }
+
+    delete this.adjacency[vertex];
+
+    for (const key of Object.keys(this.adjacency)) {
+      const list = this.adjacency[key];
+      const index = list.indexOf(vertex);
+
+      if (index !== -1) {
