base_converter.js
```
function convert(value, fromBase, toBase) {
  throw new Error('Not implemented');
}

module.exports = { convert };

```

Ok, I will:

1. I validate that both bases are integers from 2 to 36 and that the input is a non-empty string. 2. I normalize the input to uppercase and verify each character is a valid digit for the source base. 3. I accumulate the value in a BigInt using digit values from 0 to 35, which avoids precision loss for large inputs. 4. I repeatedly divide by the target base, mapping remainders back to uppercase digits. 5. I return zero as "0", strip leading zeros naturally, and throw errors for invalid bases, characters, or empty input.

Here are the diffs for those changes:

```diff
--- base_converter.js
+++ base_converter.js
@@ ... @@
-function convert(value, fromBase, toBase) {
-  throw new Error('Not implemented');
-}
-
-module.exports = { convert };
+const DIGITS = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
+
+function convert(value, fromBase, toBase) {
+  if (!Number.isInteger(fromBase) || fromBase < 2 || fromBase > 36) {
+    throw new Error('fromBase must be an integer between 2 and 36');
+  }
+
+  if (!Number.isInteger(toBase) || toBase < 2 || toBase > 36) {
+    throw new Error('toBase must be an integer between 2 and 36');
+  }
+
+  if (typeof value !== 'string' || value.length === 0) {
+    throw new Error('value must be a non-empty string');
+  }
+
+  let result = 0n;
+  const normalized = value.toUpperCase();
+
+  for (const character of normalized) {
+    const digit = DIGITS.indexOf(character);
+
+    if (digit === -1 || digit >= fromBase) {
+      throw new Error(`invalid digit ${character} for base ${fromBase}`);
+    }
+
+    result = result * BigInt(fromBase) + BigInt(digit);
+  }
+
+  if (result === 0n) {
+    return '0';
+  }
+
+  let output = '';
+  const base = BigInt(toBase);
+
+  while (result > 0n) {
+    const remainder = Number(result % base);
+    output = DIGITS[remainder] + output;
+    result /= base;
+  }
+
+  return output;
+}
+
+module.exports = { convert };
```

