+// Count the words in a phrase and report the most common ones.
+
+// Letters and digits, joined by single internal apostrophes.
+const WORD_PATTERN = /[a-z0-9]+(?:'[a-z0-9]+)*/g;
+
+/**
+ * Count occurrences of each word in the given text.
+ *
+ * @param {string} text
+ * @returns {Object<string, number>}
+ */
+function countWords(text) {
+  const counts = new Map();
+
+  if (typeof text !== 'string' || text.length === 0) {
+    return {};
+  }
+
+  const words = text.toLowerCase().match(WORD_PATTERN) || [];
+
+  for (const word of words) {
+    counts.set(word, (counts.get(word) || 0) + 1);
+  }
+
+  return Object.fromEntries(counts);
+}
+
+/**
+ * Return the most frequent words, most common first.
+ *
+ * @param {string} text
+ * @param {number} [n]
+ * @returns {Array<{ word: string, count: number }>}
+ */
+function topWords(text, n) {
+  const counts = countWords(text);
+
+  const entries = Object.keys(counts).map((word) => ({
+    word,
+    count: counts[word],
+  }));
+
+  entries.sort((a, b) => {
+    if (b.count !== a.count) {
+      return b.count - a.count;
+    }
+    if (a.word < b.word) return -1;
+    if (a.word > b.word) return 1;
+    return 0;
+  });
+
+  if (n === undefined) {
+    return entries;
+  }
+
+  if (!Number.isFinite(n) || n <= 0) {
+    return [];
+  }
+
+  return entries.slice(0, Math.floor(n));
