Ok, I will:

1. I model the grid as a boolean matrix where false means open and true means blocked.
2. I first reject empty grids, empty rows, non-rectangular grids, blocked start cells, and blocked end cells by returning None.
3. I use breadth-first search from the top-left cell, storing the number of moves to each visited open cell.
4. I expand each cell's four orthogonal neighbors, skipping out-of-bounds, blocked, or already visited cells.
5. When I reach the bottom-right cell, I return its move count; if the queue empties first, I return None.

Here are the diffs for those changes:

```diff
--- shortest_path.rs
+++ shortest_path.rs
@@ ... @@
-pub fn shortest_path(grid: &[Vec<bool>]) -> Option<usize> {
-    unimplemented!()
-}
+use std::collections::VecDeque;
+
+pub fn shortest_path(grid: &[Vec<bool>]) -> Option<usize> {
+    if grid.is_empty() {
+        return None;
+    }
+
+    let rows = grid.len();
+    let cols = grid[0].len();
+
+    if cols == 0 {
+        return None;
+    }
+
+    if grid.iter().any(|row| row.len() != cols) {
+        return None;
+    }
+
+    if grid[0][0] || grid[rows - 1][cols - 1] {
+        return None;
+    }
+
+    let mut dist = vec![vec![None; cols]; rows];
+    dist[0][0] = Some(0);
+
+    let mut queue = VecDeque::new();
+    queue.push_back((0, 0));
+
+    let directions = [(-1isize, 0isize), (1, 0), (0, -1), (0, 1)];
+
+    while let Some((r, c)) = queue.pop_front() {
+        let d = dist[r][c].unwrap();
+
+        if r == rows - 1 && c == cols - 1 {
+            return Some(d);
+        }
+
+        for &(dr, dc) in &directions {
+            let nr = r as isize + dr;
+            let nc = c as isize + dc;
+
+            if nr < 0 || nc < 0 {
+                continue;
+            }
+
+            let nr = nr as usize;
+            let nc = nc as usize;
+
+            if nr >= rows || nc >= cols {
+                continue;
+            }
+
+            if grid[nr][nc] || dist[nr][nc].is_some() {
+                continue;
+            }
+
+            dist[nr][nc] = Some(d + 1);
+            queue.push_back((nr, nc));
+        }
+    }
+
+    None
+}
