+            "daily" => start_dt.add_days(n * interval as i64),
+            "weekly" => start_dt.add_days(n * 7 * interval as i64),
+            "monthly" => start_dt.add_months(n * interval as i64),
+            "yearly" => start_dt.add_years(n * interval as i64),
+            _ => return vec![],
