+pub fn convert(input: &str, from_base: u32, to_base: u32) -> Result<String, String> {
+    if !(2..=36).contains(&from_base) || !(2..=36).contains(&to_base) {
+        return Err("base must be between 2 and 36".to_string());
+    }
+    if input.is_empty() {
+        return Err("input must not be empty".to_string());
+    }
+    let mut digits = Vec::new();
+    for c in input.chars() {
+        let d = match char_to_digit(c) {
+            Some(d) => d,
+            None => return Err(format!("invalid digit '{}' for base {}", c, from_base)),
+        };
+        if d >= from_base {
+            return Err(format!("invalid digit '{}' for base {}", c, from_base));
+        }
+        digits.push(d);
+    }
+    if digits.iter().all(|&d| d == 0) {
+        return Ok("0".to_string());
+    }
+    let mut result = vec![0u32];
+    for &d in &digits {
+        let mut carry = d;
+        for elem in result.iter_mut() {
+            let val = *elem * from_base + carry;
+            *elem = val % to_base;
+            carry = val / to_base;
+        }
+        while carry > 0 {
+            result.push(carry % to_base);
+            carry /= to_base;
+        }
+    }
+    let s: String = result.iter().rev().map(|&d| digit_to_char(d)).collect();
+    Ok(s)
+}
+
+fn char_to_digit(c: char) -> Option<u32> {
+    match c {
+        '0'..='9' => Some(c as u32 - '0' as u32),
+        'a'..='z' => Some(c as u32 - 'a' as u32 + 10),
+        'A'..='Z' => Some(c as u32 - 'A' as u32 + 10),
+        _ => None,
+    }
+}
+
+fn digit_to_char(d: u32) -> char {
+    if d < 10 {
+        (b'0' + d as u8) as char
+    } else {
+        (b'a' + (d - 10) as u8) as char
+    }
+}
