+pub struct RingBuffer<T> {
+    capacity: usize,
+    buffer: Vec<Option<T>>,
+    read_index: usize,
+    write_index: usize,
+    len: usize,
+}
+
+impl<T> RingBuffer<T> {
+    pub fn new(capacity: usize) -> Self {
+        let mut buffer = Vec::with_capacity(capacity);
+        for _ in 0..capacity {
+            buffer.push(None);
+        }
+
+        Self {
+            capacity,
+            buffer,
+            read_index: 0,
+            write_index: 0,
+            len: 0,
+        }
+    }
+
+    pub fn capacity(&self) -> usize {
+        self.capacity
+    }
+
+    pub fn len(&self) -> usize {
+        self.len
+    }
+
+    pub fn is_empty(&self) -> bool {
+        self.len == 0
+    }
+
+    pub fn is_full(&self) -> bool {
+        self.len == self.capacity
+    }
+
+    pub fn write(&mut self, value: T) -> Result<(), T> {
+        if self.is_full() {
+            return Err(value);
+        }
+
+        self.buffer[self.write_index] = Some(value);
+        self.write_index = (self.write_index + 1) % self.capacity;
+        self.len += 1;
+        Ok(())
+    }
+
+    pub fn overwrite(&mut self, value: T) -> Option<T> {
+        if self.capacity == 0 {
+            return Some(value);
+        }
+
+        if self.is_full() {
+            let old = self.buffer[self.read_index].take();
+            self.buffer[self.write_index] = Some(value);
+            self.read_index = (self.read_index + 1) % self.capacity;
+            self.write_index = (self.write_index + 1) % self.capacity;
+            old
+        } else {
+            self.buffer[self.write_index] = Some(value);
+            self.write_index = (self.write_index + 1) % self.capacity;
+            self.len += 1;
+            None
+        }
+    }
+
+    pub fn read(&mut self) -> Option<T> {
+        if self.is_empty() {
+            return None;
+        }
+
+        let value = self.buffer[self.read_index].take();
+        self.read_index = (self.read_index + 1) % self.capacity;
+        self.len -= 1;
+        value
+    }
+
+    pub fn clear(&mut self) {
+        for slot in &mut self.buffer {
+            *slot = None;
+        }
+        self.read_index = 0;
+        self.write_index = 0;
+        self.len = 0;
+    }
+
+    pub fn peek(&self) -> Option<&T> {
+        if self.is_empty() {
+            None
+        } else {
+            self.buffer[self.read_index].as_ref()
+        }
+    }
+
+    pub fn iter(&self) -> impl Iterator<Item = &T> + '_ {
+        self.buffer
+            .iter()
+            .skip(self.read_index)
+            .chain(self.buffer.iter().take(self.read_index))
+            .filter_map(|value| value.as_ref())
+    }
+}
