+pub struct Interval {
+    pub start: i64,
+    pub end: i64,
+    pub weight: i64,
+}
+
+pub fn max_weight_schedule(intervals: &[Interval]) -> i64 {
+    let mut valid: Vec<Interval> = intervals
+        .iter()
+        .filter(|iv| iv.start < iv.end && iv.weight > 0)
+        .cloned()
+        .collect();
+
+    if valid.is_empty() {
+        return 0;
+    }
+
+    valid.sort_by_key(|iv| iv.end);
+
+    let n = valid.len();
+    let mut dp = vec![0i64; n + 1];
+    let mut ends = vec![0i64; n];
+
+    for (i, iv) in valid.iter().enumerate() {
+        ends[i] = iv.end;
+    }
+
+    for i in 1..=n {
+        let iv = &valid[i - 1];
+        let j = ends[..i - 1].partition_point(|&e| e <= iv.start);
+        let take = iv.weight + dp[j];
+        let skip = dp[i - 1];
+        dp[i] = take.max(skip);
+    }
+
+    dp[n]
+}
