+            }
+            while matches!(self.peek(), Some(c) if c.is_ascii_digit()) {
+                let _ = self.next_char();
+            }
+        }
+        let number_text: String = self.chars[start..self.pos].iter().collect();
+        number_text
+            .parse::<f64>()
+            .map_err(|_| self.error("invalid number"))
