+/// Returns an empty vector when no complete window exists, that is when the
+/// list is empty, when `window_size` is zero, or when `window_size` is
+/// larger than the list.
+pub fn max_sliding_window(numbers: &[i32], window_size: usize) -> Vec<i32> {
+    if window_size == 0 || window_size > numbers.len() {
+        return Vec::new();
+    }
+
+    let mut maxima = Vec::with_capacity(numbers.len() - window_size + 1);
+
