+    // from the front to the back of the queue. The front is therefore always
+    // the index of the maximum of the current window.
+    let mut candidates: VecDeque<usize> = VecDeque::new();
+
+    for (index, &value) in numbers.iter().enumerate() {
+        // Drop indices that have slid out of the window.
+        while let Some(&front) = candidates.front() {
+            if front + window_size <= index {
+                candidates.pop_front();
+            } else {
+                break;
+            }
+        }
+
+        // Drop indices whose values can never be a maximum again.
+        while let Some(&back) = candidates.back() {
+            if numbers[back] <= value {
+                candidates.pop_back();
+            } else {
+                break;
+            }
+        }
+
+        candidates.push_back(index);
+
+        // The first full window ends at index `window_size - 1`.
+        if index + 1 >= window_size {
+            let best = *candidates.front().expect("the queue always holds the current index");
+            maxima.push(numbers[best]);
+        }
+    }
+
+    maxima
