+/// Returns `true` if `a` and `b` are anagrams, ignoring case and every
+/// non-ASCII-letter character.
+pub fn are_anagrams(a: &str, b: &str) -> bool {
+    let mut left = normalized(a);
+    let mut right = normalized(b);
+
+    if left.len() != right.len() {
+        return false;
+    }
+
+    left.sort_unstable();
+    right.sort_unstable();
+    left == right
+}
+
+/// Returns the lexicographically smallest palindrome that is an anagram of
+/// `text`, or `None` if no such palindrome exists.
+pub fn smallest_palindromic_anagram(text: &str) -> Option<String> {
+    let mut counts = [0usize; 26];
+    for letter in normalized(text) {
+        counts[(letter as u8 - b'a') as usize] += 1;
+    }
+
+    let odd_letters = counts.iter().filter(|&&n| n % 2 == 1).count();
+    if odd_letters > 1 {
+        return None;
+    }
+
+    let mut half = String::new();
+    let mut middle = None;
+
+    for (index, &count) in counts.iter().enumerate() {
+        let letter = (b'a' + index as u8) as char;
+        for _ in 0..count / 2 {
+            half.push(letter);
+        }
+        if count % 2 == 1 {
+            middle = Some(letter);
+        }
+    }
+
+    let mut result = half.clone();
+    if let Some(letter) = middle {
+        result.push(letter);
+    }
+    result.extend(half.chars().rev());
+
+    Some(result)
