+pub fn parse_csv_line(line: &str) -> Result<Vec<String>, String> {
+    if line.is_empty() {
+        return Ok(vec![]);
+    }
+
+    let chars: Vec<char> = line.chars().collect();
+    let mut fields = Vec::new();
+    let mut i = 0;
+    let n = chars.len();
+
+    while i < n {
+        let mut field = String::new();
+
+        if chars[i] == '"' {
+            // Quoted field
+            i += 1; // skip opening quote
+            loop {
+                if i >= n {
+                    return Err("unclosed quoted field".to_string());
+                }
+                if chars[i] == '"' {
+                    if i + 1 < n && chars[i + 1] == '"' {
+                        // Escaped quote
+                        field.push('"');
+                        i += 2;
+                    } else {
+                        // Closing quote
+                        i += 1;
+                        break;
+                    }
+                } else {
+                    field.push(chars[i]);
+                    i += 1;
+                }
+            }
+            // After closing quote, must be comma or end
+            if i < n && chars[i] != ',' {
+                return Err("unexpected character after closing quote".to_string());
+            }
+        } else {
+            // Unquoted field
+            while i < n && chars[i] != ',' {
+                if chars[i] == '"' {
+                    return Err("unexpected quote in unquoted field".to_string());
+                }
+                field.push(chars[i]);
+                i += 1;
+            }
+        }
+
+        fields.push(field);
+
+        if i < n {
+            // Skip comma
+            i += 1;
+            // If comma was the last character, add trailing empty field
+            if i == n {
+                fields.push(String::new());
+            }
+        }
+    }
+
+    Ok(fields)
