+use std::collections::HashMap;
+
+#[derive(Debug, PartialEq, Eq)]
+pub enum Expr {
+    Number(i64),
+    Add(Box<Expr>, Box<Expr>),
+    Sub(Box<Expr>, Box<Expr>),
+    Mul(Box<Expr>, Box<Expr>),
+    Div(Box<Expr>, Box<Expr>),
+    Neg(Box<Expr>),
+    Var(String),
