+pub enum EvalError {
+    DivisionByZero,
+    UnknownVariable(String),
+}
+
+pub fn eval(expr: &Expr, variables: &HashMap<String, i64>) -> Result<i64, EvalError> {
+    match expr {
+        Expr::Number(n) => Ok(*n),
+        Expr::Var(name) => variables
+            .get(name)
+            .copied()
+            .ok_or_else(|| EvalError::UnknownVariable(name.clone())),
+        Expr::Add(a, b) => Ok(eval(a, variables)? + eval(b, variables)?),
+        Expr::Sub(a, b) => Ok(eval(a, variables)? - eval(b, variables)?),
+        Expr::Mul(a, b) => Ok(eval(a, variables)? * eval(b, variables)?),
+        Expr::Div(a, b) => {
+            let numerator = eval(a, variables)?;
+            let denominator = eval(b, variables)?;
+            if denominator == 0 {
+                Err(EvalError::DivisionByZero)
+            } else {
+                Ok(numerator / denominator)
+            }
+        }
+        Expr::Neg(e) => Ok(-eval(e, variables)?),
+    }
+}
