+pub fn compress(input: &str) -> String {
+    let mut result = String::new();
+    let mut chars = input.chars().peekable();
+
+    while let Some(current) = chars.next() {
+        let mut count = 1;
+
+        while let Some(&next) = chars.peek() {
+            if next == current {
+                count += 1;
+                chars.next();
