+fn phi(mut n: u32) -> u64 {
+    if n == 0 {
+        return 0;
+    }
+    let mut result = n as u64;
+    let mut p = 2;
+    while p <= n / p {
+        if n % p == 0 {
+            while n % p == 0 {
+                n /= p;
+            }
+            result -= result / p as u64;
+        }
+        p += 1;
+    }
+    if n > 1 {
+        result -= result / n as u64;
+    }
+    result
+}
+
+fn binomial(n: u32, k: u32) -> u128 {
+    if k > n {
+        return 0;
+    }
+    let k = k.min(n - k);
+    let mut result: u128 = 1;
+    for i in 1..=k {
+        result = result * (n - k + i) as u128 / i as u128;
+    }
+    result
