+pub fn compress(input: &str) -> String {
+    let mut out = String::new();
+    let mut chars = input.chars().peekable();
+
+    while let Some(ch) = chars.next() {
+        let mut count = 1;
+        while chars.peek() == Some(&ch) {
+            chars.next();
+            count += 1;
+        }
+
+        if count == 1 {
+            if ch == '~' {
+                out.push_str("~~");
+            } else {
+                out.push(ch);
+            }
+        } else {
+            out.push('~');
+            out.push_str(&count.to_string());
+            out.push(':');
+            out.push(ch);
+        }
+    }
+
+    out
+}
+
+pub fn decompress(input: &str) -> Result<String, DecompressError> {
+    let mut out = String::new();
+    let mut chars = input.chars().peekable();
+
+    while let Some(ch) = chars.next() {
+        if ch != '~' {
+            out.push(ch);
+            continue;
+        }
+
+        match chars.next() {
+            Some('~') => out.push('~'),
+            Some(first_digit) if first_digit.is_ascii_digit() => {
+                let mut digits = String::new();
+                digits.push(first_digit);
+
+                while let Some(&next) = chars.peek() {
+                    if next.is_ascii_digit() {
+                        digits.push(chars.next().unwrap());
+                    } else {
+                        break;
+                    }
+                }
+
+                if chars.next() != Some(':') {
+                    return Err(DecompressError::InvalidEscape);
+                }
+
+                if digits.len() > 1 && digits.starts_with('0') {
+                    return Err(DecompressError::InvalidCount);
+                }
+
+                let count = digits
+                    .parse::<usize>()
+                    .map_err(|_| DecompressError::InvalidCount)?;
+
+                if count < 2 {
+                    return Err(DecompressError::InvalidCount);
+                }
+
+                match chars.next() {
+                    Some(repeated) => {
+                        for _ in 0..count {
+                            out.push(repeated);
+                        }
+                    }
+                    None => return Err(DecompressError::MissingCharacter),
+                }
+            }
+            Some(_) => return Err(DecompressError::InvalidEscape),
+            None => return Err(DecompressError::InvalidEscape),
+        }
+    }
