+use std::collections::HashMap;
+
+pub fn prime_permutations(digits: u32) -> Vec<[u64; 3]> {
+    if !(3..=6).contains(&digits) {
+        return Vec::new();
+    }
+
+    let start = 10u64.pow(digits - 1);
+    let end = 10u64.pow(digits) - 1;
+    let limit = end as usize;
+
+    let mut is_prime = vec![true; limit + 1];
+    is_prime[0] = false;
+    if limit >= 1 {
+        is_prime[1] = false;
+    }
+
+    let mut p = 2usize;
+    while p * p <= limit {
+        if is_prime[p] {
+            let mut multiple = p * p;
+            while multiple <= limit {
+                is_prime[multiple] = false;
+                multiple += p;
+            }
+        }
+        p += 1;
+    }
+
+    let mut groups: HashMap<Vec<u8>, Vec<u64>> = HashMap::new();
+
+    for n in start..=end {
+        if is_prime[n as usize] {
+            let mut key: Vec<u8> = n
+                .to_string()
+                .bytes()
+                .map(|byte| byte - b'0')
+                .collect();
+            key.sort_unstable();
+            groups.entry(key).or_default().push(n);
+        }
+    }
+
+    let mut result = Vec::new();
+
+    for values in groups.values_mut() {
+        values.sort_unstable();
+
+        for i in 0..values.len() {
+            for j in (i + 1)..values.len() {
+                let a = values[i];
+                let b = values[j];
+                let c = 2 * b - a;
+
+                if c > b && values.binary_search(&c).is_ok() {
+                    result.push([a, b, c]);
+                }
+            }
+        }
+    }
+
+    result.sort_unstable();
+    result
