+fn split_version(version: &str) -> (&str, Option<&str>) {
+    let without_build = version.split('+').next().unwrap_or("");
+    match without_build.split_once('-') {
+        Some((core, prerelease)) => (core, Some(prerelease)),
+        None => (without_build, None),
