+fn compare_core(left: &str, right: &str) -> Ordering {
+    let left_parts: Vec<&str> = left.split('.').collect();
+    let right_parts: Vec<&str> = right.split('.').collect();
+    let len = left_parts.len().max(right_parts.len());
