+        let right_part = right_parts.get(i).copied().unwrap_or("0");
+        let ordering = compare_numeric_identifier(left_part, right_part);
+        if ordering != Ordering::Equal {
+            return ordering;
+        }
+    }
+
+    Ordering::Equal
+}
+
+fn compare_prerelease(left: Option<&str>, right: Option<&str>) -> Ordering {
+    match (left, right) {
+        (None, None) => Ordering::Equal,
+        (None, Some(_)) => Ordering::Greater,
+        (Some(_), None) => Ordering::Less,
+        (Some(left), Some(right)) => {
+            let left_parts: Vec<&str> = left.split('.').collect();
+            let right_parts: Vec<&str> = right.split('.').collect();
+            let len = left_parts.len().max(right_parts.len());
+
+            for i in 0..len {
+                match (left_parts.get(i).copied(), right_parts.get(i).copied()) {
+                    (None, None) => return Ordering::Equal,
+                    (None, Some(_)) => return Ordering::Less,
+                    (Some(_), None) => return Ordering::Greater,
+                    (Some(left_part), Some(right_part)) => {
+                        let ordering = compare_prerelease_identifier(left_part, right_part);
+                        if ordering != Ordering::Equal {
+                            return ordering;
