+        }
+        if start == i {
+            return Err(ParseError::InvalidFormat);
+        }
+
+        let num: u64 = input[start..i]
+            .parse()
+            .map_err(|_| ParseError::Overflow)?;
+
+        if i >= bytes.len() {
+            return Err(ParseError::InvalidFormat);
+        }
+
+        let multiplier: u64 = match bytes[i] {
+            b'd' => 86_400,
+            b'h' => 3_600,
+            b'm' => 60,
+            b's' => 1,
+            other => return Err(ParseError::UnknownUnit(other as char)),
