+        }
+        let count = if let Token::Number(n) = self.tokens[self.pos] {
+            self.pos += 1;
+            n
+        } else {
+            1
+        };
+        if self.pos >= self.tokens.len() {
+            return None;
+        }
+        match self.tokens[self.pos] {
+            Token::Command(c) => {
+                self.pos += 1;
+                Some(Expr::Command(c, count))
+            }
+            Token::OpenBracket => {
+                self.pos += 1;
+                let mut exprs = Vec::new();
+                while self.pos < self.tokens.len() && self.tokens[self.pos] != Token::CloseBracket {
