+use std::sync::atomic::{AtomicUsize, Ordering};
+
+static NEXT_QUEUE_ID: AtomicUsize = AtomicUsize::new(1);
+
+#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
+pub struct Handle {
+    queue_id: usize,
+    item_id: usize,
