+    item: T,
+    priority: i32,
+    sequence: usize,
+    item_id: usize,
+}
+
+#[derive(Debug)]
+pub struct PriorityQueue<T> {
+    queue_id: usize,
+    heap: Vec<Entry<T>>,
+    positions: Vec<Option<usize>>,
+    next_item_id: usize,
+    next_sequence: usize,
+}
+
+impl<T> PriorityQueue<T> {
+    pub fn new() -> Self {
+        Self {
+            queue_id: NEXT_QUEUE_ID.fetch_add(1, Ordering::Relaxed),
+            heap: Vec::new(),
+            positions: Vec::new(),
+            next_item_id: 0,
+            next_sequence: 0,
+        }
+    }
+
+    pub fn len(&self) -> usize {
+        self.heap.len()
+    }
+
+    pub fn is_empty(&self) -> bool {
+        self.heap.is_empty()
+    }
