+    pub fn push(&mut self, item: T, priority: i32) -> Handle {
+        let item_id = self.next_item_id;
+        self.next_item_id += 1;
+
+        let sequence = self.next_sequence;
+        self.next_sequence += 1;
+
+        let entry = Entry {
+            item,
+            priority,
+            sequence,
+            item_id,
+        };
+
+        let index = self.heap.len();
+        self.heap.push(entry);
+
+        if self.positions.len() <= item_id {
+            self.positions.resize(item_id + 1, None);
+        }
+        self.positions[item_id] = Some(index);
+
+        self.sift_up(index);
+
+        Handle {
+            queue_id: self.queue_id,
+            item_id,
+        }
+    }
+
+    pub fn peek(&self) -> Option<&T> {
+        self.heap.first().map(|entry| &entry.item)
+    }
+
+    pub fn peek_priority(&self) -> Option<i32> {
+        self.heap.first().map(|entry| entry.priority)
+    }
+
+    pub fn pop(&mut self) -> Option<T> {
+        if self.heap.is_empty() {
+            None
+        } else {
+            Some(self.remove_at(0))
+        }
+    }
+
+    pub fn change_priority(&mut self, handle: Handle, priority: i32) -> bool {
+        if handle.queue_id != self.queue_id {
+            return false;
+        }
+
+        let index = match self.positions.get(handle.item_id).and_then(|position| *position) {
+            Some(index) => index,
+            None => return false,
+        };
+
+        self.heap[index].priority = priority;
+        self.repair(index);
+        true
+    }
+
+    pub fn remove(&mut self, handle: Handle) -> Option<T> {
+        if handle.queue_id != self.queue_id {
+            return None;
+        }
+
+        let index = self.positions.get(handle.item_id).and_then(|position| *position)?;
+        Some(self.remove_at(index))
+    }
+
+    pub fn clear(&mut self) {
+        self.heap.clear();
+        self.positions.clear();
+    }
+
+    fn greater(&self, a: usize, b: usize) -> bool {
+        let first = &self.heap[a];
+        let second = &self.heap[b];
+
+        if first.priority != second.priority {
+            first.priority > second.priority
+        } else {
+            first.sequence < second.sequence
+        }
+    }
+
+    fn swap(&mut self, a: usize, b: usize) {
+        self.heap.swap(a, b);
+
+        let id_a = self.heap[a].item_id;
+        let id_b = self.heap[b].item_id;
+
+        self.positions[id_a] = Some(a);
+        self.positions[id_b] = Some(b);
+    }
+
+    fn sift_up(&mut self, mut index: usize) {
+        while index > 0 {
+            let parent = (index - 1) / 2;
+
+            if self.greater(index, parent) {
+                self.swap(index, parent);
+                index = parent;
+            } else {
+                break;
+            }
+        }
+    }
+
+    fn sift_down(&mut self, mut index: usize) {
+        let len = self.heap.len();
+
+        loop {
+            let left = 2 * index + 1;
+            if left >= len {
+                break;
+            }
+
+            let right = left + 1;
+            let mut largest = left;
+
+            if right < len && self.greater(right, left) {
+                largest = right;
+            }
+
+            if self.greater(largest, index) {
+                self.swap(index, largest);
+                index = largest;
+            } else {
+                break;
+            }
+        }
+    }
+
+    fn repair(&mut self, index: usize) {
+        if index > 0 {
+            let parent = (index - 1) / 2;
+
+            if self.greater(index, parent) {
+                self.sift_up(index);
+                return;
+            }
+        }
+
+        self.sift_down(index);
+    }
+
+    fn remove_at(&mut self, index: usize) -> T {
+        let removed_id = self.heap[index].item_id;
+        let last_index = self.heap.len() - 1;
+
+        if index == last_index {
+            let entry = self.heap.pop().unwrap();
+            self.positions[removed_id] = None;
+            return entry.item;
+        }
+
+        let last = self.heap.pop().unwrap();
+        let removed = std::mem::replace(&mut self.heap[index], last);
+
+        self.positions[removed_id] = None;
+        self.positions[self.heap[index].item_id] = Some(index);
+
+        self.repair(index);
+
+        removed.item
+    }
