+fn validate_key(key: &str) -> Result<Vec<u8>, String> {
+    if key.is_empty() {
+        return Err("key must not be empty".to_string());
+    }
+
+    let mut shifts = Vec::with_capacity(key.len());
+
+    for c in key.chars() {
+        if !c.is_ascii_alphabetic() {
+            return Err("key must contain only ASCII letters".to_string());
+        }
+
+        let base = if c.is_ascii_uppercase() { b'A' } else { b'a' };
+        shifts.push(c as u8 - base);
+    }
+
+    Ok(shifts)
+}
+
+fn transform(text: &str, key: &str, encrypting: bool) -> Result<String, String> {
+    let shifts = validate_key(key)?;
+    let mut result = String::with_capacity(text.len());
+    let mut key_index = 0usize;
+
+    for ch in text.chars() {
+        if ch.is_ascii_alphabetic() {
+            let shift = shifts[key_index % shifts.len()] as i16;
+            let base = if ch.is_ascii_uppercase() { b'A' } else { b'a' };
+            let value = (ch as u8 - base) as i16;
+
+            let shifted = if encrypting {
+                (value + shift).rem_euclid(26)
+            } else {
+                (value - shift).rem_euclid(26)
+            };
+
+            result.push((base + shifted as u8) as char);
+            key_index += 1;
+        } else {
+            result.push(ch);
+        }
+    }
+
+    Ok(result)
