+use std::collections::BTreeMap;
+
+pub fn palindromic_anagrams(input: &str) -> Vec<String> {
+    let mut counts: BTreeMap<char, usize> = BTreeMap::new();
+
+    for ch in input.chars() {
+        if ch.is_ascii_alphanumeric() {
+            *counts.entry(ch.to_ascii_lowercase()).or_insert(0) += 1;
+        }
+    }
+
+    let mut odd_char = None;
+    for (&ch, &count) in counts.iter() {
+        if count % 2 == 1 {
+            if odd_char.is_some() {
+                return Vec::new();
+            }
+            odd_char = Some(ch);
+        }
+    }
+
+    let chars: Vec<char> = counts.keys().copied().collect();
+    let mut remaining: Vec<usize> = chars
+        .iter()
+        .map(|ch| counts.get(ch).copied().unwrap_or(0) / 2)
+        .collect();
+    let half_len: usize = remaining.iter().sum();
+
+    let mut half = String::new();
+    let mut results = Vec::new();
+
+    build_palindromes(
+        &chars,
+        &mut remaining,
+        half_len,
+        &mut half,
+        odd_char,
+        &mut results,
+    );
+
+    results.sort();
+    results
+}
+
+fn build_palindromes(
+    chars: &[char],
+    remaining: &mut [usize],
+    half_len: usize,
+    half: &mut String,
+    middle: Option<char>,
+    results: &mut Vec<String>,
+) {
+    if half.len() == half_len {
+        let mut palindrome = half.clone();
+
+        if let Some(ch) = middle {
+            palindrome.push(ch);
+        }
+
+        palindrome.extend(half.chars().rev());
+        results.push(palindrome);
+        return;
+    }
