+    for i in 0..chars.len() {
+        if remaining[i] == 0 {
+            continue;
+        }
+
+        remaining[i] -= 1;
+        half.push(chars[i]);
+        build_palindromes(chars, remaining, half_len, half, middle, results);
+        half.pop();
+        remaining[i] += 1;
+    }
