+/// Extended Euclidean algorithm over non-negative inputs.
+/// Returns `(g, x, y)` with `a * x + b * y = g = gcd(a, b)`.
+fn extended_gcd(a: u128, b: u128) -> (u128, i128, i128) {
+    let (g, x, y) = extended_gcd_signed(a as i128, b as i128);
+    (g as u128, x, y)
+}
+
+fn extended_gcd_signed(a: i128, b: i128) -> (i128, i128, i128) {
+    if b == 0 {
+        (a, 1, 0)
+    } else {
+        let (g, x, y) = extended_gcd_signed(b, a % b);
+        (g, y, x - (a / b) * y)
+    }
+}
+
+/// Normalize a signed coefficient into `[0, modulus)`.
+fn normalize(value: i128, modulus: u128) -> u128 {
+    let m = modulus as i128;
+    (((value % m) + m) % m) as u128
+}
