+pub fn solve_linear_congruence(a: u64, b: u64, m: u64) -> Vec<u64> {
+    if m == 0 {
+        return Vec::new();
+    }
+    let m_wide = m as u128;
+    let b_mod = (b as u128) % m_wide;
+
+    let (g, bezout, _) = extended_gcd(a as u128, m_wide);
+    if b_mod % g != 0 {
+        return Vec::new();
+    }
+
+    let reduced_modulus = m_wide / g;
+    let scale = b_mod / g;
+    let inverse = normalize(bezout, reduced_modulus);
+    let first = (inverse * scale) % reduced_modulus;
+
+    let step = reduced_modulus as u64;
+    (0..g as u64).map(|k| first as u64 + k * step).collect()
+}
