+    let mut solution: u128 = 0;
+    let mut combined: u128 = 1;
+
+    for congruence in congruences {
+        let n = congruence.modulus as u128;
+        if n == 0 {
+            return None;
+        }
+        let r = (congruence.remainder as u128) % n;
+
+        // Solve combined * t ≡ (r - solution) (mod n).
+        let (g, bezout, _) = extended_gcd(combined, n);
+        let difference = (r + n - (solution % n)) % n;
+        if difference % g != 0 {
+            return None;
+        }
