+        let reduced = n / g;
+        let inverse = normalize(bezout, reduced);
+        let scale = difference / g;
+        let t = (inverse * scale) % reduced;
+
+        let new_combined = combined * reduced;
+        solution = (solution + combined * t) % new_combined;
+        combined = new_combined;
+    }
