+pub fn flood_fill(grid: &[Vec<char>], row: usize, col: usize, new_color: char) -> Vec<Vec<char>> {
+    let mut result: Vec<Vec<char>> = grid.to_vec();
+
+    if row >= result.len() || col >= result[row].len() {
+        return result;
+    }
+
+    let target = result[row][col];
+    if target == new_color {
+        return result;
+    }
+
+    let mut stack: Vec<(usize, usize)> = vec![(row, col)];
+
+    while let Some((r, c)) = stack.pop() {
+        if r >= result.len() || c >= result[r].len() {
+            continue;
+        }
+        if result[r][c] != target {
+            continue;
+        }
+
+        result[r][c] = new_color;
+
+        if r > 0 {
+            stack.push((r - 1, c));
+        }
+        stack.push((r + 1, c));
+        if c > 0 {
+            stack.push((r, c - 1));
+        }
+        stack.push((r, c + 1));
+    }
+
+    result
