+    ZeroAmount,
+    UnknownAccount(String),
+    InsufficientFunds {
+        account: String,
+        available: u64,
+        requested: u64,
+    },
+    Overflow {
+        account: String,
+        current: u64,
+        amount: u64,
+    },
