+        match operation {
+            Operation::Deposit { account, amount } => {
+                if amount == 0 {
+                    return Err(TotalsError::ZeroAmount);
+                }
+
+                let current = *self.balances.get(&account).unwrap_or(&0);
+                let new_balance =
+                    current
+                        .checked_add(amount)
+                        .ok_or_else(|| TotalsError::Overflow {
+                            account: account.clone(),
+                            current,
+                            amount,
+                        })?;
+
+                self.balances.insert(account, new_balance);
+            }
+            Operation::Withdraw { account, amount } => {
+                if amount == 0 {
+                    return Err(TotalsError::ZeroAmount);
+                }
+
+                let current = *self
+                    .balances
+                    .get(&account)
+                    .ok_or_else(|| TotalsError::UnknownAccount(account.clone()))?;
+
+                if amount > current {
+                    return Err(TotalsError::InsufficientFunds {
+                        account,
+                        available: current,
+                        requested: amount,
+                    });
+                }
+
+                self.balances.insert(account, current - amount);
+            }
+            Operation::Transfer { from, to, amount } => {
+                if amount == 0 {
+                    return Err(TotalsError::ZeroAmount);
+                }
+
+                if from == to {
+                    return Err(TotalsError::SameAccountTransfer);
+                }
+
+                let from_balance = *self
+                    .balances
+                    .get(&from)
+                    .ok_or_else(|| TotalsError::UnknownAccount(from.clone()))?;
+
+                if amount > from_balance {
+                    return Err(TotalsError::InsufficientFunds {
+                        account: from,
+                        available: from_balance,
+                        requested: amount,
+                    });
+                }
+
+                let to_balance = *self.balances.get(&to).unwrap_or(&0);
+                let new_to_balance =
