+                        .checked_add(amount)
+                        .ok_or_else(|| TotalsError::Overflow {
+                            account: to.clone(),
+                            current: to_balance,
+                            amount,
+                        })?;
+
+                self.balances.insert(from, from_balance - amount);
+                self.balances.insert(to, new_to_balance);
+            }
+        }
