+fn normalized_chars(word: &str) -> Vec<char> {
+    word.chars()
+        .filter(|c| c.is_alphanumeric())
+        .flat_map(|c| c.to_lowercase())
+        .collect()
+}
+
+fn can_form_palindrome(sorted_chars: &[char]) -> bool {
+    let mut odd_count = 0;
+    let mut i = 0;
+
+    while i < sorted_chars.len() {
+        let mut j = i + 1;
+        while j < sorted_chars.len() && sorted_chars[j] == sorted_chars[i] {
+            j += 1;
+        }
+
+        if (j - i) % 2 == 1 {
+            odd_count += 1;
+            if odd_count > 1 {
+                return false;
+            }
+        }
+
+        i = j;
+    }
+
+    true
+}
