+use std::collections::VecDeque;
+
+pub fn max_sliding_window(values: &[i32], window_size: usize) -> Vec<i32> {
+    if window_size == 0 || window_size > values.len() {
+        return Vec::new();
+    }
+
+    let mut result = Vec::with_capacity(values.len() - window_size + 1);
+    let mut deque: VecDeque<usize> = VecDeque::new();
+
+    for (index, &value) in values.iter().enumerate() {
+        while let Some(&back) = deque.back() {
+            if values[back] <= value {
+                deque.pop_back();
+            } else {
+                break;
+            }
+        }
+
+        deque.push_back(index);
+
+        if let Some(&front) = deque.front() {
+            if front + window_size <= index {
+                deque.pop_front();
+            }
+        }
+
+        if index + 1 >= window_size {
+            if let Some(&front) = deque.front() {
+                result.push(values[front]);
+            }
+        }
+    }
+
+    result
+}
