+        let mut order: Vec<String> = Vec::new();
+        while let Some(node) = frontier.iter().next().cloned() {
+            frontier.remove(&node);
+            order.push(node.clone());
+
+            let mut outgoing: Vec<String> = self
+                .adjacency
+                .get(&node)
+                .map(|s| s.iter().cloned().collect())
+                .unwrap_or_default();
+            outgoing.sort();
+            for next in outgoing {
