+#[derive(Debug, PartialEq, Eq)]
+pub enum CipherError {
+    EmptyColumnKey,
+    InvalidCiphertext,
+}
+
+const ALPHABET: &str = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
+const SYMBOLS: [char; 6] = ['A', 'D', 'F', 'G', 'V', 'X'];
+
+pub fn encode(plaintext: &str, square_key: &str, column_key: &str) -> Result<String, CipherError> {
+    let column_key = normalize_letters(column_key);
+    if column_key.is_empty() {
+        return Err(CipherError::EmptyColumnKey);
+    }
+
+    let square = build_square(square_key);
+    let normalized = normalize_alnum(plaintext);
+    if normalized.is_empty() {
+        return Ok(String::new());
+    }
+
+    let mut fractionated = String::new();
+    for ch in normalized.chars() {
+        let (row, col) = position(&square, ch).expect("normalized plaintext is always in the square");
+        fractionated.push(SYMBOLS[row]);
+        fractionated.push(SYMBOLS[col]);
+    }
+
+    let key_chars: Vec<char> = column_key.chars().collect();
+    Ok(transpose(&fractionated, &key_chars))
+}
+
+pub fn decode(ciphertext: &str, square_key: &str, column_key: &str) -> Result<String, CipherError> {
+    let column_key = normalize_letters(column_key);
+    if column_key.is_empty() {
+        return Err(CipherError::EmptyColumnKey);
+    }
+
+    let square = build_square(square_key);
+    let normalized: String = ciphertext
+        .chars()
+        .map(|c| c.to_ascii_uppercase())
+        .filter(|c| SYMBOLS.contains(c))
+        .collect();
+
+    if normalized.is_empty() {
+        return Ok(String::new());
+    }
+
+    if normalized.len() % 2 != 0 {
+        return Err(CipherError::InvalidCiphertext);
+    }
+
+    let key_chars: Vec<char> = column_key.chars().collect();
+    let fractionated = untranspose(&normalized, &key_chars);
+    let chars: Vec<char> = fractionated.chars().collect();
+
+    let mut out = String::new();
+    for pair in chars.chunks(2) {
+        let row = symbol_index(pair[0]);
+        let col = symbol_index(pair[1]);
+        out.push(square[row * 6 + col]);
+    }
+
+    Ok(out)
+}
+
+fn normalize_alnum(s: &str) -> String {
+    s.chars()
+        .map(|c| c.to_ascii_uppercase())
+        .filter(|c| c.is_ascii_alphanumeric())
+        .collect()
+}
+
+fn normalize_letters(s: &str) -> String {
+    s.chars()
+        .map(|c| c.to_ascii_uppercase())
+        .filter(|c| c.is_ascii_alphabetic())
+        .collect()
+}
+
+fn build_square(key: &str) -> Vec<char> {
+    let mut square = Vec::with_capacity(36);
+
+    for ch in normalize_alnum(key).chars() {
+        if !square.contains(&ch) {
+            square.push(ch);
+        }
+    }
+
+    for ch in ALPHABET.chars() {
+        if !square.contains(&ch) {
+            square.push(ch);
+        }
+    }
+
+    square
+}
+
+fn position(square: &[char], ch: char) -> Option<(usize, usize)> {
+    square
+        .iter()
+        .position(|&c| c == ch)
+        .map(|idx| (idx / 6, idx % 6))
+}
+
+fn symbol_index(ch: char) -> usize {
+    match ch {
+        'A' => 0,
+        'D' => 1,
+        'F' => 2,
+        'G' => 3,
+        'V' => 4,
+        'X' => 5,
+        _ => unreachable!("filtered to ADFGVX symbols"),
+    }
+}
+
+fn column_order(column_key: &[char]) -> Vec<usize> {
+    let mut order: Vec<usize> = (0..column_key.len()).collect();
+    order.sort_by_key(|&i| (column_key[i], i));
+    order
+}
+
+fn transpose(text: &str, column_key: &[char]) -> String {
+    let k = column_key.len();
+    let chars: Vec<char> = text.chars().collect();
+
+    if chars.is_empty() {
+        return String::new();
+    }
+
+    let mut columns: Vec<Vec<char>> = vec![Vec::new(); k];
+    for (i, &ch) in chars.iter().enumerate() {
+        columns[i % k].push(ch);
+    }
+
+    let mut out = String::with_capacity(chars.len());
+    for col in column_order(column_key) {
+        for &ch in &columns[col] {
+            out.push(ch);
+        }
+    }
+    out
+}
+
+fn untranspose(text: &str, column_key: &[char]) -> String {
+    let k = column_key.len();
+    let chars: Vec<char> = text.chars().collect();
+    let n = chars.len();
+
+    let base = n / k;
+    let rem = n % k;
+    let heights: Vec<usize> = (0..k)
+        .map(|col| base + if col < rem { 1 } else { 0 })
+        .collect();
+
+    let mut columns: Vec<Vec<char>> = vec![Vec::new(); k];
+    let mut pos = 0;
+
+    for col in column_order(column_key) {
+        let height = heights[col];
+        columns[col].extend_from_slice(&chars[pos..pos + height]);
+        pos += height;
+    }
+
+    let max_height = heights.iter().copied().max().unwrap_or(0);
+    let mut out = String::with_capacity(n);
+
+    for row in 0..max_height {
+        for col in 0..k {
+            if row < columns[col].len() {
+                out.push(columns[col][row]);
+            }
+        }
+    }
+
+    out
