+
+pub fn merge_logs(logs: &[Vec<Record>]) -> Vec<Record> {
+    let mut best: BTreeMap<String, Record> = BTreeMap::new();
+
+    for log in logs {
+        for record in log {
+            match best.get(&record.key) {
+                None => {
+                    best.insert(record.key.clone(), record.clone());
+                }
+                Some(existing) => {
+                    if wins(record, existing) {
+                        best.insert(record.key.clone(), record.clone());
+                    }
+                }
+            }
+        }
+    }
+
+    best.into_iter()
+        .filter_map(|(_, record)| {
+            if record.value.is_some() {
+                Some(record)
+            } else {
+                None
+            }
+        })
+        .collect()
+}
+
+fn wins(candidate: &Record, current: &Record) -> bool {
+    if candidate.revision != current.revision {
+        return candidate.revision > current.revision;
+    }
+
+    match (&candidate.value, &current.value) {
+        (Some(candidate_value), Some(current_value)) => candidate_value > current_value,
+        (Some(_), None) => true,
+        (None, Some(_)) => false,
+        (None, None) => false,
+    }
