+pub fn merge_circular_intervals(domain_size: u32, intervals: &[(u32, u32)]) -> Vec<(u32, u32)> {
+    if domain_size == 0 {
+        return Vec::new();
+    }
+
+    let n = domain_size as u64;
+    let mut segments = Vec::new();
+
+    for &(start, end) in intervals {
+        let s = start as u64;
+        let e = end as u64;
+
+        if s >= n || e >= n {
+            continue;
+        }
+
+        if s <= e {
+            segments.push((s, e + 1));
+        } else {
+            segments.push((s, n));
+            segments.push((0, e + 1));
+        }
+    }
+
+    if segments.is_empty() {
+        return Vec::new();
+    }
+
+    segments.sort_unstable();
+
+    let mut merged: Vec<(u64, u64)> = Vec::new();
+    for (s, e) in segments {
+        if let Some(last) = merged.last_mut() {
+            if s <= last.1 {
+                if e > last.1 {
+                    last.1 = e;
+                }
+                continue;
+            }
+        }
+        merged.push((s, e));
+    }
+
+    if merged.len() == 1 && merged[0].0 == 0 && merged[0].1 == n {
+        return vec![(0, domain_size - 1)];
+    }
+
+    let mut result = Vec::new();
+    let mut start_index = 0;
+    let mut end_index = merged.len();
+
+    if merged.len() > 1 && merged[0].0 == 0 && merged.last().unwrap().1 == n {
+        let first = merged[0];
+        let last = *merged.last().unwrap();
+        result.push((last.0, first.1 - 1));
+        start_index = 1;
+        end_index = merged.len() - 1;
+    }
+
+    for &(s, e) in &merged[start_index..end_index] {
+        result.push((s, e - 1));
+    }
+
+    result.sort_unstable_by_key(|&(s, _)| s);
+
+    result
+        .into_iter()
+        .map(|(s, e)| (s as u32, e as u32))
+        .collect()
+}
