+use std::collections::VecDeque;
+
+pub fn find_path(grid: &[&str]) -> Option<Vec<(usize, usize)>> {
+    if grid.is_empty() {
+        return None;
+    }
+
+    let rows = grid.len();
+    let cols = grid[0].len();
+    if cols == 0 {
+        return None;
+    }
+
+    let mut start: Option<(usize, usize)> = None;
+    let mut end: Option<(usize, usize)> = None;
+
+    for (r, row) in grid.iter().enumerate() {
+        if row.len() != cols {
+            return None;
+        }
+
+        for (c, cell) in row.bytes().enumerate() {
+            match cell {
+                b'S' => {
+                    if start.is_some() {
+                        return None;
+                    }
+                    start = Some((r, c));
+                }
+                b'E' => {
+                    if end.is_some() {
+                        return None;
+                    }
+                    end = Some((r, c));
+                }
+                b'.' | b'#' => {}
+                _ => return None,
+            }
+        }
+    }
+
+    let start = start?;
+    let end = end?;
+
+    let mut visited = vec![vec![false; cols]; rows];
+    let mut previous = vec![vec![None; cols]; rows];
+    let mut queue = VecDeque::new();
+
+    visited[start.0][start.1] = true;
+    queue.push_back(start);
+
+    let directions = [
+        (-1isize, 0isize),
+        (0, 1),
+        (1, 0),
+        (0, -1),
+    ];
+
+    while let Some((r, c)) = queue.pop_front() {
+        if (r, c) == end {
+            break;
+        }
+
+        for &(dr, dc) in &directions {
+            let nr = r as isize + dr;
+            let nc = c as isize + dc;
+
+            if nr < 0 || nc < 0 || nr >= rows as isize || nc >= cols as isize {
+                continue;
+            }
+
+            let nr = nr as usize;
+            let nc = nc as usize;
+
+            if visited[nr][nc] {
+                continue;
+            }
+
+            if grid[nr].as_bytes()[nc] == b'#' {
+                continue;
+            }
+
+            visited[nr][nc] = true;
+            previous[nr][nc] = Some((r, c));
+            queue.push_back((nr, nc));
+        }
+    }
+
+    if !visited[end.0][end.1] {
+        return None;
+    }
+
+    let mut path = Vec::new();
+    let mut current = end;
+
+    loop {
+        path.push(current);
+
+        if current == start {
+            break;
+        }
+
+        current = previous[current.0][current.1]?;
+    }
+
+    path.reverse();
+    Some(path)
+}
