+#[derive(Debug, PartialEq, Eq)]
+pub enum ConversionError {
+    InvalidBase,
+    EmptyInput,
+    InvalidDigit(char),
+}
+
+pub fn convert(input: &str, from_base: u32, to_base: u32) -> Result<String, ConversionError> {
+    if !(2..=36).contains(&from_base) || !(2..=36).contains(&to_base) {
+        return Err(ConversionError::InvalidBase);
+    }
+
+    let (negative, digits_part) = if let Some(rest) = input.strip_prefix('-') {
+        (true, rest)
+    } else if let Some(rest) = input.strip_prefix('+') {
+        (false, rest)
+    } else {
+        (false, input)
+    };
+
+    if digits_part.is_empty() {
+        return Err(ConversionError::EmptyInput);
+    }
+
+    let mut digits = Vec::with_capacity(digits_part.len());
+    for ch in digits_part.chars() {
+        let value = match ch.to_digit(36) {
+            Some(value) if value < from_base => value,
+            _ => return Err(ConversionError::InvalidDigit(ch)),
+        };
+        digits.push(value);
+    }
+
+    let start = match digits.iter().position(|&digit| digit != 0) {
+        Some(index) => index,
+        None => return Ok("0".to_string()),
+    };
+
+    let mut current = digits[start..].to_vec();
+    let mut remainders = Vec::new();
+
+    while !current.is_empty() {
+        let mut quotient = Vec::with_capacity(current.len());
+        let mut remainder: u64 = 0;
+
+        for &digit in &current {
+            let value = remainder * from_base as u64 + digit as u64;
+            let quotient_digit = value / to_base as u64;
+            remainder = value % to_base as u64;
+
+            if !quotient.is_empty() || quotient_digit != 0 {
+                quotient.push(quotient_digit as u32);
+            }
+        }
+
+        remainders.push(remainder as u32);
+        current = quotient;
+    }
+
+    let mut result = String::new();
+    if negative {
+        result.push('-');
+    }
+
+    for &digit in remainders.iter().rev() {
+        let ch = std::char::from_digit(digit, 36)
+            .expect("remainder is always a valid base-36 digit")
+            .to_ascii_uppercase();
+        result.push(ch);
+    }
+
+    Ok(result)
