+            .prerequisites
+            .iter()
+            .map(|(course, prereqs)| (course.clone(), prereqs.len()))
+            .collect();
+
+        let mut ready: BTreeSet<String> = remaining
+            .iter()
+            .filter(|(_, count)| **count == 0)
+            .map(|(course, _)| course.clone())
+            .collect();
+
+        let mut dependents: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
+        for (course, prereqs) in &self.prerequisites {
+            for prerequisite in prereqs {
+                dependents
+                    .entry(prerequisite.clone())
+                    .or_default()
+                    .insert(course.clone());
+            }
+        }
+
+        let mut order = Vec::new();
+
+        while let Some(course) = ready.iter().next().cloned() {
+            ready.remove(&course);
+            order.push(course.clone());
+
+            if let Some(dependent_set) = dependents.get(&course) {
+                for dependent in dependent_set {
+                    if let Some(count) = remaining.get_mut(dependent) {
+                        *count -= 1;
+                        if *count == 0 {
+                            ready.insert(dependent.clone());
+                        }
+                    }
+                }
+            }
+        }
+
+        if order.len() == self.prerequisites.len() {
+            Ok(order)
+        } else {
+            let stuck = remaining
+                .into_iter()
+                .filter(|(_, count)| *count > 0)
+                .map(|(course, _)| course)
+                .collect();
+            Err(stuck)
+        }
+    }
