+//! Proleptic Gregorian calendar arithmetic.
+
+#[derive(Debug, Clone, Copy, PartialEq, Eq)]
+pub enum Weekday {
+    Monday,
+    Tuesday,
+    Wednesday,
+    Thursday,
+    Friday,
+    Saturday,
+    Sunday,
+}
+
+impl Weekday {
+    /// Monday is 0, Sunday is 6.
+    fn from_index(index: u32) -> Weekday {
+        match index % 7 {
+            0 => Weekday::Monday,
+            1 => Weekday::Tuesday,
+            2 => Weekday::Wednesday,
+            3 => Weekday::Thursday,
+            4 => Weekday::Friday,
+            5 => Weekday::Saturday,
+            _ => Weekday::Sunday,
+        }
+    }
+
+    /// ISO 8601 numbering: Monday is 1, Sunday is 7.
+    fn iso_number(self) -> u32 {
+        match self {
+            Weekday::Monday => 1,
+            Weekday::Tuesday => 2,
+            Weekday::Wednesday => 3,
+            Weekday::Thursday => 4,
+            Weekday::Friday => 5,
+            Weekday::Saturday => 6,
+            Weekday::Sunday => 7,
+        }
+    }
+}
+
+/// Days elapsed before the first day of each month in a common year.
+const CUMULATIVE_DAYS: [u32; 12] = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
+
+pub fn is_leap_year(year: u32) -> bool {
+    year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)
+}
+
+pub fn days_in_month(year: u32, month: u32) -> u32 {
+    assert!((1..=12).contains(&month), "month must be in 1..=12");
+    match month {
+        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
+        4 | 6 | 9 | 11 => 30,
+        _ => {
+            if is_leap_year(year) {
+                29
+            } else {
+                28
+            }
+        }
+    }
+}
+
+fn ordinal_day(year: u32, month: u32, day: u32) -> u32 {
+    let leap_offset = if month > 2 && is_leap_year(year) { 1 } else { 0 };
+    CUMULATIVE_DAYS[(month - 1) as usize] + day + leap_offset
+}
+
+fn days_before_year(year: u32) -> i64 {
+    let y = i64::from(year) - 1;
+    365 * y + y / 4 - y / 100 + y / 400
+}
+
+fn assert_valid_date(year: u32, month: u32, day: u32) {
+    assert!(year >= 1, "year must be at least 1");
+    assert!((1..=12).contains(&month), "month must be in 1..=12");
+    assert!(
+        day >= 1 && day <= days_in_month(year, month),
+        "day out of range for this month"
+    );
+}
+
+pub fn day_of_week(year: u32, month: u32, day: u32) -> Weekday {
+    assert_valid_date(year, month, day);
+    // Day number 1 is 0001-01-01, which is a Monday.
+    let days = days_before_year(year) + i64::from(ordinal_day(year, month, day));
+    Weekday::from_index((days - 1).rem_euclid(7) as u32)
+}
+
+pub fn nth_weekday(year: u32, month: u32, weekday: Weekday, n: i32) -> Option<u32> {
+    assert!(year >= 1, "year must be at least 1");
+    assert!((1..=12).contains(&month), "month must be in 1..=12");
+    if n == 0 {
+        return None;
+    }
+
+    let length = days_in_month(year, month);
+    let target = weekday.iso_number();
+    let count = u64::from(n.unsigned_abs() - 1);
+
+    if n > 0 {
+        let first = day_of_week(year, month, 1).iso_number();
+        let offset = (target + 7 - first) % 7;
+        let day = 1 + u64::from(offset) + 7 * count;
+        if day <= u64::from(length) {
+            Some(day as u32)
+        } else {
+            None
+        }
+    } else {
+        let last = day_of_week(year, month, length).iso_number();
+        let offset = (last + 7 - target) % 7;
+        let last_day = i64::from(length - offset);
+        let day = last_day - 7 * count as i64;
+        if day >= 1 {
+            Some(day as u32)
+        } else {
+            None
+        }
+    }
+}
+
+pub fn easter_sunday(year: u32) -> (u32, u32) {
+    assert!(year >= 1, "year must be at least 1");
+    let a = year % 19;
+    let b = year / 100;
+    let c = year % 100;
+    let d = b / 4;
+    let e = b % 4;
+    let f = (b + 8) / 25;
+    let g = (b - f + 1) / 3;
+    let h = (19 * a + b - d - g + 15) % 30;
+    let i = c / 4;
+    let k = c % 4;
+    let l = (32 + 2 * e + 2 * i - h - k) % 7;
+    let m = (a + 11 * h + 22 * l) / 451;
+    let shifted = h + l - 7 * m + 114;
+    (shifted / 31, (shifted % 31) + 1)
+}
+
+fn weeks_in_iso_year(year: u32) -> u32 {
+    fn p(year: u32) -> u32 {
+        (year + year / 4 - year / 100 + year / 400) % 7
+    }
+    if p(year) == 4 || p(year.saturating_sub(1)) == 3 {
+        53
+    } else {
+        52
+    }
+}
+
+pub fn iso_week(year: u32, month: u32, day: u32) -> (u32, u32) {
+    assert_valid_date(year, month, day);
+    let ordinal = i64::from(ordinal_day(year, month, day));
+    let weekday = i64::from(day_of_week(year, month, day).iso_number());
+    let week = (ordinal - weekday + 10) / 7;
+
+    if week < 1 {
+        if year == 1 {
+            return (1, 1);
+        }
+        let previous = year - 1;
+        (previous, weeks_in_iso_year(previous))
+    } else if week > i64::from(weeks_in_iso_year(year)) {
+        (year + 1, 1)
+    } else {
+        (year, week as u32)
+    }
+}
