+const NUMERALS: [(u32, &str); 13] = [
+    (1000, "M"),
+    (900, "CM"),
+    (500, "D"),
+    (400, "CD"),
+    (100, "C"),
+    (90, "XC"),
+    (50, "L"),
+    (40, "XL"),
+    (10, "X"),
+    (9, "IX"),
+    (5, "V"),
+    (4, "IV"),
+    (1, "I"),
+];
+
+pub fn to_roman(number: u32) -> String {
+    assert!(
+        (1..=3999).contains(&number),
+        "Roman numerals only cover numbers from 1 to 3999; got {number}"
+    );
+
+    let mut remaining = number;
+    let mut roman = String::new();
+
+    for (value, symbol) in NUMERALS {
+        while remaining >= value {
+            roman.push_str(symbol);
+            remaining -= value;
+        }
+    }
+
+    roman
+}
+
+pub fn from_roman(roman: &str) -> Result<u32, String> {
+    if roman.is_empty() {
+        return Err("an empty string is not a Roman numeral".to_string());
+    }
+
+    let mut total: i64 = 0;
+    let mut previous = 0i64;
+
+    for character in roman.chars() {
+        let value = match character {
+            'I' => 1,
+            'V' => 5,
+            'X' => 10,
+            'L' => 50,
+            'C' => 100,
+            'D' => 500,
+            'M' => 1000,
+            other => return Err(format!("'{other}' is not a Roman numeral character")),
+        };
+
+        total += value;
+        if value > previous {
+            total -= 2 * previous;
+        }
+        previous = value;
+    }
+
+    if !(1..=3999).contains(&total) {
+        return Err(format!("{total} is outside the range 1 to 3999"));
+    }
+
+    let number = total as u32;
+
+    if to_roman(number) != roman {
+        return Err(format!("'{roman}' is not in standard Roman numeral form"));
+    }
+
+    Ok(number)
