+                Ok(JsonValue::Null)
+            }
+            Some('t') => {
+                self.parse_literal("true")?;
+                Ok(JsonValue::Bool(true))
+            }
+            Some('f') => {
+                self.parse_literal("false")?;
+                Ok(JsonValue::Bool(false))
+            }
+            Some('"') => Ok(JsonValue::String(self.parse_string()?)),
+            Some('[') => self.parse_array(),
+            Some('{') => self.parse_object(),
