+        let right_segment = right_segment.unwrap_or("0").trim_start_matches('0');
+        let right_segment = if right_segment.is_empty() { "0" } else { right_segment };
+
+        let ordering = left_segment
+            .len()
+            .cmp(&right_segment.len())
+            .then_with(|| left_segment.cmp(right_segment));
+
+        if ordering != Ordering::Equal {
+            return ordering;
+        }
+    }
