+use std::cmp::Ordering;
+
+#[derive(Debug, Clone, Copy, PartialEq, Eq)]
+pub enum RoundingMode {
+    Truncate,
+    AwayFromZero,
+    Ceiling,
+    Floor,
+    HalfUp,
+    HalfDown,
+    HalfEven,
+}
+
+pub fn round_fraction(numerator: i64, denominator: i64, mode: RoundingMode) -> i64 {
+    assert!(denominator != 0, "denominator must not be zero");
+
+    let mut n = numerator as i128;
+    let mut d = denominator as i128;
+
+    if d < 0 {
+        n = -n;
+        d = -d;
+    }
+
+    let q = n / d;
+    let r = n % d;
+
+    let rounded = match mode {
+        RoundingMode::Truncate => q,
+        RoundingMode::Ceiling => {
+            if r > 0 {
+                q + 1
+            } else {
+                q
+            }
+        }
+        RoundingMode::Floor => {
+            if r < 0 {
+                q - 1
+            } else {
+                q
+            }
+        }
+        RoundingMode::AwayFromZero => {
+            if r > 0 {
+                q + 1
+            } else if r < 0 {
+                q - 1
+            } else {
+                q
+            }
+        }
+        RoundingMode::HalfUp | RoundingMode::HalfDown | RoundingMode::HalfEven => {
+            if r == 0 {
+                q
+            } else {
+                let twice_abs_remainder = r.abs() * 2;
+
+                match twice_abs_remainder.cmp(&d) {
+                    Ordering::Less => q,
+                    Ordering::Greater => {
+                        if n > 0 {
+                            q + 1
+                        } else {
+                            q - 1
+                        }
+                    }
+                    Ordering::Equal => match mode {
+                        RoundingMode::HalfUp => {
+                            if n > 0 {
+                                q + 1
+                            } else {
+                                q - 1
+                            }
+                        }
+                        RoundingMode::HalfDown => q,
+                        RoundingMode::HalfEven => {
+                            if q % 2 == 0 {
+                                q
+                            } else if n > 0 {
+                                q + 1
+                            } else {
+                                q - 1
+                            }
+                        }
+                        _ => unreachable!(),
+                    },
+                }
+            }
+        }
+    };
+
+    rounded as i64
