+/// Identifier of a bank account.
+///
+/// Ids are issued sequentially starting at 1 and are never reused.
+#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
+pub struct AccountId(pub u64);
+
+/// Errors a banking operation can report.
+#[derive(Debug, Clone, Copy, PartialEq, Eq)]
+pub enum BankError {
+    /// No open account has the given id.
+    AccountNotFound,
+    /// An amount was zero or negative, or an overdraft limit was negative.
+    InvalidAmount,
+    /// The account would drop below the negative of its overdraft limit.
+    InsufficientFunds,
+    /// A transfer used the same account as source and destination.
+    SameAccount,
+    /// The account still owes money and cannot be closed.
+    OutstandingDebt,
+}
+
+#[derive(Debug, Clone, Copy)]
+struct Account {
+    balance: i64,
+    overdraft_limit: i64,
+}
+
+#[derive(Debug, Default)]
+pub struct Bank {
+    accounts: HashMap<AccountId, Account>,
+    next_id: u64,
+}
+
+impl Bank {
+    pub fn new() -> Self {
+        Self::default()
+    }
+
+    pub fn open_account(&mut self) -> AccountId {
+        self.next_id += 1;
+        let id = AccountId(self.next_id);
+        self.accounts.insert(
+            id,
+            Account {
+                balance: 0,
+                overdraft_limit: 0,
+            },
+        );
+        id
+    }
+
+    pub fn account_count(&self) -> usize {
+        self.accounts.len()
+    }
+
+    pub fn balance(&self, id: AccountId) -> Result<i64, BankError> {
+        Ok(self.get(id)?.balance)
+    }
+
+    pub fn deposit(&mut self, id: AccountId, cents: i64) -> Result<i64, BankError> {
+        if cents <= 0 {
+            return Err(BankError::InvalidAmount);
+        }
+        let account = self.get_mut(id)?;
+        account.balance += cents;
+        Ok(account.balance)
+    }
+
+    pub fn withdraw(&mut self, id: AccountId, cents: i64) -> Result<i64, BankError> {
+        if cents <= 0 {
+            return Err(BankError::InvalidAmount);
+        }
+        let account = self.get_mut(id)?;
+        if account.balance - cents < -account.overdraft_limit {
+            return Err(BankError::InsufficientFunds);
+        }
+        account.balance -= cents;
+        Ok(account.balance)
+    }
+
+    pub fn set_overdraft_limit(&mut self, id: AccountId, cents: i64) -> Result<(), BankError> {
+        if cents < 0 {
+            return Err(BankError::InvalidAmount);
+        }
+        let account = self.get_mut(id)?;
+        account.overdraft_limit = cents;
+        Ok(())
+    }
+
+    pub fn transfer(
+        &mut self,
+        from: AccountId,
+        to: AccountId,
+        cents: i64,
+    ) -> Result<(), BankError> {
+        if cents <= 0 {
+            return Err(BankError::InvalidAmount);
+        }
+        if from == to {
+            return Err(BankError::SameAccount);
+        }
+        if !self.accounts.contains_key(&from) {
+            return Err(BankError::AccountNotFound);
+        }
+        if !self.accounts.contains_key(&to) {
+            return Err(BankError::AccountNotFound);
+        }
+
+        // Validate everything before touching either balance so that a
+        // failed transfer never leaves a half-applied state.
+        let source = self.accounts.get(&from).expect("checked above");
+        if source.balance - cents < -source.overdraft_limit {
+            return Err(BankError::InsufficientFunds);
+        }
+
+        self.accounts
+            .get_mut(&from)
+            .expect("checked above")
+            .balance -= cents;
+        self.accounts
+            .get_mut(&to)
+            .expect("checked above")
+            .balance += cents;
+        Ok(())
+    }
