+        let mut credited = 0;
+        for account in self.accounts.values_mut() {
+            if account.balance <= 0 {
+                continue;
+            }
+            let interest = account.balance * rate / 10_000;
+            if interest > 0 {
+                account.balance += interest;
+                credited += interest;
+            }
+        }
+        credited
+    }
+
+    pub fn close_account(&mut self, id: AccountId) -> Result<i64, BankError> {
+        let balance = self.get(id)?.balance;
+        if balance < 0 {
+            return Err(BankError::OutstandingDebt);
+        }
+        self.accounts.remove(&id);
+        Ok(balance)
+    }
