+    fn get(&self, id: AccountId) -> Result<&Account, BankError> {
+        self.accounts.get(&id).ok_or(BankError::AccountNotFound)
+    }
+
+    fn get_mut(&mut self, id: AccountId) -> Result<&mut Account, BankError> {
+        self.accounts.get_mut(&id).ok_or(BankError::AccountNotFound)
+    }
