+            return None;
+        }
+        if start == end {
+            return Some(vec![start]);
+        }
+        let mut queue = VecDeque::new();
+        let mut visited = HashSet::new();
+        let mut predecessor: HashMap<u32, u32> = HashMap::new();
+        queue.push_back(start);
