+                path.reverse();
+                return Some(path);
+            }
+            if let Some(neighbors) = self.adj.get(&current) {
+                for &neighbor in neighbors {
+                    if !visited.contains(&neighbor) {
+                        visited.insert(neighbor);
+                        predecessor.insert(neighbor, current);
+                        queue.push_back(neighbor);
+                    }
