+            '0'..='9' => ch as u32 - '0' as u32,
+            'a'..='z' => ch as u32 - 'a' as u32 + 10,
+            'A'..='Z' => ch as u32 - 'A' as u32 + 10,
+            _ => return Err(ConversionError::InvalidDigit(ch)),
+        };
