+pub fn shortest_path(grid: &[&str]) -> Option<usize> {
+    if grid.is_empty() {
+        return None;
+    }
+
+    let mut start = None;
+    let mut end = None;
+
+    for (r, row) in grid.iter().enumerate() {
+        for (c, ch) in row.bytes().enumerate() {
+            match ch {
+                b'S' => start = Some((r, c)),
+                b'E' => end = Some((r, c)),
+                _ => {}
+            }
+        }
+    }
+
+    let (sr, sc) = start?;
+    let (er, ec) = end?;
+
