+    let mut visited: Vec<Vec<bool>> = grid.iter().map(|row| vec![false; row.len()]).collect();
+    let mut queue = VecDeque::new();
+
+    queue.push_back((sr, sc, 0));
+    visited[sr][sc] = true;
+
+    while let Some((r, c, dist)) = queue.pop_front() {
+        for (dr, dc) in [(0isize, 1isize), (1, 0), (0, -1), (-1, 0)] {
+            let nr = r as isize + dr;
+            let nc = c as isize + dc;
+
+            if nr < 0 || nc < 0 {
+                continue;
+            }
+
+            let nr = nr as usize;
+            let nc = nc as usize;
+
+            if nr >= grid.len() || nc >= grid[nr].len() {
+                continue;
+            }
+
+            if visited[nr][nc] {
