+pub fn kaprekar_steps(n: u32) -> Option<u32> {
+    if n > 9999 {
+        return None;
+    }
+    let mut current = n;
+    let mut steps = 0u32;
+    loop {
+        if current == 6174 {
+            return Some(steps);
+        }
+        let (desc, asc) = sorted_digits(current);
+        let next = desc - asc;
+        if next == 0 {
+            return None;
+        }
+        current = next;
+        steps += 1;
+    }
+}
+
+fn sorted_digits(n: u32) -> (u32, u32) {
+    let mut digits = [0u32; 4];
+    let mut x = n;
+    for i in 0..4 {
+        digits[i] = x % 10;
+        x /= 10;
+    }
+    let slice: &mut [u32] = &mut digits;
+    slice.sort();
+    let asc = slice.iter().fold(0u32, |acc, &d| acc * 10 + d);
+    let desc = slice.iter().rev().fold(0u32, |acc, &d| acc * 10 + d);
+    (desc, asc)
+}
