+fn normalize(intervals: &[Interval]) -> Vec<Interval> {
+    let mut ranges = intervals.to_vec();
+    for &(start, end) in &ranges {
+        assert!(start <= end, "interval start must not exceed end");
+    }
+    ranges.sort_unstable();
