+            let adjacent_or_overlapping = (start as i64) <= (last.1 as i64) + 1;
+            if adjacent_or_overlapping {
+                if end > last.1 {
+                    last.1 = end;
+                }
+                continue;
+            }
+        }
+        merged.push((start, end));
+    }
+    merged
+}
