+pub fn union(first: &[Interval], second: &[Interval]) -> Vec<Interval> {
+    let mut all = Vec::with_capacity(first.len() + second.len());
+    all.extend_from_slice(first);
+    all.extend_from_slice(second);
+    normalize(&all)
+}
