+    for &(a_start, a_end) in &left {
+        let mut cursor = a_start as i64;
+        let a_end_wide = a_end as i64;
+
+        for &(b_start, b_end) in &right {
+            let b_start_wide = b_start as i64;
+            let b_end_wide = b_end as i64;
+
+            if b_end_wide < cursor {
+                continue;
+            }
+            if b_start_wide > a_end_wide {
+                break;
+            }
