+            result.push('\\');
+        }
+        result.push(ch);
+    }
+
+    result
+}
+
+pub fn decompress(input: &str) -> Result<String, DecompressionError> {
+    let mut result = String::new();
+    let mut chars = input.chars().peekable();
+
+    while let Some(ch) = chars.next() {
+        if ch == '\\' {
+            match chars.next() {
+                Some(escaped) => result.push(escaped),
+                None => return Err(DecompressionError::TrailingEscape),
+            }
+        } else if ch.is_ascii_digit() {
+            let mut count_text = String::new();
+            count_text.push(ch);
