+                }
+            }
+
+            let count = count_text
+                .parse::<usize>()
+                .map_err(|_| DecompressionError::InvalidCount)?;
+
+            if count < 2 {
+                return Err(DecompressionError::InvalidCount);
+            }
+
+            let run_char = match chars.next() {
+                None => return Err(DecompressionError::MissingCharacter),
+                Some('\\') => match chars.next() {
+                    Some(escaped) => escaped,
+                    None => return Err(DecompressionError::TrailingEscape),
+                },
+                Some(literal) => literal,
+            };
+
+            for _ in 0..count {
+                result.push(run_char);
+            }
+        } else {
