+                    self.state = State::DoorsOpen;
+                    self.target = None;
+                    Action::OpenDoors
+                } else if floor > self.floor {
+                    self.state = State::MovingUp;
+                    self.target = Some(floor);
+                    Action::MoveUp
+                } else {
+                    self.state = State::MovingDown;
+                    self.target = Some(floor);
+                    Action::MoveDown
+                }
+            }
+            State::MovingUp => {
+                if floor > self.floor && self.target.map_or(true, |target| floor > target) {
+                    self.target = Some(floor);
+                    Action::MoveUp
+                } else {
+                    Action::Ignore
+                }
+            }
+            State::MovingDown => {
+                if floor < self.floor && self.target.map_or(true, |target| floor < target) {
+                    self.target = Some(floor);
+                    Action::MoveDown
+                } else {
+                    Action::Ignore
+                }
+            }
+            State::DoorsOpen | State::OutOfService => Action::Ignore,
