+                    if self.floor == target {
+                        self.state = State::DoorsOpen;
+                        self.target = None;
+                        Action::OpenDoors
+                    } else {
+                        Action::MoveUp
+                    }
+                }
+                _ => {
+                    self.state = State::Idle;
+                    self.target = None;
+                    Action::Stop
+                }
+            },
+            State::MovingDown => match self.target {
+                Some(target) if self.floor > target => {
+                    self.floor -= 1;
+                    if self.floor == target {
+                        self.state = State::DoorsOpen;
+                        self.target = None;
+                        Action::OpenDoors
+                    } else {
+                        Action::MoveDown
+                    }
+                }
+                _ => {
+                    self.state = State::Idle;
+                    self.target = None;
+                    Action::Stop
+                }
+            },
+            _ => Action::Ignore,
+        }
+    }
+
+    fn open_doors(&mut self) -> Action {
+        if self.state == State::Idle {
+            self.state = State::DoorsOpen;
+            Action::OpenDoors
+        } else {
+            Action::Ignore
+        }
+    }
+
+    fn close_doors(&mut self) -> Action {
+        if self.state == State::DoorsOpen {
+            self.state = State::Idle;
+            Action::CloseDoors
+        } else {
+            Action::Ignore
+        }
