+    pub fn write(&mut self, value: T) -> Result<(), T> {
+        if self.len == self.buffer.len() {
+            return Err(value);
+        }
+        let tail = (self.head + self.len) % self.buffer.len();
+        self.buffer[tail] = Some(value);
+        self.len += 1;
+        Ok(())
+    }
+
+    pub fn read(&mut self) -> Option<T> {
+        if self.len == 0 {
+            return None;
+        }
+        let value = self.buffer[self.head].take();
+        self.head = (self.head + 1) % self.buffer.len();
+        self.len -= 1;
+        value
+    }
+
+    pub fn overwrite(&mut self, value: T) -> Option<T> {
+        if self.buffer.is_empty() {
+            return None;
+        }
+        if self.len < self.buffer.len() {
+            self.write(value).ok();
+            None
+        } else {
+            let old = self.buffer[self.head].take();
+            self.buffer[self.head] = Some(value);
+            self.head = (self.head + 1) % self.buffer.len();
+            old
+        }
+    }
+
+    pub fn clear(&mut self) {
+        for item in self.buffer.iter_mut() {
+            *item = None;
+        }
+        self.head = 0;
+        self.len = 0;
+    }
