+use std::cmp::Ordering;
+
+pub struct BinarySearchTree<T> {
+    root: Option<Box<Node<T>>>,
+}
+
+struct Node<T> {
+    value: T,
+    left: Option<Box<Node<T>>>,
+    right: Option<Box<Node<T>>>,
+}
+
+impl<T: Ord> BinarySearchTree<T> {
+    pub fn new() -> Self {
+        Self { root: None }
+    }
+
+    pub fn insert(&mut self, value: T) {
+        Self::insert_into(&mut self.root, value);
+    }
+
+    fn insert_into(slot: &mut Option<Box<Node<T>>>, value: T) {
+        match slot {
+            None => {
+                *slot = Some(Box::new(Node {
+                    value,
+                    left: None,
+                    right: None,
+                }));
+            }
+            Some(node) => match value.cmp(&node.value) {
+                Ordering::Less => Self::insert_into(&mut node.left, value),
+                Ordering::Greater => Self::insert_into(&mut node.right, value),
+                Ordering::Equal => {}
+            },
+        }
+    }
+
+    pub fn contains(&self, value: &T) -> bool {
+        let mut current = self.root.as_deref();
+
+        while let Some(node) = current {
+            match node.value.cmp(value) {
+                Ordering::Less => current = node.right.as_deref(),
+                Ordering::Greater => current = node.left.as_deref(),
+                Ordering::Equal => return true,
+            }
+        }
+
+        false
+    }
+
+    pub fn len(&self) -> usize {
+        Self::count(&self.root)
+    }
+
+    fn count(node: &Option<Box<Node<T>>>) -> usize {
+        match node {
+            None => 0,
+            Some(node) => 1 + Self::count(&node.left) + Self::count(&node.right),
+        }
+    }
+
+    pub fn is_empty(&self) -> bool {
+        self.root.is_none()
+    }
+
+    pub fn into_sorted_vec(self) -> Vec<T> {
+        let mut values = Vec::new();
+        Self::collect_in_order(self.root, &mut values);
+        values
+    }
+
+    fn collect_in_order(node: Option<Box<Node<T>>>, values: &mut Vec<T>) {
+        if let Some(node) = node {
+            let Node { value, left, right } = *node;
+            Self::collect_in_order(left, values);
+            values.push(value);
+            Self::collect_in_order(right, values);
+        }
+    }
+}
