+#[derive(Debug, Clone)]
+pub struct MinMaxQueue<T> {
+    front: Vec<(T, T, T)>,
+    back: Vec<(T, T, T)>,
+}
+
+impl<T: Ord + Clone> MinMaxQueue<T> {
+    pub fn new() -> Self {
+        MinMaxQueue {
+            front: Vec::new(),
+            back: Vec::new(),
+        }
+    }
+
+    pub fn push_back(&mut self, value: T) {
+        let (min, max) = match self.back.last() {
+            Some((_, lo, hi)) => (lo.clone().min(value.clone()), hi.clone().max(value.clone())),
+            None => (value.clone(), value.clone()),
+        };
+        self.back.push((value, min, max));
+    }
+
+    pub fn pop_front(&mut self) -> Option<T> {
+        if self.front.is_empty() {
+            while let Some((value, _, _)) = self.back.pop() {
+                let (min, max) = match self.front.last() {
+                    Some((_, lo, hi)) => {
+                        (lo.clone().min(value.clone()), hi.clone().max(value.clone()))
+                    }
+                    None => (value.clone(), value.clone()),
+                };
+                self.front.push((value, min, max));
+            }
+        }
+        let (value, _, _) = self.front.pop()?;
+        Some(value)
+    }
+
+    pub fn peek_front(&self) -> Option<&T> {
+        match self.front.last() {
+            Some((value, _, _)) => Some(value),
+            None => self.back.first().map(|(value, _, _)| value),
+        }
+    }
+
+    pub fn peek_back(&self) -> Option<&T> {
+        match self.back.last() {
+            Some((value, _, _)) => Some(value),
+            None => self.front.first().map(|(value, _, _)| value),
+        }
+    }
+
+    pub fn min(&self) -> Option<&T> {
+        let front = self.front.last().map(|(_, lo, _)| lo);
+        let back = self.back.last().map(|(_, lo, _)| lo);
+        match (front, back) {
+            (Some(a), Some(b)) => Some(a.min(b)),
+            (a, b) => a.or(b),
+        }
+    }
+
+    pub fn max(&self) -> Option<&T> {
+        let front = self.front.last().map(|(_, _, hi)| hi);
+        let back = self.back.last().map(|(_, _, hi)| hi);
+        match (front, back) {
+            (Some(a), Some(b)) => Some(a.max(b)),
+            (a, b) => a.or(b),
+        }
+    }
+
+    pub fn len(&self) -> usize {
+        self.front.len() + self.back.len()
+    }
+
+    pub fn is_empty(&self) -> bool {
+        self.front.is_empty() && self.back.is_empty()
+    }
+}
