+    let mut line = 1usize;
+    let mut i = 0usize;
+
+    while i < chars.len() {
+        let c = chars[i];
+
+        if in_quotes {
+            if c == '"' {
+                if i + 1 < chars.len() && chars[i + 1] == '"' {
+                    field.push('"');
+                    i += 2;
+                } else {
+                    if i + 1 < chars.len() {
+                        let next = chars[i + 1];
+                        if next != ',' && next != '\n' && next != '\r' {
+                            return Err(CsvError::InvalidQuote { line });
+                        }
+                    }
+                    in_quotes = false;
+                    i += 1;
+                }
+            } else {
+                if c == '\n' {
+                    line += 1;
+                }
+                field.push(c);
+                i += 1;
+            }
+            continue;
+        }
+
+        match c {
+            ',' => {
+                record_started = true;
+                record.push(std::mem::take(&mut field));
+                i += 1;
+            }
+            '\n' | '\r' => {
+                if c == '\r' && i + 1 < chars.len() && chars[i + 1] == '\n' {
+                    i += 2;
+                } else {
+                    i += 1;
+                }
+
+                if record_started || !field.is_empty() || !record.is_empty() {
+                    record.push(std::mem::take(&mut field));
+                    records.push(std::mem::take(&mut record));
+                }
+                record_started = false;
+                line += 1;
+            }
+            '"' if field.is_empty() => {
+                record_started = true;
+                in_quotes = true;
+                quote_start_line = line;
+                i += 1;
+            }
+            _ => {
+                record_started = true;
+                field.push(c);
+                i += 1;
+            }
+        }
+    }
+
+    if in_quotes {
+        return Err(CsvError::UnclosedQuote {
+            line: quote_start_line,
+        });
+    }
+
+    if record_started || !field.is_empty() || !record.is_empty() {
+        record.push(field);
+        records.push(record);
+    }
+
+    Ok(records)
+}
