+fn weekday_from_days(days: i64) -> Weekday {
+    let index = (days + 3).rem_euclid(7);
+    match index {
+        0 => Weekday::Monday,
+        1 => Weekday::Tuesday,
+        2 => Weekday::Wednesday,
+        3 => Weekday::Thursday,
+        4 => Weekday::Friday,
+        5 => Weekday::Saturday,
+        _ => Weekday::Sunday,
