+            self.head = (self.head + 1) % self.capacity;
+        } else {
+            let index = (self.head + self.len) % self.capacity;
+            self.data[index] = Some(value);
+            self.len += 1;
+        }
+    }
+
+    pub fn clear(&mut self) {
+        for slot in &mut self.data {
+            *slot = None;
+        }
