+            let ch = grid[nr].chars().nth(nc).unwrap();
+            if ch == '#' {
+                continue;
+            }
+            if nr == er && nc == ec {
+                return Some(dist + 1);
+            }
+            visited[nr][nc] = true;
+            queue.push_back((nr, nc, dist + 1));
+        }
+    }
