+impl Fraction {
+    pub fn new(numerator: i64, denominator: i64) -> Result<Self, FractionError> {
+        if denominator == 0 {
+            return Err(FractionError::ZeroDenominator);
+        }
+
+        let mut n = numerator as i128;
+        let mut d = denominator as i128;
+
+        if d < 0 {
+            n = -n;
+            d = -d;
+        }
+
+        if n == 0 {
+            return Ok(Fraction {
+                numerator: 0,
+                denominator: 1,
+            });
+        }
+
+        let g = gcd(n.abs(), d);
+        n /= g;
+        d /= g;
+
+        if n < i64::MIN as i128 || n > i64::MAX as i128 || d > i64::MAX as i128 {
+            return Err(FractionError::Overflow);
+        }
+
+        Ok(Fraction {
+            numerator: n as i64,
+            denominator: d as i64,
+        })
+    }
