+        let n = self.numerator as i128;
+        let d = self.denominator as i128;
+        let quotient = n.div_euclid(d);
+        let remainder = n.rem_euclid(d);
+
+        let rounded = match mode {
+            RoundingMode::Floor => quotient,
+            RoundingMode::Ceiling => {
+                if remainder == 0 {
+                    quotient
+                } else {
+                    quotient + 1
+                }
+            }
+            RoundingMode::TowardZero => {
+                if remainder == 0 {
+                    quotient
+                } else if n < 0 {
+                    quotient + 1
+                } else {
+                    quotient
+                }
+            }
+            RoundingMode::AwayFromZero => {
+                if remainder == 0 {
+                    quotient
+                } else if n < 0 {
+                    quotient
+                } else {
+                    quotient + 1
+                }
+            }
+            RoundingMode::Nearest => {
+                let twice = 2 * remainder;
+                if twice < d {
+                    quotient
+                } else if twice > d {
+                    quotient + 1
+                } else if n < 0 {
+                    quotient
+                } else {
+                    quotient + 1
+                }
+            }
+            RoundingMode::HalfEven => {
