+                    }
+                } else {
+                    field.push(c);
+                }
+            }
+        } else {
+            while let Some(&c) = chars.peek() {
+                if c == ',' {
+                    break;
+                }
+                field.push(c);
+                chars.next();
+            }
+        }
+
+        fields.push(field);
+
+        if chars.peek() == Some(&',') {
+            chars.next();
+            if chars.peek().is_none() {
+                fields.push(String::new());
+                break;
+            }
+        } else {
+            break;
+        }
+    }
