+pub fn compress(input: &str) -> String {
+    let mut out = String::new();
+    let mut chars = input.chars().peekable();
+
+    while let Some(c) = chars.next() {
+        let mut count = 1usize;
+
+        while chars.peek() == Some(&c) {
+            chars.next();
+            count += 1;
+        }
+
+        if count >= 2 {
+            out.push_str(&count.to_string());
+            out.push(':');
+            out.push(c);
+        } else if c.is_ascii_digit() || c == '\\' {
+            out.push('\\');
+            out.push(c);
+        } else {
+            out.push(c);
+        }
+    }
+
+    out
+}
+
+pub fn decompress(input: &str) -> Result<String, String> {
+    let mut out = String::new();
+    let mut chars = input.chars().peekable();
+
+    while let Some(c) = chars.next() {
+        if c == '\\' {
+            match chars.next() {
+                Some(next) => out.push(next),
+                None => return Err("trailing escape".to_string()),
+            }
+        } else if c.is_ascii_digit() {
+            let mut count = 0usize;
+            let mut digit = c;
+
+            loop {
+                let value = digit.to_digit(10).expect("ASCII digit") as usize;
+
+                count = count
+                    .checked_mul(10)
+                    .ok_or_else(|| "repeat count overflow".to_string())?;
+                count = count
+                    .checked_add(value)
+                    .ok_or_else(|| "repeat count overflow".to_string())?;
+
+                match chars.peek() {
+                    Some(next) if next.is_ascii_digit() => {
+                        digit = chars.next().expect("peeked digit");
+                    }
+                    _ => break,
+                }
+            }
+
+            if count < 2 {
+                return Err("repeat count must be at least 2".to_string());
+            }
+
+            match chars.next() {
+                Some(':') => {}
+                Some(_) | None => return Err("expected ':' after repeat count".to_string()),
+            }
+
+            match chars.next() {
+                Some(ch) => {
+                    for _ in 0..count {
+                        out.push(ch);
+                    }
+                }
+                None => return Err("expected character after ':'".to_string()),
+            }
+        } else {
+            out.push(c);
+        }
+    }
+
+    Ok(out)
+}
