+pub struct MaxDeque {
+    values: Vec<i32>,
+    start: usize,
+    end: usize,
+    size: usize,
+    tree: Vec<i32>,
+}
+
+impl MaxDeque {
+    pub fn new() -> Self {
+        Self {
+            values: Vec::new(),
+            start: 0,
+            end: 0,
+            size: 1,
+            tree: vec![i32::MIN; 2],
+        }
+    }
+
+    fn ensure_capacity(&mut self, needed: usize) {
+        if needed <= self.size {
+            return;
+        }
+
+        let mut new_size = self.size;
+        while new_size < needed {
+            new_size *= 2;
+        }
+
+        self.size = new_size;
+        self.tree = vec![i32::MIN; new_size * 2];
+
+        for (index, &value) in self.values.iter().enumerate() {
+            self.tree[new_size + index] = value;
+        }
+
+        for index in (1..new_size).rev() {
+            self.tree[index] = self.tree[2 * index].max(self.tree[2 * index + 1]);
+        }
+    }
+
+    fn update(&mut self, index: usize, value: i32) {
+        let mut position = self.size + index;
+        self.tree[position] = value;
+        position /= 2;
+
+        while position > 0 {
+            self.tree[position] = self.tree[2 * position].max(self.tree[2 * position + 1]);
+            position /= 2;
+        }
+    }
+
+    fn range_max(&self, left: usize, right: usize) -> i32 {
+        let mut left = left + self.size;
+        let mut right = right + self.size;
+        let mut result = i32::MIN;
+
+        while left < right {
+            if left % 2 == 1 {
+                result = result.max(self.tree[left]);
+                left += 1;
+            }
+
+            if right % 2 == 1 {
+                right -= 1;
+                result = result.max(self.tree[right]);
+            }
+
+            left /= 2;
+            right /= 2;
+        }
+
+        result
+    }
+
+    fn reset_if_empty(&mut self) {
+        if self.start == self.end {
+            self.start = 0;
+            self.end = 0;
+            self.values.clear();
+            self.size = 1;
+            self.tree = vec![i32::MIN; 2];
+        }
+    }
+
+    pub fn push(&mut self, value: i32) {
+        let index = self.end;
+
+        if index == self.values.len() {
+            self.values.push(value);
+            self.ensure_capacity(self.values.len());
+            self.update(index, value);
+        } else {
+            self.values[index] = value;
+            self.update(index, value);
+        }
+
+        self.end += 1;
+    }
+
+    pub fn pop(&mut self) -> Option<i32> {
+        if self.start == self.end {
+            return None;
+        }
+
+        self.end -= 1;
+        let value = self.values[self.end];
+        self.reset_if_empty();
+        Some(value)
+    }
+
+    pub fn dequeue(&mut self) -> Option<i32> {
+        if self.start == self.end {
+            return None;
+        }
+
+        let value = self.values[self.start];
+        self.start += 1;
+        self.reset_if_empty();
+        Some(value)
+    }
+
+    pub fn front(&self) -> Option<i32> {
+        if self.start < self.end {
+            Some(self.values[self.start])
+        } else {
+            None
+        }
+    }
+
+    pub fn back(&self) -> Option<i32> {
+        if self.start < self.end {
+            Some(self.values[self.end - 1])
+        } else {
+            None
+        }
+    }
+
+    pub fn max(&self) -> Option<i32> {
+        if self.start < self.end {
+            Some(self.range_max(self.start, self.end))
+        } else {
+            None
+        }
+    }
+
+    pub fn len(&self) -> usize {
+        self.end - self.start
+    }
+
+    pub fn is_empty(&self) -> bool {
+        self.start == self.end
+    }
+}
