+use std::cmp::Ordering;
+
+#[derive(Debug, PartialEq, Eq)]
+pub struct VersionError;
+
+struct Version<'a> {
+    core: [&'a str; 3],
+    pre: Option<Vec<&'a str>>,
+}
+
+pub fn compare_versions(left: &str, right: &str) -> Result<Ordering, VersionError> {
+    let left = parse(left)?;
+    let right = parse(right)?;
+    Ok(compare_parsed(&left, &right))
+}
+
+fn parse(version: &str) -> Result<Version<'_>, VersionError> {
+    let main = match version.split_once('+') {
+        Some((main, build)) => {
+            validate_identifiers(build, true)?;
+            main
+        }
+        None => version,
+    };
+
+    let (core, pre) = match main.split_once('-') {
+        Some((core, pre)) => {
+            let identifiers = validate_identifiers(pre, false)?;
+            (core, Some(identifiers))
+        }
+        None => (main, None),
+    };
+
+    let mut core_parts = core.split('.');
+    let major = core_parts.next().ok_or(VersionError)?;
+    let minor = core_parts.next().ok_or(VersionError)?;
+    let patch = core_parts.next().ok_or(VersionError)?;
+    if core_parts.next().is_some() {
+        return Err(VersionError);
+    }
+
+    validate_core_identifier(major)?;
+    validate_core_identifier(minor)?;
+    validate_core_identifier(patch)?;
+
+    Ok(Version {
+        core: [major, minor, patch],
+        pre,
+    })
+}
+
+fn validate_core_identifier(identifier: &str) -> Result<(), VersionError> {
+    if identifier.is_empty() || !identifier.bytes().all(|byte| byte.is_ascii_digit()) {
+        return Err(VersionError);
+    }
+    if identifier.len() > 1 && identifier.starts_with('0') {
+        return Err(VersionError);
+    }
+    Ok(())
+}
+
+fn validate_identifiers(
+    value: &str,
+    allow_leading_zero: bool,
+) -> Result<Vec<&str>, VersionError> {
+    if value.is_empty() {
+        return Err(VersionError);
+    }
+
+    let mut identifiers = Vec::new();
+    for identifier in value.split('.') {
+        if identifier.is_empty()
+            || !identifier
+                .bytes()
+                .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
+        {
+            return Err(VersionError);
+        }
+        if !allow_leading_zero
+            && is_numeric(identifier)
+            && identifier.len() > 1
+            && identifier.starts_with('0')
+        {
+            return Err(VersionError);
+        }
+        identifiers.push(identifier);
+    }
+    Ok(identifiers)
+}
+
+fn compare_parsed(left: &Version<'_>, right: &Version<'_>) -> Ordering {
+    for index in 0..3 {
+        let ordering = compare_numeric(left.core[index], right.core[index]);
+        if ordering != Ordering::Equal {
+            return ordering;
+        }
+    }
+    compare_prerelease(left.pre.as_deref(), right.pre.as_deref())
+}
+
+fn compare_prerelease(left: Option<&[&str]>, right: Option<&[&str]>) -> Ordering {
+    match (left, right) {
+        (None, None) => Ordering::Equal,
+        (None, Some(_)) => Ordering::Greater,
+        (Some(_), None) => Ordering::Less,
+        (Some(left), Some(right)) => {
+            for (left_identifier, right_identifier) in left.iter().zip(right.iter()) {
+                let ordering = compare_identifier(*left_identifier, *right_identifier);
+                if ordering != Ordering::Equal {
+                    return ordering;
+                }
+            }
+            left.len().cmp(&right.len())
+        }
+    }
+}
+
+fn compare_identifier(left: &str, right: &str) -> Ordering {
+    match (is_numeric(left), is_numeric(right)) {
+        (true, true) => compare_numeric(left, right),
+        (true, false) => Ordering::Less,
+        (false, true) => Ordering::Greater,
+        (false, false) => left.cmp(right),
+    }
+}
+
+fn compare_numeric(left: &str, right: &str) -> Ordering {
+    left.len().cmp(&right.len()).then_with(|| left.cmp(right))
+}
+
+fn is_numeric(value: &str) -> bool {
+    !value.is_empty() && value.bytes().all(|byte| byte.is_ascii_digit())
+}
