+
+impl<T: Ord + Clone> BinarySearchTree<T> {
+    pub fn new() -> Self {
+        Self { root: None }
+    }
+
+    pub fn insert(&mut self, value: T) -> bool {
+        fn insert_node<T: Ord>(node: &mut Option<Box<Node<T>>>, value: T) -> bool {
+            match node {
+                None => {
+                    *node = Some(Box::new(Node {
+                        value,
+                        left: None,
+                        right: None,
+                    }));
+                    true
+                }
+                Some(current) => {
+                    if value < current.value {
+                        insert_node(&mut current.left, value)
+                    } else if value > current.value {
+                        insert_node(&mut current.right, value)
+                    } else {
+                        false
+                    }
+                }
+            }
+        }
+
+        insert_node(&mut self.root, value)
+    }
+
+    pub fn contains(&self, value: &T) -> bool {
+        fn contains_node<T: Ord>(node: &Option<Box<Node<T>>>, value: &T) -> bool {
+            match node {
+                None => false,
+                Some(current) => {
+                    if value < &current.value {
+                        contains_node(&current.left, value)
+                    } else if value > &current.value {
+                        contains_node(&current.right, value)
+                    } else {
+                        true
+                    }
+                }
+            }
+        }
+
+        contains_node(&self.root, value)
+    }
+
+    pub fn remove(&mut self, value: &T) -> bool {
+        fn remove_min<T: Ord>(node: Option<Box<Node<T>>>) -> (Option<Box<Node<T>>>, T) {
+            let mut node = node.expect("remove_min requires a non-empty subtree");
+
+            if node.left.is_some() {
+                let (new_left, min) = remove_min(node.left.take());
+                node.left = new_left;
+                (Some(node), min)
+            } else {
+                let Node { value, right, .. } = *node;
+                (right, value)
+            }
+        }
+
+        fn remove_node<T: Ord + Clone>(
+            node: &mut Option<Box<Node<T>>>,
+            value: &T,
+        ) -> bool {
+            match node {
+                None => false,
+                Some(current) => {
+                    if value < &current.value {
+                        remove_node(&mut current.left, value)
+                    } else if value > &current.value {
+                        remove_node(&mut current.right, value)
+                    } else {
+                        let (left, right) = (current.left.take(), current.right.take());
+
+                        match (left, right) {
+                            (None, None) => {
+                                *node = None;
+                            }
+                            (Some(left), None) => {
+                                *node = Some(left);
+                            }
+                            (None, Some(right)) => {
+                                *node = Some(right);
+                            }
+                            (Some(left), Some(right)) => {
+                                let (new_right, successor) = remove_min(Some(right));
+                                *node = Some(Box::new(Node {
+                                    value: successor,
+                                    left: Some(left),
+                                    right: new_right,
+                                }));
+                            }
+                        }
+
+                        true
+                    }
+                }
+            }
+        }
+
+        remove_node(&mut self.root, value)
+    }
+
+    pub fn len(&self) -> usize {
+        fn count<T>(node: &Option<Box<Node<T>>>) -> usize {
+            match node {
+                None => 0,
+                Some(current) => 1 + count(&current.left) + count(&current.right),
+            }
+        }
+
+        count(&self.root)
+    }
+
+    pub fn is_empty(&self) -> bool {
+        self.root.is_none()
+    }
+
+    pub fn height(&self) -> usize {
+        fn height_of<T>(node: &Option<Box<Node<T>>>) -> usize {
+            match node {
+                None => 0,
+                Some(current) => {
+                    1 + height_of(&current.left).max(height_of(&current.right))
+                }
+            }
+        }
+
+        height_of(&self.root)
+    }
+
+    pub fn in_order(&self) -> Vec<T> {
+        fn walk<T: Clone>(node: &Option<Box<Node<T>>>, out: &mut Vec<T>) {
+            if let Some(current) = node {
+                walk(&current.left, out);
+                out.push(current.value.clone());
+                walk(&current.right, out);
+            }
+        }
+
+        let mut out = Vec::new();
+        walk(&self.root, &mut out);
+        out
+    }
+
+    pub fn level_order(&self) -> Vec<T> {
+        let mut out = Vec::new();
+        let mut queue = VecDeque::new();
+
+        if let Some(root) = &self.root {
+            queue.push_back(root);
+        }
+
+        while let Some(current) = queue.pop_front() {
+            out.push(current.value.clone());
+
+            if let Some(left) = &current.left {
+                queue.push_back(left);
+            }
+
+            if let Some(right) = &current.right {
+                queue.push_back(right);
+            }
+        }
+
+        out
+    }
+}
