+pub fn totient(n: u64) -> Option<u64> {
+    if n == 0 {
+        return None;
+    }
+
+    let mut result = n;
+    let mut remaining = n;
+    let mut factor = 2;
+
+    while factor <= remaining / factor {
+        if remaining % factor == 0 {
+            while remaining % factor == 0 {
+                remaining /= factor;
+            }
+            result -= result / factor;
+        }
+
+        factor += if factor == 2 { 1 } else { 2 };
+    }
+
+    if remaining > 1 {
+        result -= result / remaining;
+    }
+
+    Some(result)
+}
+
+pub fn totients_up_to(limit: u64) -> Vec<u64> {
+    let mut phi: Vec<u64> = (0..=limit).collect();
+
+    if let Some(first) = phi.first_mut() {
+        *first = 0;
+    }
+
+    let mut prime = 2;
+    while prime <= limit {
+        if phi[prime as usize] == prime {
+            let mut multiple = prime;
+            while multiple <= limit {
+                phi[multiple as usize] -= phi[multiple as usize] / prime;
+                multiple += prime;
+            }
+        }
+        prime += 1;
+    }
+
+    if limit >= 1 {
+        phi[1] = 1;
+    }
+
+    phi
+}
