+        let item = self
+            .items
+            .get_mut(sku)
+            .ok_or(InventoryError::UnknownSku)?;
+
+        if quantity > item.quantity {
+            return Err(InventoryError::InsufficientStock {
+                available: item.quantity,
+                requested: quantity,
+            });
+        }
+
+        item.quantity -= quantity;
+        Ok(item.quantity)
+    }
+
+    pub fn get_item(&self, sku: &str) -> Option<&Item> {
