+use std::collections::VecDeque;
+
+pub fn longest_subarray(values: &[i32], limit: i32) -> usize {
+    if values.is_empty() || limit < 0 {
+        return 0;
+    }
+
+    let mut max_queue = VecDeque::new();
+    let mut min_queue = VecDeque::new();
+    let mut left = 0;
+    let mut best = 0;
+
+    for right in 0..values.len() {
+        while let Some(&last) = max_queue.back() {
+            if values[last] <= values[right] {
+                max_queue.pop_back();
+            } else {
+                break;
+            }
+        }
+        max_queue.push_back(right);
+
+        while let Some(&last) = min_queue.back() {
+            if values[last] >= values[right] {
+                min_queue.pop_back();
+            } else {
+                break;
+            }
+        }
+        min_queue.push_back(right);
+
+        while values[*max_queue.front().unwrap()] as i64
+            - values[*min_queue.front().unwrap()] as i64
+            > i64::from(limit)
+        {
+            if max_queue.front() == Some(&left) {
+                max_queue.pop_front();
+            }
+            if min_queue.front() == Some(&left) {
+                min_queue.pop_front();
+            }
+            left += 1;
+        }
+
+        best = best.max(right - left + 1);
+    }
+
+    best
+}
