+pub fn is_valid_isbn10(isbn: &str) -> bool {
+    if isbn.chars().count() != 10 {
+        return false;
+    }
+    let mut sum = 0;
+    for (i, c) in isbn.chars().enumerate() {
+        if i < 9 {
+            if !c.is_ascii_digit() {
+                return false;
+            }
+            let digit = c.to_digit(10).unwrap() as u32;
+            sum += digit * (10 - i as u32);
+        } else {
+            let value = if c == 'X' || c == 'x' {
+                10
+            } else if c.is_ascii_digit() {
+                c.to_digit(10).unwrap()
+            } else {
+                return false;
+            };
+            sum += value;
+        }
+    }
+    sum % 11 == 0
+}
+
+pub fn check_digit_isbn10(isbn: &str) -> Option<char> {
+    if isbn.chars().count() != 9 {
+        return None;
+    }
+    let mut sum = 0;
+    for (i, c) in isbn.chars().enumerate() {
+        if !c.is_ascii_digit() {
+            return None;
+        }
+        let digit = c.to_digit(10).unwrap() as u32;
+        sum += digit * (10 - i as u32);
+    }
+    let check = (11 - (sum % 11)) % 11;
+    if check == 10 {
+        Some('X')
+    } else {
+        char::from_digit(check, 10)
+    }
+}
