+pub enum RomanError {
+    OutOfRange,
+    Empty,
+    InvalidCharacter(char),
+    InvalidNumeral,
+}
+
+const NUMERALS: &[(u16, &str)] = &[
+    (1000, "M"),
+    (900, "CM"),
+    (500, "D"),
+    (400, "CD"),
+    (100, "C"),
+    (90, "XC"),
+    (50, "L"),
+    (40, "XL"),
+    (10, "X"),
+    (9, "IX"),
+    (5, "V"),
+    (4, "IV"),
+    (1, "I"),
+];
+
+pub fn to_roman(number: u16) -> Result<String, RomanError> {
+    if number == 0 || number > 3999 {
+        return Err(RomanError::OutOfRange);
+    }
+
+    let mut remaining = number;
+    let mut result = String::new();
+
+    for &(value, numeral) in NUMERALS {
+        while remaining >= value {
+            result.push_str(numeral);
+            remaining -= value;
+        }
+    }
+
+    Ok(result)
+}
+
+pub fn from_roman(numeral: &str) -> Result<u16, RomanError> {
+    if numeral.is_empty() {
+        return Err(RomanError::Empty);
+    }
+
+    for ch in numeral.chars() {
+        if !matches!(ch, 'I' | 'V' | 'X' | 'L' | 'C' | 'D' | 'M') {
+            return Err(RomanError::InvalidCharacter(ch));
+        }
+    }
+
+    let mut total: i64 = 0;
+    let mut previous: i64 = 0;
+
+    for ch in numeral.chars().rev() {
+        let value = match ch {
+            'I' => 1,
+            'V' => 5,
+            'X' => 10,
+            'L' => 50,
+            'C' => 100,
+            'D' => 500,
+            'M' => 1000,
+            _ => unreachable!(),
+        };
+
+        if value < previous {
+            total -= value;
+        } else {
+            total += value;
+            previous = value;
+        }
+    }
+
+    if total <= 0 {
+        return Err(RomanError::InvalidNumeral);
+    }
+
+    if total > 3999 {
+        return Err(RomanError::OutOfRange);
+    }
+
+    let value = total as u16;
+    let canonical = to_roman(value)?;
+
+    if canonical.as_str() == numeral {
+        Ok(value)
+    } else {
+        Err(RomanError::InvalidNumeral)
+    }
