+pub fn convert(input: &str, from_base: u32, to_base: u32) -> Result<String, String> {
+    if !(2..=36).contains(&from_base) {
+        return Err(format!("source base must be between 2 and 36, got {from_base}"));
+    }
+    if !(2..=36).contains(&to_base) {
+        return Err(format!("target base must be between 2 and 36, got {to_base}"));
+    }
+
+    let trimmed = input.trim_matches(|c: char| c.is_ascii_whitespace());
+    if trimmed.is_empty() {
+        return Err("input is empty".to_string());
+    }
+
+    let mut decimal: Vec<u32> = vec![0];
+
+    for ch in trimmed.chars() {
+        let digit = match ch {
+            '0'..='9' => ch as u32 - '0' as u32,
+            'a'..='z' => ch as u32 - 'a' as u32 + 10,
+            'A'..='Z' => ch as u32 - 'A' as u32 + 10,
+            _ => return Err(format!("invalid digit: {ch}")),
+        };
+
+        if digit >= from_base {
+            return Err(format!("digit {ch} is out of range for base {from_base}"));
+        }
+
+        let mut carry = digit;
+        for limb in decimal.iter_mut() {
+            let value = *limb * from_base + carry;
+            *limb = value % 10;
+            carry = value / 10;
+        }
+        while carry > 0 {
+            decimal.push(carry % 10);
+            carry /= 10;
+        }
+    }
+
+    while decimal.len() > 1 && *decimal.last().unwrap() == 0 {
+        decimal.pop();
+    }
+
+    if decimal.len() == 1 && decimal[0] == 0 {
+        return Ok("0".to_string());
+    }
+
+    let mut output_digits = Vec::new();
+
+    while !(decimal.len() == 1 && decimal[0] == 0) {
+        let mut remainder = 0u32;
+        let mut quotient = Vec::with_capacity(decimal.len());
+
+        for &digit in decimal.iter().rev() {
+            let value = remainder * 10 + digit;
+            quotient.push(value / to_base);
+            remainder = value % to_base;
+        }
+
+        let first_nonzero = quotient
+            .iter()
+            .position(|&digit| digit != 0)
+            .unwrap_or(quotient.len());
+
+        let mut next_decimal: Vec<u32> = quotient[first_nonzero..].iter().rev().copied().collect();
+        if next_decimal.is_empty() {
+            next_decimal.push(0);
+        }
+        decimal = next_decimal;
+        output_digits.push(remainder);
+    }
+
+    let mut result = String::new();
+    for &digit in output_digits.iter().rev() {
+        result.push(digit_to_char(digit));
+    }
+
+    Ok(result)
