+use std::collections::VecDeque;
+
+pub fn shortest_path(grid: &[&str], start: (usize, usize), end: (usize, usize)) -> Option<usize> {
+    if grid.is_empty() {
+        return None;
+    }
+
+    let rows = grid.len();
+    let cols = grid[0].len();
+
+    if cols == 0 {
+        return None;
+    }
+
+    let in_bounds = |r: usize, c: usize| r < rows && c < cols;
+
+    if !in_bounds(start.0, start.1) || !in_bounds(end.0, end.1) {
+        return None;
+    }
+
+    let is_open = |r: usize, c: usize| grid[r].as_bytes()[c] == b'.';
+
+    if !is_open(start.0, start.1) || !is_open(end.0, end.1) {
+        return None;
+    }
+
+    if start == end {
+        return Some(0);
+    }
+
+    let mut dist = vec![vec![None; cols]; rows];
+    dist[start.0][start.1] = Some(0);
+
+    let mut queue = VecDeque::new();
+    queue.push_back(start);
+
+    let dirs = [(0isize, 1isize), (0, -1), (1, 0), (-1, 0)];
+
+    while let Some((r, c)) = queue.pop_front() {
+        let d = dist[r][c].unwrap();
+
+        for (dr, dc) in dirs {
+            let nr = r as isize + dr;
+            let nc = c as isize + dc;
+
+            if nr < 0 || nc < 0 {
+                continue;
+            }
+
+            let nr = nr as usize;
+            let nc = nc as usize;
+
+            if nr >= rows || nc >= cols {
+                continue;
+            }
+
+            if !is_open(nr, nc) {
+                continue;
+            }
+
+            if dist[nr][nc].is_none() {
+                dist[nr][nc] = Some(d + 1);
+
+                if (nr, nc) == end {
+                    return Some(d + 1);
+                }
+
+                queue.push_back((nr, nc));
+            }
+        }
+    }
+
+    None
+}
