+pub fn solve_pell(d: u32) -> Option<(u64, u64)> {
+    if d < 2 {
+        return None;
+    }
+
+    let d64 = d as u64;
+    let a0 = integer_sqrt(d64);
+    if a0 * a0 == d64 {
+        return None;
+    }
+
+    let d128 = d as u128;
+    let a0_128 = a0 as u128;
+
+    let mut m: u128 = 0;
+    let mut denominator: u128 = 1;
+    let mut a: u128 = a0_128;
+
+    let mut p_prev2: u128 = 0;
+    let mut p_prev1: u128 = 1;
+    let mut q_prev2: u128 = 1;
+    let mut q_prev1: u128 = 0;
+
+    loop {
+        let p = a.checked_mul(p_prev1)?.checked_add(p_prev2)?;
+        let q = a.checked_mul(q_prev1)?.checked_add(q_prev2)?;
+
+        if let Some(p_squared) = p.checked_mul(p) {
+            if let Some(d_q) = d128.checked_mul(q) {
+                if let Some(d_q_squared) = d_q.checked_mul(q) {
+                    if d_q_squared.checked_add(1) == Some(p_squared) {
+                        if p <= u64::MAX as u128 && q <= u64::MAX as u128 {
+                            return Some((p as u64, q as u64));
+                        }
+                        return None;
+                    }
+                }
+            }
+        }
+
+        let m_next = denominator.checked_mul(a)?.checked_sub(m)?;
+        let denominator_numerator = d128.checked_sub(m_next.checked_mul(m_next)?)?;
+        let denominator_next = denominator_numerator / denominator;
+        let a_next = (a0_128 + m_next) / denominator_next;
+
+        m = m_next;
+        denominator = denominator_next;
+        a = a_next;
+
+        p_prev2 = p_prev1;
+        p_prev1 = p;
+        q_prev2 = q_prev1;
+        q_prev1 = q;
+    }
+}
+
+fn integer_sqrt(n: u64) -> u64 {
+    let mut low = 0u64;
+    let mut high = 1u64 << 32;
+
+    while low + 1 < high {
+        let mid = (low + high) / 2;
+        if mid <= n / mid {
+            low = mid;
+        } else {
+            high = mid;
+        }
+    }
+
+    low
+}
