+#[derive(Debug, PartialEq, Eq)]
+pub enum IsbnError {
+    InvalidLength,
+    InvalidCharacter,
+    InvalidChecksum,
+}
+
+#[derive(Debug, PartialEq, Eq)]
+pub enum IsbnKind {
+    Isbn10,
+    Isbn13,
+}
+
+fn clean(isbn: &str) -> String {
+    isbn.chars().filter(|c| *c != '-' && *c != ' ').collect()
+}
+
+pub fn validate(isbn: &str) -> Result<IsbnKind, IsbnError> {
+    let s = clean(isbn);
+    match s.len() {
+        10 => validate10(&s),
+        13 => validate13(&s),
+        _ => Err(IsbnError::InvalidLength),
+    }
+}
+
+fn validate10(s: &str) -> Result<IsbnKind, IsbnError> {
+    let mut sum: i32 = 0;
+    for (i, c) in s.chars().enumerate() {
+        let value: i32 = if i == 9 && (c == 'X' || c == 'x') {
+            10
+        } else {
+            c.to_digit(10).ok_or(IsbnError::InvalidCharacter)? as i32
+        };
+        sum += value * (10 - i as i32);
+    }
+    if sum % 11 == 0 {
+        Ok(IsbnKind::Isbn10)
+    } else {
+        Err(IsbnError::InvalidChecksum)
+    }
+}
+
+fn validate13(s: &str) -> Result<IsbnKind, IsbnError> {
+    let mut sum: i32 = 0;
+    for (i, c) in s.chars().enumerate() {
+        let d = c.to_digit(10).ok_or(IsbnError::InvalidCharacter)? as i32;
+        sum += d * if i % 2 == 0 { 1 } else { 3 };
+    }
+    if sum % 10 == 0 {
+        Ok(IsbnKind::Isbn13)
+    } else {
+        Err(IsbnError::InvalidChecksum)
+    }
+}
+
+pub fn check_digit(isbn: &str) -> Result<char, IsbnError> {
+    let s = clean(isbn);
+    let digits: Result<Vec<u32>, IsbnError> = s
+        .chars()
+        .map(|c| c.to_digit(10).ok_or(IsbnError::InvalidCharacter))
+        .collect();
+    let digits = digits?;
+    match digits.len() {
+        9 => {
+            let sum: u32 = digits
+                .iter()
+                .enumerate()
+                .map(|(i, d)| d * (10 - i as u32))
+                .sum();
+            let rem = (11 - (sum % 11)) % 11;
+            Ok(if rem == 10 {
+                'X'
+            } else {
+                char::from_digit(rem, 10).unwrap()
+            })
+        }
+        12 => {
+            let sum: u32 = digits
+                .iter()
+                .enumerate()
+                .map(|(i, d)| d * if i % 2 == 0 { 1 } else { 3 })
+                .sum();
+            let check = (10 - (sum % 10)) % 10;
+            Ok(char::from_digit(check, 10).unwrap())
+        }
+        _ => Err(IsbnError::InvalidLength),
+    }
+}
