+impl Inventory {
+    pub fn new() -> Self {
+        Self {
+            items: BTreeMap::new(),
+        }
+    }
+
+    fn normalize(name: &str) -> Result<String, InventoryError> {
+        let trimmed = name.trim();
+        if trimmed.is_empty() {
+            return Err(InventoryError::InvalidName);
+        }
+        Ok(trimmed.to_string())
+    }
+
+    pub fn add(&mut self, name: &str, quantity: u32) -> Result<(), InventoryError> {
+        let key = Self::normalize(name)?;
+        if quantity == 0 {
+            return Err(InventoryError::InvalidQuantity);
+        }
+        let entry = self.items.entry(key).or_insert(0);
+        *entry = entry.saturating_add(quantity);
+        Ok(())
+    }
+
+    pub fn remove(&mut self, name: &str, quantity: u32) -> Result<(), InventoryError> {
+        let key = Self::normalize(name)?;
+        if quantity == 0 {
+            return Err(InventoryError::InvalidQuantity);
+        }
+
+        let available = match self.items.get(&key) {
+            Some(&on_hand) => on_hand,
+            None => return Err(InventoryError::UnknownItem(key)),
+        };
+
+        if quantity > available {
+            return Err(InventoryError::InsufficientStock {
+                requested: quantity,
+                available,
+            });
+        }
+
+        let remaining = available - quantity;
+        if remaining == 0 {
+            self.items.remove(&key);
+        } else {
+            self.items.insert(key, remaining);
+        }
+        Ok(())
+    }
