+        self.items.get(name.trim()).copied().unwrap_or(0)
+    }
+
+    pub fn total(&self) -> u32 {
+        self.items
+            .values()
+            .fold(0u32, |acc, &qty| acc.saturating_add(qty))
+    }
+
+    pub fn unique_items(&self) -> usize {
+        self.items.len()
+    }
+
+    pub fn low_stock(&self, threshold: u32) -> Vec<String> {
+        self.items
+            .iter()
+            .filter(|(_, qty)| **qty <= threshold)
+            .map(|(name, _)| name.clone())
+            .collect()
+    }
+
+    pub fn top_items(&self, n: usize) -> Vec<(String, u32)> {
