+pub fn spin(grid: &[&str], operations: &str) -> Result<Vec<String>, String> {
+    let mut rows: Vec<Vec<char>> = grid.iter().map(|row| row.chars().collect()).collect();
+
+    if let Some(width) = rows.first().map(|row| row.len()) {
+        if rows.iter().any(|row| row.len() != width) {
+            return Err("grid must be rectangular".to_string());
+        }
+    }
+
+    for operation in operations.chars() {
+        match operation {
+            'R' => rows = rotate_clockwise(&rows),
+            'L' => rows = rotate_counterclockwise(&rows),
+            'H' => {
+                for row in &mut rows {
+                    row.reverse();
+                }
+            }
+            'V' => rows.reverse(),
+            'T' => rows = transpose(&rows),
+            other => return Err(format!("invalid operation: {}", other)),
+        }
+    }
+
+    Ok(rows.into_iter().map(|row| row.into_iter().collect()).collect())
+}
+
+fn rotate_clockwise(rows: &[Vec<char>]) -> Vec<Vec<char>> {
+    if rows.is_empty() || rows[0].is_empty() {
+        return Vec::new();
+    }
+
+    let row_count = rows.len();
+    let column_count = rows[0].len();
+    let mut rotated = vec![vec![' '; row_count]; column_count];
+
+    for new_row in 0..column_count {
+        for new_column in 0..row_count {
+            rotated[new_row][new_column] = rows[row_count - 1 - new_column][new_row];
+        }
+    }
+
+    rotated
+}
+
+fn rotate_counterclockwise(rows: &[Vec<char>]) -> Vec<Vec<char>> {
+    if rows.is_empty() || rows[0].is_empty() {
+        return Vec::new();
+    }
+
+    let row_count = rows.len();
+    let column_count = rows[0].len();
+    let mut rotated = vec![vec![' '; row_count]; column_count];
+
+    for new_row in 0..column_count {
+        for new_column in 0..row_count {
+            rotated[new_row][new_column] = rows[new_column][column_count - 1 - new_row];
+        }
+    }
+
+    rotated
+}
+
+fn transpose(rows: &[Vec<char>]) -> Vec<Vec<char>> {
+    if rows.is_empty() || rows[0].is_empty() {
+        return Vec::new();
