+pub fn longest_consecutive_prime_sum(limit: u64) -> Option<(u64, usize)> {
+    if limit < 2 {
+        return None;
+    }
+
+    let limit = limit as usize;
+    let mut is_prime = vec![true; limit + 1];
+    is_prime[0] = false;
+    is_prime[1] = false;
+
+    let mut p = 2;
+    while p * p <= limit {
+        if is_prime[p] {
+            let mut multiple = p * p;
+            while multiple <= limit {
+                is_prime[multiple] = false;
+                multiple += p;
+            }
+        }
+        p += 1;
+    }
+
+    let primes: Vec<usize> = (2..=limit).filter(|&n| is_prime[n]).collect();
+    let mut prefix = vec![0u64; primes.len() + 1];
+    for (i, &prime) in primes.iter().enumerate() {
+        prefix[i + 1] = prefix[i] + prime as u64;
+    }
+
+    let mut best_len = 0usize;
+    let mut best_sum = 0u64;
+
+    for start in 0..primes.len() {
+        let mut end = start + best_len + 1;
+        while end <= primes.len() {
+            let sum = prefix[end] - prefix[start];
+            if sum > limit as u64 {
+                break;
+            }
+            if is_prime[sum as usize] {
+                best_len = end - start;
+                best_sum = sum;
+            }
+            end += 1;
+        }
+    }
+
+    if best_len == 0 {
+        None
+    } else {
+        Some((best_sum, best_len))
+    }
