+#[derive(Debug, PartialEq, Eq)]
+pub enum DurationError {
+    Empty,
+    InvalidNumber,
+    UnknownUnit,
+    DuplicateUnit,
+    OutOfOrder,
+    ZeroValue,
+    Overflow,
+}
+
+pub fn parse_duration(input: &str) -> Result<u64, DurationError> {
+    if input.is_empty() {
+        return Err(DurationError::Empty);
+    }
+
+    let bytes = input.as_bytes();
+    let mut i = 0;
+    let mut total = 0u64;
+    let mut seen_h = false;
+    let mut seen_m = false;
+    let mut seen_s = false;
+    let mut last_rank: Option<u8> = None;
+
+    while i < bytes.len() {
+        let start = i;
+        while i < bytes.len() && bytes[i].is_ascii_digit() {
+            i += 1;
+        }
+
+        if i == start {
+            return Err(DurationError::InvalidNumber);
+        }
+        if i == bytes.len() {
+            return Err(DurationError::InvalidNumber);
+        }
+
+        let unit = bytes[i];
+        let (rank, factor, seen): (u8, u64, &mut bool) = match unit {
+            b'h' => (2, 3600, &mut seen_h),
+            b'm' => (1, 60, &mut seen_m),
+            b's' => (0, 1, &mut seen_s),
+            _ => return Err(DurationError::UnknownUnit),
+        };
+
+        if *seen {
+            return Err(DurationError::DuplicateUnit);
+        }
+        if let Some(prev) = last_rank {
+            if rank >= prev {
+                return Err(DurationError::OutOfOrder);
+            }
+        }
+
+        *seen = true;
+        last_rank = Some(rank);
+        i += 1;
+
+        let mut number = 0u64;
+        for &byte in &bytes[start..i - 1] {
+            let digit = (byte - b'0') as u64;
+            number = number
+                .checked_mul(10)
+                .and_then(|n| n.checked_add(digit))
+                .ok_or(DurationError::Overflow)?;
+        }
+
+        if number == 0 {
+            return Err(DurationError::ZeroValue);
+        }
+
+        let contribution = number
+            .checked_mul(factor)
+            .ok_or(DurationError::Overflow)?;
+        total = total
+            .checked_add(contribution)
+            .ok_or(DurationError::Overflow)?;
+    }
+
+    Ok(total)
+}
