+pub fn solve(congruences: &[(i64, i64)]) -> Option<(i64, i64)> {
+    let mut residue: i128 = 0;
+    let mut modulus: i128 = 1;
+
+    for &(a, m) in congruences {
+        if m <= 0 {
+            return None;
+        }
+
+        let mi = m as i128;
+        let ai = a.rem_euclid(m) as i128;
+        let g = gcd(modulus, mi);
+        let diff = ai - residue;
+
+        if diff % g != 0 {
+            return None;
+        }
+
+        let reduced_modulus = mi / g;
+        if reduced_modulus == 1 {
+            continue;
+        }
+
+        let cofactor = modulus / g;
+        let inverse = mod_inverse(cofactor.rem_euclid(reduced_modulus), reduced_modulus)?;
+        let k = (diff / g).rem_euclid(reduced_modulus) * inverse % reduced_modulus;
+
+        let new_modulus = modulus.checked_mul(reduced_modulus)?;
+        if new_modulus > i64::MAX as i128 {
+            return None;
+        }
+
+        residue = (residue + modulus * k).rem_euclid(new_modulus);
+        modulus = new_modulus;
+    }
+
+    Some((residue as i64, modulus as i64))
+}
+
+fn gcd(mut a: i128, mut b: i128) -> i128 {
+    while b != 0 {
+        let remainder = a % b;
+        a = b;
+        b = remainder;
+    }
+    a.abs()
+}
+
+fn mod_inverse(a: i128, modulus: i128) -> Option<i128> {
+    let (mut old_r, mut r) = (a, modulus);
+    let (mut old_s, mut s) = (1i128, 0i128);
+
+    while r != 0 {
+        let quotient = old_r / r;
+
+        let next_r = old_r - quotient * r;
+        old_r = r;
+        r = next_r;
+
+        let next_s = old_s - quotient * s;
+        old_s = s;
+        s = next_s;
+    }
+
+    if old_r == 1 {
+        Some(old_s.rem_euclid(modulus))
+    } else {
+        None
+    }
