+pub fn prime_ring(n: usize) -> Option<Vec<usize>> {
+    match n {
+        0 => None,
+        1 => Some(vec![1]),
+        _ if n % 2 == 1 => None,
+        _ => {
+            let mut ring = vec![1];
+            let mut used = vec![false; n + 1];
+            used[1] = true;
+
+            if search(n, &mut ring, &mut used) {
+                Some(ring)
+            } else {
+                None
+            }
+        }
+    }
+}
+
+fn search(n: usize, ring: &mut Vec<usize>, used: &mut [bool]) -> bool {
+    if ring.len() == n {
+        return is_prime(ring[0] + ring[n - 1]);
+    }
+
+    let last = *ring.last().expect("ring is never empty during search");
+
+    for candidate in 2..=n {
+        if !used[candidate] && is_prime(last + candidate) {
+            used[candidate] = true;
+            ring.push(candidate);
+
+            if search(n, ring, used) {
+                return true;
+            }
+
+            ring.pop();
+            used[candidate] = false;
+        }
+    }
+
+    false
+}
+
+fn is_prime(n: usize) -> bool {
+    if n < 2 {
+        return false;
+    }
+
+    if n % 2 == 0 {
+        return n == 2;
+    }
+
+    let mut divisor = 3;
+    while divisor <= n / divisor {
+        if n % divisor == 0 {
+            return false;
+        }
+        divisor += 2;
+    }
+
+    true
+}
