+pub fn solve_congruences(remainders: &[i64], moduli: &[i64]) -> Option<i64> {
+    if remainders.len() != moduli.len() {
+        return None;
+    }
+
+    if moduli.iter().any(|&m| m <= 0) {
+        return None;
+    }
+
+    if moduli.is_empty() {
+        return Some(0);
+    }
+
+    let mut r = (remainders[0] as i128).rem_euclid(moduli[0] as i128);
+    let mut m = moduli[0] as i128;
+
+    for (&remainder, &modulus) in remainders.iter().zip(moduli.iter()).skip(1) {
+        let r2 = (remainder as i128).rem_euclid(modulus as i128);
+        let m2 = modulus as i128;
+
+        let diff = (r2 - r).rem_euclid(m2);
+        let g = gcd(m, m2);
+
+        if diff % g != 0 {
+            return None;
+        }
+
+        let m_g = m / g;
+        let m2_g = m2 / g;
+
+        let k = if m2_g == 1 {
+            0
+        } else {
+            let a = m_g.rem_euclid(m2_g);
+            let inv = mod_inverse(a, m2_g)?;
+            ((diff / g).rem_euclid(m2_g) * inv).rem_euclid(m2_g)
+        };
+
+        r += m * k;
+        m *= m2_g;
+        r = r.rem_euclid(m);
+
+        if m > i64::MAX as i128 {
+            return None;
+        }
+    }
+
+    Some(r as i64)
+}
+
+fn gcd(mut a: i128, mut b: i128) -> i128 {
+    while b != 0 {
+        let t = a % b;
+        a = b;
+        b = t;
+    }
+    a.abs()
+}
+
+fn mod_inverse(a: i128, modulus: i128) -> Option<i128> {
+    let (g, x, _) = extended_gcd(a, modulus);
+
+    if g != 1 {
+        None
+    } else {
+        Some(x.rem_euclid(modulus))
+    }
+}
+
+fn extended_gcd(a: i128, b: i128) -> (i128, i128, i128) {
+    if b == 0 {
+        (a, 1, 0)
+    } else {
+        let (g, x1, y1) = extended_gcd(b, a % b);
+        (g, y1, x1 - (a / b) * y1)
+    }
