+pub fn primes_in_range(start: u64, end: u64) -> Vec<u64> {
+    if start > end || end < 2 {
+        return Vec::new();
+    }
+
+    let low = start.max(2);
+    let high = end;
+    let limit = integer_sqrt(high);
+    let base_primes = simple_sieve(limit);
