+    let len_u64 = high - low + 1;
+    let len = len_u64 as usize;
+    let mut is_prime = vec![true; len];
+
+    for p in base_primes {
+        let p2 = p * p;
+        let rem = low % p;
+        let mut first = if rem == 0 {
+            low
+        } else {
+            let add = p - rem;
+            if low > u64::MAX - add {
+                continue;
+            }
+            low + add
+        };
+
+        if first < p2 {
+            first = p2;
+        }
+
+        let mut multiple = first;
+        while multiple <= high {
+            is_prime[(multiple - low) as usize] = false;
+            if multiple > high - p {
+                break;
+            }
+            multiple += p;
+        }
+    }
