+    is_prime
+        .into_iter()
+        .enumerate()
+        .filter_map(|(offset, prime)| {
+            if prime {
+                Some(low + offset as u64)
+            } else {
+                None
+            }
+        })
+        .collect()
+}
+
+fn integer_sqrt(n: u64) -> u64 {
+    if n < 2 {
+        return n;
+    }
+
+    let mut low = 1u64;
+    let mut high = n;
+    while low <= high {
+        let mid = low + (high - low) / 2;
+        if mid <= n / mid {
+            low = mid + 1;
+        } else {
+            high = mid - 1;
+        }
+    }
+    high
+}
+
+fn simple_sieve(limit: u64) -> Vec<u64> {
+    if limit < 2 {
+        return Vec::new();
+    }
+
+    let n = limit as usize;
+    let mut is_prime = vec![true; n + 1];
+    is_prime[0] = false;
+    is_prime[1] = false;
+
+    let mut p = 2usize;
+    while p <= n / p {
+        if is_prime[p] {
+            let mut multiple = p * p;
+            while multiple <= n {
+                is_prime[multiple] = false;
+                multiple += p;
+            }
+        }
+        p += 1;
+    }
+
+    is_prime
+        .into_iter()
+        .enumerate()
+        .filter_map(|(value, prime)| {
+            if prime {
+                Some(value as u64)
+            } else {
+                None
+            }
+        })
+        .collect()
