+pub fn rotate_rings(matrix: &[Vec<i32>], turns: usize) -> Vec<Vec<i32>> {
+    if matrix.is_empty() {
+        return Vec::new();
+    }
+    let rows = matrix.len();
+    let cols = matrix[0].len();
+    let mut result = matrix.to_vec();
+    if cols == 0 {
+        return result;
+    }
+    let layers = rows.min(cols) / 2;
+    for k in 0..layers {
+        let cells = ring_cells(k, rows, cols);
+        let len = cells.len();
+        if len == 0 {
+            continue;
+        }
+        let shift = turns % len;
+        if shift == 0 {
+            continue;
+        }
+        for idx in 0..len {
+            let source = (idx + len - shift) % len;
+            let (r, c) = cells[idx];
+            let (sr, sc) = cells[source];
+            result[r][c] = matrix[sr][sc];
+        }
+    }
+    result
+}
+
+fn ring_cells(k: usize, rows: usize, cols: usize) -> Vec<(usize, usize)> {
+    let top = k;
+    let bottom = rows - 1 - k;
+    let left = k;
+    let right = cols - 1 - k;
+    let mut cells = Vec::new();
+    if top >= bottom || left >= right {
+        return cells;
+    }
+    for c in left..right {
+        cells.push((top, c));
+    }
+    for r in top..bottom {
+        cells.push((r, right));
+    }
+    for c in ((left + 1)..=right).rev() {
+        cells.push((bottom, c));
+    }
+    for r in ((top + 1)..=bottom).rev() {
+        cells.push((r, left));
+    }
+    cells
+}
