+                                    ch: escaped,
+                                    index: backslash,
+                                })
+                            }
+                        }
+                        i += 1;
+                    } else {
+                        value.push(ch);
+                        i += 1;
+                    }
+                }
+                tokens.push(Token::Str(value));
+            }
+            c if c.is_ascii_digit() => {
+                let start = i;
+                while i < chars.len() && chars[i].is_ascii_digit() {
+                    i += 1;
+                }
+                if i + 1 < chars.len() && chars[i] == '.' && chars[i + 1].is_ascii_digit() {
