+            let mut next = cells;
+            next[i] = Some(turn);
+            let value = search(next, turn.other(), me, depth + 1);
+            if turn == me {
+                if value > best {
+                    best = value;
+                }
+            } else if value < best {
+                best = value;
+            }
+        }
+    }
+    best
