+pub fn normalize(intervals: &[(i32, i32)]) -> Vec<(i32, i32)> {
+    let mut ranges: Vec<(i64, i64)> = intervals
+        .iter()
+        .filter(|&&(start, end)| start <= end)
+        .map(|&(start, end)| (start as i64, end as i64))
+        .collect();
+
+    ranges.sort_unstable();
+
+    let mut merged: Vec<(i64, i64)> = Vec::new();
+    for (start, end) in ranges {
+        if let Some(last) = merged.last_mut() {
+            if start <= last.1 + 1 {
+                if end > last.1 {
+                    last.1 = end;
+                }
+                continue;
+            }
+        }
+        merged.push((start, end));
+    }
+
+    merged
+        .into_iter()
+        .map(|(start, end)| (start as i32, end as i32))
+        .collect()
+}
+
+pub fn union(left: &[(i32, i32)], right: &[(i32, i32)]) -> Vec<(i32, i32)> {
+    let mut all = Vec::with_capacity(left.len() + right.len());
+    all.extend_from_slice(left);
+    all.extend_from_slice(right);
+    normalize(&all)
+}
+
+pub fn intersection(left: &[(i32, i32)], right: &[(i32, i32)]) -> Vec<(i32, i32)> {
+    let left = normalize(left);
+    let right = normalize(right);
+    let mut result = Vec::new();
+    let (mut i, mut j) = (0, 0);
+
+    while i < left.len() && j < right.len() {
+        let left_start = left[i].0 as i64;
+        let left_end = left[i].1 as i64;
+        let right_start = right[j].0 as i64;
+        let right_end = right[j].1 as i64;
+
+        let start = left_start.max(right_start);
+        let end = left_end.min(right_end);
+
+        if start <= end {
+            result.push((start as i32, end as i32));
+        }
+
+        if left_end < right_end {
+            i += 1;
+        } else {
+            j += 1;
+        }
+    }
+
+    result
+}
+
+pub fn difference(left: &[(i32, i32)], right: &[(i32, i32)]) -> Vec<(i32, i32)> {
+    let left = normalize(left);
+    let right = normalize(right);
+    let mut result = Vec::new();
+
+    for &(left_start, left_end) in &left {
+        let mut start = left_start as i64;
+        let end = left_end as i64;
+
+        for &(right_start, right_end) in &right {
+            let right_start = right_start as i64;
+            let right_end = right_end as i64;
+
+            if right_end < start {
+                continue;
+            }
+            if right_start > end {
+                break;
+            }
+            if right_start > start {
+                result.push((start as i32, (right_start - 1) as i32));
+            }
+            if right_end >= end {
+                start = end + 1;
+                break;
+            }
+            start = right_end + 1;
+        }
+
+        if start <= end {
+            result.push((start as i32, end as i32));
+        }
+    }
+
+    result
+}
