+        let next_tick = self.tick.wrapping_add(1);
+        if let Some((value, last_used)) = self.entries.get_mut(key) {
+            self.tick = next_tick;
+            *last_used = self.tick;
+            Some(value.clone())
+        } else {
+            None
+        }
+    }
