+pub fn encode(message: &str, rails: usize) -> String {
+    if rails == 0 {
+        return String::new();
+    }
+    if rails == 1 {
+        return message.to_string();
+    }
+    let chars: Vec<char> = message.chars().collect();
+    if chars.is_empty() {
+        return String::new();
+    }
+    let mut rail_contents: Vec<Vec<char>> = vec![Vec::new(); rails];
+    let mut rail = 0;
+    let mut direction = 1isize;
+    for &c in &chars {
+        rail_contents[rail].push(c);
+        if rail == 0 {
+            direction = 1;
+        } else if rail == rails - 1 {
+            direction = -1;
+        }
+        rail = (rail as isize + direction) as usize;
+    }
+    let mut result = String::new();
+    for r in 0..rails {
+        for &c in &rail_contents[r] {
+            result.push(c);
+        }
+    }
+    result
+}
+
+pub fn decode(ciphertext: &str, rails: usize) -> String {
+    if rails == 0 {
+        return String::new();
+    }
+    if rails == 1 {
+        return ciphertext.to_string();
+    }
+    let chars: Vec<char> = ciphertext.chars().collect();
+    if chars.is_empty() {
+        return String::new();
+    }
+    let len = chars.len();
+    let mut pattern = Vec::with_capacity(len);
+    let mut rail = 0;
+    let mut direction = 1isize;
+    for _ in 0..len {
+        pattern.push(rail);
+        if rail == 0 {
+            direction = 1;
+        } else if rail == rails - 1 {
+            direction = -1;
+        }
+        rail = (rail as isize + direction) as usize;
+    }
+    let mut counts = vec![0; rails];
+    for &r in &pattern {
+        counts[r] += 1;
+    }
+    let mut segments: Vec<Vec<char>> = Vec::with_capacity(rails);
+    let mut start = 0;
+    for r in 0..rails {
+        let end = start + counts[r];
+        segments.push(chars[start..end].to_vec());
+        start = end;
+    }
+    let mut result = String::new();
+    let mut indices = vec![0; rails];
+    for &r in &pattern {
+        result.push(segments[r][indices[r]]);
+        indices[r] += 1;
+    }
+    result
