+pub fn best_schedule(tasks: &[(u32, u32, u32)]) -> (u32, Vec<(u32, u32, u32)>) {
+    let mut valid: Vec<(u32, u32, u32)> = tasks
+        .iter()
+        .filter(|&&(s, e, _)| s < e)
+        .cloned()
+        .collect();
+
+    valid.sort_by(|a, b| {
+        a.1.cmp(&b.1)
+            .then(a.0.cmp(&b.0))
+            .then(a.2.cmp(&b.2))
+    });
+
+    let n = valid.len();
+    if n == 0 {
+        return (0, vec![]);
+    }
+
+    let ends: Vec<u32> = valid.iter().map(|&(_, e, _)| e).collect();
+
+    let mut dp: Vec<(u32, Vec<(u32, u32, u32)>)> = Vec::with_capacity(n + 1);
+    dp.push((0, vec![]));
