+        let (start, _, value) = valid[i - 1];
+
+        let mut lo = 0;
+        let mut hi = i - 1;
+        while lo < hi {
+            let mid = (lo + hi + 1) / 2;
+            if ends[mid - 1] <= start {
+                lo = mid;
+            } else {
+                hi = mid - 1;
+            }
