+pub fn stirling_second(n: u32, k: u32) -> u128 {
+    if k > n {
+        return 0;
+    }
+    if n == 0 {
+        return if k == 0 { 1 } else { 0 };
+    }
+    if k == 0 {
+        return 0;
+    }
+
+    let k = k as usize;
+    let mut dp = vec![0u128; k + 1];
+    dp[0] = 1;
+
+    for i in 1..=n {
+        let max_j = std::cmp::min(i as usize, k);
+        for j in (1..=max_j).rev() {
+            dp[j] = dp[j - 1] + (j as u128) * dp[j];
+        }
+        dp[0] = 0;
+    }
+
+    dp[k]
+}
