+use std::cmp::Ordering;
+
+pub fn compare_versions(version1: &str, version2: &str) -> Ordering {
+    let parts1: Vec<&str> = version1.split('.').collect();
+    let parts2: Vec<&str> = version2.split('.').collect();
+    let max_len = parts1.len().max(parts2.len());
+
+    for i in 0..max_len {
+        let part1 = parts1.get(i).copied().unwrap_or("0");
+        let part2 = parts2.get(i).copied().unwrap_or("0");
+
+        let n1 = normalize(part1);
+        let n2 = normalize(part2);
+
+        let ord = n1.len().cmp(&n2.len()).then_with(|| n1.cmp(n2));
+        if ord != Ordering::Equal {
+            return ord;
+        }
+    }
+
+    Ordering::Equal
+}
+
+fn normalize(part: &str) -> &str {
+    let trimmed = part.trim_start_matches('0');
+    if trimmed.is_empty() {
+        "0"
+    } else {
+        trimmed
+    }
+}
