+    pub fn unfreeze(&mut self, id: AccountId) -> Result<(), BankError> {
+        let account = self
+            .accounts
+            .get_mut(&id)
+            .ok_or(BankError::AccountNotFound)?;
+        match account.status {
+            Status::Closed => Err(BankError::AccountClosed),
+            Status::Open => Ok(()),
+            Status::Frozen => {
+                account.status = Status::Open;
+                account.history.push(Transaction::Unfrozen);
+                Ok(())
+            }
+        }
+    }
+
+    pub fn close(&mut self, id: AccountId) -> Result<(), BankError> {
+        let account = self
+            .accounts
+            .get_mut(&id)
+            .ok_or(BankError::AccountNotFound)?;
