+fn gcd(mut a: i128, mut b: i128) -> i128 {
+    while b != 0 {
+        let t = a % b;
+        a = b;
+        b = t;
+    }
+    a.abs()
+}
+
+fn extended_gcd(a: i128, b: i128) -> (i128, i128, i128) {
+    let (mut old_r, mut r) = (a, b);
+    let (mut old_s, mut s) = (1, 0);
+    let (mut old_t, mut t) = (0, 1);
+    while r != 0 {
+        let q = old_r / r;
+        let new_r = old_r - q * r;
+        old_r = r;
+        r = new_r;
+        let new_s = old_s - q * s;
+        old_s = s;
+        s = new_s;
+        let new_t = old_t - q * t;
+        old_t = t;
+        t = new_t;
+    }
+    (old_r.abs(), old_s, old_t)
+}
+
+pub fn solve_congruences(congruences: &[(i128, i128)]) -> Option<(i128, i128)> {
+    let mut x = 0i128;
+    let mut m = 1i128;
+    for &(a, mi) in congruences {
+        if mi <= 0 {
+            return None;
+        }
+        let a = a.rem_euclid(mi);
+        let g = gcd(m, mi);
+        let diff = (a - x).rem_euclid(mi);
+        if diff % g != 0 {
+            return None;
+        }
+        let m1 = m / g;
+        let m2 = mi / g;
+        let rhs = (diff / g).rem_euclid(m2);
+        let (g2, inv, _) = extended_gcd(m1, m2);
+        debug_assert_eq!(g2, 1);
+        let t = (rhs * inv.rem_euclid(m2)).rem_euclid(m2);
+        x += m * t;
+        m = m * m2;
+        x = x.rem_euclid(m);
+    }
+    Some((x, m))
