+        if self.is_full() {
+            return Err(item);
+        }
+
+        let index = (self.head + self.len) % self.capacity;
+        self.data[index] = Some(item);
+        self.len += 1;
+        Ok(())
+    }
+
+    pub fn overwrite(&mut self, item: T) -> Option<T> {
+        if self.is_full() {
+            let index = self.head;
+            let old = self.data[index]
+                .take()
+                .expect("full ring buffer had an empty slot");
+            self.data[index] = Some(item);
+            self.head = (self.head + 1) % self.capacity;
+            Some(old)
+        } else {
+            let index = (self.head + self.len) % self.capacity;
+            self.data[index] = Some(item);
+            self.len += 1;
