+
+    pub fn is_full(&self) -> bool {
+        self.len == self.capacity
+    }
+
+    pub fn write(&mut self, value: T) -> Result<(), T> {
+        if self.is_full() {
+            return Err(value);
+        }
+        self.data[self.write_index] = Some(value);
+        self.write_index = (self.write_index + 1) % self.capacity;
+        self.len += 1;
+        Ok(())
+    }
+
+    pub fn read(&mut self) -> Option<T> {
+        if self.is_empty() {
+            return None;
+        }
+        let value = self.data[self.read_index].take();
+        self.read_index = (self.read_index + 1) % self.capacity;
+        self.len -= 1;
+        value
+    }
+
+    pub fn overwrite(&mut self, value: T) -> Option<T> {
+        if self.is_full() {
+            let old = self.data[self.write_index].take();
+            self.data[self.write_index] = Some(value);
+            self.write_index = (self.write_index + 1) % self.capacity;
+            self.read_index = self.write_index;
+            old
+        } else {
+            let _ = self.write(value);
+            None
+        }
+    }
+
+    pub fn clear(&mut self) {
+        for item in self.data.iter_mut() {
+            *item = None;
+        }
+        self.read_index = 0;
+        self.write_index = 0;
+        self.len = 0;
+    }
