+use std::collections::HashMap;
+
+#[derive(Debug, PartialEq, Clone)]
+pub enum Value {
+    Int(i64),
+    Bool(bool),
+    Str(String),
+    Tuple(Vec<Value>),
+    List(Vec<Value>),
+}
+
+#[derive(Debug, PartialEq, Clone)]
+pub enum Pattern {
+    Wildcard,
+    Variable(String),
+    Int(i64),
+    Bool(bool),
+    Str(String),
+    Tuple(Vec<Pattern>),
+    List(Vec<Pattern>),
+    Or(Vec<Pattern>),
+}
