+pub fn match_pattern(pattern: &Pattern, value: &Value) -> Option<HashMap<String, Value>> {
+    let mut bindings = HashMap::new();
+    if match_pattern_inner(pattern, value, &mut bindings) {
+        Some(bindings)
+    } else {
+        None
+    }
+}
+
+fn match_pattern_inner(pattern: &Pattern, value: &Value, bindings: &mut HashMap<String, Value>) -> bool {
+    match (pattern, value) {
+        (Pattern::Wildcard, _) => true,
+        (Pattern::Variable(name), val) => {
+            if let Some(existing) = bindings.get(name) {
+                existing == val
+            } else {
+                bindings.insert(name.clone(), val.clone());
+                true
+            }
+        }
+        (Pattern::Int(p), Value::Int(v)) => p == v,
+        (Pattern::Bool(p), Value::Bool(v)) => p == v,
+        (Pattern::Str(p), Value::Str(v)) => p == v,
+        (Pattern::Tuple(ps), Value::Tuple(vs)) => {
+            if ps.len() != vs.len() {
+                return false;
+            }
+            for (p, v) in ps.iter().zip(vs.iter()) {
+                if !match_pattern_inner(p, v, bindings) {
+                    return false;
+                }
+            }
+            true
+        }
+        (Pattern::List(ps), Value::List(vs)) => {
+            if ps.len() != vs.len() {
+                return false;
+            }
+            for (p, v) in ps.iter().zip(vs.iter()) {
+                if !match_pattern_inner(p, v, bindings) {
+                    return false;
+                }
+            }
+            true
+        }
+        (Pattern::Or(alternatives), val) => {
+            for alt in alternatives {
+                let mut new_bindings = bindings.clone();
+                if match_pattern_inner(alt, val, &mut new_bindings) {
+                    *bindings = new_bindings;
+                    return true;
+                }
+            }
+            false
+        }
+        _ => false,
+    }
